window.LAW_SEARCH_IDX = window.LAW_SEARCH_IDX || {};
window.LAW_SEARCH_IDX["人力资源社会保障部"] = {"zhuanyejishurenyuanjixujiaoyuguiding":[{"i":1,"n":"第一条","txt":"为了规范继续教育活动，保障专业技术人员权益，不断提高专业技术人员素质，根据有关法律法规和国务院规定，制定本规定。"},{"i":2,"n":"第二条","txt":"国家机关、企业、事业单位以及社会团体等组织（以下称用人单位）的专业技术人员继续教育（以下称继续教育），适用本规定。"},{"i":3,"n":"第三条","txt":"继续教育应当以经济社会发展和科技进步为导向，以能力建设为核心，突出针对性、实用性和前瞻性，坚持理论联系实际、按需施教、讲求实效、培养与使用相结合的原则。"},{"i":4,"n":"第四条","txt":"用人单位应当保障专业技术人员参加继续教育的权利。 专业技术人员应当适应岗位需要和职业发展的要求，积极参加继续教育，完善知识结构、增强创新能力、提高专业水平。"},{"i":5,"n":"第五条","txt":"继续教育实行政府、社会、用人单位和个人共同投入机制。 国家机关的专业技术人员参加继续教育所需经费应当按照国家有关规定予以保障。企业、事业单位等应当依照法律、行政法规和国家有关规定提取和使用职工教育经费，不断加大对专业技术人员继续教育经费的投入。"},{"i":6,"n":"第六条","txt":"继续教育工作实行统筹规划、分级负责、分类指导的管理体制。 人力资源社会保障部负责对全国专业技术人员继续教育工作进行综合管理和统筹协调，制定继续教育政策，编制继续教育规划并组织实施。 县级以上地方人力资源社会保障行政部门负责对本地区专业技术人员继续教育工作进行综合管理和组织实施。 行业主管部门在各自职责范围内依法做好本行业继续教育的规划、管理和实施工作。"},{"i":7,"n":"第七条","txt":"继续教育内容包括公需科目和专业科目。 公需科目包括专业技术人员应当普遍掌握的法律法规、理论政策、职业道德、技术信息等基本知识。专业科目包括专业技术人员从事专业工作应当掌握的新理论、新知识、新技术、新方法等专业知识。"},{"i":8,"n":"第八条","txt":"专业技术人员参加继续教育的时间，每年累计应不少于90学时，其中，专业科目一般不少于总学时的三分之二。 专业技术人员通过下列方式参加继续教育的，计入本人当年继续教育学时： （一）参加培训班、研修班或者进修班学习； （二）参加相关的继续教育实践活动； （三）参加远程教育; （四）参加学术会议、学术讲座、学术访问等活动； （五）符合规定的其他方式。 继续教育方式和学时的具体认定办法，由省、自治区、直辖市人力资源社会保障行政部门制定。"},{"i":9,"n":"第九条","txt":"用人单位可以根据本规定，结合本单位发展战略和岗位要求，组织开展继续教育活动或者参加本行业组织的继续教育活动，为本单位专业技术人员参加继续教育提供便利。"},{"i":10,"n":"第十条","txt":"专业技术人员根据岗位要求和职业发展需要，参加本单位组织的继续教育活动，也可以利用业余时间或者经用人单位同意利用工作时间，参加本单位组织之外的继续教育活动。"},{"i":11,"n":"第十一条","txt":"专业技术人员按照有关法律法规规定从事有职业资格要求工作的，用人单位应当为其参加继续教育活动提供保障。"},{"i":12,"n":"第十二条","txt":"专业技术人员经用人单位同意，脱产或者半脱产参加继续教育活动的，用人单位应当按照国家有关规定或者与劳动者的约定，支付工资、福利等待遇。 用人单位安排专业技术人员在工作时间之外参加继续教育活动的，双方应当约定费用分担方式和相关待遇。"},{"i":13,"n":"第十三条","txt":"用人单位可以与生产、教学、科研等单位联合开展继续教育活动，建立生产、教学、科研以及项目、资金、人才相结合的继续教育模式。"},{"i":14,"n":"第十四条","txt":"国家通过实施重大人才工程和继续教育项目、区域人才特殊培养项目、对口支援等方式，对重点领域、特殊区域和关键岗位的专业技术人员继续教育工作给予扶持。"},{"i":15,"n":"第十五条","txt":"专业技术人员应当遵守有关学习纪律和管理制度，完成规定的继续教育学时。 专业技术人员承担全部或者大部分继续教育费用的，用人单位不得指定继续教育机构。"},{"i":16,"n":"第十六条","txt":"用人单位应当建立本单位专业技术人员继续教育与使用、晋升相衔接的激励机制，把专业技术人员参加继续教育情况作为专业技术人员考核评价、岗位聘用的重要依据。 专业技术人员参加继续教育情况应当作为聘任专业技术职务或者申报评定上一级资格的重要条件。有关法律法规规定专业技术人员参加继续教育作为职业资格登记或者注册的必要条件的，从其规定。"},{"i":17,"n":"第十七条","txt":"用人单位应当建立继续教育登记管理制度，对专业技术人员参加继续教育的种类、内容、时间和考试考核结果等情况进行记录。"},{"i":18,"n":"第十八条","txt":"依法成立的高等院校、科研院所、大型企业的培训机构等各类教育培训机构（以下称继续教育机构）可以面向专业技术人员提供继续教育服务。 继续教育机构应当具备与继续教育目的任务相适应的场所、设施、教材和人员，建立健全相应的组织机构和管理制度。"},{"i":19,"n":"第十九条","txt":"继续教育机构应当认真实施继续教育教学计划，向社会公开继续教育的范围、内容、收费项目及标准等情况，建立教学档案，根据考试考核结果如实出具专业技术人员参加继续教育的证明。 继续教育机构可以充分利用现代信息技术开展远程教育，形成开放式的继续教育网络，为基层、一线专业技术人员更新知识结构、提高能力素质提供便捷高效的服务。"},{"i":20,"n":"第二十条","txt":"继续教育机构应当按照专兼职结合的原则，聘请具有丰富实践经验、理论水平高的业务骨干和专家学者，建设继续教育师资队伍。"},{"i":21,"n":"第二十一条","txt":"人力资源社会保障部按照国家有关规定遴选培训质量高、社会效益好、在继续教育方面起引领和示范作用的继续教育机构，建设国家级专业技术人员继续教育基地。 县级以上地方人力资源社会保障行政部门和有关行业主管部门可以结合实际，建设区域性、行业性专业技术人员继续教育基地。"},{"i":22,"n":"第二十二条","txt":"人力资源社会保障行政部门会同有关行业主管部门和行业组织，建立健全继续教育公共服务体系，搭建继续教育公共信息综合服务平台，发布继续教育公需科目指南和专业科目指南。 人力资源社会保障行政部门会同有关行业主管部门和行业组织，根据专业技术人员不同岗位、类别和层次，加强课程和教材体系建设，推荐优秀课程和优秀教材，促进优质资源共享。"},{"i":23,"n":"第二十三条","txt":"人力资源社会保障行政部门和有关行业主管部门直接举办继续教育活动的，应当突出公益性，不得收取费用。 人力资源社会保障行政部门和有关行业主管部门委托继续教育机构举办继续教育活动的，应当依法通过招标等方式选择，并与继续教育机构签订政府采购合同，明确双方权利和义务。 鼓励和支持企业、事业单位、行业组织等举办公益性继续教育活动。"},{"i":24,"n":"第二十四条","txt":"人力资源社会保障行政部门应当建立继续教育统计制度，对继续教育人数、时间、经费等基本情况进行常规统计和随机统计，建立专业技术人员继续教育情况数据库。"},{"i":25,"n":"第二十五条","txt":"人力资源社会保障行政部门或者其委托的第三方评估机构可以对继续教育效果实施评估，评估结果作为政府有关项目支持的重要参考。"},{"i":26,"n":"第二十六条","txt":"人力资源社会保障行政部门应当依法对用人单位、继续教育机构执行本规定的情况进行监督检查。"},{"i":27,"n":"第二十七条","txt":"用人单位违反本规定第五条、第十一条、第十二条、第十五条第二款、第十六条、第十七条规定的，由人力资源社会保障行政部门或者有关行业主管部门责令改正；给专业技术人员造成损害的，依法承担赔偿责任。"},{"i":28,"n":"第二十八条","txt":"专业技术人员违反本规定第八条第一款、第十五条第一款规定，无正当理由不参加继续教育或者在学习期间违反学习纪律和管理制度的，用人单位可视情节给予批评教育、不予报销或者要求退还学习费用。"},{"i":29,"n":"第二十九条","txt":"继续教育机构违反本规定第十九条第一款规定的，由人力资源社会保障行政部门或者有关行业主管部门责令改正，给予警告。"},{"i":30,"n":"第三十条","txt":"人力资源社会保障行政部门、有关行业主管部门及其工作人员，在继续教育管理工作中不认真履行职责或者徇私舞弊、滥用职权、玩忽职守的，由其上级主管部门或者监察机关责令改正，并按照管理权限对直接负责的主管人员和其他直接责任人员依法予以处理。"},{"i":31,"n":"第三十一条","txt":"本规定自2015年10月1日起施行。1995年11月1日原人事部发布的《全国专业技术人员继续教育暂行规定》（人核培发〔1995〕131号）同时废止。"}],"zhuanyejishurenyuanzigekaoshiweijiweiguixingweichu3feb77":[{"i":1,"n":"第一条","txt":"为加强专业技术人员资格考试工作管理，保证考试的公平、公正，规范对违纪违规行为的认定与处理，维护应试人员和考试工作人员合法权益，根据有关法律、行政法规制定本规定。"},{"i":2,"n":"第二条","txt":"专业技术人员资格考试中违纪违规行为的认定和处理，适用本规定。"},{"i":3,"n":"第三条","txt":"本规定所称专业技术人员资格考试，是指由人力资源社会保障部或者由其会同有关行政部门确定，在全国范围内统一举行的准入类职业资格考试、水平评价类职业资格考试以及与职称相关的考试。 本规定所称应试人员，是指根据专业技术人员资格考试有关规定参加考试的人员。 本规定所称考试工作人员，是指参与考试管理和服务工作的人员，包括命（审）题（卷）、监考、主考、巡考、考试系统操作、评卷等人员和考试主管部门及考试机构的有关工作人员。 本规定所称考试主管部门，是指各级人力资源社会保障行政部门、有关行政主管部门以及依据法律、行政法规规定具有考试管理职能的行业协会或者学会等。 本规定所称考试机构，是指经政府及其有关部门批准的各级具有专业技术人员资格考试工作职能的单位。"},{"i":4,"n":"第四条","txt":"认定与处理违纪违规行为，应当事实清楚、证据确凿、程序规范、适用规定准确。"},{"i":5,"n":"第五条","txt":"人力资源社会保障部负责全国专业技术人员资格考试工作的综合管理与监督。 各级考试主管部门、考试机构或者有关部门按照考试管理权限依据本规定对应试人员、考试工作人员的违纪违规行为进行认定与处理。其中，造成重大社会影响的严重违纪违规行为，由省级考试主管部门会同省级考试机构或者由省级考试机构进行认定与处理，并将处理情况报告人力资源社会保障部和相应行业的考试主管部门。"},{"i":6,"n":"第六条","txt":"应试人员在考试过程中有下列违纪违规行为之一的，给予其当次该科目考试成绩无效的处理： （一）携带通讯工具、规定以外的电子用品或者与考试内容相关的资料进入座位，经提醒仍不改正的； （二）经提醒仍不按规定书写、填涂本人身份和考试信息的； （三) 在试卷、答题纸、答题卡规定以外位置标注本人信息或者其他特殊标记的； （四）未在规定座位参加考试，或者未经考试工作人员允许擅自离开座位或者考场，经提醒仍不改正的； （五）未用规定的纸、笔作答，或者试卷前后作答笔迹不一致的； （六）在考试开始信号发出前答题，或者在考试结束信号发出后继续答题的； （七）将试卷、答题卡、答题纸带出考场的； （八）故意损坏试卷、答题纸、答题卡、电子化系统设施的； （九）未按规定使用考试系统，经提醒仍不改正的； （十）其他应当给予当次该科目考试成绩无效处理的违纪违规行为。"},{"i":7,"n":"第七条","txt":"应试人员在考试过程中有下列严重违纪违规行为之一的，给予其当次全部科目考试成绩无效的处理，并将其违纪违规行为记入专业技术人员资格考试诚信档案库，记录期限为五年： （一）抄袭、协助他人抄袭试题答案或者与考试内容相关资料的； （二）互相传递试卷、答题纸、答题卡、草稿纸等的； （三）持伪造证件参加考试的； （四）本人离开考场后，在考试结束前，传播考试试题及答案的； （五）使用禁止带入考场的通讯工具、规定以外的电子用品的； （六）其他应当给予当次全部科目考试成绩无效处理的严重违纪违规行为。"},{"i":8,"n":"第八条","txt":"应试人员在考试过程中有下列特别严重违纪违规行为之一的，给予其当次全部科目考试成绩无效的处理，并将其违纪违规行为记入专业技术人员资格考试诚信档案库，长期记录： （一）串通作弊或者参与有组织作弊的； （二）代替他人或者让他人代替自己参加考试的； （三）其他情节特别严重、影响恶劣的违纪违规行为。"},{"i":9,"n":"第九条","txt":"应试人员应当自觉维护考试工作场所秩序，服从考试工作人员管理，有下列行为之一的，终止其继续参加考试，并责令离开考场；情节严重的，按照本规定第七条、第八条的规定处理；违反《中华人民共和国治安管理处罚法》等法律法规的，交由公安机关依法处理；构成犯罪的，依法追究刑事责任： （一）故意扰乱考点、考场等考试工作场所秩序的； （二）拒绝、妨碍考试工作人员履行管理职责的； （三）威胁、侮辱、诽谤、诬陷工作人员或者其他应试人员的； （四）其他扰乱考试管理秩序的行为。"},{"i":10,"n":"第十条","txt":"应试人员有提供虚假证明材料或者以其他不正当手段取得相应资格证书或者成绩证明等严重违纪违规行为的，由证书签发机构宣布证书或者成绩证明无效，并按照本规定第七条处理。"},{"i":11,"n":"第十一条","txt":"在阅卷过程中发现应试人员之间同一科目作答内容雷同，并经阅卷专家组确认的，由考试机构或者考试主管部门给予其当次该科目考试成绩无效的处理。作答内容雷同的具体认定方法和标准，由省级以上考试机构确定。 应试人员之间同一科目作答内容雷同，并有其他相关证据证明其违纪违规行为成立的，视具体情形按照本规定第七条、第八条处理。"},{"i":12,"n":"第十二条","txt":"专业技术人员资格考试诚信档案库由人力资源社会保障部统一建立,管理办法另行制定。 考试诚信档案库纳入全国信用信息共享平台，向用人单位及社会提供查询，相关记录作为专业技术人员职业资格证书核发和注册、职称评定的重要参考。考试机构可以视情况向社会公布考试诚信档案库记录相关信息，并通知当事人所在单位。"},{"i":13,"n":"第十三条","txt":"考试工作人员有下列情形之一的，停止其继续参加当年及下一年度考试工作，并由考试机构、考试主管部门或者建议有关部门给予处分： （一）不严格掌握报名条件的； （二）擅自提前考试开始时间、推迟考试结束时间及缩短考试时间的； （三）擅自为应试人员调换考场或者座位的； （四）提示或者暗示应试人员答卷的； （五）未准确记录考场情况及违纪违规行为，并造成一定影响的； （六）未认真履行职责，造成考场秩序混乱或者所负责考场出现雷同试卷的； （七）未执行回避制度的； （八）其他一般违纪违规行为。"},{"i":14,"n":"第十四条","txt":"考试工作人员有下列情形之一的，由考试机构、考试主管部门或者建议有关部门将其调离考试工作岗位，不得再从事考试工作，并给予相应处分： （一）因命（审）题（卷）发生错误，造成严重后果的； （二）以不正当手段协助他人取得考试资格或者取得相应证书的； （三）因失职造成应试人员未能如期参加考试，或者使考试工作遭受重大损失的； （四）擅自将试卷、试题信息、答题纸、答题卡、草稿纸等带出考场或者传给他人的； （五）故意损坏试卷、试题载体、答题纸、答题卡的； （六）窃取、擅自更改、编造或者虚报考试数据、信息的； （七）泄露考务实施工作中应当保密信息的； （八）在评阅卷工作中，擅自更改评分标准或者不按评分标准进行评卷的； （九）因评卷工作失职，造成卷面成绩错误，后果严重的； （十）指使或者纵容他人作弊，或者参与考场内外串通作弊的； （十一）监管不严，使考场出现大面积作弊现象的； （十二）擅自拆启未开考试卷、"},{"i":15,"n":"第十五条","txt":"考试工作人员违反《中华人民共和国保守国家秘密法》及有关规定，造成在保密期限内的考试试题、试卷及相关材料内容泄露、丢失的，由相关部门视情节轻重，分别给予责任人和有关负责人处分；构成犯罪的，依法追究刑事责任。"},{"i":16,"n":"第十六条","txt":"对应试人员违纪违规行为被当场发现的，考试工作人员应当予以制止。对于被认定为违纪违规的，要收集、保存相应证据材料，如实记录违纪违规事实和现场处理情况，当场告知其记录内容，并要求本人签字；对于拒绝签字或者恶意损坏证据材料的，由两名考试工作人员如实记录其拒签或者恶意损坏证据材料的情况。违纪违规记录经考点负责人签字认定后，报送考试机构或者考试主管部门。"},{"i":17,"n":"第十七条","txt":"对应试人员违纪违规行为作出处理决定前，应当告知应试人员拟作出的处理决定及相关事实、理由和依据，并告知应试人员依法享有陈述和申辩的权利。作出处理决定的考试机构或者考试主管部门对应试人员提出的事实、理由和证据，应当进行复核。 对应试人员违纪违规行为作出处理决定的，由考试机构或者考试主管部门制作考试违纪违规行为处理决定书，依法送达被处理的应试人员。"},{"i":18,"n":"第十八条","txt":"被处理的应试人员对处理决定不服的，可以依法申请行政复议或者提起行政诉讼。"},{"i":19,"n":"第十九条","txt":"考试工作人员因违纪违规行为受到处分不服的，可以依法申请复核或者提出申诉。"},{"i":20,"n":"第二十条","txt":"本规定自2017年4月1日起施行。人力资源社会保障部2011年3月15日发布的《专业技术人员资格考试违纪违规行为处理规定》（人力资源和社会保障部令第12号）同时废止。 本规定施行前发生的违纪违规行为，在本规定施行后尚未作出处理决定的，按照本规定处理；在本规定施行前发生的行为按本规定属于违纪违规行为，但按原规定不属于违纪违规行为的，不得作为违纪违规行为处理。"}],"zhuanyejishuzigepingdingshixingbanfa":[{"i":1,"n":"第一条","txt":"为适应社会主义市场经注的发展，贯彻实施科学技术进步法，保证客观、公正、准确地评定科技人员的中、高级专业技术资格（即职称，下同），为用人单位科学、合理地使用人才提供服务，制订本办法。"},{"i":2,"n":"第二条","txt":"专业技术资格是学术技术水平的标志，一般没有岗位、数量的限制，不与工资等待遇挂钩，可作为聘任专业技术职务的依据。国家通过制定标准条件，实行宏观控制。"},{"i":3,"n":"第三条","txt":"人事部会同有关主管部门制定、颁发的中、高级专业技术资格评审条件，是评定科技人员是否具备相应专业技术资格的标准。"},{"i":4,"n":"第四条","txt":"专业技术资格评定实行分级管理，由政府人事（职改）部门授权组建具有权威性、公正性的跨部门、跨单位的同行专家组成的评审组织，按照颁布的标准条件和规定程序对申请人进行评价。"},{"i":5,"n":"第五条","txt":"凡申请评定专业技术资格的人员，均适用本办法。按照本办法取得专业技术资格的人员，由政府人事（职改）部门颁发资格证书。 二、组  织"},{"i":6,"n":"第六条","txt":"专业技术资格评审委员会（下称评委会），是负责评审科技人员是否符合相应资格条件的组织。评委会按评审条件划分的专业组建。一般性专业正高级评委会由有关部委或具备组建条件的省、自治区、直辖市人事（职改）部门提出申请，人事部批准组建；副高级评委会由人事部授权具备组建条件的有关部委或省、自治区、直辖市批准组建，报人事部备案；中级评委会的组建由省、自治区、直辖市人事（职改）部门参照上述原则决定。特殊性专业中、高级评委会由人事部授权国务院行业主管部门组建。（授权办法见附件一）"},{"i":7,"n":"第七条","txt":"评委会由十一名以上同行专家组成，并应有一定比例的中青年专家。评委会设主任委员一人，副主任委员一至二人。根据需要，可按分支专业组成若干评议组。评议组有推荐、建议权，但不是一级评审组织。"},{"i":8,"n":"第八条","txt":"申请授权组建有关专业高级评委会的地区必须同时具备下列条件： 1.该专业在国内有较高的知名度，能代表国家水平； 2.本地区有条件聘请足够数量的评审委员； 3.人事（职改）部门有能力承担专业技术资格评定管理工作。"},{"i":9,"n":"第九条","txt":"高级评审委员的聘请，根据评审工作的实际需要，考虑不同专业的研究层次、分支学科的覆盖面、地区和部门的分布以及评委的年龄结构加以确定。具体条件由人事部会同有关部委提出。 正高级评审委员由人事部会同行业主管部门遴选、聘请并颁发聘书；副高级评审委员由省、自治区、直辖市人事（职改）部门会同有关专业主管厅（局）遴选、聘请并颁发聘书。每届聘期一般为一至三年。 中级评审委员应具有本专业中级以上专业技术资格或职务，其中具备本专业高级专业技术资格或担任高级专业技术职务的委员不少于二分之一。具体组建条件和评委条件，由各省、自治区、直辖市人事（职改）部门会同专业主管厅（局）参照上述要求制定。"},{"i":10,"n":"第十条","txt":"资格评定办事机构设在被授权的人事（职改）部门，负责受理申请，组织评审，接受咨询等日常工作。"},{"i":11,"n":"第十一条","txt":"未经授权组建评委会的地区，应委托已经授权的地区评审。高级资格委托评审须经所在省、自治区、直辖市人事（职改）部门出具委托函，中级资格委托评审须经地（市）级人事（职改）部门出具委托函。"},{"i":12,"n":"第十二条","txt":"专业技术资格评定的专业、级别和申报时间、地点，由人事（职改）部门向社会公布。 三、申  请"},{"i":13,"n":"第十三条","txt":"申请评定专业技术资格的人员必须遵守中华人民共和国宪法和法律，具备良好的职业道德和敬业精神，符合各专业中、高级技术评审条件所规定的申报条件。"},{"i":14,"n":"第十四条","txt":"申请专业技术资格评定的人员应在规定的时间内，向相应资格评定办事机构或其指定的代办机构提出申请（也可由单位办理集体申请），填写《专业技术资格评定表》（格式见附件二）。申请人在办理申请的同时，提交经本单位确认无误的本人学历、专业经历证明，外语考试成绩和反映本人专业技术水平的业绩材料及相应证明文件的原件或复印件，其中包括能够代表本人专业技术水平的论文、著作、译作和设计、技术报告等科学技术成果。 四、审  核"},{"i":15,"n":"第十五条","txt":"专业技术资格评审材料的收受和审核工作由相应资格评定办事机构负责。对材料不完整、填写不清楚的，可通知申请人在限定时间内补办。发现弄虚作假行为，取消申请人评定资格，两年内不予受理申请，并视情节追究所在单位或有关人员的责任。"},{"i":16,"n":"第十六条","txt":"提交评委会的评审材料，应有资格评定办事机构同意送评的印章和负责人的签章。 五、评  定"},{"i":17,"n":"第十七条","txt":"资格评审的基本程序是： 1.资格评定办事机构在评审会议前十五天将有关材料分别送达评审委员。 2.评议组根据各专业技术资格的标准条件对申请人申评材料进行初审，包括必要的考核、答辩等，测定其实际水平，并写出初审意见。不设评议组的，由评委会委员分工负责上述工作，对每个申请人的考核、答辩每次必须有三名以上委员出席进行。 3.每次参加评审会议的委员不少于九人，会议由主任委员或副主任委员主持。先由评议组或初审委员介绍初审意见，然后在民主评议的基础上进行无记名投票表决。赞成票数达到出席会议评委总数的三分之二通过有效。 4.会议结束时，评委会应在《专业技术资格评定表》中写明评审结论，由主任委员或副主任委员签字，并加盖评委会印章。 评委会应建立会议记录制度。记录内容包括开会日期、出席评委、会议议程、评审对象、评委发言摘要、投票结果等。记录要有会议主持人及记录人签名，并做好归档保密工作。"},{"i":18,"n":"第十八条","txt":"评委会应遵循“公正、准确、保密”的原则，严格掌握标准条件，保证评审质量。在评审评委亲属的专业技术资格时，该评委应主动回避或被告知回避。"},{"i":19,"n":"第十九条","txt":"评委会评审结果由相应人事（职改）部门审批。资格评定办事机构应在评审工作结束后一个月内，将经审定的评定结果通知申请人。获得专业技术资格的人员应在规定时间内持评定结果通知书，到资格评定办事机构或其指定的代办机构办理《专业技术资格证书》。 六、监  督"},{"i":20,"n":"第二十条","txt":"授权部门对授权组建评委会的地区和单位的评定工作实施监督、检查，受理举报、申诉并负责核查和裁定。"},{"i":21,"n":"第二十一条","txt":"对违反评审程序和规定的评委会或委员，人事（职改）部门视情况停止其工作，宣布评审结果无效，直至收回评审权或取消评委资格。 七、费  用"},{"i":22,"n":"第二十二条","txt":"资格评定按照勤俭节约的原则，合理收费。费用由申请人支付，并在申请评定的同时交纳。 收费标准要严格执行国家有关规定，由省、部级人事（职改）部门提出，报当地财政、计划（物价）部门审批。审批通过的收费标准应向社会公布，接受广大群众和有关部门的监督。收取费用只限于评定事务开支，不得挪作他用。 八、附  则"},{"i":23,"n":"第二十三条","txt":"本办法自发文之日起执行，由人事部负责解释。 附件一：关于组建高级评委会的授权办法 附件二：专业技术资格评定表（略） 附件三：专业评委会委员审定登记表（略） 附件四：专业副高级评委会备案登记表（略） 附件一： 关于组建高级评委会的授权办法 根据《专业技术资格评定试行办法》的规定，为规范评定组织，保证评定质量，现就组建高级专业技术资格评委会（下称评委会）的授权办法规定如下： 一、各专业高级专业技术资格评委会的授权工作，由人事部在征询有关主管部门意见的基础上，按照《专业技术资格评定试行办法》第八条，即授权地区必须同时具备的三个条件审核确定。为保证评审组织的权威性和规范性，人事部对组建高级专业技术资格评委会将建立严格的批准、备案制度，凡批准组建的正高级评委会均履行批复手续，对备案的副高级评委会正式函复，并予以公布。 二、具备聘请足够数量合格的评审委员，是申请组建相应评委会的前提，也是决定可否授"}],"zhonghuajinengdajianghequanguojishunengshoupingxua021b03":[{"i":1,"n":"第一条","txt":"为表彰和宣传各行各业优秀技术工人，促进广大劳动者提高技术技能，规范中华技能大奖（以下简称大奖）和全国技术能手（以下简称能手）评选表彰活动，根据《中华人民共和国劳动法》和国家有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"大奖和能手评选表彰是国家对全国优秀技术技能人才的奖励制度。劳动和社会保障部设全国技能人才评选表彰办公室，负责大奖和能手评选表彰活动的具体组织管理工作。 大奖和能手评选的职业（工种）范围为国家职业标准中设有高级（国家职业资格三级）以上等级的职业（工种）。 全国范围的评选表彰活动每两年开展一次，每次评选表彰人数由劳动和社会保障部确定。"},{"i":3,"n":"第三条","txt":"凡中华人民共和国公民，具有良好的职业道德和敬业精神，已获得省（行业）级技术能手称号，且具有高级以上职业资格或同等资格，技术技能水平在国内本职业（工种）中有较大影响，并具备下列条件之一的可参加能手的评选： （一）在本职业（工种）中具备较高技艺，并在培养徒弟，传授技术技能方面做出突出贡献的； （二）在开展技术革新、技术改造活动中做出重要贡献，取得重大经济效益和社会效益的； （三）在本企业、同行业中具有领先的技术技能水平，并在某一生产工作领域总结出先进的操作技术方法，取得重大经济效益和社会效益的； （四）在开发、应用先进科学技术成果转化成现实生产力方面有突出贡献，并取得重大经济效益和社会效益的。"},{"i":4,"n":"第四条","txt":"凡中华人民共和国公民，已获得能手称号，在本职业（工种）中的技术技能水平在国际国内有重要影响，并具备下列条件之一的可参加大奖的评选： （一）在技术创新、攻克技术难关等方面做出突出贡献，并总结出独特的操作技术方法，产生重大经济效益和社会效益的； （二）在本职业（工种）中，具备某种绝招绝技，并在带徒传艺方面做出突出贡献，在国际国内产生重要影响的； （三）在推广应用先进技术等方面做出突出贡献的。"},{"i":5,"n":"第五条","txt":"能手候选人由用人单位申报，省级人民政府劳动保障行政部门和国务院行业主管部门劳动保障工作机构按照分配名额推荐；大奖候选人由省级人民政府劳动保障行政部门和国务院行业主管部门劳动保障工作机构按照当年规定的推荐数额推荐。推荐能手和大奖候选人应提供申报表、事迹材料和经省级人民政府劳动保障行政部门或国务院行业主管部门劳动保障工作机构认定的证明材料。 省级人民政府劳动保障行政部门和国务院行业主管部门劳动保障工作机构推荐大奖和能手候选人时，少数民族和妇女应占一定比例。"},{"i":6,"n":"第六条","txt":"大奖和能手评选实行国家和省（行业）两级评审制。劳动和社会保障部设立全国专家评审委员会，省级人民政府劳动保障行政部门和国务院行业主管部门劳动保障工作机构设立本省（行业）专家评审委员会。评审委员会由有关工程技术人员、专业管理人员等组成，其中，工程技术人员所占比例为三分之二。"},{"i":7,"n":"第七条","txt":"省专家评审委员会负责本地区技术能手的评审工作，本地区向国家推荐大奖和能手候选人的初评审工作。 行业专家评审委员会负责本行业技术能手的评审工作，本行业向国家荐大奖和能手候选人的初评审及省推荐的同行业大奖候选人的复审工作。"},{"i":8,"n":"第八条","txt":"全国专家评审委员会负责对省（行业）初评审推荐的大奖和能手候选人终评审工作。 大奖和能手候选人由全国专家评审委员会委员评议表决，劳动和社会保障部批准。"},{"i":9,"n":"第九条","txt":"大奖和能手获得者可获得如下表彰和奖励： （一）由劳动和社会保障部授予大奖获得者和能手荣誉称号，进行表彰并颁发证书、奖章和奖金； （二）能手称号获得者原具有高级（国家职业资格三级）职业资格，且本职业（工种）设有技师以上资格的，由省级人民政府劳动保障行政部门按照管理权限认定技师资格；大奖获得者原具有技师资格，且本职业（工种）设有高级技师资格的，由省级人民政府劳动保障行政部门按照管理权限认定高级技师资格。"},{"i":10,"n":"第十条","txt":"评选表彰活动所需经费由各级劳动保障行政部门商由同级财政部门予以支持。"},{"i":11,"n":"第十一条","txt":"参加国家级和国际职业技能竞赛活动，获得相应名次者，可按照劳动和社会保障部有关规定直接授予能手称号。"},{"i":12,"n":"第十二条","txt":"省技能人才评选表彰具体办法，由省级人民政府劳动保障行政部门依照本办法制定。"},{"i":13,"n":"第十三条","txt":"本办法自颁布之日起施行。"}],"zhongwaihezuozhiyejinengpeixunbanxueguanlibanfa":[{"i":1,"n":"第一条","txt":"为实施《中华人民共和国中外合作办学条例》（以下简称《中外合作办学条例》），规范中外合作职业技能培训办学活动，制定本办法。"},{"i":2,"n":"第二条","txt":"中国教育机构同外国教育机构（以下简称中外合作办学者，教育机构含职业技能培训机构）合作举办职业技能培训机构和办学项目的设立、活动及管理，适用本办法。 本办法所称中外合作职业技能培训机构，是指中外合作办学者依照《中外合作办学条例》和本办法的规定，在中国境内合作举办的以中国公民为主要招生对象，实施职业技能培训的公益性办学机构。 本办法所称中外合作职业技能培训办学项目，是指中外合作办学者依照《中外合作办学条例》和本办法的规定，不设立新的职业技能培训机构，而是通过与现有中国教育机构合作设置以中国公民为主要招生对象的专业（职业、工种）、课程的方式开展的职业技能培训项目。"},{"i":3,"n":"第三条","txt":"国家鼓励根据经济发展和劳动力市场对技能劳动者的需求及特点，引进体现国外先进技术、先进培训方法的优质职业技能培训资源。 国家鼓励在国内新兴和急需的技能含量高的职业领域开展中外合作办学。"},{"i":4,"n":"第四条","txt":"中外合作职业技能培训机构根据法律法规的规定，享受国家给予民办学校的扶持与奖励政策。 劳动保障行政部门对发展中外合作职业技能培训办学做出突出贡献的社会组织和个人给予奖励和表彰。"},{"i":5,"n":"第五条","txt":"国务院劳动保障行政部门负责全国中外合作职业技能培训办学工作的统筹规划、综合协调和宏观管理。省、自治区、直辖市人民政府劳动保障行政部门负责本行政区域内中外合作职业技能培训办学管理工作。"},{"i":6,"n":"第六条","txt":"中外合作办学者应当符合《中外合作办学条例》规定的条件，具备相应的办学资格和较高的办学质量。"},{"i":7,"n":"第七条","txt":"中外合作办学者应当在平等协商的基础上签订合作协议。合作协议应当载明下列内容： （一）合作各方的名称、住所和法定代表人的姓名、职务、国籍； （二）拟设立的中外合作职业技能培训机构的名称、住所、培养目标、办学宗旨、合作内容和期限； （三）合作各方投入资产数额、方式及资金缴纳期限； （四）解决合作各方争议的方式和程序； （五）违反合作协议的责任； （六）合作各方约定的其他事项。 合作协议应当为中文文本。有外文文本的，应当与中文文本的内容一致。"},{"i":8,"n":"第八条","txt":"中外合作办学者投入的办学资金，应当与拟设立的中外合作职业技能培训机构的层次和规模相适应。 中外合作办学者应当按照合作协议按时、足额投入办学资金。中外合作职业技能培训机构存续期间，中外合作办学者不得抽逃办学资金，不得挪用办学经费。"},{"i":9,"n":"第九条","txt":"中外合作办学者为办学投入的实物、土地使用权、知识产权以及其他财产，其作价由中外合作办学者双方按照公平合理的原则协商确定，或者聘请双方同意的社会中介组织依法进行评估，并依法办理财产权转移有关手续。 中国教育机构以国有资产作为办学投入的，应当根据国家有关国有资产监督管理规定，聘请具有评估资格的社会中介组织依法进行评估，根据评估结果合理确定国有资产的数额，并报对该国有资产负有监管职责的机构备案，依法履行国有资产管理义务。"},{"i":10,"n":"第十条","txt":"根据与外国政府部门签订的协议或者应中国教育机构的请求，国务院劳动保障行政部门或者省、自治区、直辖市人民政府可以邀请外国教育机构与中国教育机构合作办学。 被邀请的外国教育机构应当是国际上或者所在国具有一定影响力的教育机构。"},{"i":11,"n":"第十一条","txt":"设立中外合作职业技能培训机构由拟设立机构所在地的省、自治区、直辖市人民政府劳动保障行政部门审批。"},{"i":12,"n":"第十二条","txt":"设立中外合作职业技能培训机构，分为筹备设立和正式设立两个步骤。具备办学条件，达到设置标准的，可以直接申请正式设立。"},{"i":13,"n":"第十三条","txt":"申请筹备设立中外合作职业技能培训机构，应当由中国教育机构提出申请，提交《中外合作办学条例》规定的文件。其中申办报告应当按照国务院劳动保障行政部门根据《中外合作办学条例》第十四条第（一）项制定的《中外合作职业技能培训机构申请表》所规定的内容和格式填写。 申请筹备设立中外合作职业技能培训机构，还应根据《中外合作办学条例》有关条款的规定，提交中外合作办学者的注册登记证明、法定代表人的有效证明文件，其中外国合作办学者的有关证明文件应当经所在国公证机关证明。"},{"i":14,"n":"第十四条","txt":"有下列情形之一的，审批机关不予批准筹备设立中外合作职业技能培训机构，并书面说明理由： （一）违背社会公共利益、历史文化传统和职业培训的公益性质，不符合国家或者地方职业培训事业发展需要的； （二）中外合作办学者有一方不符合条件的； （三）申请文件不符合《中外合作办学条例》和本办法要求，经告知仍不改正的； （四）申请文件有虚假内容的； （五）法律、行政法规规定的其他不予批准情形。"},{"i":15,"n":"第十五条","txt":"申请正式设立中外合作职业技能培训机构，应当由中国教育机构申请，提交《中外合作办学条例》规定的文件。其中直接申请正式设立的，正式设立申请书应当按照国务院劳动保障行政部门制定的《中外合作职业技能培训机构申请表》所规定的内容和格式填写，并提交本办法第十三条第二款规定的资格证明。"},{"i":16,"n":"第十六条","txt":"正式设立中外合作职业技能培训机构，应当具备《中外合作办学条例》第十一条规定的条件。 设立中外合作职业技能培训机构，应达到以下设置标准： （一）具有同时培训不少于200人的办学规模； （二）办学场所应符合环境保护、劳动保护、安全、消防、卫生等有关规定及相关职业（工种）安全规程。建筑面积应与其办学规模相适应，一般不少于3000平方米，其中实习、实验场所一般不少于1000平方米。租用的场所其租赁期限不少于3年； （三）实习、实验设施和设备应满足教学和技能训练需要，有充足的实习工位，主要设备应达到国际先进水平。具有不少于5000册的图书资料和必要的阅览场所，并配备电子阅览设备； （四）投入的办学资金，应当与办学层次和规模相适应，并具有稳定的经费来源； （五）校长或主要行政负责人应具有中华人民共和国国籍，在中国境内定居，热爱祖国、品行良好，具备大学本科及以上学历或者高级专业技术职务任职资格、高级"},{"i":17,"n":"第十七条","txt":"设立中外合作职业技能培训机构应当按照《中外合作办学条例》的规定制定机构章程，载明下列事项： （一）中外合作职业技能培训机构的名称、住所； （二）办学宗旨、规模、层次、类别等； （三）资产数额、来源、性质以及财务制度； （四）中外合作办学者是否要求取得合理回报； （五）理事会或者董事会的产生方法、人员构成、权限、任期、议事规则等； （六）法定代表人的产生和罢免程序； （七）民主管理和监督的形式； （八）机构终止事由、程序和清算办法； （九）章程修改程序； （十）其他需要由章程规定的事项。"},{"i":18,"n":"第十八条","txt":"中外合作职业技能培训机构只能使用一个名称，其外文译名应当与中文名称相符。中外合作职业技能培训机构名称应当按所在行政区划、字号、职业技能培训学校依次确切表示。 名称中不得冠以“中国”、“全国”、“中华”等字样，不得违反国家规定，不得损害社会公共利益。"},{"i":19,"n":"第十九条","txt":"中外合作职业技能培训机构不得设立分支机构，不得举办其他中外合作办学机构。"},{"i":20,"n":"第二十条","txt":"审批机关受理正式设立中外合作技工学校的，应当组织专家委员会评议，由专家委员会提出咨询意见。 专家委员会对申请人申请材料按照分期分类的原则进行评审，所需时间由审批机关书面告知申请人，不计算在审批期限内。 审批机关认为必要时应当指派2名以上工作人员，对申请人提交的申请材料主要内容进行核查。"},{"i":21,"n":"第二十一条","txt":"有下列情形之一的，审批机关不予批准正式设立中外合作职业技能培训机构，并书面说明理由： （一）不具备办学条件、未达到设置标准的； （二）理事会、董事会的组成人员及其构成不符合法定要求，校长或者主要行政负责人、教师、财会人员不具备法定资格，经告知仍不改正的； （三）章程不符合《中外合作办学条例》和本办法要求，经告知仍不修改的； （四）在筹备设立期内有违反法律、法规行为的。 直接申请正式设立中外合作职业技能培训机构的，除前款规定的第（一）、（二）、（三）项外，有本办法第十四条规定情形之一的，审批机关不予批准。"},{"i":22,"n":"第二十二条","txt":"批准正式设立中外合作职业技能培训机构的，由该审批机关颁发国务院劳动保障行政部门统一印制、国务院教育行政部门统一编号的中外合作办学许可证。"},{"i":23,"n":"第二十三条","txt":"中外合作职业技能培训机构遗失中外合作办学许可证的，应立即登报声明，并持声明向审批机关提交补办申请，由审批机关核准后补发。"},{"i":24,"n":"第二十四条","txt":"举办中外合作职业技能培训办学项目，应当具备下列条件： （一）中外合作办学者应当具有法人资格； （二）项目的办学层次和类别与中外合作办学者的办学层次和类别相适应； （三）中国教育机构应当具备举办所开设专业（职业、工种）培训的师资、设备、设施等条件。"},{"i":25,"n":"第二十五条","txt":"举办中外合作职业技能培训办学项目，中外合作办学者应当签订合作协议，载明下列内容： （一）合作各方的名称、住所和法定代表人的姓名、职务、国籍； （二）合作项目名称、合作内容和期限； （三）合作各方投入资产数额、方式及资金缴纳期限（有资产、资金投入的）； （四）解决合作各方争议的方式和程序； （五）违反合作协议的责任； （六）合作各方约定的其他事项。 合作协议应当为中文文本。有外文文本的，应当与中文文本的内容一致。"},{"i":26,"n":"第二十六条","txt":"申请举办中外合作职业技能培训办学项目，由拟举办项目所在地的省、自治区、直辖市人民政府劳动保障行政部门审批，并报国务院劳动保障行政部门备案。"},{"i":27,"n":"第二十七条","txt":"举办中外合作职业技能培训办学项目，应当由中国教育机构提出申请，提交下列文件： （一）《中外合作职业技能培训办学项目申请表》； （二）合作协议； （三）经公证的中外合作办学者法人资格证明； （四）捐赠资产协议及相关证明（有捐赠的）。"},{"i":28,"n":"第二十八条","txt":"审批机关受理申请后应当在30个工作日内作出是否批准举办中外合作职业技能培训办学项目的决定。有下列情形之一的，审批机关不予批准举办中外合作职业技能培训办学项目，并书面说明理由： （一）违背社会公共利益、历史文化传统和职业培训的公益性质，不符合国家或者地方职业培训事业发展需要的； （二）中外合作办学者有一方不符合条件的； （三）申请文件不符合本办法要求，经告知仍不改正的； （四）申请文件有虚假内容的； （五）法律、行政法规规定的其他不予批准情形。"},{"i":29,"n":"第二十九条","txt":"批准中外合作职业技能培训办学项目的，由审批机关颁发统一格式、统一编号的中外合作办学项目批准书。 中外合作办学项目批准书由国务院劳动保障行政部门制定式样并统一编号。"},{"i":30,"n":"第三十条","txt":"中外合作职业技能培训机构应当建立学籍和教学管理、教师管理、学生管理、卫生安全管理、设备管理、财务资产管理等项制度。"},{"i":31,"n":"第三十一条","txt":"中外合作职业技能培训机构应当依照《中外合作办学条例》的规定设立理事会、董事会。国家机关工作人员不得担任中外合作职业技能培训机构的理事会或者董事会成员。"},{"i":32,"n":"第三十二条","txt":"中外合作职业技能培训机构应当聘任专职校长或者主要行政负责人。校长或者主要行政负责人依法独立行使教育教学和行政管理职权。 中外合作职业技能培训机构应当配备具有大学本科及以上学历及一定的外语交流能力，并具有中级及以上相关专业技术职务任职资格的专职教学管理人员。"},{"i":33,"n":"第三十三条","txt":"中外合作职业技能培训办学项目是举办该项目的中国教育机构教育教学活动的组成部分，应当接受举办该项目的中国教育机构的管理。"},{"i":34,"n":"第三十四条","txt":"中外合作职业技能培训机构和办学项目按照办学宗旨、培养目标和批准的专业（职业、工种）设置范围，自行设置专业（职业、工种），开展教育培训活动，但不得开展《中外合作办学条例》禁止的办学活动。 中外合作职业技能培训机构和办学项目可以在中国境内实施职业技能培训活动，也可以在中国境外实施部分职业技能培训活动。"},{"i":35,"n":"第三十五条","txt":"中外合作职业技能培训机构和办学项目依法自主确定招生范围、标准和方式。但实施技工学校教育的，应当按照国家有关规定执行。"},{"i":36,"n":"第三十六条","txt":"中外合作职业技能培训机构和办学项目应当按照招生简章或者与受培训者签订的培训协议，开设相应课程，开展职业技能培训，保证培训质量。 中外合作职业技能培训机构和办学项目应当提供与所设专业（职业、工种）相匹配的教育教学设施、设备和其他必要的办学条件。"},{"i":37,"n":"第三十七条","txt":"中外合作职业技能培训机构和办学项目按照国家有关规定颁发培训证书或者结业证书。接受职业技能培训的学生，经政府批准的职业技能鉴定机构鉴定合格，可以按照国家有关规定获得相应的国家职业资格证书。"},{"i":38,"n":"第三十八条","txt":"中外合作职业技能培训机构依法自主管理和使用本机构的资产，但不得改变按照公益事业获得的土地、校舍等资产的用途。"},{"i":39,"n":"第三十九条","txt":"举办中外合作职业技能培训办学项目的中国教育机构应当依法对中外合作职业技能培训办学项目的财务进行管理，并在学校财务账户内设立中外合作职业技能培训办学项目专项，统一办理收支业务。"},{"i":40,"n":"第四十条","txt":"中外合作职业技能培训机构和办学项目不得从事营利性经营活动。"},{"i":41,"n":"第四十一条","txt":"中外合作办学者要求取得合理回报的，应当按照《中华人民共和国民办教育促进法实施条例》的规定执行。 中外合作职业技能培训机构有《中华人民共和国民办教育促进法实施条例》第四十七条列举情形之一的，中外合作办学者不得取得回报。 中外合作职业技能培训机构应当按照《中华人民共和国民办教育促进法实施条例》第三十七条的规定提取、使用发展基金。"},{"i":42,"n":"第四十二条","txt":"中外合作职业技能培训办学项目的收费项目和标准，按照国家有关政府定价的规定确定并公布。 中外合作职业技能培训办学项目的办学结余，应当继续用于项目的教育教学活动和改善办学条件。"},{"i":43,"n":"第四十三条","txt":"有下列情形之一的，中外合作职业技能培训办学项目终止： （一）根据合作协议要求终止，并经审批机关批准的； （二）中外合作办学者有一方被依法吊销办学资格的； （三）被吊销中外合作办学项目批准书的。 中外合作职业技能培训办学项目终止，应当妥善安置在校学生；举办该项目的中国教育机构提出项目终止申请时，应当同时提交妥善安置在校学生的方案。 中外合作职业技能培训办学项目终止的，举办该项目的中国教育机构应当将中外合作办学项目批准书交回审批机关，由审批机关依法注销并向社会公布。"},{"i":44,"n":"第四十四条","txt":"劳动保障行政部门应当加强对中外合作职业技能培训机构和办学项目的监督，组织或委托社会中介组织对中外合作职业技能培训机构和办学项目的办学水平和教育培训质量，进行定期综合性评估和专项评估，并将评估结果向社会公布。"},{"i":45,"n":"第四十五条","txt":"中外合作职业技能培训机构和举办中外合作职业技能培训办学项目的中国教育机构应当于每年3月31日前向审批机关提交年度办学报告，内容应当包括中外合作职业技能培训机构和办学项目招收学生、培训专业（职业、工种）、培训期限、师资配备、教学质量、证书发放、财务状况等基本情况。"},{"i":46,"n":"第四十六条","txt":"中外合作职业技能培训机构应当依照《中华人民共和国会计法》和国家统一的会计制度进行会计核算，编制财务会计报告，于会计年度结束之日起1个月内向社会公布社会审计机构对其年度财务会计报告的审计结果，并报审批机关备案。"},{"i":47,"n":"第四十七条","txt":"中外合作职业技能培训机构和办学项目应当具有与专业（职业、工种）设置相对应的教学计划、大纲和教材。自编和从境外引进教学计划、大纲和教材应当符合法律法规规定，并报审批机关备案。"},{"i":48,"n":"第四十八条","txt":"中外合作职业技能培训机构和办学项目的招生简章和广告样本应当自发布之日起5日内报审批机关备案。招生简章和广告应当依法如实发布机构和项目的名称、培训目标、培训层次、主要课程、培训条件、培训期限、收费项目、收费标准、证书发放和就业去向等。"},{"i":49,"n":"第四十九条","txt":"中外合作职业技能培训办学项目审批机关及其工作人员，利用职务上的便利收取他人财物或者获取其他利益，滥用职权、玩忽职守，对不符合本办法规定条件者颁发中外合作办学项目批准书的，对直接负责的主管人员和其他直接责任人员依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":50,"n":"第五十条","txt":"违反本办法的规定，超越职权审批中外合作职业技能培训办学项目的，其批准文件无效，对直接负责的主管人员和其他直接责任人员，依法给予行政处分；致使公共财产、国家和人民利益遭受重大损失，构成犯罪的，依法追究刑事责任。"},{"i":51,"n":"第五十一条","txt":"中外合作职业技能培训机构违反本办法有关组织与活动的规定，导致管理混乱、教育教学质量低下，造成恶劣影响的，按照《中外合作办学条例》第五十六条规定追究法律责任。"},{"i":52,"n":"第五十二条","txt":"违反本办法的规定，未经批准擅自举办中外合作职业技能培训办学项目，或者以不正当手段骗取中外合作办学项目批准书的，由劳动保障行政部门责令举办该项目的中国教育机构限期改正、退还向学生收取的费用，并处以1万元以下罚款。"},{"i":53,"n":"第五十三条","txt":"中外合作职业技能培训办学项目未经批准增加收费项目或者提高收费标准的，由劳动保障行政部门责令举办该项目的中国教育机构退还多收的费用，并提请价格主管部门依照有关法律、行政法规的规定予以处罚。"},{"i":54,"n":"第五十四条","txt":"中外合作职业技能培训办学项目发布虚假招生简章或者招生广告，骗取钱财的，由劳动保障行政部门责令举办该项目的中国教育机构退还收取的费用后，没收剩余违法所得，并处以违法所得3倍以下且总额3万元以下的罚款。"},{"i":55,"n":"第五十五条","txt":"中外合作职业技能培训办学项目有下列情形之一的，由劳动保障行政部门责令举办该项目的中国教育机构限期改正： （一）超出审批范围、层次办学的； （二）管理混乱，教育教学质量低下的； （三）未按照国家有关规定进行财务管理的； （四）违反规定对办学结余进行分配的。"},{"i":56,"n":"第五十六条","txt":"香港特别行政区、澳门特别行政区和台湾地区的教育机构与内地教育机构合作举办职业技能培训机构或者办学项目的，参照本办法执行，国家另有规定的除外。"},{"i":57,"n":"第五十七条","txt":"在工商行政管理部门登记注册的经营性的中外合作职业技能培训机构的管理办法，按照国务院规定执行。"},{"i":58,"n":"第五十八条","txt":"外国教育机构、其他组织或者个人不得在中国境内单独设立以中国公民为主要招生对象的职业技能培训机构。"},{"i":59,"n":"第五十九条","txt":"本办法实施前已经批准举办的中外合作职业技能培训办学项目，应当补办本办法规定的中外合作办学项目批准书。其中，不完全具备本办法规定的中外合作职业技能培训办学项目举办条件的，应当在本办法施行之日起1年内达到本办法规定的条件。逾期未达到本办法规定条件的，审批机关不予补办中外合作办学项目批准书。"},{"i":60,"n":"第六十条","txt":"本办法自2006年10月1日起施行。"}],"shiyedanweigongkaizhaopinrenyuanzanxingguiding":[{"i":1,"n":"第一条","txt":"为实现事业单位人事管理的科学化、制度化和规范化，规范事业单位招聘行为，提高人员素质，制定本规定。"},{"i":2,"n":"第二条","txt":"事业单位招聘专业技术人员、管理人员和工勤人员，适用本规定。参照公务员制度进行管理和转为企业的事业单位除外。 事业单位新进人员除国家政策性安置、按干部人事管理权限由上级任命及涉密岗位等确需使用其他方法选拔任用人员外，都要实行公开招聘。"},{"i":3,"n":"第三条","txt":"公开招聘要坚持德才兼备的用人标准，贯彻公开、平等、竞争、择优的原则。"},{"i":4,"n":"第四条","txt":"公开招聘要坚持政府宏观管理与落实单位用人自主权相结合，统一规范、分类指导、分级管理。"},{"i":5,"n":"第五条","txt":"公开招聘由用人单位根据招聘岗位的任职条件及要求，采取考试、考核的方法进行。"},{"i":6,"n":"第六条","txt":"政府人事行政部门是政府所属事业单位进行公开招聘工作的主管机关。政府人事行政部门与事业单位的上级主管部门负责对事业单位公开招聘工作进行指导、监督和管理。"},{"i":7,"n":"第七条","txt":"事业单位可以成立由本单位人事部门、纪检监察部门、职工代表及有关专家组成的招聘工作组织，负责招聘工作的具体实施。"},{"i":8,"n":"第八条","txt":"事业单位招聘人员应当面向社会，凡符合条件的各类人员均可报名应聘。"},{"i":9,"n":"第九条","txt":"应聘人员必须具备下列条件： （一）具有中华人民共和国国籍； （二）遵守宪法和法律； （三）具有良好的品行； （四）岗位所需的专业或技能条件； （五）适应岗位要求的身体条件； （六）岗位所需要的其他条件。"},{"i":10,"n":"第十条","txt":"事业单位公开招聘人员，不得设置歧视性条件要求。"},{"i":11,"n":"第十一条","txt":"公开招聘应按下列程序进行： （一）制定招聘计划； （二）发布招聘信息； （三）受理应聘人员的申请，对资格条件进行审查； （四）考试、考核； （五）身体检查； （六）根据考试、考核结果，确定拟聘人员； （七）公示招聘结果； （八）签订聘用合同，办理聘用手续。"},{"i":12,"n":"第十二条","txt":"招聘计划由用人单位负责编制，主要包括以下内容：招聘的岗位及条件、招聘的时间、招聘人员的数量、采用的招聘方式等。"},{"i":13,"n":"第十三条","txt":"国务院直属事业单位的年度招聘计划须报人事部备案；国务院各部委直属事业单位的招聘计划须报上级主管部门核准并报人事部备案。 各省、自治区、直辖市人民政府直属事业单位的招聘计划须报省（区、市）政府人事行政部门备案；各省、自治区、直辖市政府部门直属事业单位的招聘计划须报上级主管部门核准并报同级政府人事行政部门备案。 地（市）、县（市）人民政府所属事业单位的招聘计划须报地区或设区的市政府人事行政部门核准。"},{"i":14,"n":"第十四条","txt":"事业单位招聘人员应当公开发布招聘信息，招聘信息应当载明用人单位情况简介、招聘的岗位、招聘人员数量及待遇；应聘人员条件；招聘办法；考试、考核的时间（时限）、内容、范围；报名方法等需要说明的事项。"},{"i":15,"n":"第十五条","txt":"用人单位或组织招聘的部门应对应聘人员的资格条件进行审查，确定符合条件的人员。"},{"i":16,"n":"第十六条","txt":"考试内容应为招聘岗位所必需的专业知识、业务能力和工作技能。"},{"i":17,"n":"第十七条","txt":"考试科目与方式根据行业、专业及岗位特点确定。"},{"i":18,"n":"第十八条","txt":"考试可采取笔试、面试等多种方式。 对于应聘工勤岗位的人员，可根据需要重点进行实际操作能力测试。"},{"i":19,"n":"第十九条","txt":"考试由事业单位自行组织，也可以由政府人事行政部门、事业单位上级主管部门统一组织。 政府人事行政部门所属考试服务机构和人才服务机构可受事业单位、政府人事行政部门或事业单位上级主管部门委托，为事业单位公开招聘人员提供服务。"},{"i":20,"n":"第二十条","txt":"急需引进的高层次、短缺专业人才，具有高级专业技术职务或博士学位的人员，可以采取直接考核的方式招聘。"},{"i":21,"n":"第二十一条","txt":"对通过考试的应聘人员，用人单位应组织对其思想政治表现、道德品质、业务能力、工作实绩等情况进行考核，并对应聘人员资格条件进行复查。"},{"i":22,"n":"第二十二条","txt":"经用人单位负责人员集体研究，按照考试和考核结果择优确定拟聘人员。"},{"i":23,"n":"第二十三条","txt":"对拟聘人员应在适当范围进行公示，公示期一般为7至15日。"},{"i":24,"n":"第二十四条","txt":"用人单位与拟聘人员签订聘用合同前，按照干部人事管理权限的规定报批或备案。"},{"i":25,"n":"第二十五条","txt":"用人单位法定代表人或者其委托人与受聘人员签订聘用合同，确立人事关系。"},{"i":26,"n":"第二十六条","txt":"事业单位公开招聘的人员按规定实行试用期制度。试用期包括在聘用合同期限内。 试用期满合格的，予以正式聘用；不合格的，取消聘用。"},{"i":27,"n":"第二十七条","txt":"事业单位公开招聘人员实行回避制度。 凡与聘用单位负责人员有夫妻关系、直系血亲关系、三代以内旁系血亲或者近姻亲关系的应聘人员，不得应聘该单位负责人员的秘书或者人事、财务、纪律检查岗位，以及有直接上下级领导关系的岗位。 聘用单位负责人员和招聘工作人员在办理人员聘用事项时，涉及与本人有上述亲属关系或者其他可能影响招聘公正的，也应当回避。"},{"i":28,"n":"第二十八条","txt":"招聘工作要做到信息公开、过程公开、结果公开，接受社会及有关部门的监督。"},{"i":29,"n":"第二十九条","txt":"政府人事行政部门和事业单位的上级主管部门要认真履行监管职责，对事业单位招聘过程中违反干部人事纪律及本规定的行为要予以制止和纠正，保证招聘工作的公开、公平、公正。"},{"i":30,"n":"第三十条","txt":"严格公开招聘纪律。对有下列违反本规定情形的，必须严肃处理。构成犯罪的，依法追究刑事责任。 （一）应聘人员伪造、涂改证件、证明，或以其他不正当手段获取应聘资格的； （二）应聘人员在考试考核过程中作弊的； （三）招聘工作人员指使、纵容他人作弊，或在考试考核过程中参与作弊的； （四）招聘工作人员故意泄露考试题目的； （五）事业单位负责人员违反规定私自聘用人员的； （六）政府人事行政部门、事业单位主管部门工作人员违反规定，影响招聘公平、公正进行的； （七）违反本规定的其他情形的。"},{"i":31,"n":"第三十一条","txt":"对违反公开招聘纪律的应聘人员，视情节轻重取消考试或聘用资格；对违反本规定招聘的受聘人员，一经查实，应当解除聘用合同，予以清退。"},{"i":32,"n":"第三十二条","txt":"对违反公开招聘纪律的工作人员，视情节轻重调离招聘工作岗位或给予处分；对违反公开招聘纪律的其他相关人员，按照有关规定追究责任。"},{"i":33,"n":"第三十三条","txt":"事业单位需要招聘外国国籍人员的，须报省级以上政府人事行政部门核准，并按照国家有关规定进行招聘。"},{"i":34,"n":"第三十四条","txt":"省、自治区、直辖市政府人事行政部门可以根据本规定，制定本地区的公开招聘办法。"},{"i":35,"n":"第三十五条","txt":"本规定自2006年1月1日起执行。"}],"shiyedanweigongkaizhaopinweijiweiguixingweichuligu3d50f4":[{"i":1,"n":"第一条","txt":"为加强事业单位公开招聘工作管理，规范公开招聘违纪违规行为的认定与处理，保证招聘工作公开、公平、公正，根据《事业单位人事管理条例》等有关规定，制定本规定。"},{"i":2,"n":"第二条","txt":"事业单位公开招聘中违纪违规行为的认定与处理，适用本规定。"},{"i":3,"n":"第三条","txt":"认定与处理公开招聘违纪违规行为，应当事实清楚、证据确凿、程序规范、适用规定准确。"},{"i":4,"n":"第四条","txt":"中央事业单位人事综合管理部门负责全国事业单位公开招聘工作的综合管理与监督。 各级事业单位人事综合管理部门、事业单位主管部门、招聘单位按照事业单位公开招聘管理权限，依据本规定对公开招聘违纪违规行为进行认定与处理。"},{"i":5,"n":"第五条","txt":"应聘人员在报名过程中有下列违纪违规行为之一的，取消其本次应聘资格： （一）伪造、涂改证件、证明等报名材料，或者以其他不正当手段获取应聘资格的； （二）提供的涉及报考资格的申请材料或者信息不实，且影响报名审核结果的； （三）其他应当取消其本次应聘资格的违纪违规行为。"},{"i":6,"n":"第六条","txt":"应聘人员在考试过程中有下列违纪违规行为之一的，给予其当次该科目考试成绩无效的处理： （一）携带规定以外的物品进入考场且未按要求放在指定位置，经提醒仍不改正的； （二）未在规定座位参加考试，或者未经考试工作人员允许擅自离开座位或者考场，经提醒仍不改正的； （三）经提醒仍不按规定填写、填涂本人信息的； （四）在试卷、答题纸、答题卡规定以外位置标注本人信息或者其他特殊标记的； （五）在考试开始信号发出前答题，或者在考试结束信号发出后继续答题，经提醒仍不停止的； （六）将试卷、答题卡、答题纸带出考场，或者故意损坏试卷、答题卡、答题纸及考试相关设施设备的； （七）其他应当给予当次该科目考试成绩无效处理的违纪违规行为。"},{"i":7,"n":"第七条","txt":"应聘人员在考试过程中有下列严重违纪违规行为之一的，给予其当次全部科目考试成绩无效的处理，并将其违纪违规行为记入事业单位公开招聘应聘人员诚信档案库，记录期限为五年： （一）抄袭、协助他人抄袭的； （二）互相传递试卷、答题纸、答题卡、草稿纸等的； （三）持伪造证件参加考试的； （四）使用禁止带入考场的通讯工具、规定以外的电子用品的； （五）本人离开考场后，在本场考试结束前，传播考试试题及答案的； （六）其他应当给予当次全部科目考试成绩无效处理并记入事业单位公开招聘应聘人员诚信档案库的严重违纪违规行为。"},{"i":8,"n":"第八条","txt":"应聘人员有下列特别严重违纪违规行为之一的，给予其当次全部科目考试成绩无效的处理，并将其违纪违规行为记入事业单位公开招聘应聘人员诚信档案库，长期记录： （一）串通作弊或者参与有组织作弊的； （二）代替他人或者让他人代替自己参加考试的； （三）其他应当给予当次全部科目考试成绩无效处理并记入事业单位公开招聘应聘人员诚信档案库的特别严重的违纪违规行为。"},{"i":9,"n":"第九条","txt":"应聘人员应当自觉维护招聘工作秩序，服从工作人员管理，有下列行为之一的，终止其继续参加考试，并责令离开现场；情节严重的，按照本规定第七条、第八条的规定处理；违反《中华人民共和国治安管理处罚法》的，交由公安机关依法处理；构成犯罪的，依法追究刑事责任： （一）故意扰乱考点、考场以及其他招聘工作场所秩序的； （二）拒绝、妨碍工作人员履行管理职责的； （三）威胁、侮辱、诽谤、诬陷工作人员或者其他应聘人员的； （四）其他扰乱招聘工作秩序的违纪违规行为。"},{"i":10,"n":"第十条","txt":"在阅卷过程中发现应聘人员之间同一科目作答内容雷同，并经阅卷专家组确认的，给予其当次该科目考试成绩无效的处理。作答内容雷同的具体认定方法和标准，由中央事业单位人事综合管理部门确定。 应聘人员之间同一科目作答内容雷同，并有其他相关证据证明其违纪违规行为成立的，视具体情形按照本规定第七条、第八条处理。"},{"i":11,"n":"第十一条","txt":"应聘人员在体检过程中弄虚作假或者隐瞒影响聘用的疾病、病史的，给予其不予聘用的处理。有请他人顶替体检以及交换、替换化验样本等严重违纪违规行为的，给予其不予聘用的处理，并将其违纪违规行为记入事业单位公开招聘应聘人员诚信档案库，记录期限为五年。"},{"i":12,"n":"第十二条","txt":"应聘人员在考察过程中提供虚假材料、隐瞒事实真相或者有其他妨碍考察工作的行为，干扰、影响考察单位客观公正作出考察结论的，给予其不予聘用的处理；情节严重、影响恶劣的，将其违纪违规行为记入事业单位公开招聘应聘人员诚信档案库，记录期限为五年。"},{"i":13,"n":"第十三条","txt":"应聘人员聘用后被查明有本规定所列违纪违规行为的，由招聘单位与其解除聘用合同、予以清退，其中符合第七条、第八条、第十一条、第十二条违纪违规行为的，记入事业单位公开招聘应聘人员诚信档案库。"},{"i":14,"n":"第十四条","txt":"事业单位公开招聘应聘人员诚信档案库由中央事业单位人事综合管理部门统一建立，纳入全国信用信息共享平台，向招聘单位及社会提供查询，相关记录作为事业单位聘用人员的重要参考，管理办法另行制定。"},{"i":15,"n":"第十五条","txt":"招聘单位在公开招聘中有下列行为之一的，事业单位主管部门或者事业单位人事综合管理部门应当责令限期改正；逾期不改正的，对直接负责的主管人员和其他直接责任人员依法给予处分： （一）未按规定权限和程序核准（备案）招聘方案，擅自组织公开招聘的； （二）设置与岗位无关的指向性或者限制性条件的； （三）未按规定发布招聘公告的； （四）招聘公告发布后，擅自变更招聘程序、岗位条件、招聘人数、考试考察方式等的； （五）未按招聘条件进行资格审查的； （六）未按规定组织体检的； （七）未按规定公示拟聘用人员名单的； （八）其他应当责令改正的违纪违规行为。"},{"i":16,"n":"第十六条","txt":"招聘工作人员有下列行为之一的，由相关部门给予处分，并停止其继续参加当年及下一年度招聘工作： （一）擅自提前考试开始时间、推迟考试结束时间及缩短考试时间的； （二）擅自为应聘人员调换考场或者座位的； （三）未准确记录考场情况及违纪违规行为，并造成一定影响的； （四）未执行回避制度的； （五）其他一般违纪违规行为。"},{"i":17,"n":"第十七条","txt":"招聘工作人员有下列行为之一的，由相关部门给予处分，并将其调离招聘工作岗位，不得再从事招聘工作；构成犯罪的，依法追究刑事责任： （一）指使、纵容他人作弊，或者在考试、考察、体检过程中参与作弊的； （二）在保密期限内，泄露考试试题、面试评分要素等应当保密的信息的； （三）擅自更改考试评分标准或者不按评分标准进行评卷的； （四）监管不严，导致考场出现大面积作弊现象的； （五）玩忽职守，造成不良影响的； （六）其他严重违纪违规行为。"},{"i":18,"n":"第十八条","txt":"应聘人员的违纪违规行为被当场发现的，招聘工作人员应当予以制止。对于被认定为违纪违规的，要收集、保存相应证据材料，如实记录违纪违规事实和现场处理情况，当场告知应聘人员记录内容，并要求本人签字；对于拒绝签字或者恶意损坏证据材料的，由两名招聘工作人员如实记录其拒签或者恶意损坏证据材料的情况。违纪违规记录经考点负责人签字认定后，报送组织实施公开招聘的部门。"},{"i":19,"n":"第十九条","txt":"对应聘人员违纪违规行为作出处理决定前，应当告知应聘人员拟作出的处理决定及相关事实、理由和依据，并告知应聘人员依法享有陈述和申辩的权利。作出处理决定的部门对应聘人员提出的事实、理由和证据，应当进行复核。 对应聘人员违纪违规行为作出处理决定的，应当制作公开招聘违纪违规行为处理决定书，依法送达被处理的应聘人员。"},{"i":20,"n":"第二十条","txt":"应聘人员对处理决定不服的，可以依法申请行政复议或者提起行政诉讼。"},{"i":21,"n":"第二十一条","txt":"参与公开招聘的工作人员对因违纪违规行为受到处分不服的，可以依法申请复核或者提出申诉。"},{"i":22,"n":"第二十二条","txt":"本规定自2018年1月1日起施行。"}],"renshibuguanyugaijinguowuyuangebumencongbeijingwai4d8a14":[{"i":1,"n":"第一条","txt":"国务院各部委、各直属机构及所属在京单位因工作需要从京外选调人员，解决干部夫妻两地分居从京外调入人员，解决老干部身边无子女从京外调入子女，离休干部回京安置，干部家属“农转非”以及接收应届中专以上非北京生源毕业生，由人事部归口管理。 上述人员调(迁)入京，由报人事部审批改为在人事部宏观管理下由国务院各部委、各直属机构审批。人事部负责政策制定、指标管理、监督检查和协调服务工作。"},{"i":2,"n":"第二条","txt":"从京外调(迁)入人员按如下程序办理： 国务院各部委、各直属机构因工作需要从京外选调人员、接收应届中专以上非北京生源毕业生、解决老干部身边无子女从京外调入子女、离休干部回京安置须按年度向人事部申请指标。人事部根据其编制、人员结构、专业特点和实际需要，本着从严控制的精神，按年度分别下达指标。国务院各部委、各直属机构在指标控制数内根据国家政策审批这些人员调(迁)入京的报文，报人事部备案。 国务院各部委、各直属机构解决干部家属“农转非”须按年度向人事部申请指标。人事部在国家计委下达的“农转非”计划内，根据各单位符合“农转非”政策的人数及有关情况，向国务院各部委、各直属机构下达“农转非”指标。国务院各部委、各直属机构根据国家关于干部家属“农转非”政策和年度指标审批“农转非”报文，报人事部备案。 国务院各部委、各直属机构根据人事部关于解决干部夫妻两地分居政策和本部门调出北京干部的户口指标，审批干部"},{"i":3,"n":"第三条","txt":"全国人大常委会办公厅、全国政协办公厅、最高人民法院、最高人民检察院从京外调(迁)入本《暂行规定》第一条所列各类人员也由人事部归口管理，并适用本《暂行规定》第二条。"},{"i":4,"n":"第四条","txt":"从京外调(迁)入有关人员的条件、随调随迁人员等政策仍按《人事部关于国务院各部门从京外调入干部审批工作有关问题的通知》(人调发(1991)12号)、《人事部关于国务院各部委、各直属机构在京事业、企业单位接收应届中专以上毕业生问题的通知》(人调发(1989)9号)等规定执行。"},{"i":5,"n":"第五条","txt":"各部门在办理审批工作中，应严格执行党和国家的有关政策和规定，对于弄虚作假、搞不正之风的行为，调动无效，并追究有关人员的责任，中止有关部门进京审批权限半年至一年。"},{"i":6,"n":"第六条","txt":"本暂行规定自发出之日起执行，以前有关规定凡与本暂行规定不符的，以本暂行规定为准。"},{"i":7,"n":"第七条","txt":"本暂行规定由人事部负责解释。"}],"renliziyuanfuwujigouguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强对人力资源服务机构的管理，规范人力资源服务活动，健全统一开放、竞争有序的人力资源市场体系，促进高质量充分就业和优化人力资源流动配置，根据《中华人民共和国就业促进法》《人力资源市场暂行条例》等法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内的人力资源服务机构从事人力资源服务活动，适用本规定。"},{"i":3,"n":"第三条","txt":"县级以上人力资源社会保障行政部门依法开展本行政区域内的人力资源服务机构管理工作。"},{"i":4,"n":"第四条","txt":"人力资源社会保障行政部门应当加强人力资源服务标准化、信息化建设，指导人力资源服务行业协会加强行业自律。"},{"i":5,"n":"第五条","txt":"经营性人力资源服务机构从事职业中介活动的，应当在市场主体登记办理完毕后，依法向住所地人力资源社会保障行政部门申请行政许可，取得人力资源服务许可证。从事网络招聘服务的，还应当依法取得电信业务经营许可证。 本规定所称职业中介活动是指为用人单位招用人员和劳动者求职提供中介服务，包括为用人单位推荐劳动者、为劳动者介绍用人单位、组织开展招聘会、开展网络招聘服务、开展高级人才寻访（猎头）服务等经营性活动。"},{"i":6,"n":"第六条","txt":"申请从事职业中介活动的，应当具备下列条件： （一）有明确的章程和管理制度； （二）有开展业务必备的固定场所、办公设施和一定数额的开办资金； （三）有3名以上专职工作人员； （四）法律、法规规定的其他条件。"},{"i":7,"n":"第七条","txt":"申请从事职业中介活动的，可以自愿选择按照一般程序或者告知承诺制方式申请行政许可。按照一般程序申请的，应当向住所地人力资源社会保障行政部门提交以下申请材料： （一）从事职业中介活动的申请书； （二）机构章程和管理制度； （三）场所的所有权证明或者租赁合同； （四）专职工作人员的基本情况表； （五）法律、法规规定的其他材料。 前款规定的申请材料通过政务信息共享可以获得的，人力资源社会保障行政部门应当通过政务信息共享获取。提交申请材料不齐全的，人力资源社会保障行政部门应当当场一次性告知需要补正的全部材料。 按照告知承诺制方式申请的，只须提交从事职业中介活动的申请书和承诺书。申请人有较严重不良信用记录或者存在曾作出虚假承诺等情形的，在信用修复前不适用告知承诺制。"},{"i":8,"n":"第八条","txt":"按照一般程序申请行政许可的，人力资源社会保障行政部门应当自收到申请之日起20日内依法作出行政许可决定。按照告知承诺制方式申请行政许可的，人力资源社会保障行政部门应当经形式审查后当场作出行政许可决定。 符合条件，人力资源社会保障行政部门作出准予行政许可决定的，应当自作出决定之日起10日内向申请人颁发、送达人力资源服务许可证；不符合条件，人力资源社会保障行政部门作出不予行政许可书面决定的，应当说明理由，并告知申请人享有依法申请行政复议或者提起行政诉讼的权利。"},{"i":9,"n":"第九条","txt":"经营性人力资源服务机构开展人力资源供求信息的收集和发布、就业和创业指导、人力资源管理咨询、人力资源测评、人力资源培训、人力资源服务外包等人力资源服务业务的，应当自开展业务之日起15日内向住所地人力资源社会保障行政部门备案，备案事项包括机构名称、法定代表人、住所地、服务范围等。 备案事项齐全的，人力资源社会保障行政部门应当予以备案，并出具备案凭证，载明备案事项、备案机关以及日期等；备案事项不齐全的，人力资源社会保障行政部门应当当场一次性告知需要补正的全部事项。 经营性人力资源服务机构开展劳务派遣、对外劳务合作业务的，执行国家有关劳务派遣、对外劳务合作的规定。"},{"i":10,"n":"第十条","txt":"依法取得的人力资源服务许可证在全国范围内长期有效。"},{"i":11,"n":"第十一条","txt":"人力资源服务许可证分为纸质证书（正、副本）和电子证书，具有同等法律效力。 人力资源服务许可证纸质证书样式、编号规则以及电子证书标准由人力资源社会保障部制定。"},{"i":12,"n":"第十二条","txt":"经营性人力资源服务机构设立分支机构的，应当自市场主体登记办理完毕之日起15日内，书面报告分支机构住所地人力资源社会保障行政部门，书面报告事项包括机构名称、统一社会信用代码、许可证编号以及分支机构名称、负责人姓名、住所地、服务范围等。 人力资源社会保障行政部门收到书面报告后，应当出具收据，载明书面报告的名称、分支机构名称、页数以及收到时间等，并由经办人员签名或者盖章。"},{"i":13,"n":"第十三条","txt":"经营性人力资源服务机构变更名称、住所、法定代表人或者终止经营活动的，应当自市场主体变更登记或者注销登记办理完毕之日起15日内，书面报告住所地人力资源社会保障行政部门。人力资源社会保障行政部门应当及时换发或者收回人力资源服务许可证、备案凭证。 经营性人力资源服务机构跨管辖区域变更住所的，应当书面报告迁入地人力资源社会保障行政部门。迁出地人力资源社会保障行政部门应当及时移交经营性人力资源服务机构申请行政许可、办理备案的原始材料。"},{"i":14,"n":"第十四条","txt":"人力资源社会保障行政部门应当公开申请行政许可和办理备案的材料目录、办事指南和咨询监督电话等信息，优化办理流程，推行当场办结、一次办结、限时办结等制度，实现集中办理、就近办理、网上办理，提升经营性人力资源服务机构申请行政许可、办理备案便利化程度。 人力资源社会保障行政部门应当及时向社会公布依法取得行政许可或者经过备案的经营性人力资源服务机构名单及其变更、注销等情况，并提供查询服务。"},{"i":15,"n":"第十五条","txt":"人力资源服务机构接受用人单位委托招聘人员的，发布招聘信息应当真实、合法，不得含有民族、种族、性别、宗教信仰等方面的歧视性内容。 人力资源服务机构不得违反国家规定，在户籍、地域、身份等方面设置限制人力资源流动的条件。"},{"i":16,"n":"第十六条","txt":"人力资源服务机构接受用人单位委托招聘人员的，应当建立招聘信息管理制度，依法对用人单位所提供材料的真实性、合法性进行审查，并将相关审查材料存档备核。审查内容应当包括以下方面： （一）用人单位招聘简章； （二）用人单位营业执照或者有关部门批准设立的文件； （三）经办人员的身份证件、用人单位的委托证明。 经办人员与用人单位的委托关系，人力资源服务机构可以依法通过企业银行结算账户等途径确认。 接受用人单位委托招聘外国人的，应当符合《外国人在中国就业管理规定》等法律、法规、规章的规定。"},{"i":17,"n":"第十七条","txt":"人力资源服务机构不得有下列行为： （一）伪造、涂改、转让人力资源服务许可证； （二）为无合法证照的用人单位提供职业中介服务； （三）介绍未满16周岁的未成年人就业； （四）为无合法身份证件的劳动者提供职业中介服务； （五）介绍劳动者从事法律、法规禁止从事的职业； （六）介绍用人单位、劳动者从事违法活动； （七）以欺诈、暴力、胁迫等方式开展相关服务活动； （八）以开展相关服务为名牟取不正当利益； （九）以欺诈、伪造证明材料等手段骗取社会保险基金支出、社会保险待遇； （十）其他违反法律、法规规定的行为。"},{"i":18,"n":"第十八条","txt":"人力资源服务机构对其发布的求职招聘信息，应当标注有效期限或者及时更新。"},{"i":19,"n":"第十九条","txt":"人力资源服务机构接受委托或者自行组织开展人力资源培训的，不得危害国家安全、损害参训人员身心健康或者诱骗财物。"},{"i":20,"n":"第二十条","txt":"人力资源服务机构举办现场招聘会，应当制定组织实施办法、应急预案和安全保卫工作方案，核实参加招聘会的招聘单位及其招聘简章的真实性、合法性，提前将招聘会信息向社会公布，并对招聘中的各项活动进行管理。 举办网络招聘会，除遵守前款规定外，还应当加强网络安全管理，履行网络安全保护义务，采取技术措施或者其他必要措施，确保网络招聘系统和用户信息安全。 举办大型现场招聘会，应当符合《大型群众性活动安全管理条例》等法律、法规的规定。"},{"i":21,"n":"第二十一条","txt":"人力资源服务机构开展人力资源供求信息收集和发布的，应当建立健全信息发布审查和投诉处理机制，确保发布的人力资源供求信息真实、合法、有效，不得以人力资源供求信息收集和发布的名义开展职业中介活动。 人力资源服务机构在业务活动中收集用人单位信息的，不得泄露或者违法使用所知悉的商业秘密。"},{"i":22,"n":"第二十二条","txt":"人力资源服务机构通过收集、存储、使用、加工、传输、提供、公开、删除等方式处理个人信息的，应当遵循合法、正当、必要和诚信原则，遵守法律、法规有关个人信息保护的规定。 人力资源服务机构收集个人信息应当限于劳动者本人基本信息以及与应聘岗位相关的知识、技能、工作经历等情况。 人力资源服务机构应当建立个人信息保护、个人信息安全监测预警等机制,不得泄露、篡改、损毁或者非法出售、非法向他人提供所收集的个人信息，并采取必要措施防范盗取个人信息等违法行为；应当对个人信息保护情况每年至少进行一次自查，记录自查情况，及时消除自查中发现的安全隐患。"},{"i":23,"n":"第二十三条","txt":"人力资源服务机构因业务需要，确需向境外提供在中华人民共和国境内运营中收集和产生的个人信息和重要数据的，应当遵守有关法律、法规的规定。"},{"i":24,"n":"第二十四条","txt":"人力资源服务机构应当建立和完善举报投诉处理机制，公布举报投诉方式，及时受理并处理有关举报投诉。 人力资源服务机构发现用人单位、与其合作的人力资源服务机构存在虚假招聘等违法活动的，应当保存有关记录，暂停或者终止提供有关服务，并向人力资源社会保障行政部门以及有关管理部门报告。"},{"i":25,"n":"第二十五条","txt":"人力资源服务机构应当加强内部制度建设，健全财务管理制度，建立服务台账，如实记录服务对象、服务过程、服务结果等信息。服务台账应当保存2年以上。 以网络招聘服务平台方式从事网络招聘服务的人力资源服务机构应当记录、保存平台上发布的招聘信息、服务信息，并确保信息的完整性、保密性、可用性。招聘信息、服务信息应当自服务完成之日起保存3年以上。"},{"i":26,"n":"第二十六条","txt":"经营性人力资源服务机构应当在服务场所明示营业执照、服务项目、收费标准、监督机关和监督电话等事项，并接受人力资源社会保障行政部门和市场监督管理、价格等主管部门的监督检查。 从事职业中介活动的，还应当在服务场所明示人力资源服务许可证。从事网络招聘服务的，应当依照《网络招聘服务管理规定》第十三条的规定公示相关信息。"},{"i":27,"n":"第二十七条","txt":"经营性人力资源服务机构不得向个人收取明示服务项目以外的服务费用，不得以各种名目诱导、强迫个人参与贷款、入股、集资等活动。 经营性人力资源服务机构不得向个人收取押金，或者以担保等名义变相收取押金。"},{"i":28,"n":"第二十八条","txt":"经营性人力资源服务机构接受用人单位委托，提供人力资源管理、开发、配置等人力资源服务外包的，不得有下列行为： （一）以欺诈、胁迫、诱导劳动者注册为个体工商户等方式，改变用人单位与劳动者的劳动关系，帮助用人单位规避用工主体责任； （二）以人力资源服务外包名义，实际上按劳务派遣，将劳动者派往其他单位工作； （三）与用人单位串通侵害劳动者的合法权益。"},{"i":29,"n":"第二十九条","txt":"经营性人力资源服务机构应当公平竞争，不得扰乱人力资源市场价格秩序，不得采取垄断、不正当竞争等手段开展服务活动。"},{"i":30,"n":"第三十条","txt":"经营性人力资源服务机构提供公益性人力资源服务的，可以通过政府购买服务等方式给予支持。"},{"i":31,"n":"第三十一条","txt":"人力资源社会保障行政部门采取随机抽取检查对象、随机选派执法人员的方式和法律、法规规定的措施，对经营性人力资源服务机构实施监督检查。被检查单位应当配合监督检查，如实提供相关资料和信息，不得隐瞒、拒绝、阻碍。 人力资源社会保障行政部门应当将监督检查情况及时向社会公布。其中，行政处罚、监督检查结果可以通过国家企业信用信息公示系统或者其他途径向社会公示。 对按照告知承诺制方式取得人力资源服务许可证的，人力资源社会保障行政部门在实施监督检查时，应当重点对告知承诺事项真实性进行检查。"},{"i":32,"n":"第三十二条","txt":"人力资源社会保障行政部门对经营性人力资源服务机构实施监督检查，按照“谁许可、谁监管，谁备案、谁监管”的原则，由作出行政许可决定或者办理备案的人力资源社会保障行政部门依法履行监督管理职责。 在作出行政许可决定、办理备案的人力资源社会保障行政部门管辖区域外，或者未经行政许可、未备案，违法从事人力资源服务活动的，由违法行为发生地人力资源社会保障行政部门管辖。多个地方人力资源社会保障行政部门对违法行为均具有管辖权的，由最先立案的人力资源社会保障行政部门管辖；发生管辖争议的，由共同的上一级人力资源社会保障行政部门指定管辖。 上级人力资源社会保障行政部门根据工作需要，可以调查处理下级人力资源社会保障行政部门管辖的案件；对重大复杂案件，可以直接指定管辖。"},{"i":33,"n":"第三十三条","txt":"人力资源社会保障行政部门应当加强对经营性人力资源服务机构的事中事后监管，建立监管风险分析研判、市场主体警示退出等新型监管机制。 人力资源社会保障行政部门负责人力资源服务领域行政许可、备案的机构和劳动保障监察机构，应当健全监督管理协作机制。 人力资源社会保障行政部门应当加强与市场监督管理、公安等部门的信息共享和协同配合，健全跨部门综合监管机制。"},{"i":34,"n":"第三十四条","txt":"人力资源社会保障行政部门应当依法督促经营性人力资源服务机构在规定期限内提交上一年度的经营情况年度报告，并在政府网站进行不少于30日的信息公示或者引导经营性人力资源服务机构在其服务场所公示年度报告的有关内容。 人力资源社会保障行政部门通过与市场监督管理等部门信息共享可以获取的信息，不得要求经营性人力资源服务机构重复提供。"},{"i":35,"n":"第三十五条","txt":"人力资源社会保障行政部门应当加强人力资源市场诚信体系建设，制定经营性人力资源服务机构信用评价制度，建立健全诚信典型树立和失信行为曝光机制，依法依规实施守信激励和失信惩戒。"},{"i":36,"n":"第三十六条","txt":"人力资源社会保障行政部门应当畅通对经营性人力资源服务机构的举报投诉渠道，依法及时处理有关举报投诉。"},{"i":37,"n":"第三十七条","txt":"有下列情形之一的，人力资源社会保障行政部门可以依法撤销行政许可： （一）工作人员滥用职权、玩忽职守作出准予许可决定的； （二）超越法定职权作出准予许可决定的； （三）违反法定程序作出准予许可决定的； （四）对不具备申请资格或者不符合申请条件的申请人作出准予许可决定的； （五）依法可以撤销行政许可的其他情形。 被许可人通过欺骗、贿赂等不正当手段取得行政许可的，应当予以撤销。 人力资源社会保障行政部门发现存在第一款、第二款规定情形的，应当及时开展调查核实，情况属实的，依法撤销行政许可。相关经营性人力资源服务机构及其人员无法联系或者拒不配合的，人力资源社会保障行政部门可以将人力资源服务许可证编号、行政许可时间等通过政府网站向社会公示，公示期为45日。公示期内没有提出异议的，人力资源社会保障行政部门可以作出撤销行政许可的决定。"},{"i":38,"n":"第三十八条","txt":"有下列情形之一的，人力资源社会保障行政部门应当依法办理行政许可注销手续： （一）经营性人力资源服务机构依法终止经营的； （二）人力资源服务许可证被依法吊销或者行政许可依法被撤销的； （三）因不可抗力导致行政许可事项无法实施的； （四）法律、法规规定的应当注销行政许可的其他情形。"},{"i":39,"n":"第三十九条","txt":"违反本规定第五条第一款规定，未经许可擅自从事职业中介活动的，由人力资源社会保障行政部门依照《人力资源市场暂行条例》第四十二条第一款的规定处罚。 违反本规定第九条第一款规定，开展人力资源服务业务未备案，违反本规定第十二条、第十三条规定，设立分支机构、办理变更登记或者注销登记未书面报告的，由人力资源社会保障行政部门依照《人力资源市场暂行条例》第四十二条第二款的规定处罚。"},{"i":40,"n":"第四十条","txt":"违反本规定第十五条第一款规定，发布的招聘信息不真实、不合法，违反本规定第二十一条的规定，未依法开展人力资源供求信息收集和发布的，由人力资源社会保障行政部门依照《人力资源市场暂行条例》第四十三条的规定处罚。"},{"i":41,"n":"第四十一条","txt":"违反本规定第十七条第（一）（二）项规定，伪造、涂改、转让人力资源服务许可证，为无合法证照的用人单位提供职业中介服务的，由人力资源社会保障行政部门依照《中华人民共和国就业促进法》第六十五条的规定处罚。 违反本规定第十七条第（三）项规定，介绍未满16周岁的未成年人就业的，依照国家禁止使用童工的规定处罚。 违反本规定第十七条第（四）（五）项规定，为无合法身份证件的劳动者提供职业中介服务，介绍劳动者从事法律、法规禁止从事的职业的，由人力资源社会保障行政部门责令改正，没有违法所得的，可处以1万元以下的罚款；有违法所得的，可处以不超过违法所得3倍的罚款，最高不得超过3万元；情节严重的，提请市场监督管理部门吊销营业执照；对当事人造成损害的，应当承担赔偿责任。 违反本规定第十七条第（六）（七）（八）项规定，未依法开展人力资源服务业务，牟取不正当利益的，由人力资源社会保障行政部门依照《人力资源市场暂行条"},{"i":42,"n":"第四十二条","txt":"违反本规定第二十条第一款规定，未依法举办现场招聘会活动，违反本规定第二十八条规定，未依法开展人力资源服务外包的，由人力资源社会保障行政部门依照《人力资源市场暂行条例》第四十三条的规定处罚。"},{"i":43,"n":"第四十三条","txt":"违反本规定第二十二条、第二十三条规定，未依法处理个人信息的，由有关主管部门依照《中华人民共和国个人信息保护法》《中华人民共和国网络安全法》等法律、法规的规定处罚。"},{"i":44,"n":"第四十四条","txt":"未依照本规定第二十五条第一款规定建立健全内部制度或者保存服务台账，未依照本规定第二十六条规定明示有关事项，未依照本规定第三十四条第一款规定提交经营情况年度报告的，由人力资源社会保障行政部门依照《人力资源市场暂行条例》第四十四条的规定处罚。"},{"i":45,"n":"第四十五条","txt":"违反本规定第二十七条第一款规定，向个人收取明示服务项目以外的服务费用，或者以各种名目诱导、强迫个人参与贷款、入股、集资等活动的，由人力资源社会保障行政部门依照《人力资源市场暂行条例》第四十三条的规定处罚。违反本规定第二十七条第二款规定，向个人收取押金的，由人力资源社会保障行政部门依照《中华人民共和国就业促进法》第六十六条的规定处罚。"},{"i":46,"n":"第四十六条","txt":"违反本规定第二十九条规定，扰乱人力资源市场价格秩序，采取垄断、不正当竞争等手段开展服务活动的，由有关主管部门依照《中华人民共和国反垄断法》《中华人民共和国反不正当竞争法》等法律、法规的规定处罚。"},{"i":47,"n":"第四十七条","txt":"人力资源社会保障行政部门和有关主管部门及其工作人员有下列情形之一的，对直接负责的领导人员和其他直接责任人员依法给予处分： （一）不依法作出行政许可决定的； （二）在办理行政许可或者备案、实施监督检查中，索取或者收受他人财物，或者谋取其他利益的； （三）不依法履行监督职责或者监督不力，造成严重后果的； （四）其他滥用职权、玩忽职守、徇私舞弊的情形。"},{"i":48,"n":"第四十八条","txt":"违反本规定，侵害劳动者合法权益，造成财产损失或者其他损害的，依法承担民事责任。 违反本规定，构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":49,"n":"第四十九条","txt":"在实行相对集中行政许可权改革或者综合行政执法改革的地区，对经营性人力资源服务机构从事人力资源服务活动的行政许可、监督管理等职责，法律、行政法规和国务院决定等另有规定的，依照有关规定执行。"},{"i":50,"n":"第五十条","txt":"公共就业和人才服务机构的设立和管理，依照《中华人民共和国就业促进法》《就业服务与就业管理规定》等规定执行。"},{"i":51,"n":"第五十一条","txt":"本规定自2023年8月1日起施行。此前人力资源社会保障部发布的人力资源服务机构管理有关规定，凡与本规定不一致的，依照本规定执行。"}],"rencaishichangguanliguiding-2":[{"i":1,"n":"第一条","txt":"为了建立和完善机制健全、运行规范、服务周到、指导监督有力的人才市场体系，优化人才资源配置，规范人才市场活动，维护人才、用人单位和人才中介服务机构的合法权益，根据有关法律、法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称的人才市场管理，是指对人才中介服务机构从事人才中介服务、用人单位招聘和个人应聘以及与之相关活动的管理。 人才市场服务的对象是指各类用人单位和具有中专以上学历或取得专业技术资格的人员，以及其他从事专业技术或管理工作的人员。"},{"i":3,"n":"第三条","txt":"人才市场活动应当遵守国家的法律、法规及政策规定，坚持公开、平等、竞争、择优的原则，实行单位自主用人，个人自主择业。"},{"i":4,"n":"第四条","txt":"县级以上政府人事行政部门是人才市场的综合管理部门，县级以上工商行政管理部门在职责范围内依法监督管理人才市场。"},{"i":5,"n":"第五条","txt":"本规定所称人才中介服务机构是指为用人单位和人才提供中介服务及其他相关服务的专营或兼营的组织。 人才中介服务机构的设置应当符合经济和社会发展的需要，根据人才市场发展的要求，统筹规划，合理布局。"},{"i":6,"n":"第六条","txt":"设立人才中介服务机构应具备下列条件： （一）有与开展人才中介业务相适应的场所、设施； （二）有5名以上大专以上学历、取得人才中介服务资格证书的专职工作人员； （三）有健全可行的工作章程和制度； （四）有独立承担民事责任的能力； （五）具备相关法律、法规规定的其他条件。"},{"i":7,"n":"第七条","txt":"设立人才中介服务机构，可以通过信函、电报、电传、传真、电子数据交换和电子邮件等方式向政府人事行政部门提出申请，并按本规定第六条的要求提交有关证明材料，但学历证明除外。其中设立固定人才交流场所的，须做专门的说明。 未经政府人事行政部门批准，不得设立人才中介服务机构。"},{"i":8,"n":"第八条","txt":"设立人才中介服务机构应当依据管理权限由县级以上政府人事行政部门（以下简称审批机关）审批。 国务院各部委、直属机构及其直属在京事业单位和在京中央直管企业、全国性社团申请设立人才中介服务机构，由人事部审批。中央在地方所属单位申请设立人才中介服务机构，由所在地的省级政府人事行政部门审批。 人才中介服务机构设立分支机构的，应当在征得原审批机关的书面同意后，由分支机构所在地政府人事行政部门审批。 政府人事行政部门应当建立完善人才中介服务机构许可制度，并在行政机关网站公布审批程序、期限和需要提交的全部材料的目录，以及批准设立的人才中介服务机构的名录等信息。"},{"i":9,"n":"第九条","txt":"审批机关应当在接到设立人才中介服务机构申请报告之日起二十日内审核完毕，二十日内不能作出决定的，经本行政机关负责人批准，可以延长十日，并应当将延长期限的理由告知申请人。 批准同意的，发给《人才中介服务许可证》（以下简称许可证），并应当在作出决定之日起十日内向申请人颁发、送达许可证，不同意的应当书面通知申请人，并说明理由。"},{"i":10,"n":"第十条","txt":"互联网信息服务提供者专营或兼营人才信息网络中介服务的，必须申领许可证。"},{"i":11,"n":"第十一条","txt":"人才中介服务机构可以从事下列业务： （一）人才供求信息的收集、整理、储存、发布和咨询服务； （二）人才信息网络服务； （三）人才推荐； （四）人才招聘； （五）人才培训； （六）人才测评； （七）法规、规章规定的其他有关业务。 审批机关可以根据人才中介服务机构所在地区或行业的经济、社会发展需要以及人才中介服务机构自身的设备条件、人员和管理情况等，批准其开展一项或多项业务。"},{"i":12,"n":"第十二条","txt":"人才中介服务机构应当依法开展经营业务活动，不得超越许可证核准的业务范围经营；不得采取不正当竞争手段从事中介活动；不得提供虚假信息或作虚假承诺。"},{"i":13,"n":"第十三条","txt":"人才中介服务机构应当公开服务内容和工作程序，公布收费项目和标准。收费项目和标准，应当符合国家和省、自治区、直辖市的有关规定。"},{"i":14,"n":"第十四条","txt":"审批机关负责对其批准成立的人才中介服务机构依法进行检查或抽查，并可以查阅或者要求其报送有关材料。人才中介服务机构应接受检查，并如实提供有关情况和材料。审批机关应公布检查结果。"},{"i":15,"n":"第十五条","txt":"人才中介服务机构有改变名称、住所、经营范围、法定代表人以及停业、终止等情形的，应当按原审批程序办理变更或者注销登记手续。"},{"i":16,"n":"第十六条","txt":"人才中介服务机构可以建立行业组织，协调行业内部活动，促进公平竞争，提高服务质量，规范职业道德，维护行业成员的合法权益。"},{"i":17,"n":"第十七条","txt":"人才中介服务机构可在规定业务范围内接受用人单位和个人委托，从事各类人事代理服务。"},{"i":18,"n":"第十八条","txt":"开展以下人事代理业务必须经过政府人事行政部门的授权。 （一）流动人员人事档案管理； （二）因私出国政审； （三）在规定的范围内申报或组织评审专业技术职务任职资格； （四）转正定级和工龄核定； （五）大中专毕业生接收手续； （六）其他需经授权的人事代理事项。"},{"i":19,"n":"第十九条","txt":"人事代理方式可由单位集体委托代理，也可由个人委托代理；可多项委托代理，也可单项委托代理；可单位全员委托代理，也可部分人员委托代理。"},{"i":20,"n":"第二十条","txt":"单位办理委托人事代理，须向代理机构提交有效证件以及委托书，确定委托代理项目。经代理机构审定后，由代理机构与委托单位签定人事代理合同书，明确双方的权利和义务，确立人事代理关系。 个人委托办理人事代理，根据委托者的不同情况，须向代理机构提交有关证件复印件以及与代理有关的证明材料。经代理机构审定后，由代理机构与个人签订人事代理合同书，确立人事代理关系。"},{"i":21,"n":"第二十一条","txt":"人才中介服务机构举办人才交流会的，应当制定相应的组织实施办法、应急预案和安全保卫工作方案，并对参加人才交流会的招聘单位的主体资格真实性和招用人员简章真实性进行核实，对招聘中的各项活动进行管理。"},{"i":22,"n":"第二十二条","txt":"用人单位可以通过委托人才中介服务机构、参加人才交流会、在公共媒体和互联网发布信息以及其他合法方式招聘人才。"},{"i":23,"n":"第二十三条","txt":"用人单位公开招聘人才，应当出具有关部门批准其设立的文件或营业执照（副本），并如实公布拟聘用人员的数量、岗位和条件。 用人单位在招聘人才时，不得以民族、宗教信仰为由拒绝聘用或者提高聘用标准；除国家规定的不适合妇女工作的岗位外，不得以性别为由拒绝招聘妇女或提高对妇女的招聘条件。"},{"i":24,"n":"第二十四条","txt":"用人单位招聘人才，不得以任何名义向应聘者收取费用，不得有欺诈行为或采取其他方式谋取非法利益。"},{"i":25,"n":"第二十五条","txt":"人才中介服务机构通过各种形式、在各种媒体（含互联网）为用人单位发布人才招聘广告，不得超出许可业务范围。广告发布者不得为超出许可业务范围或无许可证的中介服务机构发布人才招聘广告。"},{"i":26,"n":"第二十六条","txt":"用人单位不得招聘下列人员： （一）正在承担国家、省重点工程、科研项目的技术和管理的主要人员，未经单位或主管部门同意的； （二）由国家统一派出而又未满轮换年限的赴新疆、西藏工作的人员； （三）正在从事涉及国家安全或重要机密工作的人员； （四）有违法违纪嫌疑正在依法接受审查尚未结案的人员； （五）法律、法规规定暂时不能流动的其他特殊岗位的人员。"},{"i":27,"n":"第二十七条","txt":"人才应聘可以通过人才中介服务机构、人才信息网络、人才交流会或直接与用人单位联系等形式进行。应聘时出具的证件以及履历等相关材料，必须真实、有效。"},{"i":28,"n":"第二十八条","txt":"应聘人才离开原单位，应当按照国家的有关政策规定，遵守与原单位签定的合同或协议，不得擅自离职。 通过辞职或调动方式离开原单位的，应当按照国家的有关辞职、调动的规定办理手续。"},{"i":29,"n":"第二十九条","txt":"对于符合国家人才流动政策规定的应聘人才，所在单位应当及时办理有关手续，按照国家有关规定为应聘人才提供证明文件以及相关材料，不得在国家规定之外另行设置限制条件。 应聘人才凡经单位出资培训的，如个人与单位订有合同，培训费问题按合同规定办理；没有合同的，单位可以适当收取培训费，收取标准按培训后回单位服务的年限，按每年递减20%的比例计算。"},{"i":30,"n":"第三十条","txt":"应聘人才在应聘时和离开原单位后，不得带走原单位的技术资料和设备器材等，不得侵犯原单位的知识产权、商业秘密及其他合法权益。"},{"i":31,"n":"第三十一条","txt":"用人单位与应聘人才确定聘用关系后，应当在平等自愿、协商一致的基础上，依法签定聘用合同或劳动合同。"},{"i":32,"n":"第三十二条","txt":"违反本规定，未经政府人事行政部门批准擅自设立人才中介服务机构或从事人才中介服务活动的，由县级以上政府人事行政部门责令停办，并处10000元以下罚款；有违法所得的，可处以不超过违法所得3倍的罚款，但最高不得超过30000元。"},{"i":33,"n":"第三十三条","txt":"人才中介服务机构违反本规定，擅自扩大许可业务范围、不依法接受检查或提供虚假材料，不按规定办理许可证变更等手续的，由县级以上政府人事行政部门予以警告，可并处10000元以下罚款；情节严重的，责令停业整顿，有违法所得的，没收违法所得，并可处以不超过违法所得3倍的罚款，但最高不得超过30000元。"},{"i":34,"n":"第三十四条","txt":"违反本规定，未经政府人事行政部门授权从事人事代理业务的，由县级以上政府人事行政部门责令立即停办，并处10000元以下罚款；有违法所得的，可处以不超过违法所得3倍的罚款，但最高不得超过30000元；情节严重的，并责令停业整顿。"},{"i":35,"n":"第三十五条","txt":"人才中介服务机构违反本规定，超出许可业务范围接受代理业务的，由县级以上政府人事行政部门予以警告，限期改正，并处10000元以下罚款。"},{"i":36,"n":"第三十六条","txt":"用人单位违反本规定，以民族、性别、宗教信仰为由拒绝聘用或者提高聘用标准的，招聘不得招聘人员的，以及向应聘者收取费用或采取欺诈等手段谋取非法利益的，由县级以上政府人事行政部门责令改正；情节严重的，并处10000元以下罚款。"},{"i":37,"n":"第三十七条","txt":"个人违反本规定给原单位造成损失的，应当承担赔偿责任。"},{"i":38,"n":"第三十八条","txt":"用人单位、人才中介服务机构、广告发布者发布虚假人才招聘广告的，由工商行政管理部门依照《广告法》第三十七条处罚。 人才中介服务机构超出许可业务范围发布广告、广告发布者为超出许可业务范围或无许可证的中介服务机构发布广告的，由工商行政管理部门处以10000元以下罚款；有违法所得的，可处以不超过违法所得3倍的罚款，但最高不得超过30000元。"},{"i":39,"n":"第三十九条","txt":"人才中介活动违反工商行政管理规定的，由工商行政管理部门依照有关规定予以查处。"},{"i":40,"n":"第四十条","txt":"本规定由人事部、国家工商行政管理总局负责解释。"},{"i":41,"n":"第四十一条","txt":"本规定自2001年10月1日起施行。1996年1月29日人事部发布的《人才市场管理暂行规定》（人发〔1996〕11号）同时废止。"}],"rencaishichangguanliguiding":[{"i":1,"n":"第一条","txt":"为了建立和完善机制健全、运行规范、服务周到、指导监督有力的人才市场体系，优化人才资源配置，规范人才市场活动，维护人才、用人单位和人才中介服务机构的合法权益，根据有关法律、法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称的人才市场管理，是指对人才中介服务机构从事人才中介服务、用人单位招聘和个人应聘以及与之相关活动的管理。 人才市场服务的对象是指各类用人单位和具有中专以上学历或取得专业技术资格的人员，以及其他从事专业技术或管理工作的人员。"},{"i":3,"n":"第三条","txt":"人才市场活动应当遵守国家的法律、法规及政策规定，坚持公开、平等、竞争、择优的原则，实行单位自主用人，个人自主择业。"},{"i":4,"n":"第四条","txt":"县级以上政府人事行政部门是人才市场的综合管理部门，县级以上工商行政管理部门在职责范围内依法监督管理人才市场。"},{"i":5,"n":"第五条","txt":"本规定所称人才中介服务机构是指为用人单位和人才提供中介服务及其他相关服务的专营或兼营的组织。 人才中介服务机构的设置应当符合经济和社会发展的需要，根据人才市场发展的要求，统筹规划，合理布局。"},{"i":6,"n":"第六条","txt":"设立人才中介服务机构应具备下列条件： （一）有与开展人才中介业务相适应的场所、设施； （二）有5名以上大专以上学历、取得人才中介服务资格证书的专职工作人员； （三）有健全可行的工作章程和制度； （四）有独立承担民事责任的能力； （五）具备相关法律、法规规定的其他条件。"},{"i":7,"n":"第七条","txt":"设立人才中介服务机构，可以通过信函、电报、电传、传真、电子数据交换和电子邮件等方式向政府人事行政部门提出申请，并按本规定第六条的要求提交有关证明材料，但学历证明除外。其中设立固定人才交流场所的，须做专门的说明。 未经政府人事行政部门批准，不得设立人才中介服务机构。"},{"i":8,"n":"第八条","txt":"设立人才中介服务机构应当依据管理权限由县级以上政府人事行政部门（以下简称审批机关）审批。 国务院各部委、直属机构及其直属在京事业单位和在京中央直管企业、全国性社团申请设立人才中介服务机构，由人事部审批。中央在地方所属单位申请设立人才中介服务机构，由所在地的省级政府人事行政部门审批。 人才中介服务机构设立分支机构的，应当在征得原审批机关的书面同意后，由分支机构所在地政府人事行政部门审批。 政府人事行政部门应当建立完善人才中介服务机构许可制度，并在行政机关网站公布审批程序、期限和需要提交的全部材料的目录，以及批准设立的人才中介服务机构的名录等信息。"},{"i":9,"n":"第九条","txt":"审批机关应当在接到设立人才中介服务机构申请报告之日起二十日内审核完毕，二十日内不能作出决定的，经本行政机关负责人批准，可以延长十日，并应当将延长期限的理由告知申请人。 批准同意的，发给《人才中介服务许可证》（以下简称许可证），并应当在作出决定之日起十日内向申请人颁发、送达许可证，不同意的应当书面通知申请人，并说明理由。"},{"i":10,"n":"第十条","txt":"互联网信息服务提供者专营或兼营人才信息网络中介服务的，必须申领许可证。"},{"i":11,"n":"第十一条","txt":"人才中介服务机构可以从事下列业务： （一）人才供求信息的收集、整理、储存、发布和咨询服务； （二）人才信息网络服务； （三）人才推荐； （四）人才招聘； （五）人才培训； （六）人才测评； （七）法规、规章规定的其他有关业务。 审批机关可以根据人才中介服务机构所在地区或行业的经济、社会发展需要以及人才中介服务机构自身的设备条件、人员和管理情况等，批准其开展一项或多项业务。"},{"i":12,"n":"第十二条","txt":"人才中介服务机构应当依法开展经营业务活动，不得超越许可证核准的业务范围经营；不得采取不正当竞争手段从事中介活动；不得提供虚假信息或作虚假承诺。"},{"i":13,"n":"第十三条","txt":"人才中介服务机构应当公开服务内容和工作程序，公布收费项目和标准。收费项目和标准，应当符合国家和省、自治区、直辖市的有关规定。"},{"i":14,"n":"第十四条","txt":"审批机关负责对其批准成立的人才中介服务机构依法进行检查或抽查，并可以查阅或者要求其报送有关材料。人才中介服务机构应接受检查，并如实提供有关情况和材料。审批机关应公布检查结果。"},{"i":15,"n":"第十五条","txt":"人才中介服务机构有改变名称、住所、经营范围、法定代表人以及停业、终止等情形的，应当按原审批程序办理变更或者注销登记手续。"},{"i":16,"n":"第十六条","txt":"人才中介服务机构可以建立行业组织，协调行业内部活动，促进公平竞争，提高服务质量，规范职业道德，维护行业成员的合法权益。"},{"i":17,"n":"第十七条","txt":"人才中介服务机构可在规定业务范围内接受用人单位和个人委托，从事各类人事代理服务。"},{"i":18,"n":"第十八条","txt":"开展以下人事代理业务必须经过政府人事行政部门的授权。 （一）流动人员人事档案管理； （二）因私出国政审； （三）在规定的范围内申报或组织评审专业技术职务任职资格； （四）转正定级和工龄核定； （五）大中专毕业生接收手续； （六）其他需经授权的人事代理事项。"},{"i":19,"n":"第十九条","txt":"人事代理方式可由单位集体委托代理，也可由个人委托代理；可多项委托代理，也可单项委托代理；可单位全员委托代理，也可部分人员委托代理。"},{"i":20,"n":"第二十条","txt":"单位办理委托人事代理，须向代理机构提交有效证件以及委托书，确定委托代理项目。经代理机构审定后，由代理机构与委托单位签定人事代理合同书，明确双方的权利和义务，确立人事代理关系。 个人委托办理人事代理，根据委托者的不同情况，须向代理机构提交有关证件复印件以及与代理有关的证明材料。经代理机构审定后，由代理机构与个人签订人事代理合同书，确立人事代理关系。"},{"i":21,"n":"第二十一条","txt":"人才中介服务机构举办人才交流会的，应当制定相应的组织实施办法、应急预案和安全保卫工作方案，并对参加人才交流会的招聘单位的主体资格真实性和招用人员简章真实性进行核实，对招聘中的各项活动进行管理。"},{"i":22,"n":"第二十二条","txt":"用人单位可以通过委托人才中介服务机构、参加人才交流会、在公共媒体和互联网发布信息以及其他合法方式招聘人才。"},{"i":23,"n":"第二十三条","txt":"用人单位公开招聘人才，应当出具有关部门批准其设立的文件或营业执照（副本），并如实公布拟聘用人员的数量、岗位和条件。 用人单位在招聘人才时，不得以民族、宗教信仰为由拒绝聘用或者提高聘用标准；除国家规定的不适合妇女工作的岗位外，不得以性别为由拒绝招聘妇女或提高对妇女的招聘条件。"},{"i":24,"n":"第二十四条","txt":"用人单位招聘人才，不得以任何名义向应聘者收取费用，不得有欺诈行为或采取其他方式谋取非法利益。"},{"i":25,"n":"第二十五条","txt":"人才中介服务机构通过各种形式、在各种媒体（含互联网）为用人单位发布人才招聘广告，不得超出许可业务范围。广告发布者不得为超出许可业务范围或无许可证的中介服务机构发布人才招聘广告。"},{"i":26,"n":"第二十六条","txt":"用人单位不得招聘下列人员： （一）正在承担国家、省重点工程、科研项目的技术和管理的主要人员，未经单位或主管部门同意的； （二）由国家统一派出而又未满轮换年限的赴新疆、西藏工作的人员； （三）正在从事涉及国家安全或重要机密工作的人员； （四）有违法违纪嫌疑正在依法接受审查尚未结案的人员； （五）法律、法规规定暂时不能流动的其他特殊岗位的人员。"},{"i":27,"n":"第二十七条","txt":"人才应聘可以通过人才中介服务机构、人才信息网络、人才交流会或直接与用人单位联系等形式进行。应聘时出具的证件以及履历等相关材料，必须真实、有效。"},{"i":28,"n":"第二十八条","txt":"应聘人才离开原单位，应当按照国家的有关政策规定，遵守与原单位签定的合同或协议，不得擅自离职。 通过辞职或调动方式离开原单位的，应当按照国家的有关辞职、调动的规定办理手续。"},{"i":29,"n":"第二十九条","txt":"对于符合国家人才流动政策规定的应聘人才，所在单位应当及时办理有关手续，按照国家有关规定为应聘人才提供证明文件以及相关材料，不得在国家规定之外另行设置限制条件。 应聘人才凡经单位出资培训的，如个人与单位订有合同，培训费问题按合同规定办理；没有合同的，单位可以适当收取培训费，收取标准按培训后回单位服务的年限，按每年递减20%的比例计算。"},{"i":30,"n":"第三十条","txt":"应聘人才在应聘时和离开原单位后，不得带走原单位的技术资料和设备器材等，不得侵犯原单位的知识产权、商业秘密及其他合法权益。"},{"i":31,"n":"第三十一条","txt":"用人单位与应聘人才确定聘用关系后，应当在平等自愿、协商一致的基础上，依法签定聘用合同或劳动合同。"},{"i":32,"n":"第三十二条","txt":"违反本规定，未经政府人事行政部门批准擅自设立人才中介服务机构或从事人才中介服务活动的，由县级以上政府人事行政部门责令停办，并处10000元以下罚款；有违法所得的，可处以不超过违法所得3倍的罚款，但最高不得超过30000元。"},{"i":33,"n":"第三十三条","txt":"人才中介服务机构违反本规定，擅自扩大许可业务范围、不依法接受检查或提供虚假材料，不按规定办理许可证变更等手续的，由县级以上政府人事行政部门予以警告，可并处10000元以下罚款；情节严重的，责令停业整顿，有违法所得的，没收违法所得，并可处以不超过违法所得3倍的罚款，但最高不得超过30000元。"},{"i":34,"n":"第三十四条","txt":"违反本规定，未经政府人事行政部门授权从事人事代理业务的，由县级以上政府人事行政部门责令立即停办，并处10000元以下罚款；有违法所得的，可处以不超过违法所得3倍的罚款，但最高不得超过30000元；情节严重的，并责令停业整顿。"},{"i":35,"n":"第三十五条","txt":"人才中介服务机构违反本规定，超出许可业务范围接受代理业务的，由县级以上政府人事行政部门予以警告，限期改正，并处10000元以下罚款。"},{"i":36,"n":"第三十六条","txt":"用人单位违反本规定，以民族、性别、宗教信仰为由拒绝聘用或者提高聘用标准的，招聘不得招聘人员的，以及向应聘者收取费用或采取欺诈等手段谋取非法利益的，由县级以上政府人事行政部门责令改正；情节严重的，并处10000元以下罚款。"},{"i":37,"n":"第三十七条","txt":"个人违反本规定给原单位造成损失的，应当承担赔偿责任。"},{"i":38,"n":"第三十八条","txt":"用人单位、人才中介服务机构、广告发布者发布虚假人才招聘广告的，由工商行政管理部门依照《广告法》第三十七条处罚。 人才中介服务机构超出许可业务范围发布广告、广告发布者为超出许可业务范围或无许可证的中介服务机构发布广告的，由工商行政管理部门处以10000元以下罚款；有违法所得的，可处以不超过违法所得3倍的罚款，但最高不得超过30000元。"},{"i":39,"n":"第三十九条","txt":"人才中介活动违反工商行政管理规定的，由工商行政管理部门依照有关规定予以查处。"},{"i":40,"n":"第四十条","txt":"本规定由人事部、国家工商行政管理总局负责解释。"},{"i":41,"n":"第四十一条","txt":"本规定自2001年10月1日起施行。1996年1月29日人事部发布的《人才市场管理暂行规定》（人发〔1996〕11号）同时废止。"}],"qiyelaodongzhengyixieshangdiaojieguiding":[{"i":1,"n":"第一条","txt":"为规范企业劳动争议协商、调解行为，促进劳动关系和谐稳定，根据《中华人民共和国劳动争议调解仲裁法》，制定本规定。"},{"i":2,"n":"第二条","txt":"企业劳动争议协商、调解，适用本规定。"},{"i":3,"n":"第三条","txt":"企业应当依法执行职工大会、职工代表大会、厂务公开等民主管理制度，建立集体协商、集体合同制度，维护劳动关系和谐稳定。"},{"i":4,"n":"第四条","txt":"企业应当建立劳资双方沟通对话机制，畅通劳动者利益诉求表达渠道。 劳动者认为企业在履行劳动合同、集体合同，执行劳动保障法律、法规和企业劳动规章制度等方面存在问题的，可以向企业劳动争议调解委员会（以下简称调解委员会）提出。调解委员会应当及时核实情况，协调企业进行整改或者向劳动者做出说明。 劳动者也可以通过调解委员会向企业提出其他合理诉求。调解委员会应当及时向企业转达，并向劳动者反馈情况。"},{"i":5,"n":"第五条","txt":"企业应当加强对劳动者的人文关怀，关心劳动者的诉求，关注劳动者的心理健康，引导劳动者理性维权，预防劳动争议发生。"},{"i":6,"n":"第六条","txt":"协商、调解劳动争议，应当根据事实和有关法律法规的规定，遵循平等、自愿、合法、公正、及时的原则。"},{"i":7,"n":"第七条","txt":"人力资源和社会保障行政部门应当指导企业开展劳动争议预防调解工作，具体履行下列职责： （一）指导企业遵守劳动保障法律、法规和政策； （二）督促企业建立劳动争议预防预警机制； （三）协调工会、企业代表组织建立企业重大集体性劳动争议应急调解协调机制，共同推动企业劳动争议预防调解工作； （四）检查辖区内调解委员会的组织建设、制度建设和队伍建设情况。"},{"i":8,"n":"第八条","txt":"发生劳动争议，一方当事人可以通过与另一方当事人约见、面谈等方式协商解决。"},{"i":9,"n":"第九条","txt":"劳动者可以要求所在企业工会参与或者协助其与企业进行协商。工会也可以主动参与劳动争议的协商处理，维护劳动者合法权益。 劳动者可以委托其他组织或者个人作为其代表进行协商。"},{"i":10,"n":"第十条","txt":"一方当事人提出协商要求后，另一方当事人应当积极做出口头或者书面回应。5日内不做出回应的，视为不愿协商。 协商的期限由当事人书面约定，在约定的期限内没有达成一致的，视为协商不成。当事人可以书面约定延长期限。"},{"i":11,"n":"第十一条","txt":"协商达成一致，应当签订书面和解协议。和解协议对双方当事人具有约束力，当事人应当履行。 经仲裁庭审查，和解协议程序和内容合法有效的，仲裁庭可以将其作为证据使用。但是，当事人为达成和解的目的作出妥协所涉及的对争议事实的认可，不得在其后的仲裁中作为对其不利的证据。"},{"i":12,"n":"第十二条","txt":"发生劳动争议，当事人不愿协商、协商不成或者达成和解协议后，一方当事人在约定的期限内不履行和解协议的，可以依法向调解委员会或者乡镇、街道劳动就业社会保障服务所（中心）等其他依法设立的调解组织申请调解，也可以依法向劳动人事争议仲裁委员会（以下简称仲裁委员会）申请仲裁。"},{"i":13,"n":"第十三条","txt":"大中型企业应当依法设立调解委员会，并配备专职或者兼职工作人员。 有分公司、分店、分厂的企业，可以根据需要在分支机构设立调解委员会。总部调解委员会指导分支机构调解委员会开展劳动争议预防调解工作。 调解委员会可以根据需要在车间、工段、班组设立调解小组。"},{"i":14,"n":"第十四条","txt":"小微型企业可以设立调解委员会，也可以由劳动者和企业共同推举人员，开展调解工作。"},{"i":15,"n":"第十五条","txt":"调解委员会由劳动者代表和企业代表组成，人数由双方协商确定，双方人数应当对等。劳动者代表由工会委员会成员担任或者由全体劳动者推举产生，企业代表由企业负责人指定。调解委员会主任由工会委员会成员或者双方推举的人员担任。"},{"i":16,"n":"第十六条","txt":"调解委员会履行下列职责： （一）宣传劳动保障法律、法规和政策； （二）对本企业发生的劳动争议进行调解； （三）监督和解协议、调解协议的履行； （四）聘任、解聘和管理调解员； （五）参与协调履行劳动合同、集体合同、执行企业劳动规章制度等方面出现的问题； （六）参与研究涉及劳动者切身利益的重大方案； （七）协助企业建立劳动争议预防预警机制。"},{"i":17,"n":"第十七条","txt":"调解员履行下列职责： （一）关注本企业劳动关系状况，及时向调解委员会报告； （二）接受调解委员会指派，调解劳动争议案件； （三）监督和解协议、调解协议的履行； （四）完成调解委员会交办的其他工作。"},{"i":18,"n":"第十八条","txt":"调解员应当公道正派、联系群众、热心调解工作，具有一定劳动保障法律政策知识和沟通协调能力。调解员由调解委员会聘任的本企业工作人员担任，调解委员会成员均为调解员。"},{"i":19,"n":"第十九条","txt":"调解员的聘期至少为1年，可以续聘。调解员不能履行调解职责时，调解委员会应当及时调整。"},{"i":20,"n":"第二十条","txt":"调解员依法履行调解职责，需要占用生产或者工作时间的，企业应当予以支持，并按照正常出勤对待。"},{"i":21,"n":"第二十一条","txt":"发生劳动争议，当事人可以口头或者书面形式向调解委员会提出调解申请。 申请内容应当包括申请人基本情况、调解请求、事实与理由。 口头申请的，调解委员会应当当场记录。"},{"i":22,"n":"第二十二条","txt":"调解委员会接到调解申请后，对属于劳动争议受理范围且双方当事人同意调解的，应当在3个工作日内受理。对不属于劳动争议受理范围或者一方当事人不同意调解的，应当做好记录，并书面通知申请人。"},{"i":23,"n":"第二十三条","txt":"发生劳动争议，当事人没有提出调解申请，调解委员会可以在征得双方当事人同意后主动调解。"},{"i":24,"n":"第二十四条","txt":"调解委员会调解劳动争议一般不公开进行。但是，双方当事人要求公开调解的除外。"},{"i":25,"n":"第二十五条","txt":"调解委员会根据案件情况指定调解员或者调解小组进行调解，在征得当事人同意后，也可以邀请有关单位和个人协助调解。 调解员应当全面听取双方当事人的陈述，采取灵活多样的方式方法，开展耐心、细致的说服疏导工作，帮助当事人自愿达成调解协议。"},{"i":26,"n":"第二十六条","txt":"经调解达成调解协议的，由调解委员会制作调解协议书。调解协议书应当写明双方当事人基本情况、调解请求事项、调解的结果和协议履行期限、履行方式等。 调解协议书由双方当事人签名或者盖章，经调解员签名并加盖调解委员会印章后生效。 调解协议书一式三份，双方当事人和调解委员会各执一份。"},{"i":27,"n":"第二十七条","txt":"生效的调解协议对双方当事人具有约束力，当事人应当履行。 双方当事人可以自调解协议生效之日起15日内共同向仲裁委员会提出仲裁审查申请。仲裁委员会受理后，应当对调解协议进行审查，并根据《劳动人事争议仲裁办案规则》第五十四条规定，对程序和内容合法有效的调解协议，出具调解书。"},{"i":28,"n":"第二十八条","txt":"双方当事人未按前条规定提出仲裁审查申请，一方当事人在约定的期限内不履行调解协议的，另一方当事人可以依法申请仲裁。 仲裁委员会受理仲裁申请后，应当对调解协议进行审查，调解协议合法有效且不损害公共利益或者第三人合法利益的，在没有新证据出现的情况下，仲裁委员会可以依据调解协议作出仲裁裁决。"},{"i":29,"n":"第二十九条","txt":"调解委员会调解劳动争议，应当自受理调解申请之日起15日内结束。但是，双方当事人同意延期的可以延长。 在前款规定期限内未达成调解协议的，视为调解不成。"},{"i":30,"n":"第三十条","txt":"当事人不愿调解、调解不成或者达成调解协议后，一方当事人在约定的期限内不履行调解协议的，调解委员会应当做好记录，由双方当事人签名或者盖章，并书面告知当事人可以向仲裁委员会申请仲裁。"},{"i":31,"n":"第三十一条","txt":"有下列情形之一的，按照《劳动人事争议仲裁办案规则》第十条的规定属于仲裁时效中断，从中断时起，仲裁时效期间重新计算： （一）一方当事人提出协商要求后，另一方当事人不同意协商或者在5日内不做出回应的； （二）在约定的协商期限内，一方或者双方当事人不同意继续协商的； （三）在约定的协商期限内未达成一致的； （四）达成和解协议后，一方或者双方当事人在约定的期限内不履行和解协议的； （五）一方当事人提出调解申请后，另一方当事人不同意调解的； （六）调解委员会受理调解申请后，在第二十九条规定的期限内一方或者双方当事人不同意调解的； （七）在第二十九条规定的期限内未达成调解协议的； （八）达成调解协议后，一方当事人在约定期限内不履行调解协议的。"},{"i":32,"n":"第三十二条","txt":"调解委员会应当建立健全调解登记、调解记录、督促履行、档案管理、业务培训、统计报告、工作考评等制度。"},{"i":33,"n":"第三十三条","txt":"企业应当支持调解委员会开展调解工作，提供办公场所，保障工作经费。"},{"i":34,"n":"第三十四条","txt":"企业未按照本规定成立调解委员会，劳动争议或者群体性事件频发，影响劳动关系和谐，造成重大社会影响的，由县级以上人力资源和社会保障行政部门予以通报；违反法律法规规定的，依法予以处理。"},{"i":35,"n":"第三十五条","txt":"调解员在调解过程中存在严重失职或者违法违纪行为，侵害当事人合法权益的，调解委员会应当予以解聘。"},{"i":36,"n":"第三十六条","txt":"民办非企业单位、社会团体开展劳动争议协商、调解工作参照本规定执行。"},{"i":37,"n":"第三十七条","txt":"本规定自2012年1月1日起施行"}],"qiyenianjinbanfa":[{"i":1,"n":"第一条","txt":"为建立多层次的养老保险制度，推动企业年金发展，更好地保障职工退休后的生活，根据《中华人民共和国劳动法》、《中华人民共和国劳动合同法》、《中华人民共和国社会保险法》、《中华人民共和国信托法》和国务院有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称企业年金，是指企业及其职工在依法参加基本养老保险的基础上，自主建立的补充养老保险制度。国家鼓励企业建立企业年金。建立企业年金，应当按照本办法执行。"},{"i":3,"n":"第三条","txt":"企业年金所需费用由企业和职工个人共同缴纳。企业年金基金实行完全积累，为每个参加企业年金的职工建立个人账户，按照国家有关规定投资运营。企业年金基金投资运营收益并入企业年金基金。"},{"i":4,"n":"第四条","txt":"企业年金有关税收和财务管理，按照国家有关规定执行。"},{"i":5,"n":"第五条","txt":"企业和职工建立企业年金，应当确定企业年金受托人，由企业代表委托人与受托人签订受托管理合同。受托人可以是符合国家规定的法人受托机构，也可以是企业按照国家有关规定成立的企业年金理事会。"},{"i":6,"n":"第六条","txt":"企业和职工建立企业年金，应当依法参加基本养老保险并履行缴费义务，企业具有相应的经济负担能力。"},{"i":7,"n":"第七条","txt":"建立企业年金，企业应当与职工一方通过集体协商确定，并制定企业年金方案。企业年金方案应当提交职工代表大会或者全体职工讨论通过。"},{"i":8,"n":"第八条","txt":"企业年金方案应当包括以下内容： （一）参加人员； （二）资金筹集与分配的比例和办法； （三）账户管理； （四）权益归属； （五）基金管理； （六）待遇计发和支付方式； （七）方案的变更和终止； （八）组织管理和监督方式； （九）双方约定的其他事项。 企业年金方案适用于企业试用期满的职工。"},{"i":9,"n":"第九条","txt":"企业应当将企业年金方案报送所在地县级以上人民政府人力资源社会保障行政部门。 中央所属企业的企业年金方案报送人力资源社会保障部。 跨省企业的企业年金方案报送其总部所在地省级人民政府人力资源社会保障行政部门。 省内跨地区企业的企业年金方案报送其总部所在地设区的市级以上人民政府人力资源社会保障行政部门。"},{"i":10,"n":"第十条","txt":"人力资源社会保障行政部门自收到企业年金方案文本之日起15日内未提出异议的，企业年金方案即行生效。"},{"i":11,"n":"第十一条","txt":"企业与职工一方可以根据本企业情况，按照国家政策规定，经协商一致，变更企业年金方案。变更后的企业年金方案应当经职工代表大会或者全体职工讨论通过，并重新报送人力资源社会保障行政部门。"},{"i":12,"n":"第十二条","txt":"有下列情形之一的，企业年金方案终止： （一）企业因依法解散、被依法撤销或者被依法宣告破产等原因，致使企业年金方案无法履行的； （二）因不可抗力等原因致使企业年金方案无法履行的； （三）企业年金方案约定的其他终止条件出现的。"},{"i":13,"n":"第十三条","txt":"企业应当在企业年金方案变更或者终止后10日内报告人力资源社会保障行政部门，并通知受托人。企业应当在企业年金方案终止后，按国家有关规定对企业年金基金进行清算，并按照本办法第四章相关规定处理。"},{"i":14,"n":"第十四条","txt":"企业年金基金由下列各项组成： （一）企业缴费； （二）职工个人缴费； （三）企业年金基金投资运营收益。"},{"i":15,"n":"第十五条","txt":"企业缴费每年不超过本企业职工工资总额的8%。企业和职工个人缴费合计不超过本企业职工工资总额的12%。具体所需费用，由企业和职工一方协商确定。 职工个人缴费由企业从职工个人工资中代扣代缴。"},{"i":16,"n":"第十六条","txt":"实行企业年金后，企业如遇到经营亏损、重组并购等当期不能继续缴费的情况，经与职工一方协商，可以中止缴费。不能继续缴费的情况消失后，企业和职工恢复缴费，并可以根据本企业实际情况，按照中止缴费时的企业年金方案予以补缴。补缴的年限和金额不得超过实际中止缴费的年限和金额。"},{"i":17,"n":"第十七条","txt":"企业缴费应当按照企业年金方案确定的比例和办法计入职工企业年金个人账户，职工个人缴费计入本人企业年金个人账户。"},{"i":18,"n":"第十八条","txt":"企业应当合理确定本单位当期缴费计入职工企业年金个人账户的最高额与平均额的差距。企业当期缴费计入职工企业年金个人账户的最高额与平均额不得超过5倍。"},{"i":19,"n":"第十九条","txt":"职工企业年金个人账户中个人缴费及其投资收益自始归属于职工个人。 职工企业年金个人账户中企业缴费及其投资收益，企业可以与职工一方约定其自始归属于职工个人，也可以约定随着职工在本企业工作年限的增加逐步归属于职工个人，完全归属于职工个人的期限最长不超过8年。"},{"i":20,"n":"第二十条","txt":"有下列情形之一的，职工企业年金个人账户中企业缴费及其投资收益完全归属于职工个人： （一）职工达到法定退休年龄、完全丧失劳动能力或者死亡的； （二）有本办法第十二条规定的企业年金方案终止情形之一的； （三）非因职工过错企业解除劳动合同的，或者因企业违反法律规定职工解除劳动合同的； （四）劳动合同期满，由于企业原因不再续订劳动合同的； （五）企业年金方案约定的其他情形。"},{"i":21,"n":"第二十一条","txt":"企业年金暂时未分配至职工企业年金个人账户的企业缴费及其投资收益，以及职工企业年金个人账户中未归属于职工个人的企业缴费及其投资收益，计入企业年金企业账户。 企业年金企业账户中的企业缴费及其投资收益应当按照企业年金方案确定的比例和办法计入职工企业年金个人账户。"},{"i":22,"n":"第二十二条","txt":"职工变动工作单位时，新就业单位已经建立企业年金或者职业年金的，原企业年金个人账户权益应当随同转入新就业单位企业年金或者职业年金。 职工新就业单位没有建立企业年金或者职业年金的，或者职工升学、参军、失业期间，原企业年金个人账户可以暂时由原管理机构继续管理，也可以由法人受托机构发起的集合计划设置的保留账户暂时管理；原受托人是企业年金理事会的，由企业与职工协商选择法人受托机构管理。"},{"i":23,"n":"第二十三条","txt":"企业年金方案终止后，职工原企业年金个人账户由法人受托机构发起的集合计划设置的保留账户暂时管理；原受托人是企业年金理事会的，由企业与职工一方协商选择法人受托机构管理。"},{"i":24,"n":"第二十四条","txt":"符合下列条件之一的，可以领取企业年金： （一）职工在达到国家规定的退休年龄或者完全丧失劳动能力时，可以从本人企业年金个人账户中按月、分次或者一次性领取企业年金，也可以将本人企业年金个人账户资金全部或者部分购买商业养老保险产品，依据保险合同领取待遇并享受相应的继承权； （二）出国（境）定居人员的企业年金个人账户资金，可以根据本人要求一次性支付给本人； （三）职工或者退休人员死亡后，其企业年金个人账户余额可以继承。"},{"i":25,"n":"第二十五条","txt":"未达到上述企业年金领取条件之一的，不得从企业年金个人账户中提前提取资金。"},{"i":26,"n":"第二十六条","txt":"企业成立企业年金理事会作为受托人的，企业年金理事会应当由企业和职工代表组成，也可以聘请企业以外的专业人员参加，其中职工代表应不少于三分之一。 企业年金理事会除管理本企业的企业年金事务之外，不得从事其他任何形式的营业性活动。"},{"i":27,"n":"第二十七条","txt":"受托人应当委托具有企业年金管理资格的账户管理人、投资管理人和托管人，负责企业年金基金的账户管理、投资运营和托管。"},{"i":28,"n":"第二十八条","txt":"企业年金基金应当与委托人、受托人、账户管理人、投资管理人、托管人和其他为企业年金基金管理提供服务的自然人、法人或者其他组织的自有资产或者其他资产分开管理，不得挪作其他用途。 企业年金基金管理应当执行国家有关规定。"},{"i":29,"n":"第二十九条","txt":"县级以上人民政府人力资源社会保障行政部门负责对本办法的执行情况进行监督检查。对违反本办法的，由人力资源社会保障行政部门予以警告，责令改正。"},{"i":30,"n":"第三十条","txt":"因订立或者履行企业年金方案发生争议的，按照国家有关集体合同的规定执行。 因履行企业年金基金管理合同发生争议的，当事人可以依法申请仲裁或者提起诉讼。"},{"i":31,"n":"第三十一条","txt":"参加企业职工基本养老保险的其他用人单位及其职工建立补充养老保险的，参照本办法执行。"},{"i":32,"n":"第三十二条","txt":"本办法自2018年2月1日起施行。原劳动和社会保障部2004年1月6日发布的《企业年金试行办法》同时废止。 本办法施行之日已经生效的企业年金方案，与本办法规定不一致的，应当在本办法施行之日起1年内变更。"}],"qiyenianjinjijinguanlibanfa":[{"i":1,"n":"第一条","txt":"为维护企业年金各方当事人的合法权益，规范企业年金基金管理，根据劳动法、信托法、合同法、证券投资基金法等法律和国务院有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"企业年金基金的受托管理、账户管理、托管、投资管理以及监督管理适用本办法。 本办法所称企业年金基金，是指根据依法制定的企业年金计划筹集的资金及其投资运营收益形成的企业补充养老保险基金。"},{"i":3,"n":"第三条","txt":"建立企业年金计划的企业及其职工作为委托人，与企业年金理事会或者法人受托机构（以下简称受托人）签订受托管理合同。 受托人与企业年金基金账户管理机构（以下简称账户管理人）、企业年金基金托管机构（以下简称托管人）和企业年金基金投资管理机构（以下简称投资管理人）分别签订委托管理合同。"},{"i":4,"n":"第四条","txt":"受托人应当将受托管理合同和委托管理合同报人力资源社会保障行政部门备案。"},{"i":5,"n":"第五条","txt":"一个企业年金计划应当仅有一个受托人、一个账户管理人和一个托管人，可以根据资产规模大小选择适量的投资管理人。"},{"i":6,"n":"第六条","txt":"同一企业年金计划中，受托人与托管人、托管人与投资管理人不得为同一人；建立企业年金计划的企业成立企业年金理事会作为受托人的，该企业与托管人不得为同一人；受托人与托管人、托管人与投资管理人、投资管理人与其他投资管理人的总经理和企业年金从业人员，不得相互兼任。 同一企业年金计划中，法人受托机构具备账户管理或者投资管理业务资格的，可以兼任账户管理人或者投资管理人。"},{"i":7,"n":"第七条","txt":"法人受托机构兼任投资管理人时，应当建立风险控制制度，确保各项业务管理之间的独立性；设立独立的受托业务和投资业务部门，办公区域、运营管理流程和业务制度应当严格分离；直接负责的高级管理人员、受托业务和投资业务部门的工作人员不得相互兼任。 同一企业年金计划中，法人受托机构对待各投资管理人应当执行统一的标准和流程，体现公开、公平、公正原则。"},{"i":8,"n":"第八条","txt":"企业年金基金缴费必须归集到受托财产托管账户，并在45日内划入投资资产托管账户。企业年金基金财产独立于委托人、受托人、账户管理人、托管人、投资管理人和其他为企业年金基金管理提供服务的自然人、法人或者其他组织的固有财产及其管理的其他财产。 企业年金基金财产的管理、运用或者其他情形取得的财产和收益，应当归入基金财产。"},{"i":9,"n":"第九条","txt":"委托人、受托人、账户管理人、托管人、投资管理人和其他为企业年金基金管理提供服务的自然人、法人或者其他组织，因依法解散、被依法撤销或者被依法宣告破产等原因进行终止清算的，企业年金基金财产不属于其清算财产。"},{"i":10,"n":"第十条","txt":"企业年金基金财产的债权，不得与委托人、受托人、账户管理人、托管人、投资管理人和其他为企业年金基金管理提供服务的自然人、法人或者其他组织固有财产的债务相互抵销。不同企业年金计划的企业年金基金的债权债务，不得相互抵销。"},{"i":11,"n":"第十一条","txt":"非因企业年金基金财产本身承担的债务，不得对基金财产强制执行。"},{"i":12,"n":"第十二条","txt":"受托人、账户管理人、托管人、投资管理人和其他为企业年金基金管理提供服务的自然人、法人或者其他组织必须恪尽职守，履行诚实、信用、谨慎、勤勉的义务。"},{"i":13,"n":"第十三条","txt":"人力资源社会保障部负责制定企业年金基金管理的有关政策。人力资源社会保障行政部门对企业年金基金管理进行监管。"},{"i":14,"n":"第十四条","txt":"本办法所称受托人，是指受托管理企业年金基金的符合国家规定的养老金管理公司等法人受托机构（以下简称法人受托机构）或者企业年金理事会。"},{"i":15,"n":"第十五条","txt":"建立企业年金计划的企业，应当通过职工大会或者职工代表大会讨论确定，选择法人受托机构作为受托人，或者成立企业年金理事会作为受托人。"},{"i":16,"n":"第十六条","txt":"企业年金理事会由企业代表和职工代表等人员组成，也可以聘请企业以外的专业人员参加，其中职工代表不少于三分之一。理事会应当配备一定数量的专职工作人员。"},{"i":17,"n":"第十七条","txt":"企业年金理事会中的职工代表和企业以外的专业人员由职工大会、职工代表大会或者其他形式民主选举产生。企业代表由企业方聘任。 理事任期由企业年金理事会章程规定，但每届任期不得超过三年。理事任期届满，连选可以连任。"},{"i":18,"n":"第十八条","txt":"企业年金理事会理事应当具备下列条件： （一）具有完全民事行为能力； （二）诚实守信，无犯罪记录； （三）具有从事法律、金融、会计、社会保障或者其他履行企业年金理事会理事职责所必需的专业知识； （四）具有决策能力； （五）无个人所负数额较大的债务到期未清偿情形。"},{"i":19,"n":"第十九条","txt":"企业年金理事会依法独立管理本企业的企业年金基金事务，不受企业方的干预，不得从事任何形式的营业性活动，不得从企业年金基金财产中提取管理费用。"},{"i":20,"n":"第二十条","txt":"企业年金理事会会议，应当由理事本人出席；理事因故不能出席，可以书面委托其他理事代为出席，委托书中应当载明授权范围。 理事会作出决议，应当经全体理事三分之二以上通过。理事会应当对会议所议事项的决定形成会议记录，出席会议的理事应当在会议记录上签名。"},{"i":21,"n":"第二十一条","txt":"理事应当对企业年金理事会的决议承担责任。理事会的决议违反法律、行政法规、本办法规定或者理事会章程，致使企业年金基金财产遭受损失的，理事应当承担赔偿责任。但经证明在表决时曾表明异议并记载于会议记录的，该理事可以免除责任。 企业年金理事会对外签订合同，应当由全体理事签字。"},{"i":22,"n":"第二十二条","txt":"法人受托机构应当具备下列条件： （一）经国家金融监管部门批准，在中国境内注册的独立法人； （二）具有完善的法人治理结构； （三）取得企业年金基金从业资格的专职人员达到规定人数； （四）具有符合要求的营业场所、安全防范设施和与企业年金基金受托管理业务有关的其他设施； （五）具有完善的内部稽核监控制度和风险控制制度； （六）近3年没有重大违法违规行为； （七）国家规定的其他条件。"},{"i":23,"n":"第二十三条","txt":"受托人应当履行下列职责： （一）选择、监督、更换账户管理人、托管人、投资管理人； （二）制定企业年金基金战略资产配置策略； （三）根据合同对企业年金基金管理进行监督； （四）根据合同收取企业和职工缴费，向受益人支付企业年金待遇，并在合同中约定具体的履行方式； （五）接受委托人查询，定期向委托人提交企业年金基金管理和财务会计报告。发生重大事件时，及时向委托人和有关监管部门报告；定期向有关监管部门提交开展企业年金基金受托管理业务情况的报告； （六）按照国家规定保存与企业年金基金管理有关的记录自合同终止之日起至少15年； （七）国家规定和合同约定的其他职责。"},{"i":24,"n":"第二十四条","txt":"本办法所称受益人，是指参加企业年金计划并享有受益权的企业职工。"},{"i":25,"n":"第二十五条","txt":"有下列情形之一的，法人受托机构职责终止： （一）违反与委托人合同约定的； （二）利用企业年金基金财产为其谋取利益，或者为他人谋取不正当利益的； （三）依法解散、被依法撤销、被依法宣告破产或者被依法接管的； （四）被依法取消企业年金基金受托管理业务资格的； （五）委托人有证据认为更换受托人符合受益人利益的； （六）有关监管部门有充分理由和依据认为更换受托人符合受益人利益的； （七）国家规定和合同约定的其他情形。 企业年金理事会有前款第（二）项规定情形的，企业年金理事会职责终止，由委托人选择法人受托机构担任受托人。企业年金理事会有第（一）、（三）至（七）项规定情形之一的，应当按照国家规定重新组成，或者由委托人选择法人受托机构担任受托人。"},{"i":26,"n":"第二十六条","txt":"受托人职责终止的，委托人应当在45日内委任新的受托人。 受托人职责终止的，应当妥善保管企业年金基金受托管理资料，在45日内办理完毕受托管理业务移交手续，新受托人应当接收并行使相应职责。"},{"i":27,"n":"第二十七条","txt":"本办法所称账户管理人，是指接受受托人委托管理企业年金基金账户的专业机构。"},{"i":28,"n":"第二十八条","txt":"账户管理人应当具备下列条件： （一）经国家有关部门批准，在中国境内注册的独立法人； （二）具有完善的法人治理结构； （三）取得企业年金基金从业资格的专职人员达到规定人数； （四）具有相应的企业年金基金账户信息管理系统； （五）具有符合要求的营业场所、安全防范设施和与企业年金基金账户管理业务有关的其他设施； （六）具有完善的内部稽核监控制度和风险控制制度； （七）近3年没有重大违法违规行为； （八）国家规定的其他条件。"},{"i":29,"n":"第二十九条","txt":"账户管理人应当履行下列职责： （一）建立企业年金基金企业账户和个人账户； （二）记录企业、职工缴费以及企业年金基金投资收益； （三）定期与托管人核对缴费数据以及企业年金基金账户财产变化状况，及时将核对结果提交受托人； （四）计算企业年金待遇； （五）向企业和受益人提供企业年金基金企业账户和个人账户信息查询服务；向受益人提供年度权益报告； （六）定期向受托人提交账户管理数据等信息以及企业年金基金账户管理报告；定期向有关监管部门提交开展企业年金基金账户管理业务情况的报告； （七）按照国家规定保存企业年金基金账户管理档案自合同终止之日起至少15年； （八）国家规定和合同约定的其他职责。"},{"i":30,"n":"第三十条","txt":"有下列情形之一的，账户管理人职责终止： （一）违反与受托人合同约定的； （二）利用企业年金基金财产为其谋取利益，或者为他人谋取不正当利益的； （三）依法解散、被依法撤销、被依法宣告破产或者被依法接管的； （四）被依法取消企业年金基金账户管理业务资格的； （五）受托人有证据认为更换账户管理人符合受益人利益的； （六）有关监管部门有充分理由和依据认为更换账户管理人符合受益人利益的； （七）国家规定和合同约定的其他情形。"},{"i":31,"n":"第三十一条","txt":"账户管理人职责终止的，受托人应当在45日内确定新的账户管理人。 账户管理人职责终止的，应当妥善保管企业年金基金账户管理资料，在45日内办理完毕账户管理业务移交手续，新账户管理人应当接收并行使相应职责。"},{"i":32,"n":"第三十二条","txt":"本办法所称托管人，是指接受受托人委托保管企业年金基金财产的商业银行。"},{"i":33,"n":"第三十三条","txt":"托管人应当具备下列条件： （一）经国家金融监管部门批准，在中国境内注册的独立法人； （二）具有完善的法人治理结构； （三）设有专门的资产托管部门； （四）取得企业年金基金从业资格的专职人员达到规定人数； （五）具有保管企业年金基金财产的条件； （六）具有安全高效的清算、交割系统； （七）具有符合要求的营业场所、安全防范设施和与企业年金基金托管业务有关的其他设施； （八）具有完善的内部稽核监控制度和风险控制制度； （九）近3年没有重大违法违规行为； （十）国家规定的其他条件。"},{"i":34,"n":"第三十四条","txt":"托管人应当履行下列职责： （一）安全保管企业年金基金财产； （二）以企业年金基金名义开设基金财产的资金账户和证券账户等； （三）对所托管的不同企业年金基金财产分别设置账户，确保基金财产的完整和独立； （四）根据受托人指令，向投资管理人分配企业年金基金财产； （五）及时办理清算、交割事宜； （六）负责企业年金基金会计核算和估值，复核、审查和确认投资管理人计算的基金财产净值； （七）根据受托人指令，向受益人发放企业年金待遇； （八）定期与账户管理人、投资管理人核对有关数据； （九）按照规定监督投资管理人的投资运作，并定期向受托人报告投资监督情况； （十）定期向受托人提交企业年金基金托管和财务会计报告；定期向有关监管部门提交开展企业年金基金托管业务情况的报告； （十一）按照国家规定保存企业年金基金托管业务活动记录、账册、报表和其他相关资料自合同终止之日起至少15年； （十二）国家规定和合同约"},{"i":35,"n":"第三十五条","txt":"托管人发现投资管理人依据交易程序尚未成立的投资指令违反法律、行政法规、其他有关规定或者合同约定的，应当拒绝执行，立即通知投资管理人，并及时向受托人和有关监管部门报告。 托管人发现投资管理人依据交易程序已经成立的投资指令违反法律、行政法规、其他有关规定或者合同约定的，应当立即通知投资管理人，并及时向受托人和有关监管部门报告。"},{"i":36,"n":"第三十六条","txt":"有下列情形之一的，托管人职责终止： （一）违反与受托人合同约定的； （二）利用企业年金基金财产为其谋取利益，或者为他人谋取不正当利益的； （三）依法解散、被依法撤销、被依法宣告破产或者被依法接管的； （四）被依法取消企业年金基金托管业务资格的； （五）受托人有证据认为更换托管人符合受益人利益的； （六）有关监管部门有充分理由和依据认为更换托管人符合受益人利益的； （七）国家规定和合同约定的其他情形。"},{"i":37,"n":"第三十七条","txt":"托管人职责终止的，受托人应当在45日内确定新的托管人。 托管人职责终止的，应当妥善保管企业年金基金托管资料，在45日内办理完毕托管业务移交手续，新托管人应当接收并行使相应职责。"},{"i":38,"n":"第三十八条","txt":"禁止托管人有下列行为： （一）托管的企业年金基金财产与其固有财产混合管理； （二）托管的企业年金基金财产与托管的其他财产混合管理； （三）托管的不同企业年金计划、不同企业年金投资组合的企业年金基金财产混合管理； （四）侵占、挪用托管的企业年金基金财产； （五）国家规定和合同约定禁止的其他行为。"},{"i":39,"n":"第三十九条","txt":"本办法所称投资管理人，是指接受受托人委托投资管理企业年金基金财产的专业机构。"},{"i":40,"n":"第四十条","txt":"投资管理人应当具备下列条件： （一）经国家金融监管部门批准，在中国境内注册，具有受托投资管理、基金管理或者资产管理资格的独立法人； （二）具有完善的法人治理结构； （三）取得企业年金基金从业资格的专职人员达到规定人数； （四）具有符合要求的营业场所、安全防范设施和与企业年金基金投资管理业务有关的其他设施； （五）具有完善的内部稽核监控制度和风险控制制度； （六）近3年没有重大违法违规行为； （七）国家规定的其他条件。"},{"i":41,"n":"第四十一条","txt":"投资管理人应当履行下列职责： （一）对企业年金基金财产进行投资； （二）及时与托管人核对企业年金基金会计核算和估值结果； （三）建立企业年金基金投资管理风险准备金； （四）定期向受托人提交企业年金基金投资管理报告；定期向有关监管部门提交开展企业年金基金投资管理业务情况的报告； （五）根据国家规定保存企业年金基金财产会计凭证、会计账簿、年度财务会计报告和投资记录自合同终止之日起至少15年； （六）国家规定和合同约定的其他职责。"},{"i":42,"n":"第四十二条","txt":"有下列情形之一的，投资管理人应当及时向受托人报告： （一）企业年金基金单位净值大幅度波动的； （二）可能使企业年金基金财产受到重大影响的有关事项； （三）国家规定和合同约定的其他情形。"},{"i":43,"n":"第四十三条","txt":"有下列情形之一的，投资管理人职责终止： （一）违反与受托人合同约定的； （二）利用企业年金基金财产为其谋取利益，或者为他人谋取不正当利益的； （三）依法解散、被依法撤销、被依法宣告破产或者被依法接管的； （四）被依法取消企业年金基金投资管理业务资格的； （五）受托人有证据认为更换投资管理人符合受益人利益的； （六）有关监管部门有充分理由和依据认为更换投资管理人符合受益人利益的； （七）国家规定和合同约定的其他情形。"},{"i":44,"n":"第四十四条","txt":"投资管理人职责终止的，受托人应当在45日内确定新的投资管理人。 投资管理人职责终止的，应当妥善保管企业年金基金投资管理资料，在45日内办理完毕投资管理业务移交手续，新投资管理人应当接收并行使相应职责。"},{"i":45,"n":"第四十五条","txt":"禁止投资管理人有下列行为： （一）将其固有财产或者他人财产混同于企业年金基金财产； （二）不公平对待企业年金基金财产与其管理的其他财产； （三）不公平对待其管理的不同企业年金基金财产； （四）侵占、挪用企业年金基金财产； （五）承诺、变相承诺保本或者保证收益； （六）利用所管理的其他资产为企业年金计划委托人、受益人或者相关管理人谋取不正当利益； （七）国家规定和合同约定禁止的其他行为。"},{"i":46,"n":"第四十六条","txt":"企业年金基金投资管理应当遵循谨慎、分散风险的原则，充分考虑企业年金基金财产的安全性、收益性和流动性，实行专业化管理。"},{"i":47,"n":"第四十七条","txt":"企业年金基金财产限于境内投资，投资范围包括银行存款、国债、中央银行票据、债券回购、万能保险产品、投资连结保险产品、证券投资基金、股票，以及信用等级在投资级以上的金融债、企业（公司）债、可转换债（含分离交易可转换债）、短期融资券和中期票据等金融产品。"},{"i":48,"n":"第四十八条","txt":"每个投资组合的企业年金基金财产应当由一个投资管理人管理，企业年金基金财产以投资组合为单位按照公允价值计算应当符合下列规定： （一）投资银行活期存款、中央银行票据、债券回购等流动性产品以及货币市场基金的比例，不得低于投资组合企业年金基金财产净值的5%；清算备付金、证券清算款以及一级市场证券申购资金视为流动性资产；投资债券正回购的比例不得高于投资组合企业年金基金财产净值的40%。 （二）投资银行定期存款、协议存款、国债、金融债、企业（公司）债、短期融资券、中期票据、万能保险产品等固定收益类产品以及可转换债（含分离交易可转换债）、债券基金、投资连结保险产品（股票投资比例不高于30%）的比例，不得高于投资组合企业年金基金财产净值的95%。 （三）投资股票等权益类产品以及股票基金、混合基金、投资连结保险产品（股票投资比例高于或者等于30%）的比例，不得高于投资组合企业年金基金财产净值的30%。其"},{"i":49,"n":"第四十九条","txt":"根据金融市场变化和投资运作情况，人力资源社会保障部会同中国银监会、中国证监会和中国保监会，适时对投资范围和比例进行调整。"},{"i":50,"n":"第五十条","txt":"单个投资组合的企业年金基金财产，投资于一家企业所发行的股票，单期发行的同一品种短期融资券、中期票据、金融债、企业（公司）债、可转换债（含分离交易可转换债），单只证券投资基金，单个万能保险产品或者投资连结保险产品，分别不得超过该企业上述证券发行量、该基金份额或者该保险产品资产管理规模的5%；按照公允价值计算，也不得超过该投资组合企业年金基金财产净值的10%。 单个投资组合的企业年金基金财产，投资于经备案的符合第四十八条投资比例规定的单只养老金产品，不得超过该投资组合企业年金基金财产净值的30%，不受上述10%规定的限制。"},{"i":51,"n":"第五十一条","txt":"投资管理人管理的企业年金基金财产投资于自己管理的金融产品须经受托人同意。"},{"i":52,"n":"第五十二条","txt":"因证券市场波动、上市公司合并、基金规模变动等投资管理人之外的因素致使企业年金基金投资不符合本办法第四十八条、第五十条规定的比例或者合同约定的投资比例的，投资管理人应当在可上市交易之日起10个交易日内调整完毕。"},{"i":53,"n":"第五十三条","txt":"企业年金基金证券交易以现货和国务院规定的其他方式进行，不得用于向他人贷款和提供担保。 投资管理人不得从事使企业年金基金财产承担无限责任的投资。"},{"i":54,"n":"第五十四条","txt":"账户管理人应当采用份额计量方式进行账户管理，根据企业年金基金单位净值，按周或者按日足额记入企业年金基金企业账户和个人账户。"},{"i":55,"n":"第五十五条","txt":"受托人年度提取的管理费不高于受托管理企业年金基金财产净值的0.2%。"},{"i":56,"n":"第五十六条","txt":"账户管理人的管理费按照每户每月不超过5元人民币的限额，由建立企业年金计划的企业另行缴纳。 保留账户和退休人员账户的账户管理费可以按照合同约定由受益人自行承担，从受益人个人账户中扣除。"},{"i":57,"n":"第五十七条","txt":"托管人年度提取的管理费不高于托管企业年金基金财产净值的0.2%。"},{"i":58,"n":"第五十八条","txt":"投资管理人年度提取的管理费不高于投资管理企业年金基金财产净值的1.2%。"},{"i":59,"n":"第五十九条","txt":"根据企业年金基金管理情况，人力资源社会保障部会同中国银监会、中国证监会和中国保监会，适时对有关管理费进行调整。"},{"i":60,"n":"第六十条","txt":"投资管理人从当期收取的管理费中，提取20%作为企业年金基金投资管理风险准备金，专项用于弥补合同终止时所管理投资组合的企业年金基金当期委托投资资产的投资亏损。"},{"i":61,"n":"第六十一条","txt":"当合同终止时，如所管理投资组合的企业年金基金财产净值低于当期委托投资资产的，投资管理人应当用风险准备金弥补该时点的当期委托投资资产亏损，直至该投资组合风险准备金弥补完毕；如所管理投资组合的企业年金基金当期委托投资资产没有发生投资亏损或者风险准备金弥补后有剩余的，风险准备金划归投资管理人所有。"},{"i":62,"n":"第六十二条","txt":"企业年金基金投资管理风险准备金应当存放于投资管理人在托管人处开立的专用存款账户，余额达到投资管理人所管理投资组合基金财产净值的10%时可以不再提取。托管人不得对投资管理风险准备金账户收取费用。"},{"i":63,"n":"第六十三条","txt":"风险准备金由投资管理人进行管理，可以投资于银行存款、国债等高流动性、低风险金融产品。风险准备金产生的投资收益，应当纳入风险准备金管理。"},{"i":64,"n":"第六十四条","txt":"企业年金单一计划指受托人将单个委托人交付的企业年金基金，单独进行受托管理的企业年金计划。 企业年金集合计划指同一受托人将多个委托人交付的企业年金基金，集中进行受托管理的企业年金计划。"},{"i":65,"n":"第六十五条","txt":"法人受托机构设立集合计划，应当制定集合计划受托管理合同，为每个集合计划确定账户管理人、托管人各一名，投资管理人至少三名；并分别与其签订委托管理合同。 集合计划受托人应当将制定的集合计划受托管理合同、签订的委托管理合同以及该集合计划的投资组合说明书报人力资源社会保障部备案。"},{"i":66,"n":"第六十六条","txt":"一个企业年金方案的委托人只能建立一个企业年金单一计划或者参加一个企业年金集合计划。委托人加入集合计划满3年后，方可根据受托管理合同规定选择退出集合计划。"},{"i":67,"n":"第六十七条","txt":"发生下列情形之一的，企业年金单一计划变更： （一）企业年金计划受托人、账户管理人、托管人或者投资管理人变更； （二）企业年金基金管理合同主要内容变更； （三）企业年金计划名称变更； （四）国家规定的其他情形。 发生前款规定情形时，受托人应当将相关企业年金基金管理合同重新报人力资源社会保障行政部门备案。"},{"i":68,"n":"第六十八条","txt":"企业年金单一计划终止时，受托人应当组织清算组对企业年金基金财产进行清算。清算费用从企业年金基金财产中扣除。 清算组由企业代表、职工代表、受托人、账户管理人、托管人、投资管理人以及由受托人聘请的会计师事务所、律师事务所等组成。 清算组应当自清算工作完成后3个月内，向人力资源社会保障行政部门和受益人提交经会计师事务所审计以及律师事务所出具法律意见书的清算报告。 人力资源社会保障行政部门应当注销该企业年金计划。"},{"i":69,"n":"第六十九条","txt":"受益人工作单位发生变化，新工作单位已经建立企业年金计划的，其企业年金个人账户权益应当转入新工作单位的企业年金计划管理。新工作单位没有建立企业年金计划的，其企业年金个人账户权益可以在原法人受托机构发起的集合计划设置的保留账户统一管理；原受托人是企业年金理事会的，由企业与职工协商选择法人受托机构管理。"},{"i":70,"n":"第七十条","txt":"企业年金单一计划终止时，受益人企业年金个人账户权益应当转入原法人受托机构发起的集合计划设置的保留账户统一管理；原受托人是企业年金理事会的，由企业与职工协商选择法人受托机构管理。"},{"i":71,"n":"第七十一条","txt":"发生以下情形之一的，受托人应当聘请会计师事务所对企业年金计划进行审计。审计费用从企业年金基金财产中扣除。 （一）企业年金计划连续运作满三个会计年度时； （二）企业年金计划管理人职责终止时； （三）国家规定的其他情形。 账户管理人、托管人、投资管理人应当自上述情况发生之日起配合会计师事务所对企业年金计划进行审计。受托人应当自上述情况发生之日起的50日内向委托人以及人力资源社会保障行政部门提交审计报告。"},{"i":72,"n":"第七十二条","txt":"受托人应当在每季度结束后30日内向委托人提交企业年金基金管理季度报告；并应当在年度结束后60日内向委托人提交企业年金基金管理和财务会计年度报告。"},{"i":73,"n":"第七十三条","txt":"账户管理人应当在每季度结束后15日内向受托人提交企业年金基金账户管理季度报告；并应当在年度结束后45日内向受托人提交企业年金基金账户管理年度报告。"},{"i":74,"n":"第七十四条","txt":"托管人应当在每季度结束后15日内向受托人提交企业年金基金托管和财务会计季度报告；并应当在年度结束后45日内向受托人提交企业年金基金托管和财务会计年度报告。"},{"i":75,"n":"第七十五条","txt":"投资管理人应当在每季度结束后15日内向受托人提交经托管人确认财务管理数据的企业年金基金投资组合季度报告；并应当在年度结束后45日内向受托人提交经托管人确认财务管理数据的企业年金基金投资管理年度报告。"},{"i":76,"n":"第七十六条","txt":"法人受托机构、账户管理人、托管人和投资管理人发生下列情形之一的，应当及时向人力资源社会保障部报告；账户管理人、托管人和投资管理人应当同时抄报受托人。 （一）减资、合并、分立、依法解散、被依法撤销、决定申请破产或者被申请破产的； （二）涉及重大诉讼或者仲裁的； （三）董事长、总经理、直接负责企业年金业务的高级管理人员发生变动的； （四）国家规定的其他情形。"},{"i":77,"n":"第七十七条","txt":"受托人、账户管理人、托管人和投资管理人应当按照规定报告企业年金基金管理情况，并对所报告内容的真实性、完整性负责。"},{"i":78,"n":"第七十八条","txt":"法人受托机构、账户管理人、托管人、投资管理人开展企业年金基金管理相关业务，应当向人力资源社会保障部提出申请。法人受托机构、账户管理人、投资管理人向人力资源社会保障部提出申请前应当先经其业务监管部门同意，托管人向人力资源社会保障部提出申请前应当先向其业务监管部门备案。"},{"i":79,"n":"第七十九条","txt":"人力资源社会保障部收到法人受托机构、账户管理人、托管人、投资管理人的申请后，应当组织专家评审委员会，按照规定进行审慎评审。经评审符合条件的，由人力资源社会保障部会同有关部门确认公告；经评审不符合条件的，应当书面通知申请人。 专家评审委员会由有关部门代表和社会专业人士组成。每次参加评审的专家应当从专家评审委员会中随机抽取产生。"},{"i":80,"n":"第八十条","txt":"受托人、账户管理人、托管人、投资管理人开展企业年金基金管理相关业务，应当接受人力资源社会保障行政部门的监管。 法人受托机构、账户管理人、托管人和投资管理人的业务监管部门按照各自职责对其经营活动进行监督。"},{"i":81,"n":"第八十一条","txt":"人力资源社会保障部依法履行监督管理职责，可以采取以下措施： （一）查询、记录、复制与被调查事项有关的企业年金基金管理合同、财务会计报告等资料； （二）询问与调查事项有关的单位和个人，要求其对有关问题做出说明、提供有关证明材料； （三）国家规定的其他措施。 委托人、受托人、账户管理人、托管人、投资管理人和其他为企业年金基金管理提供服务的自然人、法人或者其他组织，应当积极配合检查，如实提供有关资料，不得拒绝、阻挠或者逃避检查，不得谎报、隐匿或者销毁相关证据材料。"},{"i":82,"n":"第八十二条","txt":"人力资源社会保障部依法进行调查或者检查时，应当至少由两人共同进行，并出示证件，承担下列义务： （一）依法履行职责，秉公执法，不得利用职务之便谋取私利; （二）保守在调查或者检查时知悉的商业秘密； （三）为举报人员保密。"},{"i":83,"n":"第八十三条","txt":"法人受托机构、中央企业集团公司成立的企业年金理事会、账户管理人、托管人、投资管理人违反本办法规定或者企业年金基金管理费、信息披露相关规定的，由人力资源社会保障部责令改正。其他企业（包括中央企业子公司）成立的企业年金理事会，违反本办法规定或者企业年金基金管理费、信息披露相关规定的，由管理合同备案所在地的省、自治区、直辖市或者计划单列市人力资源社会保障行政部门责令改正。"},{"i":84,"n":"第八十四条","txt":"受托人、账户管理人、托管人、投资管理人发生违法违规行为可能影响企业年金基金财产安全的，或者经责令改正而不改正的，由人力资源社会保障部暂停其接收新的企业年金基金管理业务。给企业年金基金财产或者受益人利益造成损害的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任。"},{"i":85,"n":"第八十五条","txt":"人力资源社会保障部将法人受托机构、账户管理人、托管人、投资管理人违法行为、处理结果以及改正情况予以记录，同时抄送业务监管部门。在企业年金基金管理资格有效期内，有三次以上违法记录或者一次以上经责令改正而不改正的，在其资格到期之后5年内，不再受理其开展企业年金基金管理业务的申请。"},{"i":86,"n":"第八十六条","txt":"会计师事务所和律师事务所提供企业年金中介服务应当严格遵守相关职业准则和行业规范。"},{"i":87,"n":"第八十七条","txt":"企业年金基金管理，国务院另有规定的，从其规定。"},{"i":88,"n":"第八十八条","txt":"本办法自2011年5月1日起施行。劳动和社会保障部、中国银行业监督管理委员会、中国证券监督管理委员会、中国保险监督管理委员会于2004年2月23日发布的《企业年金基金管理试行办法》(劳动保障部令第23号)同时废止。"}],"qiyenianjinjijinguanlijigouzigerendingzanxingbanfa":[{"i":1,"n":"第一条","txt":"为规范企业年金基金管理机构资格认定工作，根据《中华人民共和国行政许可法》、《国务院对确需保留的行政审批项目设定行政许可的决定》和国家有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称企业年金基金管理机构，是指从事企业年金基金管理业务的法人受托机构、账户管理人、托管人和投资管理人等补充养老保险经办机构。"},{"i":3,"n":"第三条","txt":"从事企业年金基金管理业务的机构，必须根据本办法规定的程序，取得相应的企业年金基金管理资格。 劳动保障部负责企业年金基金管理机构资格认定。"},{"i":4,"n":"第四条","txt":"申请企业年金基金管理资格的机构（以下简称申请人）应当按照本办法附件规定的内容与格式，向劳动保障部提出书面申请。"},{"i":5,"n":"第五条","txt":"法人受托机构应当具备下列条件： （一）经国家金融监管部门批准，在中国境内注册； （二）具有完善的法人治理结构； （三）取得企业年金基金从业资格的专职人员达到规定人数； （四）具有符合要求的营业场所、安全防范设施和与企业年金基金受托管理业务有关的其他设施； （五）具有完善的内部稽核监控制度和风险控制制度； （六）近3年没有重大违法违规行为； （七）国家规定的其他条件。"},{"i":6,"n":"第六条","txt":"账户管理人应当具备下列条件： （一）经国家有关部门批准，在中国境内注册的独立法人； （二）具有完善的法人治理结构； （三）取得企业年金基金从业资格的专职人员达到规定人数； （四）具有相应的企业年金基金账户管理信息系统； （五）具有符合要求的营业场所、安全防范设施和与企业年金基金账户管理业务有关的其他设施； （六）具有完善的内部稽核监控制度和风险控制制度； （七）国家规定的其他条件。 本条第（四）项规定的企业年金基金账户管理信息系统规范，由劳动保障部另行制定。"},{"i":7,"n":"第七条","txt":"托管人应当具备下列条件： （一）经国家金融监管部门批准，在中国境内注册的独立法人； （二）净资产不少于50亿元人民币； （三）取得企业年金基金从业资格的专职人员达到规定人数； （四）具有保管企业年金基金财产的条件； （五）具有安全高效的清算、交割系统； （六）具有符合要求的营业场所、安全防范设施和与企业年金基金托管业务有关的其他设施； （七）具有完善的内部稽核监控制度和风险控制制度； （八）国家规定的其他条件。 商业银行担任托管人，应当设有专门的基金托管部门。"},{"i":8,"n":"第八条","txt":"投资管理人应当具备下列条件： （一）经国家金融监管部门批准，在中国境内注册，具有受托投资管理、基金管理或者资产管理资格的独立法人； （二）具有完善的法人治理结构； （三）取得企业年金基金从业资格的专职人员达到规定人数； （四）具有符合要求的营业场所、安全防范设施和与企业年金基金投资管理业务有关的其他设施； （五）具有完善的内部稽核监控制度和风险控制制度； （六）近3年没有重大违法违规行为； （七）国家规定的其他条件。"},{"i":9,"n":"第九条","txt":"劳动保障部对申请人提出的申请，应当根据下列情况分别作出处理： （一）申请材料存在可以当场更正错误的，应当允许申请人当场更正； （二）申请材料不齐全或者不符合法定形式的，应当场或者在5个工作日内1次告知申请人需要补正的全部内容。逾期不告知的，自收到申请材料之日起即为受理； （三）申请材料齐全、符合法定形式，或者申请人按照要求提交全部补正申请材料的，劳动保障部应当受理申请人申请。 劳动保障部受理或者不受理申请人申请，应当出具加盖劳动保障部专用印章和注明日期的书面凭证。 正在接受司法机关或者有关监管机关立案调查的机构，在被调查期间，劳动保障部不受理其申请。"},{"i":10,"n":"第十条","txt":"劳动保障部受理申请人申请后，应当组建专家评审委员会对申请材料进行评审。评审委员会专家按照专业范围从专家库中随机抽取产生。专家库由有关部门代表和社会专业人士组成。 专家评审委员会对申请人申请材料按照分期分类的原则进行评审，所需时间由劳动保障部书面告知申请人。"},{"i":11,"n":"第十一条","txt":"劳动保障部认为必要时应当指派2名以上工作人员，根据申请人申请材料对申请人进行现场检查。"},{"i":12,"n":"第十二条","txt":"劳动保障部根据专家评审委员会评审结果及现场检查情况，会商中国银监会、中国证监会、中国保监会后，认定企业年金基金管理机构资格，并于认定之日起10个工作日内，向申请人颁发《企业年金基金管理资格证书》。证书制式由劳动保障部统一印制。 对于未取得企业年金基金管理资格的申请人，由劳动保障部书面通知，说明理由并告知申请人享有依法申请行政复议或者提起行政诉讼的权利。"},{"i":13,"n":"第十三条","txt":"劳动保障部会同中国银监会、中国证监会、中国保监会，在全国性报刊上公告取得企业年金基金管理资格的机构。"},{"i":14,"n":"第十四条","txt":"企业年金基金管理机构的资格证书有效期为3年，期限届满前3个月应当向劳动保障部提出延续申请。"},{"i":15,"n":"第十五条","txt":"有下列情形之一的，劳动保障部应当办理企业年金基金管理机构资格的注销手续： （一）企业年金基金管理机构资格有效期届满未延续的； （二）企业年金基金管理机构依法解散、被依法撤销、被依法宣告破产或者被依法接管的； （三）企业年金基金管理机构资格被依法撤销的； （四）国家规定的应当注销企业年金基金管理机构资格的其他情形。 劳动保障部办理企业年金基金管理机构资格的注销手续后，会同中国银监会、中国证监会、中国保监会，在全国性报刊上公告。"},{"i":16,"n":"第十六条","txt":"申请人隐瞒有关情况或者提供虚假材料的，劳动保障部不予受理或者不予认定企业年金基金管理机构资格，并给予警告；申请人1年内不得再次申请企业年金基金管理机构资格。"},{"i":17,"n":"第十七条","txt":"申请人采用贿赂、欺诈等不正当手段取得企业年金基金管理机构资格的，劳动保障部会商中国银监会、中国证监会、中国保监会后取消其资格；申请人3年内不得再次申请企业年金基金管理机构资格；构成犯罪的，移交司法机关依法追究刑事责任。"},{"i":18,"n":"第十八条","txt":"劳动保障部建立健全企业年金基金监管制度，定期或者不定期对有关机构企业年金基金管理运营情况进行监督检查。"},{"i":19,"n":"第十九条","txt":"本办法自2005年3月1日起施行。"}],"qiyejingjixingcaijianrenyuanguiding":[{"i":1,"n":"第一条","txt":"为指导用人单位依法正确行使裁减人员权利，根据《中华人民共和国劳动法》的有关规定，制定本规定。"},{"i":2,"n":"第二条","txt":"用人单位濒临破产，被人民法院宣告进入法定整顿期间或生产经营发生严重困难，达到当地政府规定的严重困难企业标准，确需裁减人员的，可以裁员。"},{"i":3,"n":"第三条","txt":"用人单位有条件的，应为被裁减的人员提供培训或就业帮助。"},{"i":4,"n":"第四条","txt":"用人单位确需裁减人员，应按下列程序进行： （一）提前三十日向工会或者全体职工说明情况，并提供有关生产经营状况的资料； （二）提出裁减人员方案，内容包括：被裁减人员名单，裁减时间及实施步骤，符合法律、法规规定和集体合同约定的被裁减人员经济补偿办法； （三）将裁减人员方案征求工会或者全体职工的意见，并对方案进行修改和完善； （四）向当地劳动行政部门报告裁减人员方案以及工会或者全体职工的意见，并听取劳动行政部门的意见； （五）由用人单位正式公布裁减人员方案，与被裁减人员办理解除劳动合同手续，按照有关规定向被裁减人员本人支付经济补偿金，出具裁减人员证明书。"},{"i":5,"n":"第五条","txt":"用人单位不得裁减下列人员： （一）患职业病或者因工负伤并被确认丧失或者部分丧失劳动能力的； （二）患病或者负伤，在规定的医疗期内的； （三）女职工在孕期、产期、哺乳期内的； （四）法律、行政法规规定的其他情形。"},{"i":6,"n":"第六条","txt":"对于被裁减而失业的人员，参加失业保险的，可到当地劳动就业服务机构登记，申领失业救济金。"},{"i":7,"n":"第七条","txt":"用人单位从裁减人员之日起，六个月内需要新招人员的，必须优先从本单位裁减的人员中录用，并向当地劳动行政部门报告录用人员的数量、时间、条件以及优先录用人员的情况。"},{"i":8,"n":"第八条","txt":"劳动行政部门对用人单位违反法律、法规和有关规定裁减人员的，应依法制止和纠正。"},{"i":9,"n":"第九条","txt":"工会或职工对裁员提出的合理意见，用人单位应认真听取。 用人单位违反法律、法规规定和集体合同约定裁减人员的，工会有权要求重新处理。"},{"i":10,"n":"第十条","txt":"因裁减人员发生的劳动争议，当事人双方应按照劳动争议处理的有关规定执行。"},{"i":11,"n":"第十一条","txt":"各省、自治区、直辖市劳动行政部门可根据本规定和本地区实际情况制定实施办法。"},{"i":12,"n":"第十二条","txt":"本规定自1995年１月１日起施行。"}],"qiyezhigongdaixinnianxiujiashishibanfa":[{"i":1,"n":"第一条","txt":"为了实施《职工带薪年休假条例》（以下简称条例），制定本实施办法。"},{"i":2,"n":"第二条","txt":"中华人民共和国境内的企业、民办非企业单位、有雇工的个体工商户等单位（以下称用人单位）和与其建立劳动关系的职工，适用本办法。"},{"i":3,"n":"第三条","txt":"职工连续工作满12个月以上的，享受带薪年休假（以下简称年休假）。"},{"i":4,"n":"第四条","txt":"年休假天数根据职工累计工作时间确定。职工在同一或者不同用人单位工作期间，以及依照法律、行政法规或者国务院规定视同工作期间，应当计为累计工作时间。"},{"i":5,"n":"第五条","txt":"职工新进用人单位且符合本办法第三条规定的，当年度年休假天数，按照在本单位剩余日历天数折算确定，折算后不足1整天的部分不享受年休假。 前款规定的折算方法为：（当年度在本单位剩余日历天数÷365天）×职工本人全年应当享受的年休假天数。"},{"i":6,"n":"第六条","txt":"职工依法享受的探亲假、婚丧假、产假等国家规定的假期以及因工伤停工留薪期间不计入年休假假期。"},{"i":7,"n":"第七条","txt":"职工享受寒暑假天数多于其年休假天数的，不享受当年的年休假。确因工作需要,职工享受的寒暑假天数少于其年休假天数的，用人单位应当安排补足年休假天数。"},{"i":8,"n":"第八条","txt":"职工已享受当年的年休假，年度内又出现条例第四条第 （二）、（三）、（四）、（五）项规定情形之一的，不享受下一年度的年休假。"},{"i":9,"n":"第九条","txt":"用人单位根据生产、工作的具体情况，并考虑职工本人意愿，统筹安排年休假。用人单位确因工作需要不能安排职工年休假或者跨1个年度安排年休假的，应征得职工本人同意。"},{"i":10,"n":"第十条","txt":"用人单位经职工同意不安排年休假或者安排职工年休假天数少于应休年休假天数，应当在本年度内对职工应休未休年休假天数，按照其日工资收入的300%支付未休年休假工资报酬，其中包含用人单位支付职工正常工作期间的工资收入。 用人单位安排职工休年休假，但是职工因本人原因且书面提出不休年休假的，用人单位可以只支付其正常工作期间的工资收入。"},{"i":11,"n":"第十一条","txt":"计算未休年休假工资报酬的日工资收入按照职工本人的月工资除以月计薪天数  （21.75天）进行折算。 前款所称月工资是指职工在用人单位支付其未休年休假工资报酬前12个月剔除加班工资后的月平均工资。在本用人单位工作时间不满12个月的，按实际月份计算月平均工资。 职工在年休假期间享受与正常工作期间相同的工资收入。实行计件工资、提成工资或者其他绩效工资制的职工，日工资收入的计发办法按照本条第一款、第二款的规定执行。"},{"i":12,"n":"第十二条","txt":"用人单位与职工解除或者终止劳动合同时，当年度未安排职工休满应休年休假天数的，应当按照职工当年已工作时间折算应休未休年休假天数并支付未休年休假工资报酬，但折算后不足1整天的部分不支付未休年休假工资报酬。 前款规定的折算方法为：（当年度在本单位已过日历天数÷365天）×职工本人全年应当享受的年休假天数-当年度已安排年休假天数。 用人单位当年已安排职工年休假的，多于折算应休年休假的天数不再扣回。"},{"i":13,"n":"第十三条","txt":"劳动合同、集体合同约定的或者用人单位规章制度规定的年休假天数、未休年休假工资报酬高于法定标准的，用人单位应当按照有关约定或者规定执行。"},{"i":14,"n":"第十四条","txt":"劳务派遣单位的职工符合本办法第三条规定条件的，享受年休假。 被派遣职工在劳动合同期限内无工作期间由劳务派遣单位依法支付劳动报酬的天数多于其全年应当享受的年休假天数的，不享受当年的年休假；少于其全年应当享受的年休假天数的，劳务派遣单位、用工单位应当协商安排补足被派遣职工年休假天数。"},{"i":15,"n":"第十五条","txt":"县级以上地方人民政府劳动行政部门应当依法监督检查用人单位执行条例及本办法的情况。 用人单位不安排职工休年休假又不依照条例及本办法规定支付未休年休假工资报酬的，由县级以上地方人民政府劳动行政部门依据职权责令限期改正；对逾期不改正的，除责令该用人单位支付未休年休假工资报酬外，用人单位还应当按照未休年休假工资报酬的数额向职工加付赔偿金；对拒不执行支付未休年休假工资报酬、赔偿金行政处理决定的，由劳动行政部门申请人民法院强制执行。"},{"i":16,"n":"第十六条","txt":"职工与用人单位因年休假发生劳动争议的，依照劳动争议处理的规定处理。"},{"i":17,"n":"第十七条","txt":"除法律、行政法规或者国务院另有规定外，机关、事业单位、社会团体和与其建立劳动关系的职工，依照本办法执行。 船员的年休假按《中华人民共和国船员条例》执行。"},{"i":18,"n":"第十八条","txt":"本办法中的 “年度”是指公历年度。"},{"i":19,"n":"第十九条","txt":"本办法自发布之日起施行。"}],"qiyezhigonghuanbinghuofeiyingongfushangyiliaoqigui870f40":[{"i":1,"n":"第一条","txt":"为了保障企业职工在患病或非因工负伤期间的合法权益，根据《中华人民共和国劳动法》第二十六、二十九条规定，制定本规定。"},{"i":2,"n":"第二条","txt":"医疗期是指企业职工因患病或非因工负伤停止工作治病休息不得解除劳动合同的时限。"},{"i":3,"n":"第三条","txt":"企业职工因患病或非因工负伤，需要停止工作医疗时，根据本人实际参加工作年限和在本单位工作年限，给予三个月到二十四个月的医疗期： （一）实际工作年限十年以下的，在本单位工作年限五年以下的为三个月；五年以上的为六个月。 （二）实际工作年限十年以上的，在本单位工作年限五年以下的为六个月；五年以上十年以下的为九个月；十年以上十五年以下的为十二个月；十五年以上二十年以下的为十八个月；二十年以上的为二十四个月。"},{"i":4,"n":"第四条","txt":"医疗期三个月的按六个月内累计病休时间计算；六个月的按十二个月内累计病休时间计算；九个月的按十五个月内累计病休时间计算；十二个月的按十八个月内累计病休时间计算；十八个月的按二十四个月内累计病休时间计算；二十四个月的按三十个月内累计病休时间计算。"},{"i":5,"n":"第五条","txt":"企业职工在医疗期内，其病假工资、疾病救济费和医疗待遇按照有关规定执行。"},{"i":6,"n":"第六条","txt":"企业职工非因工致残和经医生或医疗机构认定患有难以治疗的疾病，在医疗期内医疗终结，不能从事原工作，也不能从事用人单位另行安排的工作的，应当由劳动鉴定委员会参照工伤与职业病致残程度鉴定标准进行劳动能力的鉴定。被鉴定为一至四级的，应当退出劳动岗位，终止劳动关系，办理退休、退职手续，享受退休、退职待遇；被鉴定为五至十级的，医疗期内不得解除劳动合同。"},{"i":7,"n":"第七条","txt":"企业职工非因工致残和经医生或医疗机构认定患有难以治疗的疾病，医疗期满，应当由劳动鉴定委员会参照工伤与职业病致残程度鉴定标准进行劳动能力的鉴定。被鉴定为一至四级的，应当退出劳动岗位，解除劳动关系，并办理退休、退职手续，享受退休、退职待遇。"},{"i":8,"n":"第八条","txt":"医疗期满尚未痊愈者，被解除劳动合同的经济补偿问题按照有关规定执行。"},{"i":9,"n":"第九条","txt":"本规定自一九九五年一月一日起施行。"}],"qishiyedanweipingpinzhuanyejishuzhiwuruoganwentiza6952a3":[],"quanminsuoyouzhijiguanshiyedanweizhigongrenshuhego0dc08b":[{"i":1,"n":"第一条","txt":"为了加强全民所有制机关、事业单位职工人数和工资总额的计划管理，强化政府人事部门宏观调控职能，使计划管理科学化、规范化、制度化，特制定本暂行办法。"},{"i":2,"n":"第二条","txt":"全民所有制机关、事业单位职工人数和工资总额计划（以下简称计划），是国民经济和社会发展计划的重要组成部分，在国家劳动工资计划中单列，由各级政府人事部门负责编制和管理，实行统一计划，分级管理。"},{"i":3,"n":"第三条","txt":"计划管理范围是： （一）各级国家机关、政党机关、社会团体； （二）上述机关、团体所属的事业单位； （三）国家规定的其他应纳入机关、事业单位计划管理的部门和单位。"},{"i":4,"n":"第四条","txt":"计划工作的基本任务： （一）贯彻执行计划期党和国家提出的政治、经济、社会发展任务和重大方针政策。 （二）根据国民经济和社会发展计划要求，编制机关、事业单位职工人数、工资总额的长期规划和年度计划，合理确定机关、事业单位的职工人数和工资总额增长幅度。 （三）贯彻按劳分配原则，合理确定调整部门、地区以及各类人员之间的工资关系。 （四）按照节约、高效的原则，合理配置人力资源，调整职工队伍的布局和结构，促进人才合理流动。 （五）根据经济体制和政治体制改革的要求，不断改革和完善计划管理体制。"},{"i":5,"n":"第五条","txt":"计划由下列主要指标构成： （一）基期末预计到达数； （二）计划期计划增加（减少）数； （三）计划期末计划到达数。"},{"i":6,"n":"第六条","txt":"计划期职工人数增减包括： （一）新增职工： 1.国家统一分配的人员； 2.社会招收人员； 3.调入人员； 4.成建制划入的人员； 5.其他人员。 （二）减少职工： 1.自然减员减少的人员； 2.调出人员； 3.成建制划出的人员； 4.其他人员。"},{"i":7,"n":"第七条","txt":"计划期工资总额增减包括： （一）新增工资总额： 1.增加职工增资； 2.转正定级增资； 3.工龄、教龄、护龄津贴增长； 4.国家统一安排的新增工资项目； 5.上年增资项目翘尾； 6.晋职晋级增资； 7.增加奖金； 8.成建制划入的工资额； 9.国家规定的其他项目。 （二）减少工资总额： 1.减人减少工资； 2.掉尾工资； 3.减补员工资差额； 4.超编制单位的工资核减； 5.成建制划出的工资额； 6.其他。"},{"i":8,"n":"第八条","txt":"编制计划须具备下列资料： （一）基期计划执行情况； （二）基期和计划期国民生产总值、国民收入、社会总产值、社会劳动生产率、工业企业全员劳动生产率预计到达数和计划数； （三）基期和计划期社会商品零售物价指数、职工生活费用价格指数预计到达数和计划数； （四）基期城乡居民生活水平变动情况及计划期国家提高城乡居民生活水平的有关政策、措施； （五）计划期各项事业发展计划、重点发展领域及有关政策规定； （六）就业结构及职业需求结构与数量； （七）财政收支情况； （八）行政事业经费开支情况； （九）机构、编制定员情况； （十）新增劳动力资源，特别是干部资源状况及可供机关事业单位利用程度。"},{"i":9,"n":"第九条","txt":"报批计划按下列程序和要求进行： （一）各省、自治区、直辖市及计划单列市和国务院各部委、各直属机构的人事部门，根据人事部提出的编制计划的指导原则和政策，按照国家下达的控制数字和表式要求结合本地区、本部门的实际情况，在计划部门的指导下，经过科学的预测分析自下而上地编制计划草案，并附文字报告和详细说明，于每年九月底以前报送人事部。同时，抄送同级计划、劳动部门。 （二）人事部在汇总、审核各地区、各部门计划草案的基础上，经过综合平衡，提出分地区、分部门计划建议方案。 （三）人事部通过一定形式听取地区、部门意见后，对计划建议方案进行必要的调整，按要求时间报国家计委，同时抄送劳动部，由国家计委综合平衡后，纳入国民经济和社会发展计划（草案）。"},{"i":10,"n":"第十条","txt":"各地区、各部门在接到人事部下达的计划后，应尽快将计划逐级下达到基层。"},{"i":11,"n":"第十一条","txt":"各级人事部门在下达计划的同时，应将计划抄送同级计划、劳动部门和有关开户银行。"},{"i":12,"n":"第十二条","txt":"各地区、各部门在执行计划过程中，如发现计划与实际不符确需调整计划时，应于当年八月底前向人事部提出调整计划的报告，人事部应及时批复。未经人事部批准，不得自行修改计划。"},{"i":13,"n":"第十三条","txt":"凡属本办法《第七条》和《第八条》规定增加的职工和工资，均应纳入计划管理范围。未经国家核准不得超计划增人、增资。"},{"i":14,"n":"第十四条","txt":"根据编制定员确定增人指标。凡已满编或超编的单位，除国家另有规定外，一律不分配增人指标。确需增人时，须先申请增加编制。超编单位要逐年核减其职工人数和工资总额。"},{"i":15,"n":"第十五条","txt":"中央、国务院驻地方的机关和事业单位，根据工作需要和国家规定接收军队转业干部和城镇复退军人时，其劳动指标由当地予以划拨。"},{"i":16,"n":"第十六条","txt":"国家下达的年度计划指标（含自然减员指标）除国家另有规定外不得跨年度使用。"},{"i":17,"n":"第十七条","txt":"补充自然减员指标，由各地区、各部门按照国家有关规定使用。"},{"i":18,"n":"第十八条","txt":"各地区、各部门的人事部门应根据计划指标，对计划执行情况定期进行检查与考核，发现问题及时解决。每年集中检查两次：第一次在第三季度；第二次在下年的第一季度。每次的检查结果（附详细说明），以书面形式报送人事部。"},{"i":19,"n":"第十九条","txt":"各级人事计划部门，要制定具体指标，定期对下级人事计划部门的工作进行考核和评估。"},{"i":20,"n":"第二十条","txt":"必须维护计划的严肃性。充分发挥审计、银行等部门的监督作用。对于乱开口子，超计划增人增资的地区、部门，除在安排下年度计划时，相应核减其指标外，还应视情节轻重对责任单位，给予通报批评。对严格执行国家计划、成绩显著的单位，给予表扬和奖励。"},{"i":21,"n":"第二十一条","txt":"统计资料是编制计划的重要依据，统计是检查和控制计划执行情况的重要手段。各级人事部门必须按照有关规定，准确、全面、系统地搜集、整理和分析统计资料，并及时报送有关部门，为研究问题，制定政策、指导工作提供依据。"},{"i":22,"n":"第二十二条","txt":"各地区、各部门可根据本办法制定实施细则。"},{"i":23,"n":"第二十三条","txt":"本办法由人事部综合计划司负责解释。"},{"i":24,"n":"第二十四条","txt":"本办法自下达之日起试行。"}],"guanyuzhongwaihezirencaizhongjiejigouguanlizanxingef9bff":[],"guanyuqiyeshixingbudingshigongzuozhihezonghejisuan0f911d":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国劳动法》第三十九条的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于中华人民共和国境内的企业。"},{"i":3,"n":"第三条","txt":"企业因生产特点不能实行《中华人民共和国劳动法》第三十六条、第三十八条规定的，可以实行不定时工作制或综合计算工时工作制等其他工作和休息办法。"},{"i":4,"n":"第四条","txt":"企业对符合下列条件之一的职工，可以实行不定时工作制。 （一）企业中的高级管理人员、外勤人员、推销人员、部分值班人员和其他因工作无法按标准工作时间衡量的职工； （二）企业中的长途运输人员、出租汽车司机和铁路、港口、仓库的部分装卸人员以及因工作性质特殊，需机动作业的职工； （三）其他因生产特点、工作特殊需要或职责范围的关系，适合实行不定时工作制的职工。"},{"i":5,"n":"第五条","txt":"企业对符合下列条件之一的职工，可实行综合计算工时工作制，即分别以周、月、季、年等为周期，综合计算工作时间，但其平均日工作时间和平均周工作时间应与法定标准工作时间基本相同。 （一）交通、铁路、邮电、水运、航空、渔业等行业中因工作性质特殊，需连续作业的职工； （二）地质及资源勘探、建筑、制盐、制糖、旅游等受季节和自然条件限制的行业的部分职工； （三）其他适合实行综合计算工时工作制的职工。"},{"i":6,"n":"第六条","txt":"对于实行不定时工作制和综合计算工时工作制等其他工作和休息办法的职工，企业应根据《中华人民共和国劳动法》第一章、第四章有关规定，在保障职工身体健康并充分听取职工意见的基础上，采用集中工作、集中休息、轮休调休、弹性工作时间等适当方式，确保职工的休息休假权利和生产、工作任务的完成。"},{"i":7,"n":"第七条","txt":"中央直属企业实行不定时工作制和综合计算工时工作制等其他工作和休息办法的，经国务院行业主管部门审核，报国务院劳动行政部门批准。 地方企业实行不定时工作制和综合计算工时工作制等其他工作和休息办法的审批办法，由各省、自治区、直辖市人民政府劳动行政部门制定，报国务院劳动行政部门备案。"},{"i":8,"n":"第八条","txt":"本办法自一九九五年一月一日起施行。"}],"guanyushishilaodongbaozhangjianchatiaoliruoganguid320527":[{"i":1,"n":"第一条","txt":"为了实施《劳动保障监察条例》，规范劳动保障监察行为，制定本规定。"},{"i":2,"n":"第二条","txt":"劳动保障行政部门及所属劳动保障监察机构对企业和个体工商户（以下称用人单位）遵守劳动保障法律、法规和规章（以下简称劳动保障法律）的情况进行监察，适用本规定；对职业介绍机构、职业技能培训机构和职业技能考核鉴定机构进行劳动保障监察，依照本规定执行；对国家机关、事业单位、社会团体执行劳动保障法律情况进行劳动保障监察，根据劳动保障行政部门的职责，依照本规定执行。"},{"i":3,"n":"第三条","txt":"劳动保障监察遵循公正、公开、高效、便民的原则。 实施劳动保障行政处罚坚持以事实为依据，以法律为准绳，坚持教育与处罚相结合，接受社会监督。"},{"i":4,"n":"第四条","txt":"劳动保障监察实行回避制度。"},{"i":5,"n":"第五条","txt":"县级以上劳动保障行政部门设立的劳动保障监察行政机构和劳动保障行政部门依法委托实施劳动保障监察的组织（以下统称劳动保障监察机构）具体负责劳动保障监察管理工作。"},{"i":6,"n":"第六条","txt":"劳动保障行政部门对用人单位及其劳动场所的日常巡视检查，应当制定年度计划和中长期规划，确定重点检查范围，并按照现场检查的规定进行。"},{"i":7,"n":"第七条","txt":"劳动保障行政部门对用人单位按照要求报送的有关遵守劳动保障法律情况的书面材料应进行审查，并对审查中发现的问题及时予以纠正和查处。"},{"i":8,"n":"第八条","txt":"劳动保障行政部门可以针对劳动保障法律实施中存在的重点问题集中组织专项检查活动，必要时，可以联合有关部门或组织共同进行。"},{"i":9,"n":"第九条","txt":"劳动保障行政部门应当设立举报、投诉信箱，公开举报、投诉电话，依法查处举报和投诉反映的违反劳动保障法律的行为。"},{"i":10,"n":"第十条","txt":"任何组织或个人对违反劳动保障法律的行为，有权向劳动保障行政部门举报。"},{"i":11,"n":"第十一条","txt":"劳动保障行政部门对举报人反映的违反劳动保障法律的行为应当依法予以查处，并为举报人保密；对举报属实，为查处重大违反劳动保障法律的行为提供主要线索和证据的举报人，给予奖励。"},{"i":12,"n":"第十二条","txt":"劳动者对用人单位违反劳动保障法律、侵犯其合法权益的行为，有权向劳动保障行政部门投诉。对因同一事由引起的集体投诉，投诉人可推荐代表投诉。"},{"i":13,"n":"第十三条","txt":"投诉应当由投诉人向劳动保障行政部门递交投诉文书。书写投诉文书确有困难的，可以口头投诉，由劳动保障监察机构进行笔录，并由投诉人签字。"},{"i":14,"n":"第十四条","txt":"投诉文书应当载明下列事项： （一）投诉人的姓名、性别、年龄、职业、工作单位、住所和联系方式，被投诉用人单位的名称、住所、法定代表人或者主要负责人的姓名、职务； （二）劳动保障合法权益受到侵害的事实和投诉请求事项。"},{"i":15,"n":"第十五条","txt":"有下列情形之一的投诉，劳动保障行政部门应当告知投诉人依照劳动争议处理或者诉讼程序办理： （一）应当通过劳动争议处理程序解决的； （二）已经按照劳动争议处理程序申请调解、仲裁的； （三）已经提起劳动争议诉讼的。"},{"i":16,"n":"第十六条","txt":"下列因用人单位违反劳动保障法律行为对劳动者造成损害，劳动者与用人单位就赔偿发生争议的，依照国家有关劳动争议处理的规定处理： （一）因用人单位制定的劳动规章制度违反法律、法规规定，对劳动者造成损害的； （二）因用人单位违反对女职工和未成年工的保护规定，对女职工和未成年工造成损害的； （三）因用人单位原因订立无效合同，对劳动者造成损害的； （四）因用人单位违法解除劳动合同或者故意拖延不订立劳动合同，对劳动者造成损害的； （五）法律、法规和规章规定的其他因用人单位违反劳动保障法律的行为，对劳动者造成损害的。"},{"i":17,"n":"第十七条","txt":"劳动者或者用人单位与社会保险经办机构发生的社会保险行政争议，按照《社会保险行政争议处理办法》处理。"},{"i":18,"n":"第十八条","txt":"对符合下列条件的投诉，劳动保障行政部门应当在接到投诉之日起５个工作日内依法受理，并于受理之日立案查处： （一）违反劳动保障法律的行为发生在两年内的； （二）有明确的被投诉用人单位，且投诉人的合法权益受到侵害是被投诉用人单位违反劳动保障法律的行为所造成的； （三）属于劳动保障监察职权范围并由受理投诉的劳动保障行政部门管辖。 对不符合第一款第（一）项规定的投诉，劳动保障行政部门应当在接到投诉之日起５个工作日内决定不予受理，并书面通知投诉人。 对不符合第一款第（二）项规定的投诉，劳动保障监察机构应当告知投诉人补正投诉材料。 对不符合第一款第（三）项规定的投诉，即对不属于劳动保障监察职权范围的投诉，劳动保障监察机构应当告诉投诉人；对属于劳动保障监察职权范围但不属于受理投诉的劳动保障行政部门管辖的投诉，应当告知投诉人向有关劳动保障行政部门提出。"},{"i":19,"n":"第十九条","txt":"劳动保障行政部门通过日常巡视检查、书面审查、举报等发现用人单位有违反劳动保障法律的行为，需要进行调查处理的，应当及时立案查处。 立案应当填写立案审批表，报劳动保障监察机构负责人审查批准。劳动保障监察机构负责人批准之日即为立案之日。"},{"i":20,"n":"第二十条","txt":"劳动保障监察员进行调查、检查不得少于两人。 劳动保障监察机构应指定其中１名为主办劳动保障监察员。"},{"i":21,"n":"第二十一条","txt":"劳动保障监察员对用人单位遵守劳动保障法律情况进行监察时，应当遵循以下规定： （一）进入用人单位时，应佩戴劳动保障监察执法标志，出示劳动保障监察证件，并说明身份； （二）就调查事项制作笔录，应由劳动保障监察员和被调查人（或其委托代理人）签名或盖章。被调查人拒不签名、盖章的，应注明拒签情况。"},{"i":22,"n":"第二十二条","txt":"劳动保障监察员进行调查、检查时，承担下列义务： （一）依法履行职责，秉公执法； （二）保守在履行职责过程中获知的商业秘密； （三）为举报人保密。"},{"i":23,"n":"第二十三条","txt":"劳动保障监察员在实施劳动保障监察时，有下列情形之一的，应当回避： （一）本人是用人单位法定代表人或主要负责人的近亲属的； （二）本人或其近亲属与承办查处的案件事项有直接利害关系的； （三）因其他原因可能影响案件公正处理的。"},{"i":24,"n":"第二十四条","txt":"当事人认为劳动保障监察员符合本规定第二十三条规定应当回避的，有权向劳动保障行政部门申请，要求其回避。当事人申请劳动保障监察员回避，应当采用书面形式。"},{"i":25,"n":"第二十五条","txt":"劳动保障行政部门应当在收到回避申请之日起3个工作日内依法审查，并由劳动保障行政部门负责人作出回避决定。决定作出前，不停止实施劳动保障监察。回避决定应当告知申请人。"},{"i":26,"n":"第二十六条","txt":"劳动保障行政部门实施劳动保障监察，有权采取下列措施： （一）进入用人单位的劳动场所进行检查； （二）就调查、检查事项询问有关人员； （三）要求用人单位提供与调查、检查事项相关的文件资料，必要时可以发出调查询问书； （四）采取记录、录音、录像、照像和复制等方式收集有关的情况和资料； （五）对事实确凿、可以当场处理的违反劳动保障法律、法规或规章的行为当场予以纠正； （六）可以委托注册会计师事务所对用人单位工资支付、缴纳社会保险费的情况进行审计； （七）法律、法规规定可以由劳动保障行政部门采取的其他调查、检查措施。"},{"i":27,"n":"第二十七条","txt":"劳动保障行政部门调查、检查时，有下列情形之一的可以采取证据登记保存措施： （一）当事人可能对证据采取伪造、变造、毁灭行为的； （二）当事人采取措施不当可能导致证据灭失的； （三）不采取证据登记保存措施以后难以取得的； （四）其他可能导致证据灭失的情形的。"},{"i":28,"n":"第二十八条","txt":"采取证据登记保存措施应当按照下列程序进行： （一）劳动保障监察机构根据本规定第二十七条的规定，提出证据登记保存申请，报劳动保障行政部门负责人批准； （二）劳动保障监察员将证据登记保存通知书及证据登记清单交付当事人，由当事人签收。当事人拒不签名或者盖章的，由劳动保障监察员注明情况； （三）采取证据登记保存措施后，劳动保障行政部门应当在７日内及时作出处理决定，期限届满后应当解除证据登记保存措施。 在证据登记保存期内，当事人或者有关人员不得销毁或者转移证据；劳动保障监察机构及劳动保障监察员可以随时调取证据。"},{"i":29,"n":"第二十九条","txt":"劳动保障行政部门在实施劳动保障监察中涉及异地调查取证的，可以委托当地劳动保障行政部门协助调查。受委托方的协助调查应在双方商定的时间内完成。"},{"i":30,"n":"第三十条","txt":"劳动保障行政部门对违反劳动保障法律的行为的调查，应当自立案之日起60个工作日内完成；情况复杂的，经劳动保障行政部门负责人批准，可以延长30个工作日。"},{"i":31,"n":"第三十一条","txt":"对用人单位存在的违反劳动保障法律的行为事实确凿并有法定处罚（处理）依据的，可以当场作出限期整改指令或依法当场作出行政处罚决定。 当场作出限期整改指令或行政处罚决定的，劳动保障监察员应当填写预定格式、编有号码的限期整改指令书或行政处罚决定书，当场交付当事人。"},{"i":32,"n":"第三十二条","txt":"当场处以警告或罚款处罚的，应当按照下列程序进行： （一）口头告知当事人违法行为的基本事实、拟作出的行政处罚、依据及其依法享有的权利； （二）听取当事人的陈述和申辩； （三）填写预定格式的处罚决定书； （四）当场处罚决定书应当由劳动保障监察员签名或者盖章； （五）将处罚决定书当场交付当事人，由当事人签收。 劳动保障监察员应当在两日内将当场限期整改指令和行政处罚决定书存档联交所属劳动保障行政部门存档。"},{"i":33,"n":"第三十三条","txt":"对不能当场作出处理的违法案件，劳动保障监察员经调查取证，应当提出初步处理建议，并填写案件处理报批表。 案件处理报批表应写明被处理单位名称、案由、违反劳动保障法律行为事实、被处理单位的陈述、处理依据、建议处理意见。"},{"i":34,"n":"第三十四条","txt":"对违反劳动保障法律的行为作出行政处罚或者行政处理决定前，应当告知用人单位，听取其陈述和申辩；法律、法规规定应当依法听证的，应当告知用人单位有权依法要求举行听证；用人单位要求听证的，劳动保障行政部门应当组织听证。"},{"i":35,"n":"第三十五条","txt":"劳动保障行政部门对违反劳动保障法律的行为，根据调查、检查的结果，作出以下处理： （一）对依法应当受到行政处罚的，依法作出行政处罚决定； （二）对应当改正未改正的，依法责令改正或者作出相应的行政处理决定； （三）对情节轻微，且已改正的，撤销立案。 经调查、检查，劳动保障行政部门认定违法事实不能成立的，也应当撤销立案。 发现违法案件不属于劳动保障监察事项的，应当及时移送有关部门处理；涉嫌犯罪的，应当依法移送司法机关。"},{"i":36,"n":"第三十六条","txt":"劳动保障监察行政处罚（处理）决定书应载明下列事项： （一）被处罚（处理）单位名称、法定代表人、单位地址； （二）劳动保障行政部门认定的违法事实和主要证据； （三）劳动保障行政处罚（处理）的种类和依据； （四）处罚（处理）决定的履行方式和期限； （五）不服行政处罚（处理）决定，申请行政复议或者提起行政诉讼的途径和期限； （六）作出处罚（处理）决定的行政机关名称和作出处罚（处理）决定的日期。 劳动保障行政处罚（处理）决定书应当加盖劳动保障行政部门印章。"},{"i":37,"n":"第三十七条","txt":"劳动保障行政部门立案调查完成，应在15个工作日内作出行政处罚（行政处理或者责令改正）或者撤销立案决定；特殊情况，经劳动保障行政部门负责人批准可以延长。"},{"i":38,"n":"第三十八条","txt":"劳动保障监察限期整改指令书、劳动保障行政处理决定书、劳动保障行政处罚决定书应当在宣告后当场交付当事人；当事人不在场的，劳动保障行政部门应当在7日内依照《中华人民共和国民事诉讼法》的有关规定，将劳动保障监察限期整改指令书、劳动保障行政处理决定书、劳动保障行政处罚决定书送达当事人。"},{"i":39,"n":"第三十九条","txt":"作出行政处罚、行政处理决定的劳动保障行政部门发现决定不适当的，应当予以纠正并及时告知当事人。"},{"i":40,"n":"第四十条","txt":"劳动保障监察案件结案后应建立档案。档案资料应当至少保存3年。"},{"i":41,"n":"第四十一条","txt":"劳动保障行政处理或处罚决定依法作出后，当事人应当在决定规定的期限内予以履行。"},{"i":42,"n":"第四十二条","txt":"当事人对劳动保障行政处理或行政处罚决定不服申请行政复议或者提起行政诉讼的，行政处理或行政处罚决定不停止执行。法律另有规定的除外。"},{"i":43,"n":"第四十三条","txt":"当事人确有经济困难，需要延期或者分期缴纳罚款的，经当事人申请和劳动保障行政部门批准，可以暂缓或者分期缴纳。"},{"i":44,"n":"第四十四条","txt":"当事人对劳动保障行政部门作出的行政处罚决定、责令支付劳动者工资报酬、赔偿金或者征缴社会保险费等行政处理决定逾期不履行的，劳动保障行政部门可以申请人民法院强制执行，或者依法强制执行。"},{"i":45,"n":"第四十五条","txt":"除依法当场收缴的罚款外，作出罚款决定的劳动保障行政部门及其劳动保障监察员不得自行收缴罚款。当事人应当自收到行政处罚决定书之日起15日内，到指定银行缴纳罚款。"},{"i":46,"n":"第四十六条","txt":"地方各级劳动保障行政部门应当按照劳动保障部有关规定对承办的案件进行统计并填表上报。 地方各级劳动保障行政部门制作的行政处罚决定书，应当在10个工作日内报送上一级劳动保障行政部门备案。"},{"i":47,"n":"第四十七条","txt":"对无营业执照或者已被依法吊销营业执照，有劳动用工行为的，由劳动保障行政部门依照本规定实施劳动保障监察。"},{"i":48,"n":"第四十八条","txt":"本规定自2005年２月１日起施行。原《劳动监察规定》（劳部发〔1993〕167号）、《劳动监察程序规定》（劳部发〔1995〕457号）、《处理举报劳动违法行为规定》（劳动部令第５号，1996年12月17日）同时废止。"}],"guanyutiaozhengshiyongbudangbunengchongfenfahuizhu443299":[{"i":1,"n":"第一条","txt":"为了逐步解决部分留学回国人使用不当，不能充分发挥专长的问题，更好地发挥留学回国入员在祖国建设中的作用，特制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于用非所学、用非所长、缺少开展工作必需的基本条件等原因，在原工作单位不能充分发挥专长的留学回国人员。"},{"i":3,"n":"第三条","txt":"调整工作一般在本省、自治区、直辖市区域或国务院各部委、各直属机构系统内进行。在本地区、本系统确实难以调整的，可以跨地区、跨系统调整。"},{"i":4,"n":"第四条","txt":"调整工作技照“自主择业，双向选择”的原则，由组织或本人联系落实单位，调出、调入单位协商，所在地区（部门）人事部门审核，批准并办理调整手续。调整工作发生争议，可以向当地人才流动争议仲裁机构申请仲裁。"},{"i":5,"n":"第五条","txt":"跨地区、跨系统调整的留学回国人员，应持调入地市、县以上人事部门批准调入证明，到当地户口登记机关申报入户。其配偶及子女的随迁，按有关户口迁移规定办理。"},{"i":6,"n":"第六条","txt":"对于确因特殊需要，必须调整进京到中央国家机关及其所属单位工作的，按有关规定由接收单位的主管部委报人事部审批。"},{"i":7,"n":"第七条","txt":"国家公派、单位公派的留学回国人员在调整工作时，个人与单位签订了协议（合同）的，培训费按协议（合同）规定办理。未签订协议（合同）的，国家公派的，所在单位不得收取培训费，单位公派的，所在单位可以适当收取培训费，收取标准，按回单位服务的年限，以每年递减总培训费20%  的比例计算。"},{"i":8,"n":"第八条","txt":"各省、自治区、直辖市和国务院各部委、各直属机构可根据本办法、结合本地区、本系统的实际情况制定实施细则，报人事部备案。"},{"i":9,"n":"第九条","txt":"本办法自颁布之日起施行。"}],"laowupaiqianzanxingguiding":[{"i":1,"n":"第一条","txt":"为规范劳务派遣，维护劳动者的合法权益，促进劳动关系和谐稳定，依据《中华人民共和国劳动合同法》（以下简称劳动合同法）和《中华人民共和国劳动合同法实施条例》（以下简称劳动合同法实施条例）等法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"劳务派遣单位经营劳务派遣业务，企业（以下称用工单位）使用被派遣劳动者，适用本规定。 依法成立的会计师事务所、律师事务所等合伙组织和基金会以及民办非企业单位等组织使用被派遣劳动者，依照本规定执行。"},{"i":3,"n":"第三条","txt":"用工单位只能在临时性、辅助性或者替代性的工作岗位上使用被派遣劳动者。 前款规定的临时性工作岗位是指存续时间不超过6个月的岗位；辅助性工作岗位是指为主营业务岗位提供服务的非主营业务岗位；替代性工作岗位是指用工单位的劳动者因脱产学习、休假等原因无法工作的一定期间内，可以由其他劳动者替代工作的岗位。 用工单位决定使用被派遣劳动者的辅助性岗位，应当经职工代表大会或者全体职工讨论，提出方案和意见，与工会或者职工代表平等协商确定，并在用工单位内公示。"},{"i":4,"n":"第四条","txt":"用工单位应当严格控制劳务派遣用工数量，使用的被派遣劳动者数量不得超过其用工总量的10%。 前款所称用工总量是指用工单位订立劳动合同人数与使用的被派遣劳动者人数之和。 计算劳务派遣用工比例的用工单位是指依照劳动合同法和劳动合同法实施条例可以与劳动者订立劳动合同的用人单位。"},{"i":5,"n":"第五条","txt":"劳务派遣单位应当依法与被派遣劳动者订立2年以上的固定期限书面劳动合同。"},{"i":6,"n":"第六条","txt":"劳务派遣单位可以依法与被派遣劳动者约定试用期。劳务派遣单位与同一被派遣劳动者只能约定一次试用期。"},{"i":7,"n":"第七条","txt":"劳务派遣协议应当载明下列内容： （一）派遣的工作岗位名称和岗位性质； （二）工作地点； （三）派遣人员数量和派遣期限； （四）按照同工同酬原则确定的劳动报酬数额和支付方式； （五）社会保险费的数额和支付方式； （六）工作时间和休息休假事项； （七）被派遣劳动者工伤、生育或者患病期间的相关待遇； （八）劳动安全卫生以及培训事项； （九）经济补偿等费用； （十）劳务派遣协议期限； （十一）劳务派遣服务费的支付方式和标准； （十二）违反劳务派遣协议的责任； （十三）法律、法规、规章规定应当纳入劳务派遣协议的其他事项。"},{"i":8,"n":"第八条","txt":"劳务派遣单位应当对被派遣劳动者履行下列义务： （一）如实告知被派遣劳动者劳动合同法第八条规定的事项、应遵守的规章制度以及劳务派遣协议的内容； （二）建立培训制度，对被派遣劳动者进行上岗知识、安全教育培训； （三）按照国家规定和劳务派遣协议约定，依法支付被派遣劳动者的劳动报酬和相关待遇； （四）按照国家规定和劳务派遣协议约定，依法为被派遣劳动者缴纳社会保险费，并办理社会保险相关手续； （五）督促用工单位依法为被派遣劳动者提供劳动保护和劳动安全卫生条件； （六）依法出具解除或者终止劳动合同的证明； （七）协助处理被派遣劳动者与用工单位的纠纷； （八）法律、法规和规章规定的其他事项。"},{"i":9,"n":"第九条","txt":"用工单位应当按照劳动合同法第六十二条规定，向被派遣劳动者提供与工作岗位相关的福利待遇，不得歧视被派遣劳动者。"},{"i":10,"n":"第十条","txt":"被派遣劳动者在用工单位因工作遭受事故伤害的，劳务派遣单位应当依法申请工伤认定，用工单位应当协助工伤认定的调查核实工作。劳务派遣单位承担工伤保险责任，但可以与用工单位约定补偿办法。 被派遣劳动者在申请进行职业病诊断、鉴定时，用工单位应当负责处理职业病诊断、鉴定事宜，并如实提供职业病诊断、鉴定所需的劳动者职业史和职业危害接触史、工作场所职业病危害因素检测结果等资料，劳务派遣单位应当提供被派遣劳动者职业病诊断、鉴定所需的其他材料。"},{"i":11,"n":"第十一条","txt":"劳务派遣单位行政许可有效期未延续或者《劳务派遣经营许可证》被撤销、吊销的，已经与被派遣劳动者依法订立的劳动合同应当履行至期限届满。双方经协商一致，可以解除劳动合同。"},{"i":12,"n":"第十二条","txt":"有下列情形之一的，用工单位可以将被派遣劳动者退回劳务派遣单位： （一）用工单位有劳动合同法第四十条第三项、第四十一条规定情形的； （二）用工单位被依法宣告破产、吊销营业执照、责令关闭、撤销、决定提前解散或者经营期限届满不再继续经营的； （三）劳务派遣协议期满终止的。 被派遣劳动者退回后在无工作期间，劳务派遣单位应当按照不低于所在地人民政府规定的最低工资标准，向其按月支付报酬。"},{"i":13,"n":"第十三条","txt":"被派遣劳动者有劳动合同法第四十二条规定情形的，在派遣期限届满前，用工单位不得依据本规定第十二条第一款第一项规定将被派遣劳动者退回劳务派遣单位；派遣期限届满的，应当延续至相应情形消失时方可退回。"},{"i":14,"n":"第十四条","txt":"被派遣劳动者提前30日以书面形式通知劳务派遣单位，可以解除劳动合同。被派遣劳动者在试用期内提前3日通知劳务派遣单位，可以解除劳动合同。劳务派遣单位应当将被派遣劳动者通知解除劳动合同的情况及时告知用工单位。"},{"i":15,"n":"第十五条","txt":"被派遣劳动者因本规定第十二条规定被用工单位退回，劳务派遣单位重新派遣时维持或者提高劳动合同约定条件，被派遣劳动者不同意的，劳务派遣单位可以解除劳动合同。 被派遣劳动者因本规定第十二条规定被用工单位退回，劳务派遣单位重新派遣时降低劳动合同约定条件，被派遣劳动者不同意的，劳务派遣单位不得解除劳动合同。但被派遣劳动者提出解除劳动合同的除外。"},{"i":16,"n":"第十六条","txt":"劳务派遣单位被依法宣告破产、吊销营业执照、责令关闭、撤销、决定提前解散或者经营期限届满不再继续经营的，劳动合同终止。用工单位应当与劳务派遣单位协商妥善安置被派遣劳动者。"},{"i":17,"n":"第十七条","txt":"劳务派遣单位因劳动合同法第四十六条或者本规定第十五条、第十六条规定的情形，与被派遣劳动者解除或者终止劳动合同的，应当依法向被派遣劳动者支付经济补偿。"},{"i":18,"n":"第十八条","txt":"劳务派遣单位跨地区派遣劳动者的，应当在用工单位所在地为被派遣劳动者参加社会保险，按照用工单位所在地的规定缴纳社会保险费，被派遣劳动者按照国家规定享受社会保险待遇。"},{"i":19,"n":"第十九条","txt":"劳务派遣单位在用工单位所在地设立分支机构的，由分支机构为被派遣劳动者办理参保手续，缴纳社会保险费。 劳务派遣单位未在用工单位所在地设立分支机构的，由用工单位代劳务派遣单位为被派遣劳动者办理参保手续，缴纳社会保险费。"},{"i":20,"n":"第二十条","txt":"劳务派遣单位、用工单位违反劳动合同法和劳动合同法实施条例有关劳务派遣规定的，按照劳动合同法第九十二条规定执行。"},{"i":21,"n":"第二十一条","txt":"劳务派遣单位违反本规定解除或者终止被派遣劳动者劳动合同的，按照劳动合同法第四十八条、第八十七条规定执行。"},{"i":22,"n":"第二十二条","txt":"用工单位违反本规定第三条第三款规定的，由人力资源社会保障行政部门责令改正，给予警告；给被派遣劳动者造成损害的，依法承担赔偿责任。"},{"i":23,"n":"第二十三条","txt":"劳务派遣单位违反本规定第六条规定的，按照劳动合同法第八十三条规定执行。"},{"i":24,"n":"第二十四条","txt":"用工单位违反本规定退回被派遣劳动者的，按照劳动合同法第九十二条第二款规定执行。"},{"i":25,"n":"第二十五条","txt":"外国企业常驻代表机构和外国金融机构驻华代表机构等使用被派遣劳动者的，以及船员用人单位以劳务派遣形式使用国际远洋海员的，不受临时性、辅助性、替代性岗位和劳务派遣用工比例的限制。"},{"i":26,"n":"第二十六条","txt":"用人单位将本单位劳动者派往境外工作或者派往家庭、自然人处提供劳动的，不属于本规定所称劳务派遣。"},{"i":27,"n":"第二十七条","txt":"用人单位以承揽、外包等名义，按劳务派遣用工形式使用劳动者的，按照本规定处理。"},{"i":28,"n":"第二十八条","txt":"用工单位在本规定施行前使用被派遣劳动者数量超过其用工总量10%的，应当制定调整用工方案，于本规定施行之日起2年内降至规定比例。但是，《全国人民代表大会常务委员会关于修改〈中华人民共和国劳动合同法〉的决定》公布前已依法订立的劳动合同和劳务派遣协议期限届满日期在本规定施行之日起2年后的，可以依法继续履行至期限届满。 用工单位应当将制定的调整用工方案报当地人力资源社会保障行政部门备案。 用工单位未将本规定施行前使用的被派遣劳动者数量降至符合规定比例之前，不得新用被派遣劳动者。"},{"i":29,"n":"第二十九条","txt":"本规定自2014年3月1日起施行。"}],"laowupaiqianxingzhengxukeshishibanfa":[{"i":1,"n":"第一条","txt":"为了规范劳务派遣，根据《中华人民共和国劳动合同法》《中华人民共和国行政许可法》等法律，制定本办法。"},{"i":2,"n":"第二条","txt":"劳务派遣行政许可的申请受理、审查批准以及相关的监督检查等，适用本办法。"},{"i":3,"n":"第三条","txt":"人力资源社会保障部负责对全国的劳务派遣行政许可工作进行监督指导。 县级以上地方人力资源社会保障行政部门按照省、自治区、直辖市人力资源社会保障行政部门确定的许可管辖分工，负责实施本行政区域内劳务派遣行政许可工作以及相关的监督检查。"},{"i":4,"n":"第四条","txt":"人力资源社会保障行政部门实施劳务派遣行政许可，应当遵循权责统一、公开公正、优质高效的原则。"},{"i":5,"n":"第五条","txt":"人力资源社会保障行政部门应当在本行政机关办公场所、网站上公布劳务派遣行政许可的依据、程序、期限、条件和需要提交的全部材料目录以及监督电话，并在本行政机关网站和至少一种全地区性报纸上向社会公布获得许可的劳务派遣单位名单及其许可变更、延续、撤销、吊销、注销等情况。"},{"i":6,"n":"第六条","txt":"经营劳务派遣业务，应当向所在地有许可管辖权的人力资源社会保障行政部门（以下称许可机关）依法申请行政许可。 未经许可，任何单位和个人不得经营劳务派遣业务。"},{"i":7,"n":"第七条","txt":"申请经营劳务派遣业务应当具备下列条件： （一）注册资本不得少于人民币200万元； （二）有与开展业务相适应的固定的经营场所和设施； （三）有符合法律、行政法规规定的劳务派遣管理制度； （四）法律、行政法规规定的其他条件。"},{"i":8,"n":"第八条","txt":"申请经营劳务派遣业务的，申请人应当向许可机关提交下列材料： （一）劳务派遣经营许可申请书； （二）营业执照或者《企业名称预先核准通知书》； （三）公司章程以及验资机构出具的验资报告或者财务审计报告； （四）经营场所的使用证明以及与开展业务相适应的办公设施设备、信息管理系统等清单； （五）法定代表人的身份证明； （六）劳务派遣管理制度，包括劳动合同、劳动报酬、社会保险、工作时间、休息休假、劳动纪律等与劳动者切身利益相关的规章制度文本；拟与用工单位签订的劳务派遣协议样本。"},{"i":9,"n":"第九条","txt":"许可机关收到申请材料后，应当根据下列情况分别作出处理： （一）申请材料存在可以当场更正的错误的，应当允许申请人当场更正； （二）申请材料不齐全或者不符合法定形式的，应当当场或者在5个工作日内一次告知申请人需要补正的全部内容，逾期不告知的，自收到申请材料之日起即为受理； （三）申请材料齐全、符合法定形式，或者申请人按照要求提交了全部补正申请材料的，应当受理行政许可申请。"},{"i":10,"n":"第十条","txt":"许可机关对申请人提出的申请决定受理的，应当出具《受理决定书》；决定不予受理的，应当出具《不予受理决定书》，说明不予受理的理由，并告知申请人享有依法申请行政复议或者提起行政诉讼的权利。"},{"i":11,"n":"第十一条","txt":"许可机关决定受理申请的，应当对申请人提交的申请材料进行审查。根据法定条件和程序，需要对申请材料的实质内容进行核实的，许可机关应当指派2名以上工作人员进行核查。"},{"i":12,"n":"第十二条","txt":"许可机关应当自受理之日起20个工作日内作出是否准予行政许可的决定。20个工作日内不能作出决定的，经本行政机关负责人批准，可以延长10个工作日，并应当将延长期限的理由告知申请人。"},{"i":13,"n":"第十三条","txt":"申请人的申请符合法定条件的，许可机关应当依法作出准予行政许可的书面决定，并自作出决定之日起5个工作日内通知申请人领取《劳务派遣经营许可证》。 申请人的申请不符合法定条件的，许可机关应当依法作出不予行政许可的书面决定，说明不予行政许可的理由，并告知申请人享有依法申请行政复议或者提起行政诉讼的权利。"},{"i":14,"n":"第十四条","txt":"《劳务派遣经营许可证》应当载明单位名称、住所、法定代表人、注册资本、许可经营事项、有效期限、编号、发证机关以及发证日期等事项。《劳务派遣经营许可证》分为正本、副本。正本、副本具有同等法律效力。 《劳务派遣经营许可证》有效期为3年。 《劳务派遣经营许可证》由人力资源社会保障部统一制定样式，由各省、自治区、直辖市人力资源社会保障行政部门负责印制、免费发放和管理。"},{"i":15,"n":"第十五条","txt":"劳务派遣单位取得《劳务派遣经营许可证》后，应当妥善保管，不得涂改、倒卖、出租、出借或者以其他形式非法转让。"},{"i":16,"n":"第十六条","txt":"劳务派遣单位名称、住所、法定代表人或者注册资本等改变的，应当向许可机关提出变更申请。符合法定条件的，许可机关应当自收到变更申请之日起10个工作日内依法办理变更手续，并换发新的《劳务派遣经营许可证》或者在原《劳务派遣经营许可证》上予以注明；不符合法定条件的，许可机关应当自收到变更申请之日起10个工作日内作出不予变更的书面决定，并说明理由。"},{"i":17,"n":"第十七条","txt":"劳务派遣单位分立、合并后继续存续，其名称、住所、法定代表人或者注册资本等改变的，应当按照本办法第十六条规定执行。 劳务派遣单位分立、合并后设立新公司的，应当按照本办法重新申请劳务派遣行政许可。"},{"i":18,"n":"第十八条","txt":"劳务派遣单位需要延续行政许可有效期的，应当在有效期届满60日前向许可机关提出延续行政许可的书面申请，并提交3年以来的基本经营情况；劳务派遣单位逾期提出延续行政许可的书面申请的，按照新申请经营劳务派遣行政许可办理。"},{"i":19,"n":"第十九条","txt":"许可机关应当根据劳务派遣单位的延续申请，在该行政许可有效期届满前作出是否准予延续的决定；逾期未作决定的，视为准予延续。 准予延续行政许可的，应当换发新的《劳务派遣经营许可证》。"},{"i":20,"n":"第二十条","txt":"劳务派遣单位有下列情形之一的，许可机关应当自收到延续申请之日起10个工作日内作出不予延续书面决定，并说明理由： （一）逾期不提交劳务派遣经营情况报告或者提交虚假劳务派遣经营情况报告，经责令改正，拒不改正的； （二）违反劳动保障法律法规，在一个行政许可期限内受到2次以上行政处罚的。"},{"i":21,"n":"第二十一条","txt":"劳务派遣单位设立子公司经营劳务派遣业务的，应当由子公司向所在地许可机关申请行政许可；劳务派遣单位设立分公司经营劳务派遣业务的，应当书面报告许可机关，并由分公司向所在地人力资源社会保障行政部门备案。"},{"i":22,"n":"第二十二条","txt":"劳务派遣单位应当于每年3月31日前向许可机关提交上一年度劳务派遣经营情况报告，如实报告下列事项： （一）经营情况以及上年度财务审计报告； （二）被派遣劳动者人数以及订立劳动合同、参加工会的情况； （三）向被派遣劳动者支付劳动报酬的情况； （四）被派遣劳动者参加社会保险、缴纳社会保险费的情况； （五）被派遣劳动者派往的用工单位、派遣数量、派遣期限、用工岗位的情况； （六）与用工单位订立的劳务派遣协议情况以及用工单位履行法定义务的情况； （七）设立子公司、分公司等情况。 劳务派遣单位设立的子公司或者分公司，应当向办理许可或者备案手续的人力资源社会保障行政部门提交上一年度劳务派遣经营情况报告。"},{"i":23,"n":"第二十三条","txt":"许可机关应当对劳务派遣单位提交的年度经营情况报告进行核验，依法对劳务派遣单位进行监督，并将核验结果和监督情况载入企业信用记录。"},{"i":24,"n":"第二十四条","txt":"有下列情形之一的，许可机关或者其上级行政机关，可以撤销劳务派遣行政许可： （一）许可机关工作人员滥用职权、玩忽职守，给不符合条件的申请人发放《劳务派遣经营许可证》的； （二）超越法定职权发放《劳务派遣经营许可证》的； （三）违反法定程序发放《劳务派遣经营许可证》的； （四）依法可以撤销行政许可的其他情形。"},{"i":25,"n":"第二十五条","txt":"申请人隐瞒真实情况或者提交虚假材料申请行政许可的，许可机关不予受理、不予行政许可。 劳务派遣单位以欺骗、贿赂等不正当手段和隐瞒真实情况或者提交虚假材料取得行政许可的，许可机关应当予以撤销。被撤销行政许可的劳务派遣单位在1年内不得再次申请劳务派遣行政许可。"},{"i":26,"n":"第二十六条","txt":"有下列情形之一的，许可机关应当依法办理劳务派遣行政许可注销手续： （一）《劳务派遣经营许可证》有效期届满，劳务派遣单位未申请延续的，或者延续申请未被批准的； （二）劳务派遣单位依法终止的； （三）劳务派遣行政许可依法被撤销，或者《劳务派遣经营许可证》依法被吊销的； （四）法律、法规规定的应当注销行政许可的其他情形。"},{"i":27,"n":"第二十七条","txt":"劳务派遣单位向许可机关申请注销劳务派遣行政许可的，应当提交已经依法处理与被派遣劳动者的劳动关系及其社会保险权益等材料，许可机关应当在核实有关情况后办理注销手续。"},{"i":28,"n":"第二十八条","txt":"当事人对许可机关作出的有关劳务派遣行政许可的行政决定不服的，可以依法申请行政复议或者提起行政诉讼。"},{"i":29,"n":"第二十九条","txt":"任何组织和个人有权对实施劳务派遣行政许可中的违法违规行为进行举报，人力资源社会保障行政部门应当及时核实、处理。"},{"i":30,"n":"第三十条","txt":"人力资源社会保障行政部门有下列情形之一的，由其上级行政机关或者监察机关责令改正，对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任： （一）向不符合法定条件的申请人发放《劳务派遣经营许可证》，或者超越法定职权发放《劳务派遣经营许可证》的； （二）对符合法定条件的申请人不予行政许可或者不在法定期限内作出准予行政许可决定的； （三）在办理行政许可、实施监督检查工作中，玩忽职守、徇私舞弊，索取或者收受他人财物或者谋取其他利益的； （四）不依法履行监督职责或者监督不力，造成严重后果的。 许可机关违法实施行政许可，给当事人的合法权益造成损害的，应当依照国家赔偿法的规定给予赔偿。"},{"i":31,"n":"第三十一条","txt":"任何单位和个人违反《中华人民共和国劳动合同法》的规定，未经许可，擅自经营劳务派遣业务的，由人力资源社会保障行政部门责令停止违法行为，没收违法所得，并处违法所得1倍以上5倍以下的罚款；没有违法所得的，可以处5万元以下的罚款。"},{"i":32,"n":"第三十二条","txt":"劳务派遣单位违反《中华人民共和国劳动合同法》有关劳务派遣规定的，由人力资源社会保障行政部门责令限期改正；逾期不改正的，以每人5000元以上1万元以下的标准处以罚款，并吊销其《劳务派遣经营许可证》。"},{"i":33,"n":"第三十三条","txt":"劳务派遣单位有下列情形之一的，由人力资源社会保障行政部门处1万元以下的罚款；情节严重的，处1万元以上3万元以下的罚款： （一）涂改、倒卖、出租、出借《劳务派遣经营许可证》，或者以其他形式非法转让《劳务派遣经营许可证》的； （二）隐瞒真实情况或者提交虚假材料取得劳务派遣行政许可的； （三）以欺骗、贿赂等不正当手段取得劳务派遣行政许可的。"},{"i":34,"n":"第三十四条","txt":"劳务派遣单位在2012年12月28日至2013年6月30日之间订立的劳动合同和劳务派遣协议，2013年7月1日后应当按照《全国人大常委会关于修改〈中华人民共和国劳动合同法〉的决定》执行。 本办法施行前经营劳务派遣业务的单位，应当按照本办法取得劳务派遣行政许可后，方可经营新的劳务派遣业务；本办法施行后未取得劳务派遣行政许可的，不得经营新的劳务派遣业务。"},{"i":35,"n":"第三十五条","txt":"本办法自2013年7月1日起施行。"}],"laodongrenshizhengyizhongcaibananguize":[{"i":1,"n":"第一条","txt":"为公正及时处理劳动人事争议（以下简称争议），规范仲裁办案程序，根据《中华人民共和国劳动争议调解仲裁法》（以下简称调解仲裁法）以及《中华人民共和国公务员法》（以下简称公务员法）、《事业单位人事管理条例》、《中国人民解放军文职人员条例》和有关法律、法规、国务院有关规定，制定本规则。"},{"i":2,"n":"第二条","txt":"本规则适用下列争议的仲裁： （一）企业、个体经济组织、民办非企业单位等组织与劳动者之间，以及机关、事业单位、社会团体与其建立劳动关系的劳动者之间，因确认劳动关系，订立、履行、变更、解除和终止劳动合同，工作时间、休息休假、社会保险、福利、培训以及劳动保护，劳动报酬、工伤医疗费、经济补偿或者赔偿金等发生的争议； （二）实施公务员法的机关与聘任制公务员之间、参照公务员法管理的机关（单位）与聘任工作人员之间因履行聘任合同发生的争议； （三）事业单位与其建立人事关系的工作人员之间因终止人事关系以及履行聘用合同发生的争议； （四）社会团体与其建立人事关系的工作人员之间因终止人事关系以及履行聘用合同发生的争议； （五）军队文职人员用人单位与聘用制文职人员之间因履行聘用合同发生的争议； （六）法律、法规规定由劳动人事争议仲裁委员会（以下简称仲裁委员会）处理的其他争议。"},{"i":3,"n":"第三条","txt":"仲裁委员会处理争议案件，应当遵循合法、公正的原则，先行调解，及时裁决。"},{"i":4,"n":"第四条","txt":"仲裁委员会下设实体化的办事机构，称为劳动人事争议仲裁院（以下简称仲裁院）。"},{"i":5,"n":"第五条","txt":"劳动者一方在十人以上并有共同请求的争议，或者因履行集体合同发生的劳动争议，仲裁委员会应当优先立案，优先审理。"},{"i":6,"n":"第六条","txt":"发生争议的用人单位未办理营业执照、被吊销营业执照、营业执照到期继续经营、被责令关闭、被撤销以及用人单位解散、歇业，不能承担相关责任的，应当将用人单位和其出资人、开办单位或者主管部门作为共同当事人。"},{"i":7,"n":"第七条","txt":"劳动者与个人承包经营者发生争议，依法向仲裁委员会申请仲裁的，应当将发包的组织和个人承包经营者作为共同当事人。"},{"i":8,"n":"第八条","txt":"劳动合同履行地为劳动者实际工作场所地，用人单位所在地为用人单位注册、登记地或者主要办事机构所在地。用人单位未经注册、登记的，其出资人、开办单位或者主管部门所在地为用人单位所在地。 双方当事人分别向劳动合同履行地和用人单位所在地的仲裁委员会申请仲裁的，由劳动合同履行地的仲裁委员会管辖。有多个劳动合同履行地的，由最先受理的仲裁委员会管辖。劳动合同履行地不明确的，由用人单位所在地的仲裁委员会管辖。 案件受理后，劳动合同履行地或者用人单位所在地发生变化的，不改变争议仲裁的管辖。"},{"i":9,"n":"第九条","txt":"仲裁委员会发现已受理案件不属于其管辖范围的，应当移送至有管辖权的仲裁委员会，并书面通知当事人。 对上述移送案件，受移送的仲裁委员会应当依法受理。受移送的仲裁委员会认为移送的案件按照规定不属于其管辖，或者仲裁委员会之间因管辖争议协商不成的，应当报请共同的上一级仲裁委员会主管部门指定管辖。"},{"i":10,"n":"第十条","txt":"当事人提出管辖异议的，应当在答辩期满前书面提出。仲裁委员会应当审查当事人提出的管辖异议，异议成立的，将案件移送至有管辖权的仲裁委员会并书面通知当事人；异议不成立的，应当书面决定驳回。 当事人逾期提出的，不影响仲裁程序的进行。"},{"i":11,"n":"第十一条","txt":"当事人申请回避，应当在案件开庭审理前提出，并说明理由。回避事由在案件开庭审理后知晓的，也可以在庭审辩论终结前提出。 当事人在庭审辩论终结后提出回避申请的，不影响仲裁程序的进行。 仲裁委员会应当在回避申请提出的三日内，以口头或者书面形式作出决定。以口头形式作出的，应当记入笔录。"},{"i":12,"n":"第十二条","txt":"仲裁员、记录人员是否回避，由仲裁委员会主任或者其委托的仲裁院负责人决定。仲裁委员会主任担任案件仲裁员是否回避，由仲裁委员会决定。 在回避决定作出前，被申请回避的人员应当暂停参与该案处理，但因案件需要采取紧急措施的除外。"},{"i":13,"n":"第十三条","txt":"当事人对自己提出的主张有责任提供证据。与争议事项有关的证据属于用人单位掌握管理的，用人单位应当提供；用人单位不提供的，应当承担不利后果。"},{"i":14,"n":"第十四条","txt":"法律没有具体规定、按照本规则第十三条规定无法确定举证责任承担的，仲裁庭可以根据公平原则和诚实信用原则，综合当事人举证能力等因素确定举证责任的承担。"},{"i":15,"n":"第十五条","txt":"承担举证责任的当事人应当在仲裁委员会指定的期限内提供有关证据。当事人在该期限内提供证据确有困难的，可以向仲裁委员会申请延长期限，仲裁委员会根据当事人的申请适当延长。当事人逾期提供证据的，仲裁委员会应当责令其说明理由；拒不说明理由或者理由不成立的，仲裁委员会可以根据不同情形不予采纳该证据，或者采纳该证据但予以训诫。"},{"i":16,"n":"第十六条","txt":"当事人因客观原因不能自行收集的证据，仲裁委员会可以根据当事人的申请，参照民事诉讼有关规定予以收集；仲裁委员会认为有必要的，也可以决定参照民事诉讼有关规定予以收集。"},{"i":17,"n":"第十七条","txt":"仲裁委员会依法调查取证时，有关单位和个人应当协助配合。 仲裁委员会调查取证时，不得少于两人，并应当向被调查对象出示工作证件和仲裁委员会出具的介绍信。"},{"i":18,"n":"第十八条","txt":"争议处理中涉及证据形式、证据提交、证据交换、证据质证、证据认定等事项，本规则未规定的，可以参照民事诉讼证据规则的有关规定执行。"},{"i":19,"n":"第十九条","txt":"仲裁期间包括法定期间和仲裁委员会指定期间。 仲裁期间的计算，本规则未规定的，仲裁委员会可以参照民事诉讼关于期间计算的有关规定执行。"},{"i":20,"n":"第二十条","txt":"仲裁委员会送达仲裁文书必须有送达回证，由受送达人在送达回证上记明收到日期，并签名或者盖章。受送达人在送达回证上的签收日期为送达日期。 因企业停业等原因导致无法送达且劳动者一方在十人以上的，或者受送达人拒绝签收仲裁文书的，通过在受送达人住所留置、张贴仲裁文书，并采用拍照、录像等方式记录的，自留置、张贴之日起经过三日即视为送达，不受本条第一款的限制。 仲裁文书的送达方式，本规则未规定的，仲裁委员会可以参照民事诉讼关于送达方式的有关规定执行。"},{"i":21,"n":"第二十一条","txt":"案件处理终结后，仲裁委员会应当将处理过程中形成的全部材料立卷归档。"},{"i":22,"n":"第二十二条","txt":"仲裁案卷分正卷和副卷装订。 正卷包括：仲裁申请书、受理（不予受理）通知书、答辩书、当事人及其他仲裁参加人的身份证明材料、授权委托书、调查证据、勘验笔录、当事人提供的证据材料、委托鉴定材料、开庭通知、庭审笔录、延期通知书、撤回仲裁申请书、调解书、裁决书、决定书、案件移送函、送达回证等。 副卷包括：立案审批表、延期审理审批表、中止审理审批表、调查提纲、阅卷笔录、会议笔录、评议记录、结案审批表等。"},{"i":23,"n":"第二十三条","txt":"仲裁委员会应当建立案卷查阅制度。对案卷正卷材料，应当允许当事人及其代理人依法查阅、复制。"},{"i":24,"n":"第二十四条","txt":"仲裁裁决结案的案卷，保存期不少于十年；仲裁调解和其他方式结案的案卷，保存期不少于五年；国家另有规定的，从其规定。 保存期满后的案卷，应当按照国家有关档案管理的规定处理。"},{"i":25,"n":"第二十五条","txt":"在仲裁活动中涉及国家秘密或者军事秘密的，按照国家或者军队有关保密规定执行。 当事人协议不公开或者涉及商业秘密和个人隐私的，经相关当事人书面申请，仲裁委员会应当不公开审理。"},{"i":26,"n":"第二十六条","txt":"本规则第二条第（一）、（三）、（四）、（五）项规定的争议，申请仲裁的时效期间为一年。仲裁时效期间从当事人知道或者应当知道其权利被侵害之日起计算。 本规则第二条第（二）项规定的争议，申请仲裁的时效期间适用公务员法有关规定。 劳动人事关系存续期间因拖欠劳动报酬发生争议的，劳动者申请仲裁不受本条第一款规定的仲裁时效期间的限制；但是，劳动人事关系终止的，应当自劳动人事关系终止之日起一年内提出。"},{"i":27,"n":"第二十七条","txt":"在申请仲裁的时效期间内，有下列情形之一的，仲裁时效中断： （一）一方当事人通过协商、申请调解等方式向对方当事人主张权利的； （二）一方当事人通过向有关部门投诉，向仲裁委员会申请仲裁，向人民法院起诉或者申请支付令等方式请求权利救济的； （三）对方当事人同意履行义务的。 从中断时起，仲裁时效期间重新计算。"},{"i":28,"n":"第二十八条","txt":"因不可抗力，或者有无民事行为能力或者限制民事行为能力劳动者的法定代理人未确定等其他正当理由，当事人不能在规定的仲裁时效期间申请仲裁的，仲裁时效中止。从中止时效的原因消除之日起，仲裁时效期间继续计算。"},{"i":29,"n":"第二十九条","txt":"申请人申请仲裁应当提交书面仲裁申请，并按照被申请人人数提交副本。 仲裁申请书应当载明下列事项： （一）劳动者的姓名、性别、出生日期、身份证件号码、住所、通讯地址和联系电话，用人单位的名称、住所、通讯地址、联系电话和法定代表人或者主要负责人的姓名、职务； （二）仲裁请求和所根据的事实、理由； （三）证据和证据来源，证人姓名和住所。 书写仲裁申请确有困难的，可以口头申请，由仲裁委员会记入笔录，经申请人签名、盖章或者捺印确认。 对于仲裁申请书不规范或者材料不齐备的，仲裁委员会应当当场或者在五日内一次性告知申请人需要补正的全部材料。 仲裁委员会收取当事人提交的材料应当出具收件回执。"},{"i":30,"n":"第三十条","txt":"仲裁委员会对符合下列条件的仲裁申请应当予以受理，并在收到仲裁申请之日起五日内向申请人出具受理通知书： （一）属于本规则第二条规定的争议范围； （二）有明确的仲裁请求和事实理由； （三）申请人是与本案有直接利害关系的自然人、法人或者其他组织，有明确的被申请人； （四）属于本仲裁委员会管辖范围。"},{"i":31,"n":"第三十一条","txt":"对不符合本规则第三十条第（一）、（二）、（三）项规定之一的仲裁申请，仲裁委员会不予受理，并在收到仲裁申请之日起五日内向申请人出具不予受理通知书；对不符合本规则第三十条第（四）项规定的仲裁申请，仲裁委员会应当在收到仲裁申请之日起五日内，向申请人作出书面说明并告知申请人向有管辖权的仲裁委员会申请仲裁。 对仲裁委员会逾期未作出决定或者决定不予受理的，申请人可以就该争议事项向人民法院提起诉讼。"},{"i":32,"n":"第三十二条","txt":"仲裁委员会受理案件后，发现不应当受理的，除本规则第九条规定外，应当撤销案件，并自决定撤销案件后五日内，以决定书的形式通知当事人。"},{"i":33,"n":"第三十三条","txt":"仲裁委员会受理仲裁申请后，应当在五日内将仲裁申请书副本送达被申请人。 被申请人收到仲裁申请书副本后，应当在十日内向仲裁委员会提交答辩书。仲裁委员会收到答辩书后，应当在五日内将答辩书副本送达申请人。被申请人逾期未提交答辩书的，不影响仲裁程序的进行。"},{"i":34,"n":"第三十四条","txt":"符合下列情形之一，申请人基于同一事实、理由和仲裁请求又申请仲裁的，仲裁委员会不予受理： （一）仲裁委员会已经依法出具不予受理通知书的； （二）案件已在仲裁、诉讼过程中或者调解书、裁决书、判决书已经发生法律效力的。"},{"i":35,"n":"第三十五条","txt":"仲裁处理结果作出前，申请人可以自行撤回仲裁申请。申请人再次申请仲裁的，仲裁委员会应当受理。"},{"i":36,"n":"第三十六条","txt":"被申请人可以在答辩期间提出反申请，仲裁委员会应当自收到被申请人反申请之日起五日内决定是否受理并通知被申请人。 决定受理的，仲裁委员会可以将反申请和申请合并处理。 反申请应当另行申请仲裁的，仲裁委员会应当书面告知被申请人另行申请仲裁；反申请不属于本规则规定应当受理的，仲裁委员会应当向被申请人出具不予受理通知书。 被申请人答辩期满后对申请人提出反申请的，应当另行申请仲裁。"},{"i":37,"n":"第三十七条","txt":"仲裁委员会应当在受理仲裁申请之日起五日内组成仲裁庭并将仲裁庭的组成情况书面通知当事人。"},{"i":38,"n":"第三十八条","txt":"仲裁庭应当在开庭五日前，将开庭日期、地点书面通知双方当事人。当事人有正当理由的，可以在开庭三日前请求延期开庭。是否延期，由仲裁委员会根据实际情况决定。"},{"i":39,"n":"第三十九条","txt":"申请人收到书面开庭通知，无正当理由拒不到庭或者未经仲裁庭同意中途退庭的，可以按撤回仲裁申请处理；申请人重新申请仲裁的，仲裁委员会不予受理。被申请人收到书面开庭通知，无正当理由拒不到庭或者未经仲裁庭同意中途退庭的，仲裁庭可以继续开庭审理，并缺席裁决。"},{"i":40,"n":"第四十条","txt":"当事人申请鉴定的，鉴定费由申请鉴定方先行垫付，案件处理终结后，由鉴定结果对其不利方负担。鉴定结果不明确的，由申请鉴定方负担。"},{"i":41,"n":"第四十一条","txt":"开庭审理前，记录人员应当查明当事人和其他仲裁参与人是否到庭，宣布仲裁庭纪律。 开庭审理时，由仲裁员宣布开庭、案由和仲裁员、记录人员名单，核对当事人，告知当事人有关的权利义务，询问当事人是否提出回避申请。 开庭审理中，仲裁员应当听取申请人的陈述和被申请人的答辩，主持庭审调查、质证和辩论、征询当事人最后意见，并进行调解。"},{"i":42,"n":"第四十二条","txt":"仲裁庭应当将开庭情况记入笔录。当事人或者其他仲裁参与人认为对自己陈述的记录有遗漏或者差错的，有权当庭申请补正。仲裁庭认为申请无理由或者无必要的，可以不予补正，但是应当记录该申请。 仲裁员、记录人员、当事人和其他仲裁参与人应当在庭审笔录上签名或者盖章。当事人或者其他仲裁参与人拒绝在庭审笔录上签名或者盖章的，仲裁庭应当记明情况附卷。"},{"i":43,"n":"第四十三条","txt":"仲裁参与人和其他人应当遵守仲裁庭纪律，不得有下列行为： （一）未经准许进行录音、录像、摄影； （二）未经准许以移动通信等方式现场传播庭审活动； （三）其他扰乱仲裁庭秩序、妨害审理活动进行的行为。 仲裁参与人或者其他人有前款规定的情形之一的，仲裁庭可以训诫、责令退出仲裁庭，也可以暂扣进行录音、录像、摄影、传播庭审活动的器材，并责令其删除有关内容。拒不删除的，可以采取必要手段强制删除，并将上述事实记入庭审笔录。"},{"i":44,"n":"第四十四条","txt":"申请人在举证期限届满前可以提出增加或者变更仲裁请求；仲裁庭对申请人增加或者变更的仲裁请求审查后认为应当受理的，应当通知被申请人并给予答辩期，被申请人明确表示放弃答辩期的除外。 申请人在举证期限届满后提出增加或者变更仲裁请求的，应当另行申请仲裁。"},{"i":45,"n":"第四十五条","txt":"仲裁庭裁决案件，应当自仲裁委员会受理仲裁申请之日起四十五日内结束。案情复杂需要延期的，经仲裁委员会主任或者其委托的仲裁院负责人书面批准，可以延期并书面通知当事人，但延长期限不得超过十五日。"},{"i":46,"n":"第四十六条","txt":"有下列情形的，仲裁期限按照下列规定计算： （一）仲裁庭追加当事人或者第三人的，仲裁期限从决定追加之日起重新计算； （二）申请人需要补正材料的，仲裁委员会收到仲裁申请的时间从材料补正之日起重新计算； （三）增加、变更仲裁请求的，仲裁期限从受理增加、变更仲裁请求之日起重新计算； （四）仲裁申请和反申请合并处理的，仲裁期限从受理反申请之日起重新计算； （五）案件移送管辖的，仲裁期限从接受移送之日起重新计算； （六）中止审理期间、公告送达期间不计入仲裁期限内； （七）法律、法规规定应当另行计算的其他情形。"},{"i":47,"n":"第四十七条","txt":"有下列情形之一的，经仲裁委员会主任或者其委托的仲裁院负责人批准，可以中止案件审理，并书面通知当事人： （一）劳动者一方当事人死亡，需要等待继承人表明是否参加仲裁的； （二）劳动者一方当事人丧失民事行为能力，尚未确定法定代理人参加仲裁的； （三）用人单位终止，尚未确定权利义务承继者的； （四）一方当事人因不可抗拒的事由，不能参加仲裁的； （五）案件审理需要以其他案件的审理结果为依据，且其他案件尚未审结的； （六）案件处理需要等待工伤认定、伤残等级鉴定以及其他鉴定结论的； （七）其他应当中止仲裁审理的情形。 中止审理的情形消除后，仲裁庭应当恢复审理。"},{"i":48,"n":"第四十八条","txt":"当事人因仲裁庭逾期未作出仲裁裁决而向人民法院提起诉讼并立案受理的，仲裁委员会应当决定该案件终止审理；当事人未就该争议事项向人民法院提起诉讼的，仲裁委员会应当继续处理。"},{"i":49,"n":"第四十九条","txt":"仲裁庭裁决案件时，其中一部分事实已经清楚的，可以就该部分先行裁决。当事人对先行裁决不服的，可以按照调解仲裁法有关规定处理。"},{"i":50,"n":"第五十条","txt":"仲裁庭裁决案件时，申请人根据调解仲裁法第四十七条第（一）项规定，追索劳动报酬、工伤医疗费、经济补偿或者赔偿金，如果仲裁裁决涉及数项，对单项裁决数额不超过当地月最低工资标准十二个月金额的事项，应当适用终局裁决。 前款经济补偿包括《中华人民共和国劳动合同法》（以下简称劳动合同法）规定的竞业限制期限内给予的经济补偿、解除或者终止劳动合同的经济补偿等；赔偿金包括劳动合同法规定的未签订书面劳动合同第二倍工资、违法约定试用期的赔偿金、违法解除或者终止劳动合同的赔偿金等。 根据调解仲裁法第四十七条第（二）项的规定，因执行国家的劳动标准在工作时间、休息休假、社会保险等方面发生的争议，应当适用终局裁决。 仲裁庭裁决案件时，裁决内容同时涉及终局裁决和非终局裁决的，应当分别制作裁决书，并告知当事人相应的救济权利。"},{"i":51,"n":"第五十一条","txt":"仲裁庭对追索劳动报酬、工伤医疗费、经济补偿或者赔偿金的案件，根据当事人的申请，可以裁决先予执行，移送人民法院执行。 仲裁庭裁决先予执行的，应当符合下列条件： （一）当事人之间权利义务关系明确； （二）不先予执行将严重影响申请人的生活。 劳动者申请先予执行的，可以不提供担保。"},{"i":52,"n":"第五十二条","txt":"裁决应当按照多数仲裁员的意见作出，少数仲裁员的不同意见应当记入笔录。仲裁庭不能形成多数意见时，裁决应当按照首席仲裁员的意见作出。"},{"i":53,"n":"第五十三条","txt":"裁决书应当载明仲裁请求、争议事实、裁决理由、裁决结果、当事人权利和裁决日期。裁决书由仲裁员签名，加盖仲裁委员会印章。对裁决持不同意见的仲裁员，可以签名，也可以不签名。"},{"i":54,"n":"第五十四条","txt":"对裁决书中的文字、计算错误或者仲裁庭已经裁决但在裁决书中遗漏的事项，仲裁庭应当及时制作决定书予以补正并送达当事人。"},{"i":55,"n":"第五十五条","txt":"当事人对裁决不服向人民法院提起诉讼的，按照调解仲裁法有关规定处理。"},{"i":56,"n":"第五十六条","txt":"争议案件符合下列情形之一的，可以简易处理： （一）事实清楚、权利义务关系明确、争议不大的； （二）标的额不超过本省、自治区、直辖市上年度职工年平均工资的； （三）双方当事人同意简易处理的。 仲裁委员会决定简易处理的，可以指定一名仲裁员独任仲裁，并应当告知当事人。"},{"i":57,"n":"第五十七条","txt":"争议案件有下列情形之一的，不得简易处理： （一）涉及国家利益、社会公共利益的； （二）有重大社会影响的； （三）被申请人下落不明的； （四）仲裁委员会认为不宜简易处理的。"},{"i":58,"n":"第五十八条","txt":"简易处理的案件，经与被申请人协商同意，仲裁庭可以缩短或者取消答辩期。"},{"i":59,"n":"第五十九条","txt":"简易处理的案件，仲裁庭可以用电话、短信、传真、电子邮件等简便方式送达仲裁文书，但送达调解书、裁决书除外。 以简便方式送达的开庭通知，未经当事人确认或者没有其他证据证明当事人已经收到的，仲裁庭不得按撤回仲裁申请处理或者缺席裁决。"},{"i":60,"n":"第六十条","txt":"简易处理的案件，仲裁庭可以根据案件情况确定举证期限、开庭日期、审理程序、文书制作等事项，但应当保障当事人陈述意见的权利。"},{"i":61,"n":"第六十一条","txt":"仲裁庭在审理过程中，发现案件不宜简易处理的，应当在仲裁期限届满前决定转为按照一般程序处理，并告知当事人。 案件转为按照一般程序处理的，仲裁期限自仲裁委员会受理仲裁申请之日起计算，双方当事人已经确认的事实，可以不再进行举证、质证。"},{"i":62,"n":"第六十二条","txt":"处理劳动者一方在十人以上并有共同请求的争议案件，或者因履行集体合同发生的劳动争议案件，适用本节规定。 符合本规则第五十六条第一款规定情形之一的集体劳动人事争议案件，可以简易处理，不受本节规定的限制。"},{"i":63,"n":"第六十三条","txt":"发生劳动者一方在十人以上并有共同请求的争议的，劳动者可以推举三至五名代表参加仲裁活动。代表人参加仲裁的行为对其所代表的当事人发生效力，但代表人变更、放弃仲裁请求或者承认对方当事人的仲裁请求，进行和解，必须经被代表的当事人同意。 因履行集体合同发生的劳动争议，经协商解决不成的，工会可以依法申请仲裁；尚未建立工会的，由上级工会指导劳动者推举产生的代表依法申请仲裁。"},{"i":64,"n":"第六十四条","txt":"仲裁委员会应当自收到当事人集体劳动人事争议仲裁申请之日起五日内作出受理或者不予受理的决定。决定受理的，应当自受理之日起五日内将仲裁庭组成人员、答辩期限、举证期限、开庭日期和地点等事项一次性通知当事人。"},{"i":65,"n":"第六十五条","txt":"仲裁委员会处理集体劳动人事争议案件，应当由三名仲裁员组成仲裁庭，设首席仲裁员。 仲裁委员会处理因履行集体合同发生的劳动争议，应当按照三方原则组成仲裁庭处理。"},{"i":66,"n":"第六十六条","txt":"仲裁庭处理集体劳动人事争议，开庭前应当引导当事人自行协商，或者先行调解。 仲裁庭处理集体劳动人事争议案件，可以邀请法律工作者、律师、专家学者等第三方共同参与调解。 协商或者调解未能达成协议的，仲裁庭应当及时裁决。"},{"i":67,"n":"第六十七条","txt":"仲裁庭开庭场所可以设在发生争议的用人单位或者其他便于及时处理争议的地点。"},{"i":68,"n":"第六十八条","txt":"仲裁委员会处理争议案件，应当坚持调解优先，引导当事人通过协商、调解方式解决争议，给予必要的法律释明以及风险提示。"},{"i":69,"n":"第六十九条","txt":"对未经调解、当事人直接申请仲裁的争议，仲裁委员会可以向当事人发出调解建议书，引导其到调解组织进行调解。当事人同意先行调解的，应当暂缓受理；当事人不同意先行调解的，应当依法受理。"},{"i":70,"n":"第七十条","txt":"开庭之前，经双方当事人同意，仲裁庭可以委托调解组织或者其他具有调解能力的组织、个人进行调解。 自当事人同意之日起十日内未达成调解协议的，应当开庭审理。"},{"i":71,"n":"第七十一条","txt":"仲裁庭审理争议案件时，应当进行调解。必要时可以邀请有关单位、组织或者个人参与调解。"},{"i":72,"n":"第七十二条","txt":"仲裁调解达成协议的，仲裁庭应当制作调解书。 调解书应当写明仲裁请求和当事人协议的结果。调解书由仲裁员签名，加盖仲裁委员会印章，送达双方当事人。调解书经双方当事人签收后，发生法律效力。 调解不成或者调解书送达前，一方当事人反悔的，仲裁庭应当及时作出裁决。"},{"i":73,"n":"第七十三条","txt":"当事人就部分仲裁请求达成调解协议的，仲裁庭可以就该部分先行出具调解书。"},{"i":74,"n":"第七十四条","txt":"经调解组织调解达成调解协议的，双方当事人可以自调解协议生效之日起十五日内，共同向有管辖权的仲裁委员会提出仲裁审查申请。 当事人申请审查调解协议，应当向仲裁委员会提交仲裁审查申请书、调解协议和身份证明、资格证明以及其他与调解协议相关的证明材料，并提供双方当事人的送达地址、电话号码等联系方式。"},{"i":75,"n":"第七十五条","txt":"仲裁委员会收到当事人仲裁审查申请，应当及时决定是否受理。决定受理的，应当出具受理通知书。 有下列情形之一的，仲裁委员会不予受理： （一）不属于仲裁委员会受理争议范围的； （二）不属于本仲裁委员会管辖的； （三）超出规定的仲裁审查申请期间的； （四）确认劳动关系的； （五）调解协议已经人民法院司法确认的。"},{"i":76,"n":"第七十六条","txt":"仲裁委员会审查调解协议，应当自受理仲裁审查申请之日起五日内结束。因特殊情况需要延期的，经仲裁委员会主任或者其委托的仲裁院负责人批准，可以延长五日。 调解书送达前，一方或者双方当事人撤回仲裁审查申请的，仲裁委员会应当准许。"},{"i":77,"n":"第七十七条","txt":"仲裁委员会受理仲裁审查申请后，应当指定仲裁员对调解协议进行审查。 仲裁委员会经审查认为调解协议的形式和内容合法有效的，应当制作调解书。调解书的内容应当与调解协议的内容相一致。调解书经双方当事人签收后，发生法律效力。"},{"i":78,"n":"第七十八条","txt":"调解协议具有下列情形之一的，仲裁委员会不予制作调解书： （一）违反法律、行政法规强制性规定的； （二）损害国家利益、社会公共利益或者公民、法人、其他组织合法权益的； （三）当事人提供证据材料有弄虚作假嫌疑的； （四）违反自愿原则的； （五）内容不明确的； （六）其他不能制作调解书的情形。 仲裁委员会决定不予制作调解书的，应当书面通知当事人。"},{"i":79,"n":"第七十九条","txt":"当事人撤回仲裁审查申请或者仲裁委员会决定不予制作调解书的，应当终止仲裁审查。"},{"i":80,"n":"第八十条","txt":"本规则规定的“三日”、“五日”、“十日”指工作日，“十五日”、“四十五日”指自然日。"},{"i":81,"n":"第八十一条","txt":"本规则自2017年7月1日起施行。2009年1月1日人力资源社会保障部公布的《劳动人事争议仲裁办案规则》（人力资源和社会保障部令第2号）同时废止。"}],"laodongrenshizhengyizhongcaizuzhiguize":[{"i":1,"n":"第一条","txt":"为公正及时处理劳动人事争议（以下简称争议），根据《中华人民共和国劳动争议调解仲裁法》（以下简称调解仲裁法）和《中华人民共和国公务员法》、《事业单位人事管理条例》、《中国人民解放军文职人员条例》等有关法律、法规，制定本规则。"},{"i":2,"n":"第二条","txt":"劳动人事争议仲裁委员会（以下简称仲裁委员会）由人民政府依法设立，专门处理争议案件。"},{"i":3,"n":"第三条","txt":"人力资源社会保障行政部门负责指导本行政区域的争议调解仲裁工作，组织协调处理跨地区、有影响的重大争议，负责仲裁员的管理、培训等工作。"},{"i":4,"n":"第四条","txt":"仲裁委员会按照统筹规划、合理布局和适应实际需要的原则设立，由省、自治区、直辖市人民政府依法决定。"},{"i":5,"n":"第五条","txt":"仲裁委员会由干部主管部门代表、人力资源社会保障等相关行政部门代表、军队文职人员工作管理部门代表、工会代表和用人单位方面代表等组成。 仲裁委员会组成人员应当是单数。"},{"i":6,"n":"第六条","txt":"仲裁委员会设主任一名，副主任和委员若干名。 仲裁委员会主任由政府负责人或者人力资源社会保障行政部门主要负责人担任。"},{"i":7,"n":"第七条","txt":"仲裁委员会依法履行下列职责： （一）聘任、解聘专职或者兼职仲裁员； （二）受理争议案件； （三）讨论重大或者疑难的争议案件； （四）监督本仲裁委员会的仲裁活动； （五）制定本仲裁委员会的工作规则； （六）其他依法应当履行的职责。"},{"i":8,"n":"第八条","txt":"仲裁委员会应当每年至少召开两次全体会议，研究本仲裁委员会职责履行情况和重要工作事项。 仲裁委员会主任或者三分之一以上的仲裁委员会组成人员提议召开仲裁委员会会议的，应当召开。 仲裁委员会的决定实行少数服从多数原则。"},{"i":9,"n":"第九条","txt":"仲裁委员会下设实体化的办事机构，具体承担争议调解仲裁等日常工作。办事机构称为劳动人事争议仲裁院（以下简称仲裁院），设在人力资源社会保障行政部门。 仲裁院对仲裁委员会负责并报告工作。"},{"i":10,"n":"第十条","txt":"仲裁委员会的经费依法由财政予以保障。仲裁经费包括人员经费、公用经费、仲裁专项经费等。 仲裁院可以通过政府购买服务等方式聘用记录人员、安保人员等办案辅助人员。"},{"i":11,"n":"第十一条","txt":"仲裁委员会组成单位可以派兼职仲裁员常驻仲裁院，参与争议调解仲裁活动。"},{"i":12,"n":"第十二条","txt":"仲裁委员会处理争议案件实行仲裁庭制度，实行一案一庭制。 仲裁委员会可以根据案件处理实际需要设立派驻仲裁庭、巡回仲裁庭、流动仲裁庭，就近就地处理争议案件。"},{"i":13,"n":"第十三条","txt":"处理下列争议案件应当由三名仲裁员组成仲裁庭，设首席仲裁员： （一）十人以上并有共同请求的争议案件； （二）履行集体合同发生的争议案件； （三）有重大影响或者疑难复杂的争议案件； （四）仲裁委员会认为应当由三名仲裁员组庭处理的其他争议案件。 简单争议案件可以由一名仲裁员独任仲裁。"},{"i":14,"n":"第十四条","txt":"记录人员负责案件庭审记录等相关工作。 记录人员不得由本庭仲裁员兼任。"},{"i":15,"n":"第十五条","txt":"仲裁庭组成不符合规定的，仲裁委员会应当予以撤销并重新组庭。"},{"i":16,"n":"第十六条","txt":"仲裁委员会应当有专门的仲裁场所。仲裁场所应当悬挂仲裁徽章，张贴仲裁庭纪律及注意事项等，并配备仲裁庭专业设备、档案储存设备、安全监控设备和安检设施等。"},{"i":17,"n":"第十七条","txt":"仲裁工作人员在仲裁活动中应当统一着装，佩戴仲裁徽章。"},{"i":18,"n":"第十八条","txt":"仲裁员是由仲裁委员会聘任、依法调解和仲裁争议案件的专业工作人员。 仲裁员分为专职仲裁员和兼职仲裁员。专职仲裁员和兼职仲裁员在调解仲裁活动中享有同等权利，履行同等义务。 兼职仲裁员进行仲裁活动，所在单位应当予以支持。"},{"i":19,"n":"第十九条","txt":"仲裁委员会应当依法聘任一定数量的专职仲裁员，也可以根据办案工作需要，依法从干部主管部门、人力资源社会保障行政部门、军队文职人员工作管理部门、工会、企业组织等相关机构的人员以及专家学者、律师中聘任兼职仲裁员。"},{"i":20,"n":"第二十条","txt":"仲裁员享有以下权利： （一）履行职责应当具有的职权和工作条件； （二）处理争议案件不受干涉； （三）人身、财产安全受到保护； （四）参加聘前培训和在职培训； （五）法律、法规规定的其他权利。"},{"i":21,"n":"第二十一条","txt":"仲裁员应当履行以下义务： （一）依法处理争议案件； （二）维护国家利益和公共利益，保护当事人合法权益； （三）严格执行廉政规定，恪守职业道德； （四）自觉接受监督； （五）法律、法规规定的其他义务。"},{"i":22,"n":"第二十二条","txt":"仲裁委员会聘任仲裁员时，应当从符合调解仲裁法第二十条规定的仲裁员条件的人员中选聘。 仲裁委员会应当根据工作需要，合理配备专职仲裁员和办案辅助人员。专职仲裁员数量不得少于三名，办案辅助人员不得少于一名。"},{"i":23,"n":"第二十三条","txt":"仲裁委员会应当设仲裁员名册，并予以公告。 省、自治区、直辖市人力资源社会保障行政部门应当将本行政区域内仲裁委员会聘任的仲裁员名单报送人力资源社会保障部备案。"},{"i":24,"n":"第二十四条","txt":"仲裁员聘期一般为五年。仲裁委员会负责仲裁员考核，考核结果作为解聘和续聘仲裁员的依据。"},{"i":25,"n":"第二十五条","txt":"仲裁委员会应当制定仲裁员工作绩效考核标准，重点考核办案质量和效率、工作作风、遵纪守法情况等。考核结果分为优秀、合格、不合格。"},{"i":26,"n":"第二十六条","txt":"仲裁员有下列情形之一的，仲裁委员会应当予以解聘： （一）聘期届满不再续聘的； （二）在聘期内因工作岗位变动或者其他原因不再履行仲裁员职责的； （三）年度考核不合格的； （四）因违纪、违法犯罪不能继续履行仲裁员职责的； （五）其他应当解聘的情形。"},{"i":27,"n":"第二十七条","txt":"人力资源社会保障行政部门负责对拟聘任的仲裁员进行聘前培训。 拟聘为省、自治区、直辖市仲裁委员会仲裁员及副省级市仲裁委员会仲裁员的，参加人力资源社会保障部组织的聘前培训；拟聘为地（市）、县（区）仲裁委员会仲裁员的，参加省、自治区、直辖市人力资源社会保障行政部门组织的仲裁员聘前培训。"},{"i":28,"n":"第二十八条","txt":"人力资源社会保障行政部门负责每年对本行政区域内的仲裁员进行政治思想、职业道德、业务能力和作风建设培训。 仲裁员每年脱产培训的时间累计不少于四十学时。"},{"i":29,"n":"第二十九条","txt":"仲裁委员会应当加强仲裁员作风建设，培育和弘扬具有行业特色的仲裁文化。"},{"i":30,"n":"第三十条","txt":"人力资源社会保障部负责组织制定仲裁员培训大纲，开发培训教材，建立师资库和考试题库。"},{"i":31,"n":"第三十一条","txt":"建立仲裁员职业保障机制，拓展仲裁员职业发展空间。"},{"i":32,"n":"第三十二条","txt":"仲裁委员会应当建立仲裁监督制度，对申请受理、办案程序、处理结果、仲裁工作人员行为等进行监督。"},{"i":33,"n":"第三十三条","txt":"仲裁员不得有下列行为： （一）徇私枉法，偏袒一方当事人； （二）滥用职权，侵犯当事人合法权益； （三）利用职权为自己或者他人谋取私利； （四）隐瞒证据或者伪造证据； （五）私自会见当事人及其代理人，接受当事人及其代理人的请客送礼； （六）故意拖延办案、玩忽职守； （七）泄露案件涉及的国家秘密、商业秘密和个人隐私或者擅自透露案件处理情况； （八）在受聘期间担任所在仲裁委员会受理案件的代理人； （九）其他违法违纪的行为。"},{"i":34,"n":"第三十四条","txt":"仲裁员有本规则第三十三条规定情形的，仲裁委员会视情节轻重，给予批评教育、解聘等处理；被解聘的，五年内不得再次被聘为仲裁员。仲裁员所在单位根据国家有关规定对其给予处分；构成犯罪的，依法追究刑事责任。"},{"i":35,"n":"第三十五条","txt":"记录人员等办案辅助人员应当认真履行职责，严守工作纪律，不得有玩忽职守、偏袒一方当事人、泄露案件涉及的国家秘密、商业秘密和个人隐私或者擅自透露案件处理情况等行为。 办案辅助人员违反前款规定的，应当按照有关法律法规和本规则第三十四条的规定处理。"},{"i":36,"n":"第三十六条","txt":"被聘任为仲裁员的，由人力资源社会保障部统一免费发放仲裁员证和仲裁徽章。"},{"i":37,"n":"第三十七条","txt":"仲裁委员会对被解聘、辞职以及其他原因不再聘任的仲裁员，应当及时收回仲裁员证和仲裁徽章，并予以公告。"},{"i":38,"n":"第三十八条","txt":"本规则自2017年7月1日起施行。2010年1月20日人力资源社会保障部公布的《劳动人事争议仲裁组织规则》（人力资源和社会保障部令第5号）同时废止。"}],"laodongjiuyefuwuqiyechanquanjiedingguiding":[{"i":1,"n":"第一条","txt":"为了明晰劳动就业服务企业（以下简称劳服企业）产权关系，保障国家、集体和其他资产所有者的合法权益，促进劳服企业健康发展，进一步发挥其为就业服务的作用，根据国家有关法律、法规和《城镇集体所有制企业、单位清产核资产权界定暂行办法》，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称劳服企业是依法持有《劳动就业服务企业证书》，并经工商行政管理机关核准登记的企业。"},{"i":3,"n":"第三条","txt":"劳服企业产权界定系指按照国家有关法律、法规规定，明确劳服企业财产所有权归属的一种法律行为。"},{"i":4,"n":"第四条","txt":"劳服企业使用主办或扶持单位提供的资金、厂房、实物及无形资产等资产，凡事先约定为投资关系、债权债务关系或无偿资助关系的，按约定界定产权；没有约定的，按下列规定处理： （一）劳服企业开办初期和发展过程中，使用主办或扶持单位为解决职工子女和富余人员就业提供的厂房、设备和其他实物资产、无形资产及所形成的收益，应归劳服企业集体所有； （二）主办或扶持单位及其所属人员将其发明、专利技术（非职务发明、专利除外）以及其他无形资产带给劳服企业所形成的资产，应归劳服企业集体所有； （三）劳服企业使用主办或扶持单位的设备、房屋等实物资产，凡主办或扶持单位收取的折旧费、资产占用费、管理费及其他费用或实物计价之和达到或超过其资产净值的，该实物资产及其形成的资产，归劳服企业集体所有；没有超过其资产净值的剩余资产，按本规定第十三条处理。"},{"i":5,"n":"第五条","txt":"劳服企业按照国家法律、法规规定所享受的免税、减税、税前还贷和以税还贷等优惠政策，其所得及形成的资产，1993年6月30日前形成的，其产权归劳服企业集体所有；1993年7月1日后形成的，国家对其规定专门用途的，从其规定；没有规定的，按集体企业各投资者所拥有财产（含劳动积累）的比例确定产权归属。"},{"i":6,"n":"第六条","txt":"劳服企业使用银行贷款、国家借款、主办单位借款等借贷资金形成的资产，其产权归劳服企业集体所有。主办或扶持单位为劳服企业使用的贷款和借款提供了担保，并履行了连带责任的，须确定主办或扶持单位和劳服企业之间的债权债务关系。"},{"i":7,"n":"第七条","txt":"凡劳服企业按照国家有关规定使用属于主办或扶持单位提供的生产经营场地，应缴纳土地使用占用费或租凭费，其生产经营场地，该劳服企业有权继续使用。"},{"i":8,"n":"第八条","txt":"劳服企业联合经济组织投资及其形成的资产，归劳服企业联合经济组织集体所有。"},{"i":9,"n":"第九条","txt":"劳服企业使用公益金所形成的资产，归劳服企业劳动者集体所有。"},{"i":10,"n":"第十条","txt":"劳服企业资产中个人投资及其投资收益所形成的资产，应归投资者所有。"},{"i":11,"n":"第十一条","txt":"劳服企业资产中接受无偿资助的资产，归劳服企业集体所有，难以明确投资主体的，其产权暂归劳服企业劳动者集体所有。"},{"i":12,"n":"第十二条","txt":"劳服企业资产中界定为国有资产的，原主办或扶持单位不得无故抽回，该劳服企业继续有偿使用。"},{"i":13,"n":"第十三条","txt":"劳服企业使用国有资产，可按下列方式之一处理： （一）作为安置主办或扶持单位富余人员及失业人员的扶持条件； （二）由劳服企业一次付清或分散付款； （三）按国家有关规定作为投资； （四）按国家规定交纳不高于同期银行贷款利率的资产占用费，或按约定交付租金。"},{"i":14,"n":"第十四条","txt":"劳服企业资产已被平调、侵吞或无偿占用的，应依据国务院第66号令《劳动就业服务企业管理规定》和本规定进行产权界定，凡界定为劳服企业集体资产的，应按有关规定办理有关手续。 劳服企业集体所有制性质发生变化时，应依法进行产权界定。凡界定为劳服企业集体资产的，应由行业部门劳服企业管理机构或当地劳动行政部门将该资产用于兴办劳服企业，安置就业。"},{"i":15,"n":"第十五条","txt":"劳服企业日常的产权界定由各级劳动行政部门会同同级国有资产管理部门、地方税务部门进行。行业部门劳服企业管理机构应组织好本行业劳服企业的清产核资工作，并参与有关部门组织的产权界定。 劳服企业清产核资中产权界定具体工作程序，按照财政部、国家经贸委、国家税务总局下发的《城镇集体所有制企业、单位清产核资产权界定工作的具体规定》执行。"},{"i":16,"n":"第十六条","txt":"劳服企业资产中凡界定为集体、个人或其他投资者所有的，由地方税务部门进行资产核实，由当地劳动行政部门核准登记，并报地方有关部门备案；界定为国有资产的，须经当地劳动行政部门审核，并由地方税务部门进行资产核实，由国有资产管理部门核准登记。"},{"i":17,"n":"第十七条","txt":"劳服企业产权界定过程中与主管单位发生产权纠纷时，由当地劳动行政部门会同同级国有资产管理部门、地方税务部门进行调解和裁决。当事人对裁决不服的，可以提请行政复议和行政诉讼。"},{"i":18,"n":"第十八条","txt":"实行股份合作制的劳服企业和新开办的劳服企业，应按本规定进行产权界定。"},{"i":19,"n":"第十九条","txt":"凡违反本规定，阻挠、抵制或破坏劳服企业产权界定工作的，由劳动行政部门、国有资产管理部门和地方税务部门给予警告，责令其改正，并可建议企业主管部门对有关负责人员给予行政处分；构成犯罪的，提请司法机关依法追究其刑事责任。"},{"i":20,"n":"第二十条","txt":"本规定颁布前出台的有关规定中，凡与本规定条款有抵触的，一律以本规定为准。"},{"i":21,"n":"第二十一条","txt":"本规定自颁布之日起施行。"}],"laodongjianchayuanguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强劳动监察员管理工作，规范劳动监察行为，提高劳动监察工作质量，保障劳动法律、法规的贯彻实施，根据《中华人民共和国劳动法》有关监督检查人员的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"县级以上各级人民政府劳动行政部门应按照本办法规定对劳动监察员进行管理和监督。 劳动安全卫生监察员管理工作，按照现行规定执行。"},{"i":3,"n":"第三条","txt":"劳动监察员是县级以上各级人民政府劳动行政部门执行劳动监督检查公务的人员。"},{"i":4,"n":"第四条","txt":"劳动监察员必须坚持严肃执法、文明执法原则，做到有法必依、执法必严、违法必究。"},{"i":5,"n":"第五条","txt":"县级以上各级人民政府劳动行政部门根据工作需要配备专职劳动监察员和兼职劳动监察员。专职劳动监察员是劳动行政部门专门从事劳动监察工作的人员，兼职劳动监察员是劳动行政部门非专门从事劳动监察工作的人员。 兼职监察员，主要负责与其业务有关的单项监察，须对用人单位处罚时，应会同专职监察员进行。"},{"i":6,"n":"第六条","txt":"劳动监察人员执行公务，有权进入用人单位了解遵守劳动法律、法规的情况，查阅必要的资料，并对劳动场所进行检查。劳动监察人员执行公务，必须出示中华人民共和国劳动监察证件，秉公执法，并遵守有关规定。"},{"i":7,"n":"第七条","txt":"劳动监察员应当具备以下任职条件： （一）认真贯彻执行国家法律、法规和政策； （二）熟悉劳动业务，熟练掌握和运用劳动法律、法规知识； （三）坚持原则，作风正派，勤政廉洁； （四）在劳动行政部门从事劳动行政业务工作三年以上，并经国务院劳动行政部门或省级劳动行政部门劳动监察专业培训合格。"},{"i":8,"n":"第八条","txt":"劳动监察员培训工作应纳入劳动行政部门公务员培训计划，按照有关公务员培训规定办理。"},{"i":9,"n":"第九条","txt":"劳动监察员的任命程序： 劳动行政部门专职劳动监察员的任命，由劳动监察机构负责提出任命建议并填写中华人民共和国劳动监察员审批表，经同级人事管理机构审核，报劳动行政部门领导批准；兼职劳动监察员的任命，由有关业务工作机构按规定推荐人选，并填写中华人民共和国劳动监察员审批表，经同级劳动监察机构和人事管理机构进行审核，报劳动行政部门领导批准。经批准任命的劳动监察员由劳动监察机构办理颁发中华人民共和国劳动监察证件手续。 劳动监察员任命后，地方各级劳动行政部门按照规定填写《中华人民共和国劳动监察证件统计表》，逐级上报省级劳动行政部门，由省级劳动行政部门汇总并报国务院劳动行政部门备案。"},{"i":10,"n":"第十条","txt":"中华人民共和国劳动监察证件由国务院劳动行政部门统一监制。"},{"i":11,"n":"第十一条","txt":"劳动监察员遗失劳动监察证件应立即向发证单位报告。发证单位应在报上登载启事声明作废。对遗失证件者，经发证机关审核后，予以补发。 劳动监察员调离原工作岗位，或不再直接承担劳动监察任务时，由任命机关免去任职，监察机构负责收回其监察证件，并交回发证机关注销。"},{"i":12,"n":"第十二条","txt":"劳动监察员实行每三年进行一次考核验证制度。对经考核合格的换发新证，并按本办法第九条第二款规定填写报送《中华人民共和国劳动监察证件统计表》。 持证人未按规定考核验证或经考核不能胜任劳动监察工作的，注销其中华人民共和国劳动监察证件。"},{"i":13,"n":"第十三条","txt":"各级劳动行政部门应建立劳动监察员培训制度，制定培训计划，按岗位技能要求，组织进行职业技能、专业理论知识等方面的培训，不断提高监察人员的政治素质和业务素质。"},{"i":14,"n":"第十四条","txt":"劳动行政部门对模范执法、成绩优异的劳动监察员应当按照《中华人民共和国公务员法》给予奖励。"},{"i":15,"n":"第十五条","txt":"应加强对劳动监察员的监督。对越权或非公务场合使用劳动监察证件，或利用职权谋取私利、违法乱纪的劳动监察人员，应给予批评教育；情节严重的，由任命机关撤销任命、收缴其劳动监察证件，并给予处分；触犯刑律的，由司法机关依法追究刑事责任。"},{"i":16,"n":"第十六条","txt":"本办法自1995年1月1日起实行。"}],"laodongxingzhengchufatingzhengchengxuguiding":[{"i":1,"n":"第一条","txt":"为规范劳动行政处罚听证程序,根据《中华人民共和国行政处罚法》，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于依法享有行政处罚权的县级以上劳动行政部门和依法申请听证的行政处罚当事人。 县级以上劳动行政部门的法制工作机构或承担法制工作的机构负责本部门的听证工作。 劳动行政部门的法制工作机构与劳动行政执法机构为同一机构的，应遵循听证与案件调查取证职责分离的原则。"},{"i":3,"n":"第三条","txt":"劳动行政部门作出下列行政处罚决定，应当告知当事人有要求听证的权利，当事人要求听证的，劳动行政部门应当组织听证： （一）较大数额罚款； （二）没收较大数额违法所得、没收较大价值非法财物； （三）降低资质等级、吊销许可证件； （四）责令停产停业、责令关闭、限制从业； （五）其他较重的行政处罚； （六）法律、法规、规章规定的其他情形。 当事人不承担组织听证的费用。"},{"i":4,"n":"第四条","txt":"听证由听证主持人、听证记录员、案件调查取证人员、当事人及其委托代理人、与案件的处理结果有直接利害关系的第三人参加。"},{"i":5,"n":"第五条","txt":"劳动行政部门应当从本部门的下列人员中指定一名听证主持人、一名听证记录员: （一)法制工作机构的公务员； （二)未设法制机构的,承担法制工作的其他机构的公务员； （三)法制机构与行政执法机构为同一机构的，该机构其他非参与本案调查的公务员。"},{"i":6,"n":"第六条","txt":"听证主持人享有下列权利: （一)决定举行听证的时间和地点； （二)就案件的事实或者与之相关的法律进行询问、发问； （三)维护听证秩序，对违反听证秩序的人员进行警告或者批评； （四)中止或者终止听证； （五)就听证案件的处理向劳动行政部门的负责人提出书面建议。"},{"i":7,"n":"第七条","txt":"听证主持人承担下列义务: （一)将与听证有关的通知及有关材料依法及时送达当事人及其他有关人员； （二)根据听证认定的证据，依法独立、客观、公正地作出判断并写出书面报告； （三)保守与案件相关的国家秘密、商业秘密和个人隐私。 听证记录员负责制作听证笔录,并承担前款第(三)项的义务。"},{"i":8,"n":"第八条","txt":"听证案件的当事人依法享有下列权利: （一)申请回避权。依法申请听证主持人、听证记录员回避； （二)委托代理权。当事人可以亲自参加听证，也可以委托一至二人代理参加听证; (三)质证权。对本案的证据向调查人员及其证人进行质询; （四)申辩权。就本案的事实与法律问题进行申辩; （五)最后陈述权。听证结束前有权就本案的事实、法律及处理进行最后陈述。"},{"i":9,"n":"第九条","txt":"听证案件的当事人依法承担下列义务: （一)按时参加听证； （二)如实回答听证主持人的询问； （三)遵守听证秩序。"},{"i":10,"n":"第十条","txt":"与案件的处理结果有直接利害关系的第三人享有与当事人相同的权利并承担相同的义务。"},{"i":11,"n":"第十一条","txt":"劳动行政部门告知当事人有要求举行听证的权利，可以用书面形式告知，也可以用口头形式告知。以口头形式告知应当制作笔录，并经当事人签名。在告知当事人有权要求听证的同时,必须告知当事人要求举行听证的期限,即应在告知后5个工作日内提出。 当事人要求听证的，应当在接受劳动行政部门告知后5个工作日内以书面或者口头形式提出。经口头形式提出的，劳动行政部门应制作笔录，并经当事人签名。逾期不提出者，视为放弃听证权。"},{"i":12,"n":"第十二条","txt":"劳动行政部门负责听证的机构接到当事人要求听证的申请后，应当立即确定听证主持人和听证记录员。由听证主持人在举行听证的7个工作日前送达听证通知书。听证通知书应载明听证主持人和听证记录员姓名、听证时间、听证地点、调查取证人员认定的违法事实、证据及行政处罚建议等内容。 劳动行政部门的有关机构或人员接到当事人要求听证的申请后，应当立即告知本部门负责听证的机构。 除涉及国家秘密、商业秘密或者个人隐私依法予以保密外，听证应当公开进行。对于公开举行的听证，劳动行政部门可以先期公布听证案由、听证时间及地点。"},{"i":13,"n":"第十三条","txt":"听证主持人有下列情况之一的，应当自行回避，当事人也有权申请其回避: （一)参与本案的调查取证人员； （二)本案当事人的近亲属或者与当事人有其他利害关系的人员； （三)与案件的处理结果有利害关系，可能影响听证公正进行的人员。 听证记录员的回避适用前款的规定。 听证主持人和听证记录员的回避，由劳动行政部门负责人决定。"},{"i":14,"n":"第十四条","txt":"听证应当按照下列程序进行: （一)由听证主持人宣布听证会开始，宣布听证纪律、告知当事人听证中的权利和义务； （二)由案件调查取证人员宣布案件的事实、证据、适用的法律、法规和规章，以及拟作出的行政处罚决定的理由； （三)听证主持人询问当事人、案件调查取证人员、证人和其他有关人员并要求出示有关证据材料； （四)由当事人或者其代理人从事实和法律上进行答辩，并对证据材料进行质证； （五)当事人或者其代理人和本案调查取证人员就本案相关的事实和法律问题进行辩论； （六)辩论结束后，当事人作最后陈述； （七)听证主持人宣布听证会结束。 当事人及其代理人无正当理由拒不出席听证或者未经许可中途退出听证的，视为放弃听证权利，劳动行政部门终止听证。"},{"i":15,"n":"第十五条","txt":"听证应当制作笔录。笔录由听证记录员制作。听证笔录在听证结束后，应当立即交当事人或者其代理人核对无误后签字或者盖章。当事人或者其代理人拒绝签字或者盖章的，由听证主持人在笔录中注明。"},{"i":16,"n":"第十六条","txt":"所有与认定案件主要事实有关的证据都必须在听证中出示，并通过质证和辩论进行认定。劳动行政部门不得以未经听证认定的证据作为行政处罚的依据。"},{"i":17,"n":"第十七条","txt":"听证结束后，听证主持人应当根据听证确定的事实和证据，依据法律、法规和规章，向劳动行政部门负责人提出对听证案件处理的书面建议。劳动行政部门应当根据听证笔录，依据《中华人民共和国行政处罚法》第五十七条的规定作出决定。"},{"i":18,"n":"第十八条","txt":"本规定自1996年10月1日起施行。"}],"yingongsiwangzhigonggongyangqinshufanweiguiding":[{"i":1,"n":"第一条","txt":"为明确因工死亡职工供养亲属范围，根据《工伤保险条例》第三十七条第一款第二项的授权，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称因工死亡职工供养亲属，是指该职工的配偶、子女、父母、祖父母、外祖父母、孙子女、外孙子女、兄弟姐妹。 本规定所称子女，包括婚生子女、非婚生子女、养子女和有抚养关系的继子女，其中，婚生子女、非婚生子女包括遗腹子女； 本规定所称父母，包括生父母、养父母和有抚养关系的继父母； 本规定所称兄弟姐妹，包括同父母的兄弟姐妹、同父异母或者同母异父的兄弟姐妹、养兄弟姐妹、有抚养关系的继兄弟姐妹。"},{"i":3,"n":"第三条","txt":"上条规定的人员，依靠因工死亡职工生前提供主要生活来源，并有下列情形之一的，可按规定申请供养亲属抚恤金： （一）完全丧失劳动能力的； （二）工亡职工配偶男年满6O周岁、女年满55周岁的； （三）工亡职工父母男年满60周岁、女年满55周岁的； （四）工亡职工子女未满18周岁的； （五）工亡职工父母均已死亡，其祖父、外祖父年满60周岁，祖母、外祖母年满55周岁的； （六）工亡职工子女已经死亡或完全丧失劳动能力，其孙子女、外孙子女未满18周岁的； （七）工亡职工父母均已死亡或完全丧失劳动能力，其兄弟姐妹未满18周岁的。"},{"i":4,"n":"第四条","txt":"领取抚恤金人员有下列情形之一的，停止享受抚恤金待遇： （一）年满18周岁且未完全丧失劳动能力的； （二）就业或参军的； （三）工亡职工配偶再婚的； （四）被他人或组织收养的； （五）死亡的。"},{"i":5,"n":"第五条","txt":"领取抚恤金的人员，在被判刑收监执行期间，停止享受抚恤金待遇。刑满释放仍符合领取抚恤金资格的，按规定的标准享受抚恤金。"},{"i":6,"n":"第六条","txt":"因工死亡职工供养亲属享受抚恤金待遇的资格，由统筹地区社会保险经办机构核定。 因工死亡职工供养亲属的劳动能力鉴定，由因工死亡职工生前单位所在地设区的市级劳动能力鉴定委员会负责。"},{"i":7,"n":"第七条","txt":"本办法自2004年1月1日起施行。"}],"guojiajiguanshiyedanweiguancheguowuyuanguanyuzhigo287225":[{"i":1,"n":"第一条","txt":"根据《国务院关于职工工作时间的规定》（以下简称《规定》），制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于中华人民共和国境内的国家机关、社会团体和事业单位的职工。"},{"i":3,"n":"第三条","txt":"职工每日工作8小时，每周工作40小时。国家机关、事业单位实行统一的工作时间，星期六和星期日为周休息日。实行这一制度，应保证完成工作任务。一些与人民群众的安全、保健及其他日常生活密切相关的机关、事业单位，需要在国家规定的周休息日和节假日继续工作的，要调整好人员和班制，加强内部管理，保证星期六和星期日照常工作，方便人民群众。"},{"i":4,"n":"第四条","txt":"在特殊条件下从事劳动和有特殊情况，需要适当缩短工作时间的，由各省、自治区、直辖市和各主管部门按隶属关系提出意见，报人事部批准。"},{"i":5,"n":"第五条","txt":"因工作性质或者职责限制，不能实行每日工作8小时、每周工作40小时标准工时制度的，由国务院行业主管部门制定实施意见，报人事部门批准后可实行不定时工作制或综合计算工作时间制等办法。 因工作需要，不能执行国家统一的工作和休息时间的部门和单位，可根据实际情况采取轮班制的办法，灵活安排周休息日，并报同级人事部门备案。"},{"i":6,"n":"第六条","txt":"下列情况可以延长职工工作时间： （一）由于发生严重自然灾害、事故或其他灾害使人民的安全健康和国家财产遭到严重威胁需要紧急处理的； （二）为完成国家紧急任务或完成上级安排的其他紧急任务的。"},{"i":7,"n":"第七条","txt":"根据本办法第六条延长职工工作时间的，应给职工安排相应的补休。"},{"i":8,"n":"第八条","txt":"1995年5月1日实施《规定》有困难的事业单位，可以适当推迟，但最迟应当自1996年1月1日起施行。在推迟实施期间，仍按国家现行工时制度的有关规定执行。"},{"i":9,"n":"第九条","txt":"各级人事部门对《规定》的执行情况进行监督检查。"},{"i":10,"n":"第十条","txt":"各省、自治区、直辖市人民政府人事部门和国务院行业主管部门应根据《规定》和本办法，结合本地区、本行业的实际情况，提出实施意见，并报人事部备案。"},{"i":11,"n":"第十一条","txt":"本办法自1995年5月1日起施行。"},{"i":12,"n":"第十二条","txt":"本办法由人事部负责解释。"}],"guoyouqiyegongzizongetongjingjixiaoyiguagouguiding":[{"i":1,"n":"第一条","txt":"为了深化国有企业（以下简称企业）工资制度改革，建立健全工资总量调控机制，促进企业经营机制的转变和经济效益的提高，根据《全民所有制工业企业转换经营机制条例》制定本规定。"},{"i":2,"n":"第二条","txt":"工资总额同经济效益挂钩（以下简称工效挂钩）目前是向社会主义市场经济体制转换过程中，确定和调控企业工资总量的主要形式。企业实行工效挂钩办法，必须坚持工资总额增长幅度低于本企业经济效益（依据实现利税计算）增长幅度、职工实际平均工资增长幅度低于本企业劳动生产率（依据净产值计算）增长幅度的原则。"},{"i":3,"n":"第三条","txt":"实行企业工效挂钩，要贯彻效益与公平的原则，根据企业的生产经营特点，从实际情况出发，确定具体的挂钩形式。企业的工资总额基数，应在地区工资总额弹性计划范围内核定。"},{"i":4,"n":"第四条","txt":"本规定所称的经济效益指标，是指由企业选择并报经财政、劳动部门审核确定的企业工效挂钩的经济指标，本规定所称经济效益指标基数，是指用以计算上述指标增长幅度的基额。"},{"i":5,"n":"第五条","txt":"实行工效挂钩，应以能够综合反映企业经济效益和社会效益的指标作为挂钩指标，一般以实现利税、实现利润、上缴税利为主要挂钩指标；因企业生产经营特点不同，也可将实物（工作）量、业务量、销售收入、创汇额、收汇额以及劳动生产率、工资利税率、资本金利税率等综合经济效益指标做为复合挂钩指标。经财政部门认定的亏损企业可实行工资总额与减亏额指标挂钩，或采用新增工资按减亏的一定比例提取的办法。工资总额与税利总额严重倒挂的企业，可采取税利新增长部分按核定定额提取效益工资的办法。"},{"i":6,"n":"第六条","txt":"要建立能够全面反映企业综合经济效益和社会效益的考核指标体系。考核指标一般包括：企业承包合同完成情况、国有资产保值增殖状况以及质量、消耗、安全等。要把国有资产保值增殖作为否定指标，达不到考核要求的不能提取新增效益工资。其他考核指标达不到要求的，要扣减一定比例的新增效益工资。"},{"i":7,"n":"第七条","txt":"经济效益指标基数要按照鼓励先进、鞭策后进的原则核定，既对企业自身经济效益高低、潜力大小进行纵向比较，又进行企业间的横向比较。 经济效益指标基数，一般以企业上年实际完成数为基础，剔除不可比因素或不合理部分，并参照本地区同行业平均水平进行核定。"},{"i":8,"n":"第八条","txt":"对已实行工效挂钩的企业，调整经济效益指标基数还应考虑以下因素： （1）暂未实行基建和生产单位统一核算管理的企业，新建扩建项目由基建正式移交生产后，在按该项目计划增加的人数相应核增工资总额基数的同时，参照同行业或该企业人均效益水平合理核增挂钩的经济效益指标基数； （2）企业之间成建制划入划出职工，按上年决算数调整经济效益指标基数； （3）国家批准的重大经济政策改革对企业经济效益影响较大时，由财政、劳动部门批准，可适当调整企业经济效益指标基数。"},{"i":9,"n":"第九条","txt":"本规定所称工资总额基数，是指经劳动、财政部门审核确定的，工效挂钩企业用以计算年度工资总额提取量的基额。"},{"i":10,"n":"第十条","txt":"企业挂钩的工资总额，应为国家规定的全部职工的工资总额。要将职工全部工资收入逐步纳入挂钩工资总额基数，取消挂钩工资总额外提取和列支的各种工资项目。"},{"i":11,"n":"第十一条","txt":"企业的挂钩工资总额基数，原则上以企业上年劳动工资统计年报中的工资总额为基础核定，实行增人不增工资总额、减人不减工资总额的办法。"},{"i":12,"n":"第十二条","txt":"已实行工效挂钩办法的企业，其工资总额基数以上年工资清算应提取的   工资总额为基础，核增暂未实行基建和生产单位统一核算管理企业新建扩建项目的增人增资、按国家政策接收复转军人和大中专毕业生的增人增资，以及增减成建制划入划出职工的工资等其它增减工资的因素后确定。"},{"i":13,"n":"第十三条","txt":"新实行工效挂钩办法的企业，其工资总额基数以上年劳动工资统计年报中的工资总额为基础，核减一次性补发上年工资、成建制划出职工工资以及各种不合理的工资性支出；核增上年增人、成建制划入职工的翘尾工资以及国家规定的增减工资后确定。"},{"i":14,"n":"第十四条","txt":"挂钩工资总额基数外单列的原材料、燃料、动力节约奖、各种单项奖及其他工资性支出等，应纳入挂钩工资总额基数，具体办法另行制定。"},{"i":15,"n":"第十五条","txt":"本规定所称浮动比例，是指工效挂钩企业工资总额随挂钩经济指标变化而浮动的比例系数或工资含量系数。"},{"i":16,"n":"第十六条","txt":"企业工效挂钩的浮动比例，根据企业劳动生产率、工资利税率、资本金利税率等经济效益指标高低和潜力大小，按企业纵向比较与企业之间横向比较相结合的方法确定。挂钩的浮动比例一般按１：0.3～0.7核定。少数特殊的企业，其浮动比例经过批准可适当提高，但最高按低于１：１核定。"},{"i":17,"n":"第十七条","txt":"实行工资含量办法的企业，经济效益指标完成核定基数和超过基数一定幅度以内，按核定的工资系数（含量）提取含量工资，超过基数一定幅度后一般按不超过工资系数（含量）的７０％提取含量工资。"},{"i":18,"n":"第十八条","txt":"挂钩基数、浮动比例的核定，可以实行“环比”办法，办法每年核定一次；也可以采取“定比”、“工资系数”或“工资含量”法，一定三至五年不变。"},{"i":19,"n":"第十九条","txt":"企业挂钩工资总额应根据企业挂钩效益指标当年实际完成情况，严格按核定的挂钩浮动比例计算提取。经济效益增长时按核定比例增提工资总额，下降时按核定比例减提工资总额。"},{"i":20,"n":"第二十条","txt":"劳动、财政部门会同计划等部门对企业工效挂钩实施综合管理，主要职责是： （1）制定工效挂钩的政策法规和实施办法； （2）根据国民经济和社会发展对企业的要求及企业的生产经营特点，审核确定企业的挂钩方案； （3）核定企业挂钩的工资总额基数、经济效益指标基数和挂钩浮动比例，并进行年终工资清算； （4）监督检查企业工效挂钩的执行情况。"},{"i":21,"n":"第二十一条","txt":"企业工效挂钩的办法，由劳动、财政部门会同有关部门，依据本规定并结合企业的生产经营特点确定。挂钩办法要科学合理、简便易行。劳动、财政部门要积极支持企业探索新的挂钩形式，凡能促进企业改善经营管理、走向市场、提高经济效益和社会效益的挂钩办法，经批准后即可实行。"},{"i":22,"n":"第二十二条","txt":"企业的全部工资性收入应逐步纳入成本管理，实行工效挂钩办法的企业，其工资总额基数和新增工资按有关财务规定在企业成本中列支。"},{"i":23,"n":"第二十三条","txt":"企业要认真编报工资总额同经济效益挂钩方案，按管理体制经劳动、财政部门会同计划部门审核批准后执行。企业挂钩执行情况，应按劳动部、财政部、国家计委统一制定的工资总额同经济效益挂钩年度清算表，依工资管理体制进行清算。企业超过核定比例多提多发工资总额的，劳动、财政、计划部门应予以纠正并扣回。"},{"i":24,"n":"第二十四条","txt":"本规定所称国有企业包括工业、交通运输、邮电、地质勘探、建筑安装、商业、外贸、物资、农林、水利、文教、科技等企业、公司以及企业集团。"},{"i":25,"n":"第二十五条","txt":"本规定自发布之日起实行。过去办法与本规定不符合的，按本规定执行。"},{"i":26,"n":"第二十六条","txt":"各省、自治区、直辖市及计划单列市可根据本规定制定具体规定。"},{"i":27,"n":"第二十七条","txt":"本规定由劳动部、财政部、国家计委负责解释。"}],"zaizhongguojingneijiuyedewaiguorenshenjiashehuibao8fae26":[{"i":1,"n":"第一条","txt":"为了维护在中国境内就业的外国人依法参加社会保险和享受社会保险待遇的合法权益，加强社会保险管理，根据《中华人民共和国社会保险法》（以下简称社会保险法），制定本办法。"},{"i":2,"n":"第二条","txt":"在中国境内就业的外国人，是指依法获得《外国人就业证》、《外国专家证》、《外国常驻记者证》等就业证件和外国人居留证件，以及持有《外国人永久居留证》，在中国境内合法就业的非中国国籍的人员。"},{"i":3,"n":"第三条","txt":"在中国境内依法注册或者登记的企业、事业单位、社会团体、民办非企业单位、基金会、律师事务所、会计师事务所等组织（以下称用人单位）依法招用的外国人，应当依法参加职工基本养老保险、职工基本医疗保险、工伤保险、失业保险和生育保险，由用人单位和本人按照规定缴纳社会保险费。 与境外雇主订立雇用合同后，被派遣到在中国境内注册或者登记的分支机构、代表机构（以下称境内工作单位）工作的外国人，应当依法参加职工基本养老保险、职工基本医疗保险、工伤保险、失业保险和生育保险，由境内工作单位和本人按照规定缴纳社会保险费。"},{"i":4,"n":"第四条","txt":"用人单位招用外国人的，应当自办理就业证件之日起30日内为其办理社会保险登记。 受境外雇主派遣到境内工作单位工作的外国人，应当由境内工作单位按照前款规定为其办理社会保险登记。 依法办理外国人就业证件的机构，应当及时将外国人来华就业的相关信息通报当地社会保险经办机构。社会保险经办机构应当定期向相关机构查询外国人办理就业证件的情况。"},{"i":5,"n":"第五条","txt":"参加社会保险的外国人，符合条件的，依法享受社会保险待遇。 在达到规定的领取养老金年龄前离境的，其社会保险个人账户予以保留，再次来中国就业的，缴费年限累计计算；经本人书面申请终止社会保险关系的，也可以将其社会保险个人账户储存额一次性支付给本人。"},{"i":6,"n":"第六条","txt":"外国人死亡的，其社会保险个人账户余额可以依法继承。"},{"i":7,"n":"第七条","txt":"在中国境外享受按月领取社会保险待遇的外国人，应当至少每年向负责支付其待遇的社会保险经办机构提供一次由中国驻外使、领馆出具的生存证明，或者由居住国有关机构公证、认证并经中国驻外使、领馆认证的生存证明。 外国人合法入境的，可以到社会保险经办机构自行证明其生存状况，不再提供前款规定的生存证明。"},{"i":8,"n":"第八条","txt":"依法参加社会保险的外国人与用人单位或者境内工作单位因社会保险发生争议的，可以依法申请调解、仲裁、提起诉讼。用人单位或者境内工作单位侵害其社会保险权益的，外国人也可以要求社会保险行政部门或者社会保险费征收机构依法处理。"},{"i":9,"n":"第九条","txt":"具有与中国签订社会保险双边或者多边协议国家国籍的人员在中国境内就业的，其参加社会保险的办法按照协议规定办理。"},{"i":10,"n":"第十条","txt":"社会保险经办机构应当根据《外国人社会保障号码编制规则》，为外国人建立社会保障号码，并发放中华人民共和国社会保障卡。"},{"i":11,"n":"第十一条","txt":"社会保险行政部门应当按照社会保险法的规定，对外国人参加社会保险的情况进行监督检查。用人单位或者境内工作单位未依法为招用的外国人办理社会保险登记或者未依法为其缴纳社会保险费的，按照社会保险法、《劳动保障监察条例》等法律、行政法规和有关规章的规定处理。 用人单位招用未依法办理就业证件或者持有《外国人永久居留证》的外国人的，按照《外国人在中国就业管理规定》处理。"},{"i":12,"n":"第十二条","txt":"本办法自2011年10月15日起施行。 附件： 外国人社会保障号码编制规则 外国人参加中国社会保险，其社会保障号码由外国人所在国家或地区代码、有效证件号码组成。外国人有效证件为护照或《外国人永久居留证》。所在国家或地区代码和有效证件号码之间预留一位。其表现形式为：  XXX                   X             XXXXXXXXXXXXXX （国家或地区代码）  （预留位）      （有效证件号码） 1．外国人所在国家或地区代码按“ISO 3166-1-2006”国家及其地区的名称代码的第一部分国家代码规定的3位英文字母表示，如德国为DEU，丹麦DNK。遇国际标准升级时，人力资源和社会保障部统一确定代码升级时间。 取得在中国永久居留资格的外国人所在国家或地区代码与其所持《外国人永久居留证》号码中第1-3位的国家或地区代码一致（也为三位）。 2．预留位1位，默"}],"chengzhenjitisuoyouzhiqiyegongzitongjingjixiaoyigu8ff0ad":[],"jingwaijiuyezhongjieguanliguiding":[{"i":1,"n":"第一条","txt":"为规范境外就业中介活动，维护境外就业人员合法权益，根据《中华人民共和国劳动法》和国务院有关规定，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于在中国境内从事境外就业中介活动的管理。 本规定所称境外就业，是指中国公民与境外雇主签订劳动合同，在境外提供劳动并获取劳动报酬的就业行为。 本规定所称境外就业中介，是指为中国公民境外就业或者为境外雇主在中国境内招聘中国公民到境外就业提供相关服务的活动。经批准，从事该项活动的机构为境外就业中介机构。"},{"i":3,"n":"第三条","txt":"境外就业中介实行行政许可制度。未经批准及登记注册，任何单位和个人不得从事境外就业中介活动。"},{"i":4,"n":"第四条","txt":"劳动保障部门负责境外就业活动的管理和监督检查。 公安机关负责境外就业中介活动出入境秩序的管理。 工商行政管理部门负责境外就业中介机构登记注册和境外就业中介活动市场经济秩序的监督管理。"},{"i":5,"n":"第五条","txt":"从事境外就业中介活动应当具备以下条件： （一）符合企业法人设立的条件； （二）具有法律、外语、财会专业资格的专职工作人员，有健全的工作制度和工作人员守则； （三）备用金不低于50万元； （四）法律、行政法规规定的其他条件。"},{"i":6,"n":"第六条","txt":"申请从事境外就业中介活动的机构（以下简称申请机构）应当向其所在地的省级劳动保障行政部门提出申请，经初审同意并征得同级公安机关同意后，报劳动和社会保障部审批。劳动和社会保障部自收到申请之日起60日内做出答复。新设境外就业中介机构报劳动和社会保障部审批前，应当到工商行政管理机关办理名称预先核准登记。劳动和社会保障部审查批准并抄送公安部后，向该机构颁发境外就业中介许可证（以下简称许可证）。 许可证自颁发之日起有效期为3年。 境外机构、个人及外国驻华机构不得在中国境内从事境外就业中介活动。"},{"i":7,"n":"第七条","txt":"申请机构应当向审核机关提交以下文件材料： （一）填写完整的境外就业中介资格申请表； （二）企业名称预先核准通知书； （三）法定代表人或者拟任人选、主要工作人员或者拟聘用人选的简历和有关资格证明； （四）具有法定资格的验资机构出具的验资报告； （五）机构章程及内部有关规章、制度； （六）拟开展境外就业中介活动的行政区域和可行性报告； （七）住所和经营场所使用证明； （八）省级劳动保障行政部门认可的备用金存款证明； （九）劳动和社会保障部规定的其他材料。"},{"i":8,"n":"第八条","txt":"申请机构应当自领取许可证之日起30日内，到工商行政管理机关申请企业法人设立登记或者变更登记，并应当于设立登记或者变更登记核准之日起10日内，到所在地的省级劳动保障行政部门和公安机关备案。"},{"i":9,"n":"第九条","txt":"境外就业中介机构依法从事下列业务： （一）为中国公民提供境外就业信息、咨询； （二）接受境外雇主的委托，为其推荐所需招聘人员； （三）为境外就业人员进行出境前培训，并协助其办理有关职业资格证书公证等手续； （四）协助境外就业人员办理出境所需要护照、签证、公证材料、体检、防疫注射等手续和证件； （五）为境外就业人员代办社会保险； （六）协助境外就业人员通过调解、仲裁、诉讼等程序维护其合法权益。"},{"i":10,"n":"第十条","txt":"境外就业中介机构应当依法履行下列义务： （一）核查境外雇主的合法开业证明、资信证明、境外雇主所在国家或者地区移民部门或者其他有关政府主管部门批准的招聘外籍人员许可证明等有关资料； （二）协助、指导境外就业人员同境外雇主签订劳动合同，并对劳动合同的内容进行确认。 劳动合同内容应当包括合同期限、工作地点、工作内容、工作时间、劳动条件、劳动报酬、社会保险、劳动保护、休息休假、食宿条件、变更或者解除合同的条件以及劳动争议处理、违约责任等条款。"},{"i":11,"n":"第十一条","txt":"境外就业中介机构应当依法与境外就业人员签订境外就业中介服务协议书。协议书应当对双方的权利和义务、服务项目、收费标准、违约责任、赔偿条款等内容作出明确规定。"},{"i":12,"n":"第十二条","txt":"境外就业中介机构应当将签订的境外就业中介服务协议书和经其确认的境外就业劳动合同报省级劳动保障行政部门备案。省级劳动保障行政部门在10日内未提出异议的，境外就业中介机构可以向境外就业人员发出境外就业确认书。公安机关依据有关规定，凭境外就业确认书为境外就业人员办理出入境证件。"},{"i":13,"n":"第十三条","txt":"境外就业中介机构设立分支机构的，应当按照本规定第二章的规定办理申请审批、登记和备案手续。"},{"i":14,"n":"第十四条","txt":"境外就业中介机构不得以承包、转包等方式交由其他未经批准的中介机构或者个人开展境外就业中介活动。"},{"i":15,"n":"第十五条","txt":"境外就业中介机构不得组织非法出入境，不得组织中国公民到境外从事中国法律所禁止的违法犯罪活动。"},{"i":16,"n":"第十六条","txt":"发布有关境外就业中介服务广告，发布前必须经中介机构所在地省、自治区、直辖市工商行政管理局批准。无批准文件的，不得发布。"},{"i":17,"n":"第十七条","txt":"境外就业中介机构可向境外就业人员或者境外雇主收取合理的中介服务费，并接受当地物价部门监督。"},{"i":18,"n":"第十八条","txt":"境外就业中介机构应当在服务场所明示合法证照、服务项目、收费标准、监督机关名称和监督电话等，并接受劳动保障行政部门及其他有关部门的监督检查。"},{"i":19,"n":"第十九条","txt":"境外就业中介机构的名称、住所或者经营场所、法定代表人发生变更的，应当按照本规定规定的申办程序办理许可证变更，并凭新的许可证到原企业登记主管机关申请变更登记。其中，涉及名称变更的，应当在申请新的许可证时提交工商行政管理机关同意变更名称的证明文件。其他登记事项的变更，按照现行企业登记管理的有关规定办理。"},{"i":20,"n":"第二十条","txt":"境外就业中介机构拟在许可证有效期届满后继续从事境外就业中介活动的，应当在许可证有效期届满前90日内，依照本规定规定的申办程序办理更换许可证手续。许可证有效期届满，境外就业中介机构未申请更换的，由劳动和社会保障部予以注销。"},{"i":21,"n":"第二十一条","txt":"境外就业中介许可证实行年审制度。境外就业中介机构应当向所在地省级劳动保障行政部门提交上一年度经营情况以及其他相关材料。对审验不合格的境外就业中介机构，省级劳动保障行政部门应当报劳动和社会保障部，由劳动和社会保障部注销其许可证，并通报公安机关和工商行政管理机关。"},{"i":22,"n":"第二十二条","txt":"境外就业中介机构在破产、解散前，应当以书面形式向省级劳动保障行政部门提出注销许可证申请和善后事宜处理措施，并办理注销许可证手续。"},{"i":23,"n":"第二十三条","txt":"发证机关应当及时将注销境外就业中介机构经营资格的情况通报公安机关和工商行政管理机关。被注销资格的境外就业中介机构应当在收到被注销资格通知之日起10日内向发证机关缴还许可证，向原登记机关申请注销或者变更登记。"},{"i":24,"n":"第二十四条","txt":"凡违反本规定被注销境外就业中介许可证的，其法定代表人和主要责任人3年内不得从事境外就业中介活动。"},{"i":25,"n":"第二十五条","txt":"境外就业中介实行备用金制度。备用金用于因境外就业中介机构责任造成其服务对象合法权益受到损害时的赔偿及支付罚款、罚金。"},{"i":26,"n":"第二十六条","txt":"境外就业中介机构按照规定将备用金存入省级劳动保障行政部门指定的国有商业银行中该境外就业中介机构的专门帐户，实行专款专用。"},{"i":27,"n":"第二十七条","txt":"备用金及其利息由境外就业中介机构所在地省级劳动保障行政部门实行监管。未经监管部门的许可，任何单位和个人不得擅自动用备用金。"},{"i":28,"n":"第二十八条","txt":"备用金及其利息归境外就业中介机构所有。境外就业中介机构破产、解散时，其备用金及其利息作为境外就业中介机构资产的一部分，按照有关规定处置。"},{"i":29,"n":"第二十九条","txt":"境外就业中介机构无力按照仲裁机构的裁决或者人民法院的判决进行赔偿，或者无力支付罚款、罚金时，可以书面形式向备用金监管部门提出动用备用金及其利息的申请。 境外就业中介机构拒不支付罚款、罚金，拒不执行仲裁机构或者人民法院的裁决或者判决的，由执行机关依法强制执行。"},{"i":30,"n":"第三十条","txt":"备用金不足以补偿服务对象合法权益受到侵害造成的经济损失时，境外就业中介机构必须按照国家有关规定承担民事责任。"},{"i":31,"n":"第三十一条","txt":"备用金被动用后低于本规定所规定数额时，境外就业中介机构应在60日内将备用金补足至规定数额，逾期未补足的，不得开展境外就业中介业务。"},{"i":32,"n":"第三十二条","txt":"境外就业中介机构自行解散、破产或许可证被注销后，如2年内未发生针对该境外就业中介机构的投诉或者诉讼，可凭备用金监管部门开具的证明，到开户银行领取其备用金及其利息。"},{"i":33,"n":"第三十三条","txt":"单位或者个人未经劳动保障行政部门批准和工商行政管理机关登记注册，擅自从事境外就业中介活动的，由劳动保障行政部门会同工商行政管理机关依法取缔、没收其经营物品和违法所得。因非法从事境外就业中介活动，给当事人造成损害的，应当承担赔偿责任。"},{"i":34,"n":"第三十四条","txt":"境外就业中介机构违反本规定，有下列行为之一的，由劳动保障行政部门责令改正，没有违法所得的，处以10000元以下罚款；有违法所得的，处以违法所得3倍以下但不超过30000元的罚款；对当事人造成损害的，应当承担赔偿责任；构成犯罪的，依法追究刑事责任： （一）提供虚假材料骗领许可证的； （二）以承包、转包等方式交由其他未经批准的中介机构或者个人开展境外就业中介活动的； （三）拒不履行本规定第十条规定义务的； （四）不与其服务对象签订境外就业中介服务协议书的； （五）逾期未补足备用金而开展境外就业中介业务的； （六）违反本规定，严重损害境外就业人员合法权益的。"},{"i":35,"n":"第三十五条","txt":"违反本规定第十二条规定，未将境外就业中介服务协议书和劳动合同备案的，由劳动保障行政部门处以1000元以下罚款。"},{"i":36,"n":"第三十六条","txt":"境外就业中介机构在中介活动中为他人编造情况和提供假证明，骗取出入境证件，没有违法所得的，由县级以上公安机关处以10000元以下的罚款；有违法所得的，没收违法所得，并可处以违法所得3倍以下但不超过30000元的罚款；构成犯罪的，依法追究刑事责任。"},{"i":37,"n":"第三十七条","txt":"境外就业中介机构违反工商行政管理法规，由工商行政管理机关依法查处。 对未经批准发布境外就业中介服务广告的，由工商行政管理机关责令停止发布，没有违法所得的，处以10000元以下的罚款；有违法所得的，没收违法所得，并可处以违法所得3倍以下但不超过30000元的罚款。"},{"i":38,"n":"第三十八条","txt":"境外就业中介资格申请表、境外就业中介许可证由劳动和社会保障部统一制定。"},{"i":39,"n":"第三十九条","txt":"本规定实施前已领取境外就业中介许可证的，应当自本规定实施之日起90日内重新申请许可证和登记注册。"},{"i":40,"n":"第四十条","txt":"劳动和社会保障部及时向社会公布获得或者被注销许可证的境外就业中介机构名单。"},{"i":41,"n":"第四十一条","txt":"省、自治区、直辖市劳动保障行政部门可以会同同级公安机关、工商行政管理机关根据本规定制定实施办法，并报劳动和社会保障部、公安部、国家工商行政管理总局备案。"},{"i":42,"n":"第四十二条","txt":"为内地公民到香港、澳门特别行政区和台湾地区就业提供中介服务活动，不适用本规定。"},{"i":43,"n":"第四十三条","txt":"本规定自2002年7月1日起施行。原劳动部1992年11月14日公布的《境外就业服务机构管理规定》同时废止。"}],"waishangtouzirencaizhongjiejigouguanlizanxingguidifbf8ac-2":[{"i":1,"n":"第一条","txt":"为了加强对外商投资人才中介机构的管理，维护人才市场秩序，促进人才市场发展，根据有关法律、法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称外商投资人才中介机构，是指全部或者部分由外国投资者投资，依照中国法律在中国境内经登记、许可设立的人才中介机构。"},{"i":3,"n":"第三条","txt":"外国企业常驻中国代表机构和在中国成立的商会等组织不得在中国境内从事人才中介服务。"},{"i":4,"n":"第四条","txt":"外商投资人才中介机构必须遵守中华人民共和国法律、法规，不得损害中华人民共和国的社会公共利益和国家安全。 外商投资人才中介机构的正当经营活动和合法权益，受中华人民共和国法律保护。"},{"i":5,"n":"第五条","txt":"县级以上人民政府人事行政部门、商务部门和工商行政管理部门依法按照职责分工负责本行政区域内外商投资人才中介机构的审批、登记、管理和监督工作。"},{"i":6,"n":"第六条","txt":"申请设立外商投资人才中介机构，必须符合下列条件： （一）有健全的组织机构；有熟悉人力资源管理业务的人员，其中必须有5名以上具有大专以上学历并取得人才中介服务资格证书的专职人员； （二）有与其申请的业务相适应的固定场所、资金和办公设施； （三）有健全可行的机构章程、管理制度、工作规则，有明确的业务范围； （四）能够独立享有民事权利，承担民事责任； （五）法律、法规规定的其他条件。"},{"i":7,"n":"第七条","txt":"申请设立外商投资人才中介机构，应当由拟设立机构所在地的县级以上人民政府人事行政部门审批。"},{"i":8,"n":"第八条","txt":"申请设立外商投资人才中介机构，可以通过信函、电报、电传、传真、电子数据交换和电子邮件等方式向县级以上人民政府人事行政部门提出申请。申请材料应包括以下内容： （一）书面申请及可行性报告； （二）管理制度草案与章程； （三）工商营业执照（副本）； （四）法律、法规和县级以上人民政府人事行政部门要求提供的其他材料。 上述所列的申请材料凡是用外文书写的，应当附有中文译本。"},{"i":9,"n":"第九条","txt":"县级以上人民政府人事行政部门在接到设立外商投资人才中介机构的申请报告之日起20日内审核完毕，20日内不能作出决定的，经本行政机关负责人批准，可以延长10日，并应当将延长期限的理由告知申请人。 批准同意的，发给《人才中介服务许可证》（以下简称许可证），并应当在作出决定之日起10日内向申请人颁发、送达许可证；不同意的应当书面通知申请人，并说明理由。 审批机关应在行政机关网站上公布审批程序、期限和需要提交的全部材料的目录，以及批准设立的外商投资人才中介机构的名录等信息。"},{"i":10,"n":"第十条","txt":"县级以上人民政府人事行政部门根据外商投资人才中介机构的资金、人员和管理水平情况，在下列业务范围内，核准其开展一项或多项业务： （一）人才供求信息的收集、整理、储存、发布和咨询服务； （二）人才推荐； （三）人才招聘； （四）人才测评； （五）人才培训； （六）人才信息网络服务； （七）法规、规章规定的其他有关业务。"},{"i":11,"n":"第十一条","txt":"外商投资人才中介机构必须遵循自愿、公平、诚信的原则，遵守行业道德，在核准的业务范围内开展活动，不得采用不正当竞争手段。"},{"i":12,"n":"第十二条","txt":"外商投资人才中介机构招聘人才出境，应当按照中国政府有关规定办理手续。其中，不得招聘下列人才出境： （一）正在承担国家、省级重点工程、科研项目的技术和管理人员，未经单位或主管部门同意的； （二）在职国家公务员； （三）由国家统一派出而又未满轮换年限的支援西部开发的人员； （四）在岗的涉密人员和离岗脱密期未满的涉密人员； （五）有违法嫌疑正在依法接受审查尚未结案的人员； （六）法律、法规规定暂时不能流动的其他特殊岗位的人员或者需经批准方可出境的人员。"},{"i":13,"n":"第十三条","txt":"外商投资人才中介机构设立分支机构、变更机构名称、法定代表人和经营场所，应当自工商登记或者变更登记办理完毕之日起15日内，书面报告人事行政部门。"},{"i":14,"n":"第十四条","txt":"县级以上人民政府人事行政部门依法指导、检查和监督外商投资人才中介机构的日常管理和业务开展情况。 县级以上人民政府人事行政部门对其批准成立的外商投资人才中介机构依法进行检查或抽查，并可以查阅或者要求其报送有关材料。外商投资人才中介机构应接受检查，并如实提供有关情况和材料。县级以上人民政府人事行政部门应将检查结果进行公布。"},{"i":15,"n":"第十五条","txt":"外商投资人才中介机构不依法接受检查，不按规定办理许可证变更等手续，提供虚假信息或者采取其他手段欺骗用人单位和应聘人员的，县级以上人民政府人事行政部门予以警告，并可处以10000元人民币以下罚款；情节严重的，有违法所得的，处以不超过违法所得3倍的罚款，但最高不得超过30000元人民币。"},{"i":16,"n":"第十六条","txt":"违反本规定，未经批准擅自设立外商投资人才中介机构的，超出核准登记的经营范围从事经营活动的，按照《公司登记管理条例》、《无照经营查处取缔办法》和有关规定进行处罚。采用不正当竞争行为的，按照《反不正当竞争法》有关规定进行处罚。"},{"i":17,"n":"第十七条","txt":"政府部门工作人员在审批和管理外商投资人才中介机构工作中，玩忽职守、徇私舞弊，侵犯单位、个人和合资各方合法权益的，按照管理权限，由有关部门给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":18,"n":"第十八条","txt":"香港特别行政区、澳门特别行政区、台湾地区投资者投资设立人才中介机构，参照本规定执行。法律法规另有规定的，依照其规定执行。"},{"i":19,"n":"第十九条","txt":"外商投资人才中介机构在中国境内从事涉及外籍人员业务活动的，按照有关规定执行。"},{"i":20,"n":"第二十条","txt":"本规定由人事部、商务部、国家工商行政管理总局负责解释。"},{"i":21,"n":"第二十一条","txt":"本规定自2003年11月1日起施行。"}],"waishangtouzirencaizhongjiejigouguanlizanxingguidifbf8ac":[{"i":1,"n":"第一条","txt":"为了加强对外商投资人才中介机构的管理，维护人才市场秩序，促进人才市场发展，根据有关法律、法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称外商投资人才中介机构，是指全部或者部分由外国投资者投资，依照中国法律在中国境内经登记、许可设立的人才中介机构。"},{"i":3,"n":"第三条","txt":"外国企业常驻中国代表机构和在中国成立的商会等组织不得在中国境内从事人才中介服务。"},{"i":4,"n":"第四条","txt":"外商投资人才中介机构必须遵守中华人民共和国法律、法规，不得损害中华人民共和国的社会公共利益和国家安全。 外商投资人才中介机构的正当经营活动和合法权益，受中华人民共和国法律保护。"},{"i":5,"n":"第五条","txt":"县级以上人民政府人事行政部门、商务部门和工商行政管理部门依法按照职责分工负责本行政区域内外商投资人才中介机构的审批、登记、管理和监督工作。"},{"i":6,"n":"第六条","txt":"申请设立外商投资人才中介机构，必须符合下列条件： （一）有健全的组织机构；有熟悉人力资源管理业务的人员，其中必须有5名以上具有大专以上学历并取得人才中介服务资格证书的专职人员； （二）有与其申请的业务相适应的固定场所、资金和办公设施； （三）有健全可行的机构章程、管理制度、工作规则，有明确的业务范围； （四）能够独立享有民事权利，承担民事责任； （五）法律、法规规定的其他条件。"},{"i":7,"n":"第七条","txt":"申请设立外商投资人才中介机构，应当由拟设立机构所在地的县级以上人民政府人事行政部门审批。"},{"i":8,"n":"第八条","txt":"申请设立外商投资人才中介机构，可以通过信函、电报、电传、传真、电子数据交换和电子邮件等方式向县级以上人民政府人事行政部门提出申请。申请材料应包括以下内容： （一）书面申请及可行性报告； （二）管理制度草案与章程； （三）工商营业执照（副本）； （四）法律、法规和县级以上人民政府人事行政部门要求提供的其他材料。 上述所列的申请材料凡是用外文书写的，应当附有中文译本。"},{"i":9,"n":"第九条","txt":"县级以上人民政府人事行政部门在接到设立外商投资人才中介机构的申请报告之日起20日内审核完毕，20日内不能作出决定的，经本行政机关负责人批准，可以延长10日，并应当将延长期限的理由告知申请人。 批准同意的，发给《人才中介服务许可证》（以下简称许可证），并应当在作出决定之日起10日内向申请人颁发、送达许可证；不同意的应当书面通知申请人，并说明理由。 审批机关应在行政机关网站上公布审批程序、期限和需要提交的全部材料的目录，以及批准设立的外商投资人才中介机构的名录等信息。"},{"i":10,"n":"第十条","txt":"县级以上人民政府人事行政部门根据外商投资人才中介机构的资金、人员和管理水平情况，在下列业务范围内，核准其开展一项或多项业务： （一）人才供求信息的收集、整理、储存、发布和咨询服务； （二）人才推荐； （三）人才招聘； （四）人才测评； （五）人才培训； （六）人才信息网络服务； （七）法规、规章规定的其他有关业务。"},{"i":11,"n":"第十一条","txt":"外商投资人才中介机构必须遵循自愿、公平、诚信的原则，遵守行业道德，在核准的业务范围内开展活动，不得采用不正当竞争手段。"},{"i":12,"n":"第十二条","txt":"外商投资人才中介机构招聘人才出境，应当按照中国政府有关规定办理手续。其中，不得招聘下列人才出境： （一）正在承担国家、省级重点工程、科研项目的技术和管理人员，未经单位或主管部门同意的； （二）在职国家公务员； （三）由国家统一派出而又未满轮换年限的支援西部开发的人员； （四）在岗的涉密人员和离岗脱密期未满的涉密人员； （五）有违法嫌疑正在依法接受审查尚未结案的人员； （六）法律、法规规定暂时不能流动的其他特殊岗位的人员或者需经批准方可出境的人员。"},{"i":13,"n":"第十三条","txt":"外商投资人才中介机构设立分支机构、变更机构名称、法定代表人和经营场所，应当自工商登记或者变更登记办理完毕之日起15日内，书面报告人事行政部门。"},{"i":14,"n":"第十四条","txt":"县级以上人民政府人事行政部门依法指导、检查和监督外商投资人才中介机构的日常管理和业务开展情况。 县级以上人民政府人事行政部门对其批准成立的外商投资人才中介机构依法进行检查或抽查，并可以查阅或者要求其报送有关材料。外商投资人才中介机构应接受检查，并如实提供有关情况和材料。县级以上人民政府人事行政部门应将检查结果进行公布。"},{"i":15,"n":"第十五条","txt":"外商投资人才中介机构不依法接受检查，不按规定办理许可证变更等手续，提供虚假信息或者采取其他手段欺骗用人单位和应聘人员的，县级以上人民政府人事行政部门予以警告，并可处以10000元人民币以下罚款；情节严重的，有违法所得的，处以不超过违法所得3倍的罚款，但最高不得超过30000元人民币。"},{"i":16,"n":"第十六条","txt":"违反本规定，未经批准擅自设立外商投资人才中介机构的，超出核准登记的经营范围从事经营活动的，按照《公司登记管理条例》、《无照经营查处取缔办法》和有关规定进行处罚。采用不正当竞争行为的，按照《反不正当竞争法》有关规定进行处罚。"},{"i":17,"n":"第十七条","txt":"政府部门工作人员在审批和管理外商投资人才中介机构工作中，玩忽职守、徇私舞弊，侵犯单位、个人和合资各方合法权益的，按照管理权限，由有关部门给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":18,"n":"第十八条","txt":"香港特别行政区、澳门特别行政区、台湾地区投资者投资设立人才中介机构，参照本规定执行。法律法规另有规定的，依照其规定执行。"},{"i":19,"n":"第十九条","txt":"外商投资人才中介机构在中国境内从事涉及外籍人员业务活动的，按照有关规定执行。"},{"i":20,"n":"第二十条","txt":"本规定由人事部、商务部、国家工商行政管理总局负责解释。"},{"i":21,"n":"第二十一条","txt":"本规定自2003年11月1日起施行。"}],"waishangtouzizhiyejieshaojigousheliguanlizanxinggu6e0478-2":[{"i":1,"n":"第一条","txt":"为规范外商投资职业介绍机构的设立，保障求职者和用人单位的合法权益，根据有关法律、法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称外商投资职业介绍机构，是指全部或者部分由外国投资者投资，依照中国法律在中国境内经登记、许可设立的职业介绍机构。"},{"i":3,"n":"第三条","txt":"劳动保障行政部门、外经贸行政部门和工商行政管理部门在各自职权范围内负责外商投资职业介绍机构的审批、登记、管理和监督检查工作。 设立外商投资职业介绍机构应当到企业住所地国家工商行政管理总局授权的地方工商行政管理局进行登记注册后，由县级以上人民政府劳动保障行政部门（以下简称县级以上劳动保障行政部门）批准。 外国企业常驻中国代表机构和在中国成立的外国商会不得在中国从事职业介绍服务。"},{"i":4,"n":"第四条","txt":"外商投资职业介绍机构应当依法开展经营活动，其依法开展的经营活动受中国法律保护。"},{"i":5,"n":"第五条","txt":"外商投资职业介绍机构可以从事下列业务： （一）为中外求职者和用人单位、居民家庭提供职业介绍服务； （二）提供职业指导、咨询服务； （三）收集和发布劳动力市场信息； （四）举办职业招聘洽谈会 （五）根据国家有关规定从事互联网职业信息服务； （六）经县级以上劳动保障行政部门核准的其他服务项目。 外商投资职业介绍机构介绍中国公民出境就业和外国企业常驻中国代表机构聘用中方雇员按照国家有关规定执行。"},{"i":6,"n":"第六条","txt":"拟设立的外商投资职业介绍机构应当具有一定数量具备职业介绍资格的专职工作人员，有明确的业务范围、机构章程、管理制度，有与开展业务相适应的固定场所、办公设施。"},{"i":7,"n":"第七条","txt":"设立外商投资职业介绍机构，应当依法到拟设立企业住所所在地国家工商行政管理总局授权的地方工商行政管理局申请登记注册，领取营业执照。"},{"i":8,"n":"第八条","txt":"外商投资职业介绍机构应当到县级以上劳动保障行政部门提出申请，并提交下列材料： （一）设立申请书； （二）机构章程和管理制度草案； （三）拟任专职工作人员的简历和职业资格证明； （四）住所使用证明； （五）拟任负责人的基本情况、身份证明； （六）工商营业执照（副本）； （七）法律、法规规定的其他文件。"},{"i":9,"n":"第九条","txt":"县级以上劳动保障行政部门应当在接到申请之日起20个工作日内审核完毕。批准同意的，发给职业介绍许可；不予批准的，应当通知申请者。"},{"i":10,"n":"第十条","txt":"外商投资职业介绍机构设立分支机构，应当自工商登记办理完毕之日起15日内，书面报告劳动保障行政部门。"},{"i":11,"n":"第十一条","txt":"外商投资职业介绍机构的管理适用《就业服务与就业管理规定》和外商投资企业的有关管理规定。"},{"i":12,"n":"第十二条","txt":"香港特别行政区、澳门特别行政区投资者在内地以及台湾地区投资者在大陆投资设立职业介绍机构，参照本规定执行。法律法规另有规定的，依照其规定执行。"},{"i":13,"n":"第十三条","txt":"本规定自2001年12月1日起施行。"}],"waishangtouzizhiyejieshaojigousheliguanlizanxinggu6e0478":[{"i":1,"n":"第一条","txt":"为规范外商投资职业介绍机构的设立，保障求职者和用人单位的合法权益，根据有关法律、法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称外商投资职业介绍机构，是指全部或者部分由外国投资者投资，依照中国法律在中国境内经登记、许可设立的职业介绍机构。"},{"i":3,"n":"第三条","txt":"劳动保障行政部门、外经贸行政部门和工商行政管理部门在各自职权范围内负责外商投资职业介绍机构的审批、登记、管理和监督检查工作。 设立外商投资职业介绍机构应当到企业住所地国家工商行政管理总局授权的地方工商行政管理局进行登记注册后，由县级以上人民政府劳动保障行政部门（以下简称县级以上劳动保障行政部门）批准。 外国企业常驻中国代表机构和在中国成立的外国商会不得在中国从事职业介绍服务。"},{"i":4,"n":"第四条","txt":"外商投资职业介绍机构应当依法开展经营活动，其依法开展的经营活动受中国法律保护。"},{"i":5,"n":"第五条","txt":"外商投资职业介绍机构可以从事下列业务： （一）为中外求职者和用人单位、居民家庭提供职业介绍服务； （二）提供职业指导、咨询服务； （三）收集和发布劳动力市场信息； （四）举办职业招聘洽谈会 （五）根据国家有关规定从事互联网职业信息服务； （六）经县级以上劳动保障行政部门核准的其他服务项目。 外商投资职业介绍机构介绍中国公民出境就业和外国企业常驻中国代表机构聘用中方雇员按照国家有关规定执行。"},{"i":6,"n":"第六条","txt":"拟设立的外商投资职业介绍机构应当具有一定数量具备职业介绍资格的专职工作人员，有明确的业务范围、机构章程、管理制度，有与开展业务相适应的固定场所、办公设施。"},{"i":7,"n":"第七条","txt":"设立外商投资职业介绍机构，应当依法到拟设立企业住所所在地国家工商行政管理总局授权的地方工商行政管理局申请登记注册，领取营业执照。"},{"i":8,"n":"第八条","txt":"外商投资职业介绍机构应当到县级以上劳动保障行政部门提出申请，并提交下列材料： （一）设立申请书； （二）机构章程和管理制度草案； （三）拟任专职工作人员的简历和职业资格证明； （四）住所使用证明； （五）拟任负责人的基本情况、身份证明； （六）工商营业执照（副本）； （七）法律、法规规定的其他文件。"},{"i":9,"n":"第九条","txt":"县级以上劳动保障行政部门应当在接到申请之日起20个工作日内审核完毕。批准同意的，发给职业介绍许可；不予批准的，应当通知申请者。"},{"i":10,"n":"第十条","txt":"外商投资职业介绍机构设立分支机构，应当自工商登记办理完毕之日起15日内，书面报告劳动保障行政部门。"},{"i":11,"n":"第十一条","txt":"外商投资职业介绍机构的管理适用《就业服务与就业管理规定》和外商投资企业的有关管理规定。"},{"i":12,"n":"第十二条","txt":"香港特别行政区、澳门特别行政区投资者在内地以及台湾地区投资者在大陆投资设立职业介绍机构，参照本规定执行。法律法规另有规定的，依照其规定执行。"},{"i":13,"n":"第十三条","txt":"本规定自2001年12月1日起施行。"}],"waiguorenzaizhongguojiuyeguanliguiding":[{"i":1,"n":"第一条","txt":"为加强外国人在中国就业的管理，根据有关法律、法规的规定，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称外国人，指依照《中华人民共和国国籍法》规定不具有中国国籍的人员。本规定所称外国人在中国就业，指没有取得定居权的外国人在中国境内依法从事社会劳动并获取劳动报酬的行为。"},{"i":3,"n":"第三条","txt":"本规定适用于在中国境内就业的外国人和聘用外国人的用人单位。本规定不适用于外国驻华使、领馆和联合国驻华代表机构、其他国际组织中享有外交特权与豁免的人员。"},{"i":4,"n":"第四条","txt":"各省、自治区、直辖市人民政府劳动行政部门及其授权的地市级劳动行政部门负责外国人在中国就业的管理。"},{"i":5,"n":"第五条","txt":"用人单位聘用外国人须为该外国人申请就业许可，经获准并取得《中华人民共和国外国人就业许可证书》(以下简称许可证书)后方可聘用。"},{"i":6,"n":"第六条","txt":"用人单位聘用外国人从事的岗位应是有特殊需要，国内暂缺适当人选，且不违反国家有关规定的岗位。用人单位不得聘用外国人从事营业性文艺演出，但符合本规定第九条第三项规定的人员除外。"},{"i":7,"n":"第七条","txt":"外国人在中国就业须具备下列条件： (一)年满18周岁，身体健康； (二)具有从事其工作所必需的专业技能和相应的工作经历； (三)无犯罪记录； (四)有确定的聘用单位； (五)持有有效护照或能代替护照的其他国际旅行证件(以下简称代替护照的证件)。"},{"i":8,"n":"第八条","txt":"在中国就业的外国人应持Z字签证入境(有互免签证协议的，按协议办理)，入境后取得《外国人就业证》(以下简称就业证)和外国人居留证件，方可在中国境内就业。 未取得居留证件的外国人(即持F、L、C、G字签证者)、在中国留学、实习的外国人及持Z字签证外国人的随行家属不得在中国就业。特殊情况，应由用人单位按本规定规定的审批程序申领许可证书，被聘用的外国人凭许可证书到公安机关改变身份，办理就业证、居留证后方可就业。 外国驻中国使、领馆和联合国系统、其他国际组织驻中国代表机构人员的配偶在中国就业，应按《中华人民共和国外交部关于外国驻中国使领馆和联合国系统组织驻中国代表机构人员的配偶在中国任职的规定》执行，并按本条第二款规定的审批程序办理有关手续。 许可证书和就业证由劳动部统一制作。"},{"i":9,"n":"第九条","txt":"凡符合下列条件之一的外国人可免办就业许可和就业证： (一)由我国政府直接出资聘请的外籍专业技术和管理人员，或由国家机关和事业单位出资聘请，具有本国或国际权威技术管理部门或行业协会确认的高级技术职称或特殊技能资格证书的外籍专业技术和管理人员，并持有外国专家局签发的《外国专家证》的外国人； (二)持有《外国人在中华人民共和国从事海上石油作业工作准证》从事海上石油作业、不需登陆、有特殊技能的外籍劳务人员；(三)经文化部批准持《临时营业演出许可证》进行营业性文艺演出的外国人。"},{"i":10,"n":"第十条","txt":"凡符合下列条件之一的外国人可免办许可证书，入境后凭Z字签证及有关证明直接办理就业证： (一)按照我国与外国政府间、国际组织间协议、协定，执行中外合作交流项目受聘来中国工作的外国人； (二)外国企业常驻中国代表机构中的首席代表、代表。"},{"i":11,"n":"第十一条","txt":"用人单位聘用外国人，须填写《聘用外国人就业申请表》  (以下简称申请表)，向其与劳动行政主管部门同级的行业主管部门(以下简称行业主管部门)提出申请，并提供下列有效文件： (一)拟聘用外国人履历证明； (二)聘用意向书； (三)拟聘用外国人原因的报告； (四)拟聘用的外国人从事该项工作的资格证明； (五)拟聘用的外国人健康状况证明； (六)法律、法规规定的其他文件。 行业主管部门应按照本规定第六条、第七条及有关法律、法规的规定进行审批。"},{"i":12,"n":"第十二条","txt":"经行业主管部门批准后，用人单位应持申请表到本单位所在地区的省、自治区、直辖市劳动行政部门或其授权的地市级劳动行政部门办理核准手续。省、自治区、直辖市劳动行政部门或授权的地市级劳动行政部门应指定专门机构(以下简称发证机关)具体负责签发许可证书工作。发证机关应根据行业主管部门的意见和劳动力市场的需求状况进行核准，并在核准后向用人单位签发许可证书。"},{"i":13,"n":"第十三条","txt":"中央级用人单位、无行业主管部门的用人单位聘用外国人，可直接到劳动行政部门发证机关提出申请和办理就业许可手续。 外商投资企业聘雇外国人，无须行业主管部门审批，可凭合同、章程、批准证书、营业执照和本规定第十一条所规定的文件直接到劳动行政部门发证机关申领许可证书。"},{"i":14,"n":"第十四条","txt":"获准来中国工作的外国人，应凭许可证书及本国有效护照或能代替护照的证件，到中国驻外使、领馆、处申请Z字签证。 凡符合本规定第九条第二项规定的人员，应凭中国海洋石油总公司签发的通知函电申请Z字签证；凡符合第九条第三项规定的人员，应凭文化部的批件申请Z字签证； 凡符合本规定第十条第一款规定的人员，应凭合作交流项目书申请Z字签证；凡符合第十条第二项规定的人员，应凭工商行政管理部门的登记证明申请Z字签证。"},{"i":15,"n":"第十五条","txt":"用人单位应在被聘用的外国人入境后15日内，持许可证书、与被聘用的外国人签订的劳动合同及其有效护照或能代替护照的证件到原发证机关为外国人办理就业证，并填写《外国人就业登记表》。 就业证只在发证机关规定的区域内有效。"},{"i":16,"n":"第十六条","txt":"已办理就业证的外国人，应在入境后30日内，持就业证到公安机关申请办理居留证。居留证件的有效期限可根据就业证的有效期确定。"},{"i":17,"n":"第十七条","txt":"用人单位与被聘用的外国人应依法订立劳动合同。劳动合同的期限最长不得超过五年。劳动合同期限届满即行终止，但按本规定第十九条的规定履行审批手续后可以续订。"},{"i":18,"n":"第十八条","txt":"被聘用的外国人与用人单位签订的劳动合同期满时，其就业证即行失效。如需续订，该用人单位应在原合同期满前30日内，向劳动行政部门提出延长聘用时间的申请，经批准并办理就业证延期手续。"},{"i":19,"n":"第十九条","txt":"外国人被批准延长在中国就业期限或变更就业区域、单位后，应在10日内到当地公安机关办理居留证件延期或变更手续。"},{"i":20,"n":"第二十条","txt":"被聘用的外国人与用人单位的劳动合同被解除后，该用人单位应及时报告劳动、公安部门，交还该外国人的就业证和居留证件，并到公安机关办理出境手续。"},{"i":21,"n":"第二十一条","txt":"用人单位支付所聘用外国人的工资不得低于当地最低工资标准。"},{"i":22,"n":"第二十二条","txt":"在中国就业的外国人的工作时间、休息、休假劳动安全卫生以及社会保险按国家有关规定执行。"},{"i":23,"n":"第二十三条","txt":"外国人在中国就业的用人单位必须与其就业证所注明的单位相一致。 外国人在发证机关规定的区域内变更用人单位但仍从事原职业的，须经原发证机关批准，并办理就业证变更手续。 外国人离开发证机关规定的区域就业或在原规定的区域内变更用人单位且从事不同职业的，须重新办理就业许可手续。"},{"i":24,"n":"第二十四条","txt":"因违反中国法律被中国公安机关取消居留资格的外国人，用人单位应解除劳动合同，劳动部门应吊销就业证。"},{"i":25,"n":"第二十五条","txt":"用人单位与被聘用的外国人发生劳动争议，应按照《中华人民共和国劳动法》和《中华人民共和国劳动争议调解仲裁法》处理。"},{"i":26,"n":"第二十六条","txt":"劳动行政部门对就业证实行年检。用人单位聘用外国人就业每满1年，应在期满前30日内到劳动行政部门发证机关为被聘用的外国人办理就业证年检手续。逾期未办的，就业证自行失效。 外国人在中国就业期间遗失或损坏其就业证的，应立即到原发证机关办理挂失、补办或换证手续。"},{"i":27,"n":"第二十七条","txt":"对违反本规定未申领就业证擅自就业的外国人和未办理许可证书擅自聘用外国人的用人单位，由公安机关按《中华人民共和国外国人入境出境管理法实施细则》第四十四条处理。"},{"i":28,"n":"第二十八条","txt":"对拒绝劳动行政部门检查就业证、擅自变更用人单位、擅自更换职业、擅自延长就业期限的外国人，由劳动行政部门收回其就业证，并提请公安机关取消其居留资格。对需该机关遣送出境的，遣送费用由聘用单位或该外国人承担。"},{"i":29,"n":"第二十九条","txt":"对伪造、涂改、冒用、转让、买卖就业证和许可证书的外国人和用人单位，由劳动行政部门收缴就业证和许可证书，没收其非法所得，并处以1万元以上10万元以下的罚款；情节严重构成犯罪的，移送司法机关依法追究刑事责任。"},{"i":30,"n":"第三十条","txt":"发证机关或者有关部门的工作人员滥用职权、非法收费、徇私舞弊，构成犯罪的，依法追究刑事责任；不构成犯罪的，给予行政处分。"},{"i":31,"n":"第三十一条","txt":"中国的台湾和香港、澳门地区居民在内地就业按《台湾和香港、澳门居民在内地就业管理规定》执行。"},{"i":32,"n":"第三十二条","txt":"外国人在中国的台湾和香港、澳门地区就业不适用本规定。"},{"i":33,"n":"第三十三条","txt":"禁止个体经济组织和公民个人聘用外国人。"},{"i":34,"n":"第三十四条","txt":"省、自治区、直辖市劳动行政部门可会同公安等部门依据本规定制定本地区的实施细则，并报劳动部、公安部、外交部、对外贸易经济合作部备案。"},{"i":35,"n":"第三十五条","txt":"本规定由劳动部解释。"},{"i":36,"n":"第三十六条","txt":"本规定自1996年5月1日起施行。原劳动人事部和公安部1987年10月5日发布的《关于未取得居留证件的外国人和来中国留学的外国人在中国就业的若干规定》同时废止。"}],"shiyebaoxianjinshenlingfafangbanfa":[{"i":1,"n":"第一条","txt":"为保证失业人员及时获得失业保险金及其他失业保险待遇，根据《失业保险条例》（以下简称《条例》），制定本办法。"},{"i":2,"n":"第二条","txt":"参加失业保险的城镇企业事业单位职工以及按照省级人民政府规定参加失业保险的其他单位人员失业后（以下统称失业人员），申请领取失业保险金、享受其他失业保险待遇适用本办法；按照规定应参加而尚未参加失业保险的不适用本办法。"},{"i":3,"n":"第三条","txt":"劳动保障行政部门设立的经办失业保险业务的社会保险经办机构（以下简称经办机构）按照本办法规定受理失业人员领取失业保险金的申请，审核确认领取资格，核定领取失业保险金、享受其他失业保险待遇的期限及标准，负责发放失业保险金并提供其他失业保险待遇。"},{"i":4,"n":"第四条","txt":"失业人员符合《条例》第十四条规定条件的，可以申请领取失业保险金，享受其他失业保险待遇。其中，非因本人意愿中断就业的是指下列人员： （一）终止劳动合同的； （二）被用人单位解除劳动合同的； （三）被用人单位开除、除名和辞退的； （四）根据《中华人民共和国劳动法》第三十二条第二、三项与用人单位解除劳动合同的； （五）法律、行政法规另有规定的。"},{"i":5,"n":"第五条","txt":"失业人员失业前所在单位，应将失业人员的名单自终止或者解除劳动合同之日起7日内报受理其失业保险业务的经办机构备案，并按要求提供终止或解除劳动合同证明等有关材料。"},{"i":6,"n":"第六条","txt":"失业人员应在终止或者解除劳动合同之日起60日内到受理其单位失业保险业务的经办机构申领失业保险金。"},{"i":7,"n":"第七条","txt":"失业人员申领失业保险金应填写《失业保险金申领表》，并出示下列证明材料： （一）本人身份证明； （二）所在单位出具的终止或者解除劳动合同的证明； （三）失业登记； （四）省级劳动保障行政部门规定的其他材料。"},{"i":8,"n":"第八条","txt":"失业人员领取失业保险金，应由本人按月到经办机构领取，同时应向经办机构如实说明求职和接受职业指导、职业培训情况。"},{"i":9,"n":"第九条","txt":"失业人员在领取失业保险金期间患病就医的，可以按照规定向经办机构申请领取医疗补助金。"},{"i":10,"n":"第十条","txt":"失业人员在领取失业保险金期间死亡的，其家属可持失业人员死亡证明、领取人身份证明、与失业人员的关系证明，按规定向经办机构领取一次性丧葬补助金和其供养配偶、直系亲属的抚恤金。失业人员当月尚未领取的失业保险金可由其家属一并领取。"},{"i":11,"n":"第十一条","txt":"失业人员在领取失业保险金期间，应积极求职，接受职业指导和职业培训。失业人员在领取失业保险金期间求职时，可以按规定享受就业服务减免费用等优惠政策。"},{"i":12,"n":"第十二条","txt":"失业人员在领取失业保险金期间或期满后，符合享受当地城市居民最低生活保障条件的，可以按照规定申请享受城市居民最低生活保障待遇。"},{"i":13,"n":"第十三条","txt":"失业人员在领取失业保险金期间，发生《条例》第十五条规定情形之一的，不得继续领取失业保险金和享受其他失业保险待遇。"},{"i":14,"n":"第十四条","txt":"经办机构自受理失业人员领取失业保险金申请之日起10日内，对申领者的资格进行审核认定，并将结果及有关事项告知本人。经审核合格者，从其办理失业登记之日起计发失业保险金。"},{"i":15,"n":"第十五条","txt":"经办机构根据失业人员累计缴费时间核定其领取失业保险金的期限。失业人员累计缴费时间按照下列原则确定： （一）实行个人缴纳失业保险费前，按国家规定计算的工龄视同缴费时间，与《条例》发布后缴纳失业保险费的时间合并计算。 （二）失业人员在领取失业保险金期间重新就业后再次失业的，缴费时间重新计算，其领取失业保险金的期限可以与前次失业应领取而尚未领取的失业保险金的期限合并计算，但是最长不得超过24个月。失业人员在领取失业保险金期间重新就业后不满一年再次失业的，可以继续申领其前次失业应领取而尚未领取的失业保险金。"},{"i":16,"n":"第十六条","txt":"失业保险金以及医疗补助金、丧葬补助金、抚恤金、职业培训和职业介绍补贴等失业保险待遇的标准按照各省、自治区、直辖市人民政府的有关规定执行。"},{"i":17,"n":"第十七条","txt":"失业保险金应按月发放，由经办机构开具单证，失业人员凭单证到指定银行领取。"},{"i":18,"n":"第十八条","txt":"对领取失业保险金期限即将届满的失业人员，经办机构应提前一个月告知本人。 失业人员在领取失业保险金期间，发生《条例》第十五条规定情形之一的，经办机构有权即行停止其失业保险金发放，并同时停止其享受其他失业保险待遇。"},{"i":19,"n":"第十九条","txt":"经办机构应当通过准备书面资料、开设服务窗口、设立咨询电话等方式，为失业人员、用人单位和社会公众提供咨询服务。"},{"i":20,"n":"第二十条","txt":"经办机构应按规定负责失业保险金申领、发放的统计工作。"},{"i":21,"n":"第二十一条","txt":"对失业人员失业前所在单位与本人户籍不在同一统筹地区的，其失业保险金的发放和其他失业保险待遇的提供由两地劳动保障行政部门进行协商，明确具体办法。协商未能取得一致的，由上一级劳动保障行政部门确定。"},{"i":22,"n":"第二十二条","txt":"失业人员失业保险关系跨省、自治区、直辖市转迁的，失业保险费用应随失业保险关系相应划转。需划转的失业保险费用包括失业保险金、医疗补助金和职业培训、职业介绍补贴。其中，医疗补助金和职业培训、职业介绍补贴按失业人员应享受的失业保险金总额的一半计算。"},{"i":23,"n":"第二十三条","txt":"失业人员失业保险关系在省、自治区范围内跨统筹地区转迁，失业保险费用的处理由省级劳动保障行政部门规定。"},{"i":24,"n":"第二十四条","txt":"失业人员跨统筹地区转移的，凭失业保险关系迁出地经办机构出具的证明材料到迁入地经办机构领取失业保险金。"},{"i":25,"n":"第二十五条","txt":"经办机构发现不符合条件，或以涂改、伪造有关材料等非法手段骗取失业保险金和其他失业保险待遇的，应责令其退还；对情节严重的，经办机构可以提请劳动保障行政部门对其进行处罚。"},{"i":26,"n":"第二十六条","txt":"经办机构工作人员违反本办法规定的，由经办机构或主管该经办机构的劳动保障行政部门责令其改正；情节严重的，依法给予行政处分；给失业人员造成损失的，依法赔偿。"},{"i":27,"n":"第二十七条","txt":"失业人员因享受失业保险待遇与经办机构发生争议的，可以依法申请行政复议或者提起行政诉讼。"},{"i":28,"n":"第二十八条","txt":"符合《条例》规定的劳动合同期满未续订或者提前解除劳动合同的农民合同制工人申领一次性生活补助，按各省、自治区、直辖市办法执行。"},{"i":29,"n":"第二十九条","txt":"《失业保险金申领表》的样式，由劳动和社会保障部统一制定。"},{"i":30,"n":"第三十条","txt":"本办法自二〇〇一年一月一日起施行。 附件1  失业保险金申领登记表(略) 附件2 《中华人民共和国劳动法》第三十二条  有下列情形之一的，劳动者可以随时通知用人单位解除劳动合同： （一）在试用期内的； （二）用人单位以暴力、威胁或者非法限制人身自由的手段强迫劳动的； （三）用人单位未按照劳动合同约定支付劳动报酬或者提供劳动条件的。 《失业保险条例》第十四条  具备下列条件的失业人员，可以领取失业保险金： （一）按照规定参加失业保险，所在单位和本人已按照规定履行缴费义务满1年的； （二）非因本人意愿中断就业的； （三）已办理失业登记，并有求职要求的。 失业人员在领取失业保险金期间，按照规定同时享受其他失业保险待遇。 《失业保险条例》第十五条  失业人员在领取失业保险金期间有下列情形之一的，停止领取失业保险金，并同时停止享受其他失业保险待遇： （一）重新就业的； （二）应征服兵役的； （三"}],"shishishehuibaoxianfaruoganguiding":[{"i":1,"n":"第一条","txt":"社会保险法第十五条规定的统筹养老金，按照国务院规定的基础养老金计发办法计发。"},{"i":2,"n":"第二条","txt":"参加职工基本养老保险的个人达到法定退休年龄时，累计缴费不足十五年的，可以延长缴费至满十五年。社会保险法实施前参保、延长缴费五年后仍不足十五年的，可以一次性缴费至满十五年。"},{"i":3,"n":"第三条","txt":"参加职工基本养老保险的个人达到法定退休年龄后，累计缴费不足十五年（含依照第二条规定延长缴费）的，可以申请转入户籍所在地新型农村社会养老保险或者城镇居民社会养老保险，享受相应的养老保险待遇。 参加职工基本养老保险的个人达到法定退休年龄后，累计缴费不足十五年（含依照第二条规定延长缴费），且未转入新型农村社会养老保险或者城镇居民社会养老保险的，个人可以书面申请终止职工基本养老保险关系。社会保险经办机构收到申请后，应当书面告知其转入新型农村社会养老保险或者城镇居民社会养老保险的权利以及终止职工基本养老保险关系的后果，经本人书面确认后，终止其职工基本养老保险关系，并将个人账户储存额一次性支付给本人。"},{"i":4,"n":"第四条","txt":"参加职工基本养老保险的个人跨省流动就业，达到法定退休年龄时累计缴费不足十五年的，按照《国务院办公厅关于转发人力资源社会保障部财政部城镇企业职工基本养老保险关系转移接续暂行办法的通知》(国办发〔2009〕66号)有关待遇领取地的规定确定继续缴费地后，按照本规定第二条办理。"},{"i":5,"n":"第五条","txt":"参加职工基本养老保险的个人跨省流动就业，符合按月领取基本养老金条件时，基本养老金分段计算、统一支付的具体办法，按照《国务院办公厅关于转发人力资源社会保障部财政部城镇企业职工基本养老保险关系转移接续暂行办法的通知》(国办发〔2009〕66号)执行。"},{"i":6,"n":"第六条","txt":"职工基本养老保险个人账户不得提前支取。个人在达到法定的领取基本养老金条件前离境定居的，其个人账户予以保留,达到法定领取条件时，按照国家规定享受相应的养老保险待遇。其中，丧失中华人民共和国国籍的，可以在其离境时或者离境后书面申请终止职工基本养老保险关系。社会保险经办机构收到申请后，应当书面告知其保留个人账户的权利以及终止职工基本养老保险关系的后果，经本人书面确认后，终止其职工基本养老保险关系，并将个人账户储存额一次性支付给本人。 参加职工基本养老保险的个人死亡后，其个人账户中的余额可以全部依法继承。"},{"i":7,"n":"第七条","txt":"社会保险法第二十七条规定的退休人员享受基本医疗保险待遇的缴费年限按照各地规定执行。 参加职工基本医疗保险的个人，基本医疗保险关系转移接续时，基本医疗保险缴费年限累计计算。"},{"i":8,"n":"第八条","txt":"参保人员在协议医疗机构发生的医疗费用，符合基本医疗保险药品目录、诊疗项目、医疗服务设施标准的，按照国家规定从基本医疗保险基金中支付。 参保人员确需急诊、抢救的，可以在非协议医疗机构就医；因抢救必须使用的药品可以适当放宽范围。参保人员急诊、抢救的医疗服务具体管理办法由统筹地区根据当地实际情况制定。"},{"i":9,"n":"第九条","txt":"职工（包括非全日制从业人员）在两个或者两个以上用人单位同时就业的，各用人单位应当分别为职工缴纳工伤保险费。职工发生工伤，由职工受到伤害时工作的单位依法承担工伤保险责任。"},{"i":10,"n":"第十条","txt":"社会保险法第三十七条第二项中的醉酒标准，按照《车辆驾驶人员血液、呼气酒精含量阈值与检验》（GB19522-2004）执行。公安机关交通管理部门、医疗机构等有关单位依法出具的检测结论、诊断证明等材料，可以作为认定醉酒的依据。"},{"i":11,"n":"第十一条","txt":"社会保险法第三十八条第八项中的因工死亡补助金是指《工伤保险条例》第三十九条的一次性工亡补助金，标准为工伤发生时上一年度全国城镇居民人均可支配收入的20倍。 上一年度全国城镇居民人均可支配收入以国家统计局公布的数据为准。"},{"i":12,"n":"第十二条","txt":"社会保险法第三十九条第一项治疗工伤期间的工资福利，按照《工伤保险条例》第三十三条有关职工在停工留薪期内应当享受的工资福利和护理等待遇的规定执行。"},{"i":13,"n":"第十三条","txt":"失业人员符合社会保险法第四十五条规定条件的，可以申请领取失业保险金并享受其他失业保险待遇。其中，非因本人意愿中断就业包括下列情形： （一）依照劳动合同法第四十四条第一项、第四项、第五项规定终止劳动合同的； （二）由用人单位依照劳动合同法第三十九条、第四十条、第四十一条规定解除劳动合同的； （三）用人单位依照劳动合同法第三十六条规定向劳动者提出解除劳动合同并与劳动者协商一致解除劳动合同的； （四）由用人单位提出解除聘用合同或者被用人单位辞退、除名、开除的； （五）劳动者本人依照劳动合同法第三十八条规定解除劳动合同的； （六）法律、法规、规章规定的其他情形。"},{"i":14,"n":"第十四条","txt":"失业人员领取失业保险金后重新就业的，再次失业时，缴费时间重新计算。失业人员因当期不符合失业保险金领取条件的，原有缴费时间予以保留，重新就业并参保的，缴费时间累计计算。"},{"i":15,"n":"第十五条","txt":"失业人员在领取失业保险金期间，应当积极求职，接受职业介绍和职业培训。失业人员接受职业介绍、职业培训的补贴由失业保险基金按照规定支付。"},{"i":16,"n":"第十六条","txt":"社会保险基金预算、决算草案的编制、审核和批准，依照《国务院关于试行社会保险基金预算的意见》(国发〔2010〕2号)的规定执行。"},{"i":17,"n":"第十七条","txt":"社会保险经办机构应当每年至少一次将参保人员个人权益记录单通过邮寄方式寄送本人。同时，社会保险经办机构可以通过手机短信或者电子邮件等方式向参保人员发送个人权益记录。"},{"i":18,"n":"第十八条","txt":"社会保险行政部门、社会保险经办机构及其工作人员应当依法为用人单位和个人的信息保密，不得违法向他人泄露下列信息： （一）涉及用人单位商业秘密或者公开后可能损害用人单位合法利益的信息； （二）涉及个人权益的信息。"},{"i":19,"n":"第十九条","txt":"用人单位在终止或者解除劳动合同时拒不向职工出具终止或者解除劳动关系证明，导致职工无法享受社会保险待遇的，用人单位应当依法承担赔偿责任。"},{"i":20,"n":"第二十条","txt":"职工应当缴纳的社会保险费由用人单位代扣代缴。用人单位未依法代扣代缴的，由社会保险费征收机构责令用人单位限期代缴，并自欠缴之日起向用人单位按日加收万分之五的滞纳金。用人单位不得要求职工承担滞纳金。"},{"i":21,"n":"第二十一条","txt":"用人单位因不可抗力造成生产经营出现严重困难的，经省级人民政府社会保险行政部门批准后，可以暂缓缴纳一定期限的社会保险费，期限一般不超过一年。暂缓缴费期间，免收滞纳金。到期后，用人单位应当缴纳相应的社会保险费。"},{"i":22,"n":"第二十二条","txt":"用人单位按照社会保险法第六十三条的规定，提供担保并与社会保险费征收机构签订缓缴协议的，免收缓缴期间的滞纳金。"},{"i":23,"n":"第二十三条","txt":"用人单位按照本规定第二十一条、第二十二条缓缴社会保险费期间，不影响其职工依法享受社会保险待遇。"},{"i":24,"n":"第二十四条","txt":"用人单位未按月将缴纳社会保险费的明细情况告知职工本人的，由社会保险行政部门责令改正；逾期不改的，按照《劳动保障监察条例》第三十条的规定处理。"},{"i":25,"n":"第二十五条","txt":"医疗机构、药品经营单位等社会保险服务机构以欺诈、伪造证明材料或者其他手段骗取社会保险基金支出的，由社会保险行政部门责令退回骗取的社会保险金，处骗取金额二倍以上五倍以下的罚款。对与社会保险经办机构签订服务协议的医疗机构、药品经营单位，由社会保险经办机构按照协议追究责任，情节严重的，可以解除与其签订的服务协议。对有执业资格的直接负责的主管人员和其他直接责任人员，由社会保险行政部门建议授予其执业资格的有关主管部门依法吊销其执业资格。"},{"i":26,"n":"第二十六条","txt":"社会保险经办机构、社会保险费征收机构、社会保险基金投资运营机构、开设社会保险基金专户的机构和专户管理银行及其工作人员有下列违法情形的，由社会保险行政部门按照社会保险法第九十一条的规定查处： （一）将应征和已征的社会保险基金，采取隐藏、非法放置等手段，未按规定征缴、入账的； （二）违规将社会保险基金转入社会保险基金专户以外的账户的； （三）侵吞社会保险基金的； （四）将各项社会保险基金互相挤占或者其他社会保障基金挤占社会保险基金的； （五）将社会保险基金用于平衡财政预算，兴建、改建办公场所和支付人员经费、运行费用、管理费用的； （六）违反国家规定的投资运营政策的。"},{"i":27,"n":"第二十七条","txt":"职工与所在用人单位发生社会保险争议的，可以依照《中华人民共和国劳动争议调解仲裁法》、《劳动人事争议仲裁办案规则》的规定，申请调解、仲裁，提起诉讼。 职工认为用人单位有未按时足额为其缴纳社会保险费等侵害其社会保险权益行为的，也可以要求社会保险行政部门或者社会保险费征收机构依法处理。社会保险行政部门或者社会保险费征收机构应当按照社会保险法和《劳动保障监察条例》等相关规定处理。在处理过程中，用人单位对双方的劳动关系提出异议的，社会保险行政部门应当依法查明相关事实后继续处理。"},{"i":28,"n":"第二十八条","txt":"在社会保险经办机构征收社会保险费的地区，社会保险行政部门应当依法履行社会保险法第六十三条所规定的有关行政部门的职责。"},{"i":29,"n":"第二十九条","txt":"2011年7月1日后对用人单位未按时足额缴纳社会保险费的处理，按照社会保险法和本规定执行；对2011年7月1日前发生的用人单位未按时足额缴纳社会保险费的行为，按照国家和地方人民政府的有关规定执行。"},{"i":30,"n":"第三十条","txt":"本规定自2011年7月1日起施行。"}],"jiuyefuwuyujiuyeguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强就业服务和就业管理，培育和完善统一开放、竞争有序的人力资源市场，为劳动者就业和用人单位招用人员提供服务，根据就业促进法等法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"劳动者求职与就业，用人单位招用人员，劳动保障行政部门举办的公共就业服务机构和经劳动保障行政部门审批的职业中介机构从事就业服务活动，适用本规定。 本规定所称用人单位，是指在中华人民共和国境内的企业、个体经济组织、民办非企业单位等组织，以及招用与之建立劳动关系的劳动者的国家机关、事业单位、社会团体。"},{"i":3,"n":"第三条","txt":"县级以上劳动保障行政部门依法开展本行政区域内的就业服务和就业管理工作。"},{"i":4,"n":"第四条","txt":"劳动者依法享有平等就业的权利。劳动者就业，不因民族、种族、性别、宗教信仰等不同而受歧视。"},{"i":5,"n":"第五条","txt":"农村劳动者进城就业享有与城镇劳动者平等的就业权利，不得对农村劳动者进城就业设置歧视性限制。"},{"i":6,"n":"第六条","txt":"劳动者依法享有自主择业的权利。劳动者年满16周岁，有劳动能力且有就业愿望的，可凭本人身份证件，通过公共就业服务机构、职业中介机构介绍或直接联系用人单位等渠道求职。"},{"i":7,"n":"第七条","txt":"劳动者求职时，应当如实向公共就业服务机构或职业中介机构、用人单位提供个人基本情况以及与应聘岗位直接相关的知识技能、工作经历、就业现状等情况，并出示相关证明。"},{"i":8,"n":"第八条","txt":"劳动者应当树立正确的择业观念，提高就业能力和创业能力。 国家鼓励劳动者在就业前接受必要的职业教育或职业培训，鼓励城镇初高中毕业生在就业前参加劳动预备制培训。 国家鼓励劳动者自主创业、自谋职业。各级劳动保障行政部门应当会同有关部门，简化程序，提高效率，为劳动者自主创业、自谋职业提供便利和相应服务。"},{"i":9,"n":"第九条","txt":"用人单位依法享有自主用人的权利。用人单位招用人员，应当向劳动者提供平等的就业机会和公平的就业条件。"},{"i":10,"n":"第十条","txt":"用人单位可以通过下列途径自主招用人员： （一）委托公共就业服务机构或职业中介机构； （二）参加职业招聘洽谈会； （三）委托报纸、广播、电视、互联网站等大众传播媒介发布招聘信息； （四）利用本企业场所、企业网站等自有途径发布招聘信息； （五）其他合法途径。"},{"i":11,"n":"第十一条","txt":"用人单位委托公共就业服务机构或职业中介机构招用人员，或者参加招聘洽谈会时，应当提供招用人员简章，并出示营业执照（副本）或者有关部门批准其设立的文件、经办人的身份证件和受用人单位委托的证明。 招用人员简章应当包括用人单位基本情况、招用人数、工作内容、招录条件、劳动报酬、福利待遇、社会保险等内容，以及法律、法规规定的其他内容。"},{"i":12,"n":"第十二条","txt":"用人单位招用人员时，应当依法如实告知劳动者有关工作内容、工作条件、工作地点、职业危害、安全生产状况、劳动报酬以及劳动者要求了解的其他情况。 用人单位应当根据劳动者的要求，及时向其反馈是否录用的情况。"},{"i":13,"n":"第十三条","txt":"用人单位应当对劳动者的个人资料予以保密。公开劳动者的个人资料信息和使用劳动者的技术、智力成果，须经劳动者本人书面同意。"},{"i":14,"n":"第十四条","txt":"用人单位招用人员不得有下列行为： （一）提供虚假招聘信息，发布虚假招聘广告； （二）扣押被录用人员的居民身份证和其他证件； （三）以担保或者其他名义向劳动者收取财物； （四）招用未满16周岁的未成年人以及国家法律、行政法规规定不得招用的其他人员； （五）招用无合法身份证件的人员； （六）以招用人员为名牟取不正当利益或进行其他违法活动。"},{"i":15,"n":"第十五条","txt":"用人单位不得以诋毁其他用人单位信誉、商业贿赂等不正当手段招聘人员。"},{"i":16,"n":"第十六条","txt":"用人单位在招用人员时，除国家规定的不适合妇女从事的工种或者岗位外，不得以性别为由拒绝录用妇女或者提高对妇女的录用标准。 用人单位录用女职工，不得在劳动合同中规定限制女职工结婚、生育的内容。"},{"i":17,"n":"第十七条","txt":"用人单位招用人员，应当依法对少数民族劳动者给予适当照顾。"},{"i":18,"n":"第十八条","txt":"用人单位招用人员，不得歧视残疾人。"},{"i":19,"n":"第十九条","txt":"用人单位招用人员，不得以是传染病病原携带者为由拒绝录用。但是，经医学鉴定传染病病原携带者在治愈前或者排除传染嫌疑前，不得从事法律、行政法规和国务院卫生行政部门规定禁止从事的易使传染病扩散的工作。 用人单位招用人员，除国家法律、行政法规和国务院卫生行政部门规定禁止乙肝病原携带者从事的工作外，不得强行将乙肝病毒血清学指标作为体检标准。"},{"i":20,"n":"第二十条","txt":"用人单位发布的招用人员简章或招聘广告，不得包含歧视性内容。"},{"i":21,"n":"第二十一条","txt":"用人单位招用从事涉及公共安全、人身健康、生命财产安全等特殊工种的劳动者，应当依法招用持相应工种职业资格证书的人员；招用未持相应工种职业资格证书人员的，须组织其在上岗前参加专门培训，使其取得职业资格证书后方可上岗。"},{"i":22,"n":"第二十二条","txt":"用人单位招用台港澳人员后，应当按有关规定到当地劳动保障行政部门备案，并为其办理《台港澳人员就业证》。"},{"i":23,"n":"第二十三条","txt":"用人单位招用外国人，应当在外国人入境前，按有关规定到当地劳动保障行政部门为其申请就业许可，经批准并获得《中华人民共和国外国人就业许可证书》后方可招用。 用人单位招用外国人的岗位必须是有特殊技能要求、国内暂无适当人选的岗位，并且不违反国家有关规定。"},{"i":24,"n":"第二十四条","txt":"县级以上劳动保障行政部门统筹管理本行政区域内的公共就业服务工作，根据政府制定的发展计划，建立健全覆盖城乡的公共就业服务体系。 公共就业服务机构根据政府确定的就业工作目标任务，制定就业服务计划，推动落实就业扶持政策，组织实施就业服务项目，为劳动者和用人单位提供就业服务，开展人力资源市场调查分析，并受劳动保障行政部门委托经办促进就业的相关事务。"},{"i":25,"n":"第二十五条","txt":"公共就业服务机构应当免费为劳动者提供以下服务： （一）就业政策法规咨询； （二）职业供求信息、市场工资指导价位信息和职业培训信息发布； （三）职业指导和职业介绍； （四）对就业困难人员实施就业援助； （五）办理就业登记、失业登记等事务； （六）其他公共就业服务。"},{"i":26,"n":"第二十六条","txt":"公共就业服务机构应当积极拓展服务功能，根据用人单位需求提供以下服务： （一）招聘用人指导服务； （二）代理招聘服务； （三）跨地区人员招聘服务； （四）企业人力资源管理咨询等专业性服务； （五）劳动保障事务代理服务； （六）为满足用人单位需求开发的其他就业服务项目。"},{"i":27,"n":"第二十七条","txt":"公共就业服务机构应当加强职业指导工作，配备专（兼）职职业指导工作人员，向劳动者和用人单位提供职业指导服务。 公共就业服务机构应当为职业指导工作提供相应的设施和条件，推动职业指导工作的开展，加强对职业指导工作的宣传。"},{"i":28,"n":"第二十八条","txt":"职业指导工作包括以下内容： （一）向劳动者和用人单位提供国家有关劳动保障的法律法规和政策、人力资源市场状况咨询； （二）帮助劳动者了解职业状况，掌握求职方法，确定择业方向，增强择业能力； （三）向劳动者提出培训建议，为其提供职业培训相关信息； （四）开展对劳动者个人职业素质和特点的测试，并对其职业能力进行评价； （五）对妇女、残疾人、少数民族人员及退出现役的军人等就业群体提供专门的职业指导服务； （六）对大中专学校、职业院校、技工学校学生的职业指导工作提供咨询和服务； （七）对准备从事个体劳动或开办私营企业的劳动者提供创业咨询服务； （八）为用人单位提供选择招聘方法、确定用人条件和标准等方面的招聘用人指导； （九）为职业培训机构确立培训方向和专业设置等提供咨询参考。"},{"i":29,"n":"第二十九条","txt":"公共就业服务机构在劳动保障行政部门的指导下，组织实施劳动力资源调查和就业、失业状况统计工作。"},{"i":30,"n":"第三十条","txt":"公共就业服务机构应当针对特定就业群体的不同需求，制定并组织实施专项计划。 公共就业服务机构应当根据服务对象的特点，在一定时期内为不同类型的劳动者、就业困难对象或用人单位集中组织活动，开展专项服务。 公共就业服务机构受劳动保障行政部门委托，可以组织开展促进就业的专项工作。"},{"i":31,"n":"第三十一条","txt":"县级以上公共就业服务机构建立综合性服务场所，集中为劳动者和用人单位提供一站式就业服务，并承担劳动保障行政部门安排的其他工作。 街道、乡镇、社区公共就业服务机构建立基层服务窗口，开展以就业援助为重点的公共就业服务，实施劳动力资源调查统计，并承担上级劳动保障行政部门安排的其他就业服务工作。 公共就业服务机构使用全国统一标识。"},{"i":32,"n":"第三十二条","txt":"公共就业服务机构应当不断提高服务的质量和效率。 公共就业服务机构应当加强内部管理，完善服务功能，统一服务流程，按照国家制定的服务规范和标准，为劳动者和用人单位提供优质高效的就业服务。 公共就业服务机构应当加强工作人员的政策、业务和服务技能培训，组织职业指导人员、职业信息分析人员、劳动保障协理员等专业人员参加相应职业资格培训。 公共就业服务机构应当公开服务制度，主动接受社会监督。"},{"i":33,"n":"第三十三条","txt":"县级以上劳动保障行政部门和公共就业服务机构应当按照劳动保障信息化建设的统一规划、标准和规范，建立完善人力资源市场信息网络及相关设施。 公共就业服务机构应当逐步实行信息化管理与服务，在城市内实现就业服务、失业保险、就业培训信息共享和公共就业服务全程信息化管理，并逐步实现与劳动工资信息、社会保险信息的互联互通和信息共享。"},{"i":34,"n":"第三十四条","txt":"公共就业服务机构应当建立健全人力资源市场信息服务体系，完善职业供求信息、市场工资指导价位信息、职业培训信息、人力资源市场分析信息的发布制度，为劳动者求职择业、用人单位招用人员以及培训机构开展培训提供支持。"},{"i":35,"n":"第三十五条","txt":"县级以上劳动保障行政部门应当按照信息化建设统一要求，逐步实现全国人力资源市场信息联网。其中，城市应当按照劳动保障数据中心建设的要求，实现网络和数据资源的集中和共享；省、自治区应当建立人力资源市场信息网省级监测中心，对辖区内人力资源市场信息进行监测；劳动保障部设立人力资源市场信息网全国监测中心，对全国人力资源市场信息进行监测和分析。"},{"i":36,"n":"第三十六条","txt":"县级以上劳动保障行政部门应当对公共就业服务机构加强管理，定期对其完成各项任务情况进行绩效考核。"},{"i":37,"n":"第三十七条","txt":"公共就业服务经费纳入同级财政预算。各级劳动保障行政部门和公共就业服务机构应当根据财政预算编制的规定，依法编制公共就业服务年度预算，报经同级财政部门审批后执行。 公共就业服务机构可以按照就业专项资金管理相关规定，依法申请公共就业服务专项扶持经费。 公共就业服务机构接受社会各界提供的捐赠和资助，按照国家有关法律法规管理和使用。 公共就业服务机构为用人单位提供的服务，应当规范管理，严格控制服务收费。确需收费的，具体项目由省级劳动保障行政部门会同相关部门规定。"},{"i":38,"n":"第三十八条","txt":"公共就业服务机构不得从事经营性活动。 公共就业服务机构举办的招聘会，不得向劳动者收取费用。"},{"i":39,"n":"第三十九条","txt":"各级残疾人联合会所属的残疾人就业服务机构是公共就业服务机构的组成部分，负责为残疾劳动者提供相关就业服务，并经劳动保障行政部门委托，承担残疾劳动者的就业登记、失业登记工作。"},{"i":40,"n":"第四十条","txt":"公共就业服务机构应当制定专门的就业援助计划，对就业援助对象实施优先扶持和重点帮助。 本规定所称就业援助对象包括就业困难人员和零就业家庭。就业困难对象是指因身体状况、技能水平、家庭因素、失去土地等原因难以实现就业，以及连续失业一定时间仍未能实现就业的人员。零就业家庭是指法定劳动年龄内的家庭人员均处于失业状况的城市居民家庭。 对援助对象的认定办法，由省级劳动保障行政部门依据当地人民政府规定的就业援助对象范围制定。"},{"i":41,"n":"第四十一条","txt":"就业困难人员和零就业家庭可以向所在地街道、社区公共就业服务机构申请就业援助。经街道、社区公共就业服务机构确认属实的，纳入就业援助范围。"},{"i":42,"n":"第四十二条","txt":"公共就业服务机构应当建立就业困难人员帮扶制度，通过落实各项就业扶持政策、提供就业岗位信息、组织技能培训等有针对性的就业服务和公益性岗位援助，对就业困难人员实施优先扶持和重点帮助。 在公益性岗位上安置的就业困难人员，按照国家规定给予岗位补贴。"},{"i":43,"n":"第四十三条","txt":"公共就业服务机构应当建立零就业家庭即时岗位援助制度，通过拓宽公益性岗位范围，开发各类就业岗位等措施，及时向零就业家庭中的失业人员提供适当的就业岗位，确保零就业家庭至少有一人实现就业。"},{"i":44,"n":"第四十四条","txt":"街道、社区公共就业服务机构应当对辖区内就业援助对象进行登记，建立专门台账，实行就业援助对象动态管理和援助责任制度，提供及时、有效的就业援助。"},{"i":45,"n":"第四十五条","txt":"县级以上劳动保障行政部门应当加强对职业中介机构的管理，鼓励其提高服务质量，发挥其在促进就业中的作用。 本规定所称职业中介机构，是指由法人、其他组织和公民个人举办，为用人单位招用人员和劳动者求职提供中介服务以及其他相关服务的经营性组织。 政府部门不得举办或者与他人联合举办经营性的职业中介机构。"},{"i":46,"n":"第四十六条","txt":"从事职业中介活动，应当遵循合法、诚实信用、公平、公开的原则。 禁止任何组织或者个人利用职业中介活动侵害劳动者和用人单位的合法权益。"},{"i":47,"n":"第四十七条","txt":"职业中介实行行政许可制度。设立职业中介机构或其他机构开展职业中介活动，须经劳动保障行政部门批准，并获得职业中介许可证。 未经依法许可和登记的机构，不得从事职业中介活动。 职业中介许可证由劳动保障部统一印制并免费发放。"},{"i":48,"n":"第四十八条","txt":"设立职业中介机构应当具备下列条件： （一）有明确的机构章程和管理制度； （二）有开展业务必备的固定场所、办公设施和一定数额的开办资金； （三）有一定数量具备相应职业资格的专职工作人员； （四）法律、法规规定的其他条件。"},{"i":49,"n":"第四十九条","txt":"设立职业中介机构，应当向当地县级以上劳动保障行政部门提出申请，提交下列文件： （一）设立申请书； （二）机构章程和管理制度草案； （三）场所使用权证明； （四）拟任负责人的基本情况、身份证明； （五）具备相应职业资格的专职工作人员的相关证明； （六）工商营业执照（副本）； （七）法律、法规规定的其他文件。"},{"i":50,"n":"第五十条","txt":"劳动保障行政部门接到设立职业中介机构的申请后，应当自受理申请之日起20日内审理完毕。对符合条件的，应当予以批准；不予批准的，应当说明理由。 劳动保障行政部门对经批准设立的职业中介机构实行年度审验。 职业中介机构的具体设立条件、审批和年度审验程序，由省级劳动保障行政部门统一规定。"},{"i":51,"n":"第五十一条","txt":"职业中介机构变更名称、住所、法定代表人等或者终止的，应当按照设立许可程序办理变更或者注销登记手续。 设立分支机构的，应当在征得原审批机关的书面同意后，由拟设立分支机构所在地县级以上劳动保障行政部门审批。"},{"i":52,"n":"第五十二条","txt":"职业中介机构可以从事下列业务： （一）为劳动者介绍用人单位； （二）为用人单位和居民家庭推荐劳动者； （三）开展职业指导、人力资源管理咨询服务； （四）收集和发布职业供求信息； （五）根据国家有关规定从事互联网职业信息服务； （六）组织职业招聘洽谈会； （七）经劳动保障行政部门核准的其他服务项目。"},{"i":53,"n":"第五十三条","txt":"职业中介机构应当在服务场所明示营业执照、职业中介许可证、服务项目、收费标准、监督机关名称和监督电话等，并接受劳动保障行政部门及其他有关部门的监督检查。"},{"i":54,"n":"第五十四条","txt":"职业中介机构应当建立服务台账，记录服务对象、服务过程、服务结果和收费情况等，并接受劳动保障行政部门的监督检查。"},{"i":55,"n":"第五十五条","txt":"职业中介机构提供职业中介服务不成功的，应当退还向劳动者收取的中介服务费。"},{"i":56,"n":"第五十六条","txt":"职业中介机构租用场地举办大规模职业招聘洽谈会，应当制定相应的组织实施办法和安全保卫工作方案，并向批准其设立的机关报告。 职业中介机构应当对入场招聘用人单位的主体资格真实性和招用人员简章真实性进行核实。"},{"i":57,"n":"第五十七条","txt":"职业中介机构为特定对象提供公益性就业服务的，可以按照规定给予补贴。可以给予补贴的公益性就业服务的范围、对象、服务效果和补贴办法，由省级劳动保障行政部门会同有关部门制定。"},{"i":58,"n":"第五十八条","txt":"禁止职业中介机构有下列行为： （一）提供虚假就业信息； （二）发布的就业信息中包含歧视性内容； （三）伪造、涂改、转让职业中介许可证； （四）为无合法证照的用人单位提供职业中介服务； （五）介绍未满16周岁的未成年人就业； （六）为无合法身份证件的劳动者提供职业中介服务； （七）介绍劳动者从事法律、法规禁止从事的职业； （八）扣押劳动者的居民身份证和其他证件，或者向劳动者收取押金； （九）以暴力、胁迫、欺诈等方式进行职业中介活动； （十）超出核准的业务范围经营； （十一）其他违反法律、法规规定的行为。"},{"i":59,"n":"第五十九条","txt":"县级以上劳动保障行政部门应当依法对经审批设立的职业中介机构开展职业中介活动进行监督指导，定期组织对其服务信用和服务质量进行评估，并将评估结果向社会公布。 县级以上劳动保障行政部门应当指导职业中介机构开展工作人员培训，提高服务质量。 县级以上劳动保障行政部门对在诚信服务、优质服务和公益性服务等方面表现突出的职业中介机构和个人，报经同级人民政府批准后，给予表彰和奖励。"},{"i":60,"n":"第六十条","txt":"设立外商投资职业中介机构以及职业中介机构从事境外就业中介服务的，按照有关规定执行。"},{"i":61,"n":"第六十一条","txt":"劳动保障行政部门应当建立健全就业登记制度和失业登记制度，完善就业管理和失业管理。 公共就业服务机构负责就业登记与失业登记工作，建立专门台账，及时、准确地记录劳动者就业与失业变动情况，并做好相应统计工作。 就业登记和失业登记在各省、自治区、直辖市范围内实行统一的就业失业登记证（以下简称登记证），向劳动者免费发放，并注明可享受的相应扶持政策。 就业登记、失业登记的具体程序和登记证的样式，由省级劳动保障行政部门规定。"},{"i":62,"n":"第六十二条","txt":"劳动者被用人单位招用的，由用人单位为劳动者办理就业登记。用人单位招用劳动者和与劳动者终止或者解除劳动关系，应当到当地公共就业服务机构备案，为劳动者办理就业登记手续。用人单位招用人员后，应当于录用之日起30日内办理登记手续；用人单位与职工终止或者解除劳动关系后，应当于15日内办理登记手续。 劳动者从事个体经营或灵活就业的，由本人在街道、乡镇公共就业服务机构办理就业登记。 就业登记的内容主要包括劳动者个人信息、就业类型、就业时间、就业单位以及订立、终止或者解除劳动合同情况等。就业登记的具体内容和所需材料由省级劳动保障行政部门规定。 公共就业服务机构应当对用人单位办理就业登记及相关手续设立专门服务窗口，简化程序，方便用人单位办理。"},{"i":63,"n":"第六十三条","txt":"在法定劳动年龄内，有劳动能力，有就业要求，处于无业状态的城镇常住人员，可以到常住地的公共就业服务机构进行失业登记。"},{"i":64,"n":"第六十四条","txt":"劳动者进行失业登记时，须持本人身份证件；有单位就业经历的，还须持与原单位终止、解除劳动关系或者解聘的证明。 登记失业人员凭登记证享受公共就业服务和就业扶持政策；其中符合条件的，按规定申领失业保险金。 登记失业人员应当定期向公共就业服务机构报告就业失业状况，积极求职，参加公共就业服务机构安排的就业培训。"},{"i":65,"n":"第六十五条","txt":"失业登记的范围包括下列失业人员： （一）年满16周岁，从各类学校毕业、肄业的； （二）从企业、机关、事业单位等各类用人单位失业的； （三）个体工商户业主或私营企业业主停业、破产停止经营的； （四）承包土地被征用，符合当地规定条件的； （五）军人退出现役且未纳入国家统一安置的； （六）刑满释放、假释、监外执行的； （七）各地确定的其他失业人员。"},{"i":66,"n":"第六十六条","txt":"登记失业人员出现下列情形之一的，由公共就业服务机构注销其失业登记： （一）被用人单位录用的； （二）从事个体经营或创办企业，并领取工商营业执照的； （三）已从事有稳定收入的劳动，并且月收入不低于当地最低工资标准的； （四）已享受基本养老保险待遇的； （五）完全丧失劳动能力的； （六）入学、服兵役、移居境外的； （七）被判刑收监执行的； （八）终止就业要求或拒绝接受公共就业服务的； （九）连续6个月未与公共就业服务机构联系的； （十）已进行就业登记的其他人员或各地规定的其他情形。"},{"i":67,"n":"第六十七条","txt":"用人单位违反本规定第十四条第（二）、（三）项规定的，按照劳动合同法第八十四条的规定予以处罚；用人单位违反第十四条第（四）项规定的，按照国家禁止使用童工和其他有关法律、法规的规定予以处罚。用人单位违反第十四条第（一）、（五）、（六）项规定的，由劳动保障行政部门责令改正，并可处以一千元以下的罚款；对当事人造成损害的，应当承担赔偿责任。"},{"i":68,"n":"第六十八条","txt":"用人单位违反本规定第十九条第二款规定，在国家法律、行政法规和国务院卫生行政部门规定禁止乙肝病原携带者从事的工作岗位以外招用人员时，将乙肝病毒血清学指标作为体检标准的，由劳动保障行政部门责令改正，并可处以一千元以下的罚款；对当事人造成损害的，应当承担赔偿责任。"},{"i":69,"n":"第六十九条","txt":"违反本规定第三十八条规定，公共就业服务机构从事经营性职业中介活动向劳动者收取费用的，由劳动保障行政部门责令限期改正，将违法收取的费用退还劳动者，并对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":70,"n":"第七十条","txt":"违反本规定第四十七条规定，未经许可和登记，擅自从事职业中介活动的，由劳动保障行政部门或者其他主管部门按照就业促进法第六十四条规定予以处罚。"},{"i":71,"n":"第七十一条","txt":"职业中介机构违反本规定第五十三条规定，未明示职业中介许可证、监督电话的，由劳动保障行政部门责令改正，并可处以一千元以下的罚款；未明示收费标准的，提请价格主管部门依据国家有关规定处罚；未明示营业执照的，提请工商行政管理部门依据国家有关规定处罚。"},{"i":72,"n":"第七十二条","txt":"职业中介机构违反本规定第五十四条规定，未建立服务台账，或虽建立服务台账但未记录服务对象、服务过程、服务结果和收费情况的，由劳动保障行政部门责令改正，并可处以一千元以下的罚款。"},{"i":73,"n":"第七十三条","txt":"职业中介机构违反本规定第五十五条规定，在职业中介服务不成功后未向劳动者退还所收取的中介服务费的，由劳动保障行政部门责令改正，并可处以一千元以下的罚款。"},{"i":74,"n":"第七十四条","txt":"职业中介机构违反本规定第五十八条第（一）、（三）、（四）、（八）项规定的，按照就业促进法第六十五条、第六十六条规定予以处罚。违反本规定第五十八条第（五）项规定的，按照国家禁止使用童工的规定予以处罚。违反本规定第五十八条其他各项规定的，由劳动保障行政部门责令改正，没有违法所得的，可处以一万元以下的罚款；有违法所得的，可处以不超过违法所得三倍的罚款，但最高不得超过三万元；情节严重的，提请工商部门依法吊销营业执照；对当事人造成损害的，应当承担赔偿责任。"},{"i":75,"n":"第七十五条","txt":"用人单位违反本规定第六十二条规定，未及时为劳动者办理就业登记手续的，由劳动保障行政部门责令改正。"},{"i":76,"n":"第七十六条","txt":"本规定自2008年1月1日起施行。劳动部1994年10月27日颁布的《职业指导办法》、劳动保障部2000年12月8日颁布的《劳动力市场管理规定》同时废止。"}],"gongshangbaoxianfuzhuqijupeizhiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范工伤保险辅助器具配置管理，维护工伤职工的合法权益，根据《工伤保险条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"工伤职工因日常生活或者就业需要，经劳动能力鉴定委员会确认，配置假肢、矫形器、假眼、假牙和轮椅等辅助器具的，适用本办法。"},{"i":3,"n":"第三条","txt":"人力资源社会保障行政部门负责工伤保险辅助器具配置的监督管理工作。民政、卫生计生等行政部门在各自职责范围内负责工伤保险辅助器具配置的有关监督管理工作。 社会保险经办机构（以下称经办机构）负责对申请承担工伤保险辅助器具配置服务的辅助器具装配机构和医疗机构（以下称工伤保险辅助器具配置机构）进行协议管理，并按照规定核付配置费用。"},{"i":4,"n":"第四条","txt":"设区的市级（含直辖市的市辖区、县）劳动能力鉴定委员会（以下称劳动能力鉴定委员会）负责工伤保险辅助器具配置的确认工作。"},{"i":5,"n":"第五条","txt":"省、自治区、直辖市人力资源社会保障行政部门负责制定工伤保险辅助器具配置机构评估确定办法。 经办机构按照评估确定办法，与工伤保险辅助器具配置机构签订服务协议，并向社会公布签订服务协议的工伤保险辅助器具配置机构（以下称协议机构）名单。"},{"i":6,"n":"第六条","txt":"人力资源社会保障部根据社会经济发展水平、工伤职工日常生活和就业需要等，组织制定国家工伤保险辅助器具配置目录，确定配置项目、适用范围、最低使用年限等内容，并适时调整。 省、自治区、直辖市人力资源社会保障行政部门可以结合本地区实际，在国家目录确定的配置项目基础上，制定省级工伤保险辅助器具配置目录，适当增加辅助器具配置项目，并确定本地区辅助器具配置最高支付限额等具体标准。"},{"i":7,"n":"第七条","txt":"工伤职工认为需要配置辅助器具的，可以向劳动能力鉴定委员会提出辅助器具配置确认申请，并提交下列材料： （一）居民身份证或者社会保障卡等有效身份证明原件； （二）有效的诊断证明、按照医疗机构病历管理有关规定复印或者复制的检查、检验报告等完整病历材料。 工伤职工本人因身体等原因无法提出申请的，可由其近亲属或者用人单位代为申请。"},{"i":8,"n":"第八条","txt":"劳动能力鉴定委员会收到辅助器具配置确认申请后，应当及时审核；材料不完整的，应当自收到申请之日起5个工作日内一次性书面告知申请人需要补正的全部材料；材料完整的，应当在收到申请之日起60日内作出确认结论。伤情复杂、涉及医疗卫生专业较多的，作出确认结论的期限可以延长30日。"},{"i":9,"n":"第九条","txt":"劳动能力鉴定委员会专家库应当配备辅助器具配置专家，从事辅助器具配置确认工作。 劳动能力鉴定委员会应当根据配置确认申请材料，从专家库中随机抽取3名或者5名专家组成专家组，对工伤职工本人进行现场配置确认。专家组中至少包括1名辅助器具配置专家、2名与工伤职工伤情相关的专家。"},{"i":10,"n":"第十条","txt":"专家组根据工伤职工伤情，依据工伤保险辅助器具配置目录有关规定，提出是否予以配置的确认意见。专家意见不一致时，按照少数服从多数的原则确定专家组的意见。 劳动能力鉴定委员会根据专家组确认意见作出配置辅助器具确认结论。其中，确认予以配置的，应当载明确认配置的理由、依据和辅助器具名称等信息；确认不予配置的，应当说明不予配置的理由。"},{"i":11,"n":"第十一条","txt":"劳动能力鉴定委员会应当自作出确认结论之日起20日内将确认结论送达工伤职工及其用人单位，并抄送经办机构。"},{"i":12,"n":"第十二条","txt":"工伤职工收到予以配置的确认结论后，及时向经办机构进行登记，经办机构向工伤职工出具配置费用核付通知单，并告知下列事项： （一）工伤职工应当到协议机构进行配置； （二）确认配置的辅助器具最高支付限额和最低使用年限； （三）工伤职工配置辅助器具超目录或者超出限额部分的费用，工伤保险基金不予支付。"},{"i":13,"n":"第十三条","txt":"工伤职工可以持配置费用核付通知单，选择协议机构配置辅助器具。 协议机构应当根据与经办机构签订的服务协议，为工伤职工提供配置服务，并如实记录工伤职工信息、配置器具产品信息、最高支付限额、最低使用年限以及实际配置费用等配置服务事项。 前款规定的配置服务记录经工伤职工签字后，分别由工伤职工和协议机构留存。"},{"i":14,"n":"第十四条","txt":"协议机构或者工伤职工与经办机构结算配置费用时，应当出具配置服务记录。经办机构核查后，应当按照工伤保险辅助器具配置目录有关规定及时支付费用。"},{"i":15,"n":"第十五条","txt":"工伤职工配置辅助器具的费用包括安装、维修、训练等费用，按照规定由工伤保险基金支付。 经经办机构同意，工伤职工到统筹地区以外的协议机构配置辅助器具发生的交通、食宿费用，可以按照统筹地区人力资源社会保障行政部门的规定，由工伤保险基金支付。"},{"i":16,"n":"第十六条","txt":"辅助器具达到规定的最低使用年限的，工伤职工可以按照统筹地区人力资源社会保障行政部门的规定申请更换。 工伤职工因伤情发生变化，需要更换主要部件或者配置新的辅助器具的，经向劳动能力鉴定委员会重新提出确认申请并经确认后，由工伤保险基金支付配置费用。"},{"i":17,"n":"第十七条","txt":"辅助器具配置专家应当具备下列条件之一： （一）具有医疗卫生中高级专业技术职务任职资格； （二）具有假肢师或者矫形器师职业资格； （三）从事辅助器具配置专业技术工作5年以上。 辅助器具配置专家应当具有良好的职业品德。"},{"i":18,"n":"第十八条","txt":"工伤保险辅助器具配置机构的具体条件，由省、自治区、直辖市人力资源社会保障行政部门会同民政、卫生计生行政部门规定。"},{"i":19,"n":"第十九条","txt":"经办机构与工伤保险辅助器具配置机构签订的服务协议，应当包括下列内容： （一）经办机构与协议机构名称、法定代表人或者主要负责人等基本信息； （二）服务协议期限； （三）配置服务内容； （四）配置费用结算； （五）配置管理要求； （六）违约责任及争议处理； （七）法律、法规规定应当纳入服务协议的其他事项。"},{"i":20,"n":"第二十条","txt":"配置的辅助器具应当符合相关国家标准或者行业标准。统一规格的产品或者材料等辅助器具在装配前应当由国家授权的产品质量检测机构出具质量检测报告，标注生产厂家、产品品牌、型号、材料、功能、出品日期、使用期和保修期等事项。"},{"i":21,"n":"第二十一条","txt":"协议机构应当建立工伤职工配置服务档案，并至少保存至服务期限结束之日起两年。经办机构可以对配置服务档案进行抽查，并作为结算配置费用的依据之一。"},{"i":22,"n":"第二十二条","txt":"经办机构应当建立辅助器具配置工作回访制度，对辅助器具装配的质量和服务进行跟踪检查，并将检查结果作为对协议机构的评价依据。"},{"i":23,"n":"第二十三条","txt":"工伤保险辅助器具配置机构违反国家规定的辅助器具配置管理服务标准，侵害工伤职工合法权益的，由民政、卫生计生行政部门在各自监管职责范围内依法处理。"},{"i":24,"n":"第二十四条","txt":"有下列情形之一的，经办机构不予支付配置费用： （一）未经劳动能力鉴定委员会确认，自行配置辅助器具的； （二）在非协议机构配置辅助器具的； （三）配置辅助器具超目录或者超出限额部分的； （四）违反规定更换辅助器具的。"},{"i":25,"n":"第二十五条","txt":"工伤职工或者其近亲属认为经办机构未依法支付辅助器具配置费用，或者协议机构认为经办机构未履行有关协议的，可以依法申请行政复议或者提起行政诉讼。"},{"i":26,"n":"第二十六条","txt":"经办机构在协议机构管理和核付配置费用过程中收受当事人财物的，由人力资源社会保障行政部门责令改正，对直接负责的主管人员和其他直接责任人员依法给予处分；情节严重，构成犯罪的，依法追究刑事责任。"},{"i":27,"n":"第二十七条","txt":"从事工伤保险辅助器具配置确认工作的组织或者个人有下列情形之一的，由人力资源社会保障行政部门责令改正，处2000元以上1万元以下的罚款；情节严重，构成犯罪的，依法追究刑事责任： （一）提供虚假确认意见的； （二）提供虚假诊断证明或者病历的； （三）收受当事人财物的。"},{"i":28,"n":"第二十八条","txt":"协议机构不按照服务协议提供服务的，经办机构可以解除服务协议，并按照服务协议追究相应责任。 经办机构不按时足额结算配置费用的，由人力资源社会保障行政部门责令改正；协议机构可以解除服务协议。"},{"i":29,"n":"第二十九条","txt":"用人单位、工伤职工或者其近亲属骗取工伤保险待遇，辅助器具装配机构、医疗机构骗取工伤保险基金支出的，按照《工伤保险条例》第六十条的规定，由人力资源社会保障行政部门责令退还，处骗取金额2倍以上5倍以下的罚款；情节严重，构成犯罪的，依法追究刑事责任。"},{"i":30,"n":"第三十条","txt":"用人单位未依法参加工伤保险，工伤职工需要配置辅助器具的，按照本办法的相关规定执行，并由用人单位支付配置费用。"},{"i":31,"n":"第三十一条","txt":"本办法自2016年4月1日起施行。"}],"gongshangzhigonglaodongnenglijiandingguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强劳动能力鉴定管理，规范劳动能力鉴定程序，根据《中华人民共和国社会保险法》、《中华人民共和国职业病防治法》和《工伤保险条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"劳动能力鉴定委员会依据《劳动能力鉴定  职工工伤与职业病致残等级》国家标准，对工伤职工劳动功能障碍程度和生活自理障碍程度组织进行技术性等级鉴定，适用本办法。"},{"i":3,"n":"第三条","txt":"省、自治区、直辖市劳动能力鉴定委员会和设区的市级（含直辖市的市辖区、县，下同）劳动能力鉴定委员会分别由省、自治区、直辖市和设区的市级人力资源社会保障行政部门、卫生计生行政部门、工会组织、用人单位代表以及社会保险经办机构代表组成。 承担劳动能力鉴定委员会日常工作的机构，其设置方式由各地根据实际情况决定。"},{"i":4,"n":"第四条","txt":"劳动能力鉴定委员会履行下列职责： （一）选聘医疗卫生专家，组建医疗卫生专家库，对专家进行培训和管理； （二）组织劳动能力鉴定； （三）根据专家组的鉴定意见作出劳动能力鉴定结论; （四）建立完整的鉴定数据库，保管鉴定工作档案50年； （五）法律、法规、规章规定的其他职责。"},{"i":5,"n":"第五条","txt":"设区的市级劳动能力鉴定委员会负责本辖区内的劳动能力初次鉴定、复查鉴定。 省、自治区、直辖市劳动能力鉴定委员会负责对初次鉴定或者复查鉴定结论不服提出的再次鉴定。"},{"i":6,"n":"第六条","txt":"劳动能力鉴定相关政策、工作制度和业务流程应当向社会公开。"},{"i":7,"n":"第七条","txt":"职工发生工伤，经治疗伤情相对稳定后存在残疾、影响劳动能力的，或者停工留薪期满（含劳动能力鉴定委员会确认的延长期限），工伤职工或者其用人单位应当及时向设区的市级劳动能力鉴定委员会提出劳动能力鉴定申请。"},{"i":8,"n":"第八条","txt":"申请劳动能力鉴定应当填写劳动能力鉴定申请表，并提交下列材料： （一）有效的诊断证明、按照医疗机构病历管理有关规定复印或者复制的检查、检验报告等完整病历材料； （二）工伤职工的居民身份证或者社会保障卡等其他有效身份证明原件。"},{"i":9,"n":"第九条","txt":"劳动能力鉴定委员会收到劳动能力鉴定申请后，应当及时对申请人提交的材料进行审核；申请人提供材料不完整的，劳动能力鉴定委员会应当自收到劳动能力鉴定申请之日起5个工作日内一次性书面告知申请人需要补正的全部材料。 申请人提供材料完整的，劳动能力鉴定委员会应当及时组织鉴定，并在收到劳动能力鉴定申请之日起60日内作出劳动能力鉴定结论。伤情复杂、涉及医疗卫生专业较多的，作出劳动能力鉴定结论的期限可以延长30日。"},{"i":10,"n":"第十条","txt":"劳动能力鉴定委员会应当视伤情程度等从医疗卫生专家库中随机抽取3名或者5名与工伤职工伤情相关科别的专家组成专家组进行鉴定。"},{"i":11,"n":"第十一条","txt":"劳动能力鉴定委员会应当提前通知工伤职工进行鉴定的时间、地点以及应当携带的材料。工伤职工应当按照通知的时间、地点参加现场鉴定。对行动不便的工伤职工，劳动能力鉴定委员会可以组织专家上门进行劳动能力鉴定。组织劳动能力鉴定的工作人员应当对工伤职工的身份进行核实。 工伤职工因故不能按时参加鉴定的，经劳动能力鉴定委员会同意，可以调整现场鉴定的时间，作出劳动能力鉴定结论的期限相应顺延。"},{"i":12,"n":"第十二条","txt":"因鉴定工作需要，专家组提出应当进行有关检查和诊断的，劳动能力鉴定委员会可以委托具备资格的医疗机构协助进行有关的检查和诊断。"},{"i":13,"n":"第十三条","txt":"专家组根据工伤职工伤情，结合医疗诊断情况，依据《劳动能力鉴定  职工工伤与职业病致残等级》国家标准提出鉴定意见。参加鉴定的专家都应当签署意见并签名。 专家意见不一致时，按照少数服从多数的原则确定专家组的鉴定意见。"},{"i":14,"n":"第十四条","txt":"劳动能力鉴定委员会根据专家组的鉴定意见作出劳动能力鉴定结论。劳动能力鉴定结论书应当载明下列事项: （一）工伤职工及其用人单位的基本信息； （二）伤情介绍，包括伤残部位、器官功能障碍程度、诊断情况等； （三）作出鉴定的依据； （四）鉴定结论。"},{"i":15,"n":"第十五条","txt":"劳动能力鉴定委员会应当自作出鉴定结论之日起20日内将劳动能力鉴定结论及时送达工伤职工及其用人单位，并抄送社会保险经办机构。"},{"i":16,"n":"第十六条","txt":"工伤职工或者其用人单位对初次鉴定结论不服的，可以在收到该鉴定结论之日起15日内向省、自治区、直辖市劳动能力鉴定委员会申请再次鉴定。 申请再次鉴定，应当提供劳动能力鉴定申请表，以及工伤职工的居民身份证或者社会保障卡等有效身份证明原件。 省、自治区、直辖市劳动能力鉴定委员会作出的劳动能力鉴定结论为最终结论。"},{"i":17,"n":"第十七条","txt":"自劳动能力鉴定结论作出之日起1年后，工伤职工、用人单位或者社会保险经办机构认为伤残情况发生变化的，可以向设区的市级劳动能力鉴定委员会申请劳动能力复查鉴定。 对复查鉴定结论不服的，可以按照本办法第十六条规定申请再次鉴定。"},{"i":18,"n":"第十八条","txt":"工伤职工本人因身体等原因无法提出劳动能力初次鉴定、复查鉴定、再次鉴定申请的，可由其近亲属代为提出。"},{"i":19,"n":"第十九条","txt":"再次鉴定和复查鉴定的程序、期限等按照本办法第九条至第十五条的规定执行。"},{"i":20,"n":"第二十条","txt":"劳动能力鉴定委员会应当每3年对专家库进行一次调整和补充，实行动态管理。确有需要的，可以根据实际情况适时调整。"},{"i":21,"n":"第二十一条","txt":"劳动能力鉴定委员会选聘医疗卫生专家，聘期一般为3年，可以连续聘任。 聘任的专家应当具备下列条件： （一）具有医疗卫生高级专业技术职务任职资格； （二）掌握劳动能力鉴定的相关知识； （三）具有良好的职业品德。"},{"i":22,"n":"第二十二条","txt":"参加劳动能力鉴定的专家应当按照规定的时间、地点进行现场鉴定，严格执行劳动能力鉴定政策和标准，客观、公正地提出鉴定意见。"},{"i":23,"n":"第二十三条","txt":"用人单位、工伤职工或者其近亲属应当如实提供鉴定需要的材料，遵守劳动能力鉴定相关规定,按照要求配合劳动能力鉴定工作。 工伤职工有下列情形之一的，当次鉴定终止： （一）无正当理由不参加现场鉴定的； （二）拒不参加劳动能力鉴定委员会安排的检查和诊断的。"},{"i":24,"n":"第二十四条","txt":"医疗机构及其医务人员应当如实出具与劳动能力鉴定有关的各项诊断证明和病历材料。"},{"i":25,"n":"第二十五条","txt":"劳动能力鉴定委员会组成人员、劳动能力鉴定工作人员以及参加鉴定的专家与当事人有利害关系的，应当回避。"},{"i":26,"n":"第二十六条","txt":"任何组织或者个人有权对劳动能力鉴定中的违法行为进行举报、投诉。"},{"i":27,"n":"第二十七条","txt":"劳动能力鉴定委员会和承担劳动能力鉴定委员会日常工作的机构及其工作人员在从事或者组织劳动能力鉴定时，有下列行为之一的，由人力资源社会保障行政部门或者有关部门责令改正，对直接负责的主管人员和其他直接责任人员依法给予相应处分；构成犯罪的，依法追究刑事责任： （一）未及时审核并书面告知申请人需要补正的全部材料的； （二）未在规定期限内作出劳动能力鉴定结论的； （三）未按照规定及时送达劳动能力鉴定结论的； （四）未按照规定随机抽取相关科别专家进行鉴定的； （五）擅自篡改劳动能力鉴定委员会作出的鉴定结论的； （六）利用职务之便非法收受当事人财物的； （七）有违反法律法规和本办法的其他行为的。"},{"i":28,"n":"第二十八条","txt":"从事劳动能力鉴定的专家有下列行为之一的，劳动能力鉴定委员会应当予以解聘；情节严重的，由卫生计生行政部门依法处理： （一）提供虚假鉴定意见的； （二）利用职务之便非法收受当事人财物的； （三）无正当理由不履行职责的； （四）有违反法律法规和本办法的其他行为的。"},{"i":29,"n":"第二十九条","txt":"参与工伤救治、检查、诊断等活动的医疗机构及其医务人员有下列情形之一的，由卫生计生行政部门依法处理： （一）提供与病情不符的虚假诊断证明的； （二）篡改、伪造、隐匿、销毁病历材料的； （三）无正当理由不履行职责的。"},{"i":30,"n":"第三十条","txt":"以欺诈、伪造证明材料或者其他手段骗取鉴定结论、领取工伤保险待遇的，按照《中华人民共和国社会保险法》第八十八条的规定，由人力资源社会保障行政部门责令退回骗取的社会保险金，处骗取金额2倍以上5倍以下的罚款。"},{"i":31,"n":"第三十一条","txt":"未参加工伤保险的公务员和参照公务员法管理的事业单位、社会团体工作人员因工（公）致残的劳动能力鉴定，参照本办法执行。"},{"i":32,"n":"第三十二条","txt":"本办法中的劳动能力鉴定申请表、初次（复查）鉴定结论书、再次鉴定结论书、劳动能力鉴定材料收讫补正告知书等文书基本样式由人力资源社会保障部制定。"},{"i":33,"n":"第三十三条","txt":"本办法自2014年4月1日起施行。"}],"gongshangrendingbanfa":[{"i":1,"n":"第一条","txt":"为规范工伤认定程序，依法进行工伤认定，维护当事人的合法权益，根据《工伤保险条例》的有关规定，制定本办法"},{"i":2,"n":"第二条","txt":"社会保险行政部门进行工伤认定按照本办法执行。"},{"i":3,"n":"第三条","txt":"工伤认定应当客观公正、简捷方便，认定程序应当向社会公开。"},{"i":4,"n":"第四条","txt":"职工发生事故伤害或者按照职业病防治法规定被诊断、鉴定为职业病，所在单位应当自事故伤害发生之日或者被诊断、鉴定为职业病之日起30日内，向统筹地区社会保险行政部门提出工伤认定申请。遇有特殊情况，经报社会保险行政部门同意，申请时限可以适当延长。 按照前款规定应当向省级社会保险行政部门提出工伤认定申请的，根据属地原则应当向用人单位所在地设区的市级社会保险行政部门提出。"},{"i":5,"n":"第五条","txt":"用人单位未在规定的时限内提出工伤认定申请的，受伤害职工或者其近亲属、工会组织在事故伤害发生之日或者被诊断、鉴定为职业病之日起1年内，可以直接按照本办法第四条规定提出工伤认定申请。"},{"i":6,"n":"第六条","txt":"提出工伤认定申请应当填写《工伤认定申请表》，并提交下列材料： （一）劳动、聘用合同文本复印件或者与用人单位存在劳动关系（包括事实劳动关系）、人事关系的其他证明材料； （二）医疗机构出具的受伤后诊断证明书或者职业病诊断证明书（或者职业病诊断鉴定书）。"},{"i":7,"n":"第七条","txt":"工伤认定申请人提交的申请材料符合要求，属于社会保险行政部门管辖范围且在受理时限内的，社会保险行政部门应当受理。"},{"i":8,"n":"第八条","txt":"社会保险行政部门收到工伤认定申请后，应当在15日内对申请人提交的材料进行审核，材料完整的，作出受理或者不予受理的决定；材料不完整的，应当以书面形式一次性告知申请人需要补正的全部材料。社会保险行政部门收到申请人提交的全部补正材料后，应当在15日内作出受理或者不予受理的决定。 社会保险行政部门决定受理的，应当出具《工伤认定申请受理决定书》；决定不予受理的，应当出具《工伤认定申请不予受理决定书》。"},{"i":9,"n":"第九条","txt":"社会保险行政部门受理工伤认定申请后，可以根据需要对申请人提供的证据进行调查核实。"},{"i":10,"n":"第十条","txt":"社会保险行政部门进行调查核实，应当由两名以上工作人员共同进行，并出示执行公务的证件。"},{"i":11,"n":"第十一条","txt":"社会保险行政部门工作人员在工伤认定中，可以进行以下调查核实工作： （一）根据工作需要，进入有关单位和事故现场； （二）依法查阅与工伤认定有关的资料，询问有关人员并作出调查笔录； （三）记录、录音、录像和复制与工伤认定有关的资料。调查核实工作的证据收集参照行政诉讼证据收集的有关规定执行。"},{"i":12,"n":"第十二条","txt":"社会保险行政部门工作人员进行调查核实时，有关单位和个人应当予以协助。用人单位、工会组织、医疗机构以及有关部门应当负责安排相关人员配合工作，据实提供情况和证明材料。"},{"i":13,"n":"第十三条","txt":"社会保险行政部门在进行工伤认定时，对申请人提供的符合国家有关规定的职业病诊断证明书或者职业病诊断鉴定书，不再进行调查核实。职业病诊断证明书或者职业病诊断鉴定书不符合国家规定的要求和格式的，社会保险行政部门可以要求出具证据部门重新提供。"},{"i":14,"n":"第十四条","txt":"社会保险行政部门受理工伤认定申请后，可以根据工作需要，委托其他统筹地区的社会保险行政部门或者相关部门进行调查核实。"},{"i":15,"n":"第十五条","txt":"社会保险行政部门工作人员进行调查核实时，应当履行下列义务： （一）保守有关单位商业秘密以及个人隐私； （二）为提供情况的有关人员保密。"},{"i":16,"n":"第十六条","txt":"社会保险行政部门工作人员与工伤认定申请人有利害关系的，应当回避。"},{"i":17,"n":"第十七条","txt":"职工或者其近亲属认为是工伤，用人单位不认为是工伤的，由该用人单位承担举证责任。用人单位拒不举证的，社会保险行政部门可以根据受伤害职工提供的证据或者调查取得的证据，依法作出工伤认定决定。"},{"i":18,"n":"第十八条","txt":"社会保险行政部门应当自受理工伤认定申请之日起60日内作出工伤认定决定，出具《认定工伤决定书》或者《不予认定工伤决定书》。"},{"i":19,"n":"第十九条","txt":"《认定工伤决定书》应当载明下列事项： （一）用人单位全称； （二）职工的姓名、性别、年龄、职业、身份证号码； （三）受伤害部位、事故时间和诊断时间或职业病名称、受伤害经过和核实情况、医疗救治的基本情况和诊断结论； （四）认定工伤或者视同工伤的依据； （五）不服认定决定申请行政复议或者提起行政诉讼的部门和时限； （六）作出认定工伤或者视同工伤决定的时间。 《不予认定工伤决定书》应当载明下列事项： （一）用人单位全称； （二）职工的姓名、性别、年龄、职业、身份证号码； （三）不予认定工伤或者不视同工伤的依据； （四）不服认定决定申请行政复议或者提起行政诉讼的部门和时限； （五）作出不予认定工伤或者不视同工伤决定的时间。 《认定工伤决定书》和《不予认定工伤决定书》应当加盖社会保险行政部门工伤认定专用印章。"},{"i":20,"n":"第二十条","txt":"社会保险行政部门受理工伤认定申请后，作出工伤认定决定需要以司法机关或者有关行政主管部门的结论为依据的，在司法机关或者有关行政主管部门尚未作出结论期间，作出工伤认定决定的时限中止，并书面通知申请人。"},{"i":21,"n":"第二十一条","txt":"社会保险行政部门对于事实清楚、权利义务明确的工伤认定申请，应当自受理工伤认定申请之日起15日内作出工伤认定决定。"},{"i":22,"n":"第二十二条","txt":"社会保险行政部门应当自工伤认定决定作出之日起20日内，将《认定工伤决定书》或者《不予认定工伤决定书》送达受伤害职工（或者其近亲属）和用人单位，并抄送社会保险经办机构。 《认定工伤决定书》和《不予认定工伤决定书》的送达参照民事法律有关送达的规定执行。"},{"i":23,"n":"第二十三条","txt":"职工或者其近亲属、用人单位对不予受理决定不服或者对工伤认定决定不服的，可以依法申请行政复议或者提起行政诉讼。"},{"i":24,"n":"第二十四条","txt":"工伤认定结束后，社会保险行政部门应当将工伤认定的有关资料保存50年。"},{"i":25,"n":"第二十五条","txt":"用人单位拒不协助社会保险行政部门对事故伤害进行调查核实的，由社会保险行政部门责令改正，处2000元以上2万元以下的罚款。"},{"i":26,"n":"第二十六条","txt":"本办法中的《工伤认定申请表》、《工伤认定申请受理决定书》、《工伤认定申请不予受理决定书》、《认定工伤决定书》、《不予认定工伤决定书》的样式由国务院社会保险行政部门统一制定。"},{"i":27,"n":"第二十七条","txt":"本办法自2011年1月1日起施行。劳动和社会保障部2003年9月23日颁布的《工伤认定办法》同时废止。"}],"gongzizhifuzanxingguiding":[{"i":1,"n":"第一条","txt":"为维护劳动者通过劳动获得劳动报酬的权利，规范用人单位的工资支付行为，根据《中华人民共和国劳动法》有关规定，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于在中华人民共和国境内的企业、个体经济组织（以下统称用人单位）和与之形成劳动关系的劳动者。 国家机关、事业组织、社会团体和与之建立劳动合同关系的劳动者，依照本规定执行。"},{"i":3,"n":"第三条","txt":"本规定所称工资是指用人单位依据劳动合同的规定，以各种形式支付给劳动者的工资报酬。"},{"i":4,"n":"第四条","txt":"工资支付主要包括：工资支付项目、工资支付水平、工资支付形式、工资支付对象、工资支付时间以及特殊情况下的工资支付。"},{"i":5,"n":"第五条","txt":"工资应当以法定货币支付。不得以实物及有价证券替代货币支付。"},{"i":6,"n":"第六条","txt":"用人单位应将工资支付给劳动者本人。劳动者本人因故不能领取工资时，可由其亲属或委托他人代领。 用人单位可委托银行代发工资。 用人单位必须书面记录支付劳动者工资的数额、时间、领取者的姓名以及签字，并保存两年以上备查。用人单位在支付工资时应向劳动者提供一份其个人的工资清单。"},{"i":7,"n":"第七条","txt":"工资必须在用人单位与劳动者约定的日期支付。如遇节假日或休息日，则应提前在最近的工作日支付。工资至少每月支付一次，实行周、日、小时工资制的可按周、日、小时支付工资。"},{"i":8,"n":"第八条","txt":"对完成一次性临时劳动或某项具体工作的劳动者，用人单位应按有关协议或合同规定在其完成劳动任务后即支付工资。"},{"i":9,"n":"第九条","txt":"劳动关系双方依法解除或终止劳动合同时，用人单位应在解除或终止劳动合同时一次付清劳动者工资。"},{"i":10,"n":"第十条","txt":"劳动者在法定工作时间内依法参加社会活动期间，用人单位应视同其提供了正常劳动而支付工资。社会活动包括：依法行使选举权或被选举权；当选代表出席乡（镇）、区以上政府、党派、工会、青年团、妇女联合会等组织召开的会议；出任人民法庭证明人；出席劳动模范、先进工作者大会；《工会法》规定的不脱产工会基层委员会委员因工会活动占用的生产或工作时间；其它依法参加的社会活动。"},{"i":11,"n":"第十一条","txt":"劳动者依法享受年休假、探亲假、婚假、丧假期间，用人单位应按劳动合同规定的标准支付劳动者工资。"},{"i":12,"n":"第十二条","txt":"非因劳动者原因造成单位停工、停产在一个工资支付周期内的，用人单位应按劳动合同规定的标准支付劳动者工资。超过一个工资支付周期的，若劳动者提供了正常劳动，则支付给劳动者的劳动报酬不得低于当地的最低工资标准；若劳动者没有提供正常劳动，应按国家有关规定办理。"},{"i":13,"n":"第十三条","txt":"用人单位在劳动者完成劳动定额或规定的工作任务后，根据实际需要安排劳动者在法定标准工作时间以外工作的，应按以下标准支付工资： （一）用人单位依法安排劳动者在日法定标准工作时间以外延长工作时间的，按照不低于劳动合同规定的劳动者本人小时工资标准的150％支付劳动者工资； （二）用人单位依法安排劳动者在休息日工作，而又不能安排补休的，按照不低于劳动合同规定的劳动者本人日或小时工资标准的200％支付劳动者工资； （三）用人单位依法安排劳动者在法定休假节日工作的，按照不低于劳动合同规定的劳动者本人日或小时工资标准的300％支付劳动者工资。 实行计件工资的劳动者，在完成计件定额任务后，由用人单位安排延长工作时间的，应根据上述规定的原则，分别按照不低于其本人法定工作时间计件单价的150％、200％、300％支付其工资。 经劳动行政部门批准实行综合计算工时工作制的，其综合计算工作时间超过法定标准工作时间"},{"i":14,"n":"第十四条","txt":"用人单位依法破产时，劳动者有权获得其工资。在破产清偿中用人单位应按《中华人民共和国企业破产法》规定的清偿顺序，首先支付欠付本单位劳动者的工资。"},{"i":15,"n":"第十五条","txt":"用人单位不得克扣劳动者工资。有下列情况之一的，用人单位可以代扣劳动者工资： （一）用人单位代扣代缴的个人所得税； （二）用人单位代扣代缴的应由劳动者个人负担的各项社会保险费用； （三）法院判决、裁定中要求代扣的抚养费、赡养费； （四）法律、法规规定可以从劳动者工资中扣除的其他费用。"},{"i":16,"n":"第十六条","txt":"因劳动者本人原因给用人单位造成经济损失的，用人单位可按照劳动合同的约定要求其赔偿经济损失。经济损失的赔偿，可从劳动者本人的工资中扣除。但每月扣除的部分不得超过劳动者当月工资的20％。若扣除后的剩余工资部分低于当地月最低工资标准，则按最低工资标准支付。"},{"i":17,"n":"第十七条","txt":"用人单位应根据本规定，通过与职工大会、职工代表大会或者其他形式协商制定内部的工资支付制度，并告知本单位全体劳动者，同时抄报当地劳动行政部门备案。"},{"i":18,"n":"第十八条","txt":"各级劳动行政部门有权监察用人单位工资支付的情况。用人单位有下列侵害劳动者合法权益行为的，由劳动行政部门责令其支付劳动者工资和经济补偿，并可责令其支付赔偿金： （一）克扣或者无故拖欠劳动者工资的； （二）拒不支付劳动者延长工作时间工资的； （三）低于当地最低工资标准支付劳动者工资的。 经济补偿和赔偿金的标准，按国家有关规定执行。"},{"i":19,"n":"第十九条","txt":"劳动者与用人单位因工资支付发生劳动争议的，当事人可依法向劳动争议仲裁机关申请仲裁。对仲裁裁决不服的，可以向人民法院提起诉讼。"},{"i":20,"n":"第二十条","txt":"本规定自一九九五年一月一日起执行。"}],"gongzijitixieshangshixingbanfa":[{"i":1,"n":"第一条","txt":"为规范工资集体协商和签订工资集体协议（以下简称工资协议）的行为，保障劳动关系双方的合法权益，促进劳动关系的和谐稳定，依据《中华人民共和国劳动法》和国家有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"中华人民共和国境内的企业依法开展工资集体协商，签订工资协议，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称工资集体协商，是指职工代表与企业代表依法就企业内部工资分配制度、工资分配形式、工资收入水平等事项进行平等协商，在协商一致的基础上签订工资协议的行为。 本办法所称工资协议，是指专门就工资事项签订的专项集体合同。已订立集体合同的，工资协议作为集体合同的附件，并与集体合同具有同等效力。"},{"i":4,"n":"第四条","txt":"依法订立的工资协议对企业和职工双方具有同等约束力。双方必须全面履行工资协议规定的义务，任何一方不得擅自变更或解除工资协议。"},{"i":5,"n":"第五条","txt":"职工个人与企业订立的劳动合同中关于工资报酬的标准，不得低于工资协议规定的最低标准。"},{"i":6,"n":"第六条","txt":"县级以上劳动保障行政部门依法对工资协议进行审查，对协议的履行情况进行监督检查。"},{"i":7,"n":"第七条","txt":"工资集体协商一般包括以下内容： （一）工资协议的期限； （二）工资分配制度、工资标准和工资分配形式； （三）职工年度平均工资水平及其调整幅度； （四）奖金、津贴、补贴等分配办法； （五）工资支付办法； （六）变更、解除工资协议的程序； （七）工资协议的终止条件； （八）工资协议的违约责任； （九）双方认为应当协商约定的其他事项。"},{"i":8,"n":"第八条","txt":"协商确定职工年度工资水平应符合国家有关工资分配的宏观调控政策，并综合参考下列因素： （一）地区、行业、企业的人工成本水平； （二）地区、行业的职工平均工资水平； （三）当地政府发布的工资指导线、劳动力市场工资指导价位； （四）本地区城镇居民消费价格指数； （五）企业劳动生产率和经济效益； （六）国有资产保值增值； （七）上年度企业职工工资总额和职工平均工资水平； （八）其他与工资集体协商有关的情况。"},{"i":9,"n":"第九条","txt":"工资集体协商代表应依照法定程序产生。职工一方由工会代表。未建工会的企业由职工民主推举代表，并得到半数以上职工的同意。企业代表由法定代表人和法定代表人指定的其他人员担任。"},{"i":10,"n":"第十条","txt":"协商双方各确定一名首席代表。职工首席代表应当由工会主席担任，工会主席可以书面委托其他人员作为自己的代理人；未成立工会的，由职工集体协商代表推举。企业首席代表应当由法定代表人担任，法定代表人可以书面委托其他管理人员作为自己的代理人。"},{"i":11,"n":"第十一条","txt":"协商双方的首席代表在工资集体协商期间轮流担任协商会议执行主席。协商会议执行主席的主要职责是负责工资集体协商有关组织协调工作，并对协商过程中发生的问题提出处理建议。"},{"i":12,"n":"第十二条","txt":"协商双方可书面委托本企业以外的专业人士作为本方协商代表。委托人数不得超过本方代表的１／３。"},{"i":13,"n":"第十三条","txt":"协商双方享有平等的建议权、否决权和陈述权。"},{"i":14,"n":"第十四条","txt":"由企业内部产生的协商代表参加工资集体协商的活动应视为提供正常劳动，享受的工资、奖金、津贴、补贴、保险福利待遇不变。其中，职工协商代表的合法权益受法律保护。企业不得对职工协商代表采取歧视性行为，不得违法解除或变更其劳动合同。"},{"i":15,"n":"第十五条","txt":"协商代表应遵守双方确定的协商规则，履行代表职责，并负有保守企业商业秘密的责任。协商代表任何一方不得采取过激、威胁、收买、欺骗等行为。"},{"i":16,"n":"第十六条","txt":"协商代表应了解和掌握工资分配的有关情况，广泛征求各方面的意见，接受本方人员对工资集体协商有关问题的质询。"},{"i":17,"n":"第十七条","txt":"职工和企业任何一方均可提出进行工资集体协商的要求。工资集体协商的提出方应向另一方提出书面的协商意向书，明确协商的时间、地点、内容等。另一方接到协商意向书后，应于20日内予以书面答复，并与提出方共同进行工资集体协商。"},{"i":18,"n":"第十八条","txt":"在不违反有关法律、法规的前提下，协商双方有义务按照对方要求，在协商开始前5日内，提供与工资集体协商有关的真实情况和资料。"},{"i":19,"n":"第十九条","txt":"工资协议草案应提交职工代表大会或职工大会讨论审议。"},{"i":20,"n":"第二十条","txt":"工资集体协商双方达成一致意见后，由企业行政方制作工资协议文本。工资协议经双方首席代表签字盖章后成立。"},{"i":21,"n":"第二十一条","txt":"工资协议签订后，应于7日内由企业将工资协议一式三份及说明，报送劳动保障行政部门审查。"},{"i":22,"n":"第二十二条","txt":"劳动保障行政部门应在收到工资协议15日内，对工资集体协商双方代表资格、工资协议的条款内容和签订程序等进行审查。 劳动保障行政部门经审查对工资协议无异议，应及时向协商双方送达《工资协议审查意见书》，工资协议即行生效。 劳动保障行政部门对工资协议有修改意见，应将修改意见在《工资协议审查意见书》中通知协商双方。双方应就修改意见及时协商，修改工资协议，并重新报送劳动保障行政部门。 工资协议向劳动保障行政部门报送经过15日后，协议双方未收到劳动保障行政部门的《工资协议审查意见书》，视为已经劳动保障行政部门同意，该工资协议即行生效。"},{"i":23,"n":"第二十三条","txt":"协商双方应于5日内将已经生效的工资协议以适当形式向本方全体人员公布。"},{"i":24,"n":"第二十四条","txt":"工资集体协商一般情况下一年进行一次。职工和企业双方均可在原工资协议期满前60日内，向对方书面提出协商意向书，进行下一轮的工资集体协商，做好新旧工资协议的相互衔接。"},{"i":25,"n":"第二十五条","txt":"本办法对工资集体协商和工资协议的有关内容未做规定的，按《集体合同规定》的有关规定执行。"},{"i":26,"n":"第二十六条","txt":"本办法自发布之日起施行。"}],"ganbudiaopeigongzuoguiding":[{"i":1,"n":"第一条","txt":"为加强干部队伍管理，保证调配工作顺利进行，特制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于国家机关和事业、企业单位具有全民所有制身份的干部。"},{"i":3,"n":"第三条","txt":"干部调配工作必须坚持党的干部路线、方针和政策，为党和国家中心任务服务，适应改革开放的需要，促进国民经济和其他各项事业的发展。"},{"i":4,"n":"第四条","txt":"干部调配必须按照国家规定的编制员额和干部人数计划进行，保证干部在地区、行业、部门之间的合理分布及部门内的合理配置。"},{"i":5,"n":"第五条","txt":"干部调配应坚持以工作需要为主，注意发挥干部的专业特长，适当照顾干部的实际困难，鼓励和支持干部到基层单位、艰苦行业和边远贫困地区工作。"},{"i":6,"n":"第六条","txt":"干部调配工作中应严格执行有关干部回避的规定。"},{"i":7,"n":"第七条","txt":"各级人事部门可据下列原因之一，在国家机关和事业、企业单位之间调配干部： （一）改善干部队伍结构进行的人员调整； （二）满足国家重点建设、重大科研项目及国家重点加强部门的需要； （三）充实基层单位，支援边远贫困地区和艰苦行业； （四）补充国家机关和事业、企业单位人员空缺； （五）安置因单位撤销、合并或缩减编制员额而富余的人员； （六）调整现任工作与所具有的专业、特长不相适应的人员； （七）解决干部夫妻两地分居或其他特殊困难； （八）符合政策规定的易地安置； （九）满足国家机关、事业、企业单位其他工作需要。"},{"i":8,"n":"第八条","txt":"干部具有下列情形之一的，一般不得调动： （一）见习期未满的； （二）正在接受有关部门审查处理的。"},{"i":9,"n":"第九条","txt":"干部因工作需要跨地区调动的，一般应夫妻同调。"},{"i":10,"n":"第十条","txt":"干部跨地区调动，有关部门可根据其申请，按有关规定办理家属随调或随迁手续。"},{"i":11,"n":"第十一条","txt":"具有全民所有制身份的干部调到非全民所有制单位，其全民所有制身份可以保留。"},{"i":12,"n":"第十二条","txt":"各级政府人事部门是干部调配工作的综合管理部门，负责同级党委和政府确定的管理范围内的国家干部的调配工作。"},{"i":13,"n":"第十三条","txt":"国务院各部委、各直属机构之间的干部调动，由各有关部门审批。国务院各部委、各直属机构在京外直属单位之间跨地区调动干部，应与调入地区的县级以上政府人事部门协商办理。"},{"i":14,"n":"第十四条","txt":"国务院各部委、各直属机构与各省、自治区、直辖市之间的干部调配，由各有关部门与其所涉及地区的县级以上政府人事部门协商办理。国务院各部委、各直属机构及其所属在京事业、企业单位从京外调入干部，报人事部审核批准。"},{"i":15,"n":"第十五条","txt":"各省、自治区、直辖市之间的干部调配，由所涉及地区的县级以上政府人事部门负责审批办理。"},{"i":16,"n":"第十六条","txt":"各省、自治区、直辖市范围内的干部调配，凡是由事业、企业单位调入到国家行政机关的，须由同级政府人事部门审批办理。"},{"i":17,"n":"第十七条","txt":"调动干部时，应先由调出、调入单位进行商洽，并征求被调干部的意见，然后按干部管理权限报其主管部门审核批准。"},{"i":18,"n":"第十八条","txt":"干部个人要求调动的，应向本单位提出书面申请，并按干部管理权限报其主管部门审核批准。"},{"i":19,"n":"第十九条","txt":"调出单位必须如实提供有关材料和证明；接收单位必须按有关规定对拟调干部进行认真审核。"},{"i":20,"n":"第二十条","txt":"从事业、企业单位调入国家各级行政机关，应按照国家行政机关干部调配的有关规定办理。"},{"i":21,"n":"第二十一条","txt":"干部调出单位接到调动通知后，应在规定的期限内办理调动手续。"},{"i":22,"n":"第二十二条","txt":"各级政府人事部门要严格遵守组织原则和调配规定，对上级按有关政策下达的调配任务，应予完成。"},{"i":23,"n":"第二十三条","txt":"国家机关、事业、企业单位有义务根据国家需要调出干部支援国家重点建设、边远贫困地区和重点加强部门；有责任接收同级政府人事部门按有关政策分配的干部。"},{"i":24,"n":"第二十四条","txt":"从事调配工作的干部，必须坚持原则，公道正派，依法办事，严格遵守党和国家有关廉政建设的规定。违反调配纪律的，应严肃处理。"},{"i":25,"n":"第二十五条","txt":"各级干部应自觉服从组织的调动和安排，凡接到调令的干部，须按规定的时间办理调动手续；无正当理由不服从调动，经批评教育无效的，要给予必要的行政处分；调动后无故逾期不报到的，应视为旷工，并按有关规定处理。"},{"i":26,"n":"第二十六条","txt":"干部调配工作中，涉及职务、工资、福利待遇等问题时，分别按国家有关规定办理。"},{"i":27,"n":"第二十七条","txt":"各省、自治区、直辖市和国务院各部委、各直属机构可根据本规定并结合本地区或本部门的实际情况，制定实施办法。"},{"i":28,"n":"第二十八条","txt":"本规定由人事部负责解释。"},{"i":29,"n":"第二十九条","txt":"本规定自颁布之日起施行。一九八〇年五月五日民政部发布的《干部调配工作暂行规定》同时废止。"}],"jigongxuexiaogongzuoguiding":[{"i":1,"n":"第一条","txt":"为了贯彻执行《中共中央关于教育体制改革的决定》中的有关规定，适应国民经济和社会发展的需要，进一步办好和发展技工学校，特制定本规定。"},{"i":2,"n":"第二条","txt":"技工学校是培养技术工人的中等职业技术学校，是国家职业技术教育事业的重要组成部分，属于高中阶段的职业技术教育。它必须执行党和国家的教育方针，面向现代化，面向世界，面向未来，不断提高教学质量，把学生培养成为合格的中级技术工人，做到多出人才、出好人才，为国民经济和社会发展服务。"},{"i":3,"n":"第三条","txt":"技工学校在完成培养中级技术工人任务的前提下，应当根据需要和可能，积极承担多种培训任务，包括在职工人（含班组长）的提高培训、转业培训，待业青年的就业培训，学徒的技术培训等。"},{"i":4,"n":"第四条","txt":"技工学校培养中级技术工人的具体要求是： 思想政治方面：培养学生爱祖国、爱人民、爱劳动、爱科学、爱社会主义，讲文明、懂礼貌、守纪律，有良好的职业道德，有为国家富强和人民富裕而艰苦奋斗的献身精神。 操作技术方面：培养学生熟练地掌握本工种（专业）的基本操作技能，完成本工种（专业）中级技术水平的作业，养成遵守操作规范和安全生产、文明生产的习惯。 文化技术知识方面，培养学生扎实地掌握本工种（专业）中级技术所需的文化和技术理论基础知识，具有一定的分析和解决问题的能力。 身体方面：重视体育锻炼，使学生具有健康的身体。"},{"i":5,"n":"第五条","txt":"技工学校的学制，应根据培养目标、招生对象的不同，分别确定。培养中级技术工人，主要招收初中毕业生，学制为三年（个别工种（专业）确有需要的，可以招收高中毕业生，经省、自治区、直辖市劳动人事部门批准，学制为一至二年）。"},{"i":6,"n":"第六条","txt":"技工学校的招生计划，分别由国务院各主管部门和各省、自治区、直辖市劳动人事厅、局（劳动局）会同计（经）委、教育部门提出，经劳动人事部汇总平衡，报国家计划委员会列入国民经济和社会发展计划，同时抄报国家教育委员会。 技工学校招生，坚持德智体全面考核、择优录取的原则。"},{"i":7,"n":"第七条","txt":"技工学校毕业生的分配办法，必须进一步改革。改革的方向是把国家统包统配改为按“三结合”方针就业。当前，要实行在国家计划指导下，由学校推荐、用人单位择优录用的制度，既应面向全民所有制单位，也应面向集体所有制单位。"},{"i":8,"n":"第八条","txt":"技工学校由劳动人事部在国家教育委员会指导下进行综合管理。在省、自治区、直辖市的技工学校由省、自治区、直辖市劳动人事厅、局（劳动局）综合管理。省、自治区、直辖市教育委员会负责统筹协调。"},{"i":9,"n":"第九条","txt":"发展技工学校应统筹规划，合理布局，根据经济建设和社会发展的需要，采取多种形式办学。主要是： 各级产业部门办； 各级劳动人事部门办； 厂矿企、事业单位办； 有关部门、单位联合办； 鼓励集体所有制单位办。"},{"i":10,"n":"第十条","txt":"技工学校的办学规模和工种（专业）设置，从经济和社会发展需要出发，由办学主管部门核定。规模不宜过小，在校学生一般不应少于200人。工种（专业）设置，应以操作技术复杂、技术业务知识要求高的为主；为增强学生就业后的适应能力，不宜划分过细。"},{"i":11,"n":"第十一条","txt":"技工学校应该具备的办学条件是： 按照选拔干部的原则和劳动人事部颁发的《技工学校机构设置和人员编制标准暂行规定》，设置机构、配备教职工和实习工厂（场、店）工作人员； 有稳定可靠的经费来源； 有同办学规模、工种（专业）设置相适应的校舍、实习实验场所、设备、体育活动场地。有切实可行的教学计划、教学大纲、教材和图书资料。"},{"i":12,"n":"第十二条","txt":"技工学校的开办、调整、撤销，由国务院各部门办的，在商得有关省、自治区、直辖市劳动人事、教育部门同意后，由国务院有关主管部门批准；属于地方办的，由省、自治区、直辖市劳动人事部门会商教育部门，由劳动人事部门审查，报省、自治区、直辖市人民政府批准；以上均应报劳动人事部备案。 已经批准开办的技工学校不准改为中等专业学校或其他性质的学校。"},{"i":13,"n":"第十三条","txt":"技工学校必须把社会效益作为衡量工作的根本标准。应当加强校际之间的横向联系，开展专业化协作。 在培训方面，各校应取长补短，进行工种（专业）的合理分工和协作，保持主要工种（专业）的相对稳定。有关教学、实习和实验、文体活动等要相互配合。 在生产经营方面，各校应在平等协商、自愿互利的原则下，开展灵活多样的相互支援与协作。可以在校际之间自行联系挂钩，也可以按地区、行业组织起来定期协商交流，还可以成立校际之间的松散联合组织，开展生产协作。劳动人事部门要加强指导。"},{"i":14,"n":"第十四条","txt":"技工学校的教学，必须着重操作技能的训练；并紧密围绕培养目标，安排必要的文化与技术理论基础课程。"},{"i":15,"n":"第十五条","txt":"技工学校的教学，必须根据国务院各有关主管部门制定和颁发的教学计划、教学大纲进行。学校应按照教学计划、教学大纲的要求，编制学期的、月份的生产（业务）实习教学计划和文化、专业技术理论课的学期教学进度计划。教师应编制学期授课计划和课时授课计划。 对于上述教学计划、教学大纲，学校可以根据地区和企业的不同特点，做必要的调整。课时的调整幅度一般可占总课时的百分之十五左右。"},{"i":16,"n":"第十六条","txt":"技工学校的生产（业务）实习教学，是培养学生掌握操作技能的主要手段。学生的生产（业务）实习，应尽可能结合生产（业务工作）进行。可以在校办工厂实习，也可以下厂（车间、工地、店堂）实习。生产（业务）实习教学的内容，应包括基本功训练和综合课题训练。 基本功训练和综合课题训练，一般应在校办实习工厂（场、店），采用课堂教学形式进行。学校应根据所设工种（专业）建立实习工厂（场、店），配备实习设备、对于不便于建立实习工厂的工种（专业），应加强实验、模拟教学。组织学生下厂实习的，学校应事先同企业商订出生产（业务）实习教学工作计划，力求做到定课题、定学时、定岗位、定师傅、定期考核和定期轮换实习岗位。"},{"i":17,"n":"第十七条","txt":"技工学校专业技术理论课的教学，应同本工种（专业）操作技能训练密切结合。其他课程的教学，也应坚持理论联系实际，并注意各课之间的配合与协调。 技工学校应建立专课教室、实验室、图书馆（室），并根据教学需要，不断充实仪器、教具，图书、教学资料和有关技术资料。并积极创造条件，逐步实施电化教学。"},{"i":18,"n":"第十八条","txt":"技工学校应建立、健全学生学业成绩考核制度，认真进行平时考查，学期、学年和毕业考试。"},{"i":19,"n":"第十九条","txt":"技工学校应按照工种（专业）和课程的不同，建立教学研究组。教学研究组应制订执行教学计划、教学大纲的措施，研究教学内容和教学方法，积极采用先进教学手段，总结交流教学经验和开展业务学习。"},{"i":20,"n":"第二十条","txt":"技工学校领导人员应把主要精力放在教学工作上，通过听课、参加教学研究、检查学生作业和实习工件、召开师生座谈会等，深入了解教学情况，提出改进措施。"},{"i":21,"n":"第二十一条","txt":"技工学校的学生、教职工和实习工厂（场、店）工作人员的思想政治工作，必须大力加强。应当认真开展社会主义精神文明建设的教育，加强对学生进行马列主义基本知识教育、共产主义教育、职业道德教育、时事政策教育、法制教育。应当结合形势、任务，针对思想实际，寓思想教育于教学活动之中。培养学生成为有理想、有道德、有文化、有纪律的技术工人、教师要身教重于言教。应当表彰不愧于为人师表的教职人员，克服不良倾向。"},{"i":22,"n":"第二十二条","txt":"对思想性质的问题，必须采取民主讨论的方法、说理的方法、批评和自我批评的方法去解决，必须采取教育和疏导的方法去解决。"},{"i":23,"n":"第二十三条","txt":"在技工学校党组织的领导下，充分发挥共青团、学生会和工会的作用，开展适合青年特点和教职工需要的有益身心健康的活动。"},{"i":24,"n":"第二十四条","txt":"技工学校应建立、健全学生的品德考核制度，做好学生操作评定工作。这种评定一个学期进行一次，由班主任考察学生的表现，听取各方面的意见，写出评语。评语要实事求是，鼓励上进。"},{"i":25,"n":"第二十五条","txt":"技工学校学生必须按时入学办理入学注册手续，遵守学籍管理制度。"},{"i":26,"n":"第二十六条","txt":"技工学校学生应当发扬勤工俭学的精神；努力学习，不断上进；应当尊敬师长，遵纪守法，遵守《技工学校学生守则》和学校的规章制度。 对于在道德品质、学习、生产劳动等方面表现优秀的学生，应该分别情况，给予表扬、记功和奖励，可以颁发奖状和发给一定的奖品。对于违犯纪律又屡教不改的学生，应该分别情节轻重，给予警告、严重警告、记过、留校察看、责令退学直至开除学籍的处分。 处分学生，应该经过校务会议讨论，由校长批准执行。责令学生退学和开除学生学籍，应报主管部门和当地劳动人事部门备案。"},{"i":27,"n":"第二十七条","txt":"技工学校按国家计划招收的学生，实行助学金和奖金相结合的办法。"},{"i":28,"n":"第二十八条","txt":"技工学校应引导和帮助学生建立、健全学生会组织，培养学生自己管理自己的能力。学生会和共青团及其班级组织，应协助学校领导和教师做好学生的思想工作；推动学生好好学习，遵纪守法；组织学生开展课余学习、文体活动、公益劳动；管好学生宿舍；做好社会工作。"},{"i":29,"n":"第二十九条","txt":"学生学习期满、经过课程结束考试、操行考核和毕业考试，成绩合格者，准予毕业，发给毕业证书。毕业考试成绩有两门课程不及格或操行成绩不及格的，不能毕业，发给结业证书。"},{"i":30,"n":"第三十条","txt":"技工学校的教师，按照《技工学校教师职务试行条例》的规定，逐步实行聘任制。"},{"i":31,"n":"第三十一条","txt":"技工学校教师应当认识时代和人民的要求，努力提高自己的思想道德素质和业务素质，做到为人师表；关心和爱护学生，认真钻研教学业务，改进教学方法，提高教学质量，完成教育、教学任务。"},{"i":32,"n":"第三十二条","txt":"技工学校教师的任课时数，根据所任课程、年级的不同分别确定。担任生产（业务）实习课的，根据技工学校人员编制标准的有关规定，按负责一个实习教学班确定；担任文化、技术理论课和其他各门课程的，一般按每周十二至十六课时安排。"},{"i":33,"n":"第三十三条","txt":"技工学校必须认真执行党的知识分子政策，调动教师的教学积极性，充分发挥教师在教学中的主导作用。学校领导者要从政治上关心教师，帮助教师解决工作和生活中的困难和问题，保证教师有充分的时间用于教学工作。 学校应切实加强对教师的培训和业务进修工作。生产实习课指导教师要努力达到能教本工种（专业）的工艺理论课；技术理论课教师应掌握一定的实际操作技能。应支持和鼓励教师积极参加教学研究和学术讨论活动。"},{"i":34,"n":"第三十四条","txt":"技工学校应按学期或学年做好教师的考核工作。对于在工作中做出显著成绩的教师，要给予表扬和奖励；对于有特殊成绩和突出贡献的教师，可以提前晋职。对于失职和违犯纪律的教师，应给予批评教育以至降职、解聘。"},{"i":35,"n":"第三十五条","txt":"技工学校的实习工厂（场、店）应统筹安排实习教学任务和生产经营活动，既要保证完成教学计划，又要通过生产经营，增加学校收益。"},{"i":36,"n":"第三十六条","txt":"技工学校实习工厂（场、店）必须根据生产实习教学的要求制定实施计划，安排好学生的基本操作技能训练，尽可能减少纯消耗性的实习，应当防止发生脱离实习教学，单纯追求产值利润的偏向。 必须积极掌握技术信息资料、及时改进实习教学和生产经营管理。 学校主管部门和办学单位，应帮助学校实习工厂（场、店）开拓生产业务门路，疏通供销渠道，解决实习教学和生产经营所需要的原材料、物资、设备等问题。实习工厂（场、店）要建立、健全原材料、物资、设备等各项管理制度，严格实行岗位责任制。应注意采用和推广新技术、新工艺和先进操作法，鼓励师生员工开展技术革新和发明创造。对改革、创新确有成效的，应给予表扬和奖励。实习工厂（场、店）要实行单独核算，严格执行财经纪律。 学校承担生产任务和经营业务。必须严格履行所签订的经济合同，按照国家规定的标准生产和检验产品，保证产品质量和经营服务质量。"},{"i":37,"n":"第三十七条","txt":"技工学校实习工厂（场、店）必须切实改善劳动条件，完善防护设备，严格执行安全操作规程，做好劳动保护工作。"},{"i":38,"n":"第三十八条","txt":"技工学校可以试行校长负责制。校长是学校的行政领导人，全面负责学校的教学、生产等各项工作。 学校应该建立、健全校务会议制度。校务会议由校长主持，副校长、各部门负责人和其他有关人员参加，讨论学校计划、总结和其他重要问题。 学校应该建立、健全教职工大会或教职工代表会议制度。教职工大会或教职工代表会议是教职工行使民主权利，参加学校管理的重要形式。"},{"i":39,"n":"第三十九条","txt":"技工学校的后勤工作要明确树立为教学和生产经营服务、为师生员工服务的思想，关心群众生活，办好公共食堂、搞好集体福利，做好卫生保健、绿化美化环境工作，管理好学生宿舍和学校的各种物资、设备。"},{"i":40,"n":"第四十条","txt":"技工学校的食堂要实行民主管理，健全管理制度，定期公布帐目，杜绝贪污浪费，努力改善伙食，注意饮食营养卫生。"},{"i":41,"n":"第四十一条","txt":"技工学校应建立独立的财务机构，经费由主办单位按照规定的程序、经费开支渠道和标准拨给，由学校支配使用。学校要配备财会人员，健全财务制度，遵守财经纪律。一切开支必须精打细算，厉行节约。 应建立技工学校基金制度，具体办法按照劳动人事部、财政部《关于在技工学校建立学校基金制度的联合通知》办理。"},{"i":42,"n":"第四十二条","txt":"技工学校的领导干部，要模范地执行党的方针政策，遵守党纪国法，努力学习政治理论和学校管理知识，认真总结经验，研究技工教育的规律，不断改进领导作风和领导方法，把学校切实办好。"},{"i":43,"n":"第四十三条","txt":"各省、自治区、直辖市劳动人事厅、局（劳动局）和国务院各有关部门，可以参照本规定制定实施细则。"},{"i":44,"n":"第四十四条","txt":"本规定自一九八七年一月一日起实行，一九七九年二月二十日原国家劳动总局颁发的《技工学校工作条例（试行）》同时废止。"}],"jigongxuexiaojiaoyududaopingguzanxingguiding":[{"i":1,"n":"第一条","txt":"为了规范对技工学校的教育督导评估（以下简称督导评估）工作，促进技工学校教育质量的提高和技工学校的健康发展，根据《教育法》和《职业教育法》的有关规定，制定本规定。"},{"i":2,"n":"第二条","txt":"技工学校教育督导评估工作应按照本规定执行。"},{"i":3,"n":"第三条","txt":"本规定所称督导评估，是指劳动行政部门的督导评估机构对下级劳动行政部门、技工学校和学校主管部门贯彻国家教育方针、政策，执行法律、法规情况进行监督、检查和指导；对技工学校是否达到办学标准给予认定。"},{"i":4,"n":"第四条","txt":"督导评估包括下列内容： （一）贯彻执行国家教育法律、法规和方针、政策的情况； （二）执行国家办学标准、工作条例及管理制度情况； （三）基础设施、办学条件、教学管理和教学质量； （四）教师上岗资格、职业道德和相关待遇； （五）学生德、智、体全面发展的情况； （六）对学生进行职业指导和毕业生就业服务情况； （七）承担劳动预备制度培训任务和开展其他培训情况。"},{"i":5,"n":"第五条","txt":"督导评估机构分国家级和省级。国家级督导评估委员会由劳动部会同有关行业部门组成，办公室设在劳动部。 国家级督导评估委员会履行下列职责： （一）制定督导评估实施方案； （二）对国家重点技工学校、高级技工学校和国务院部委直属学校督导评估； （三）指导地方督导评估工作； （四）组织培训督导评估人员； （五）总结推广督导评估工作经验，开展工作研究。 省级督导评估机构的职责由省级劳动行政部门制定。"},{"i":6,"n":"第六条","txt":"国家级督导评估人员由劳动部聘任并颁发证书；省级督导评估人员由省级劳动行政部门聘任和颁发证书，并报劳动部备案。"},{"i":7,"n":"第七条","txt":"督导评估人员应具备以下条件： （一）坚持四项基本原则，热爱技工教育事业； （二）熟悉国家有关职业教育法律、法规和政策； （三）具有大专以上学历或同等学历； （四）有五年以上从事职业培训或技工学校管理工作经历； （五）身体健康。"},{"i":8,"n":"第八条","txt":"督导评估机构可聘请企业的技师、高级技师参与督导评估。"},{"i":9,"n":"第九条","txt":"督导评估分为综合督导评估和专项督导评估，督导评估机构根据劳动行政部门或上级督导机构的决定组织实施督导评估工作。"},{"i":10,"n":"第十条","txt":"督导评估人员具有以下职权： （一）列席被督导评估单位的有关会议； （二）要求被督导评估单位提供有关文件并汇报工作； （三）对被督导评估单位进行现场调查； （四）到用人单位听取对技工学校毕业生的评价意见。"},{"i":11,"n":"第十一条","txt":"督导评估人员应对被督导评估单位存在的问题提出意见，经督导评估机构确认后，被督导评估单位应采取改进措施。"},{"i":12,"n":"第十二条","txt":"被督导评估单位或有关人员弄虚作假，不报实情的，由其主管部门责令改正；情节严重的，督导评估机构可以建议主管部门对直接责任人员给予行政处分。"},{"i":13,"n":"第十三条","txt":"督导评估人员利用职权谋取私利或滥用职权的，视其情节由督导评估机构建议所在单位给予行政处分。"},{"i":14,"n":"第十四条","txt":"督导评估机构可对督导评估结果进行公布。"},{"i":15,"n":"第十五条","txt":"本规定自1997年9月1日起施行。"}],"tuoqiannongmingonggongzishixinlianhechengjieduixia60def2":[{"i":1,"n":"第一条","txt":"为了维护劳动者合法权益，完善失信约束机制，加强信用监管，规范拖欠农民工工资失信联合惩戒对象名单（以下简称失信联合惩戒名单）管理工作，根据《保障农民工工资支付条例》等有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"人力资源社会保障行政部门实施列入失信联合惩戒名单、公开信息、信用修复等管理活动，适用本办法。"},{"i":3,"n":"第三条","txt":"人力资源社会保障部负责组织、指导全国失信联合惩戒名单管理工作。 县级以上地方人力资源社会保障行政部门依据行政执法管辖权限，负责失信联合惩戒名单管理的具体实施工作。"},{"i":4,"n":"第四条","txt":"失信联合惩戒名单管理实行“谁执法、谁认定、谁负责”，遵循依法依规、客观公正、公开透明、动态管理的原则。 实施失信联合惩戒名单管理，应当依法依规加强信用信息安全和个人信息保护。人力资源社会保障行政部门及其工作人员对实施失信联合惩戒名单管理过程中知悉的国家秘密、商业秘密、个人隐私，应当依法依规予以保密。"},{"i":5,"n":"第五条","txt":"用人单位拖欠农民工工资，具有下列情形之一，经人力资源社会保障行政部门依法责令限期支付工资，逾期未支付的，人力资源社会保障行政部门应当作出列入决定，将该用人单位及其法定代表人或者主要负责人、直接负责的主管人员和其他直接责任人员（以下简称当事人）列入失信联合惩戒名单： （一）克扣、无故拖欠农民工工资达到认定拒不支付劳动报酬罪数额标准的； （二）因拖欠农民工工资违法行为引发群体性事件、极端事件造成严重不良社会影响的。"},{"i":6,"n":"第六条","txt":"人力资源社会保障行政部门在作出列入决定前，应当告知当事人拟列入失信联合惩戒名单的事由、依据、提出异议等依法享有的权利和本办法第七条可以不予列入失信联合惩戒名单的规定。 当事人自收到告知之日起5个工作日内，可以向人力资源社会保障行政部门提出异议。对异议期内提出的异议，人力资源社会保障行政部门应当自收到异议之日起5个工作日内予以核实，并将结果告知当事人。"},{"i":7,"n":"第七条","txt":"用人单位在人力资源社会保障行政部门作出列入决定前，已经改正拖欠农民工工资违法行为，且作出不再拖欠农民工工资书面信用承诺的，可以不予列入失信联合惩戒名单。"},{"i":8,"n":"第八条","txt":"人力资源社会保障行政部门应当自责令限期支付工资文书指定期限届满之日起20个工作日内作出列入决定。情况复杂的，经人力资源社会保障行政部门负责人批准，可以延长20个工作日。 人力资源社会保障行政部门作出列入决定，应当制作列入决定书。列入决定书应当载明列入事由、列入依据、联合惩戒措施提示、提前移出条件和程序、救济措施等，并按照有关规定交付或者送达当事人。"},{"i":9,"n":"第九条","txt":"作出列入决定的人力资源社会保障行政部门应当按照政府信息公开等有关规定，通过本部门门户网站和其他指定的网站公开失信联合惩戒名单。"},{"i":10,"n":"第十条","txt":"作出列入决定的人力资源社会保障行政部门应当按照有关规定，将失信联合惩戒名单信息共享至同级信用信息共享平台，供相关部门作为在各自职责范围内按照《保障农民工工资支付条例》等有关规定，对被列入失信联合惩戒名单的当事人实施联合惩戒的依据。 对被列入失信联合惩戒名单的当事人，由相关部门在政府资金支持、政府采购、招投标、融资贷款、市场准入、税收优惠、评优评先、交通出行等方面依法依规予以限制。"},{"i":11,"n":"第十一条","txt":"当事人被列入失信联合惩戒名单的期限为3年，自人力资源社会保障行政部门作出列入决定之日起计算。"},{"i":12,"n":"第十二条","txt":"用人单位同时符合下列条件的，可以向作出列入决定的人力资源社会保障行政部门申请提前移出失信联合惩戒名单： （一）已经改正拖欠农民工工资违法行为的； （二）自改正之日起被列入失信联合惩戒名单满6个月的； （三）作出不再拖欠农民工工资书面信用承诺的。"},{"i":13,"n":"第十三条","txt":"用人单位符合本办法第十二条规定条件，但是具有下列情形之一的，不得提前移出失信联合惩戒名单： （一）列入失信联合惩戒名单期限内再次发生拖欠农民工工资违法行为的； （二）因涉嫌拒不支付劳动报酬犯罪正在刑事诉讼期间或者已经被追究刑事责任的； （三）法律、法规和党中央、国务院政策文件规定的其他情形。"},{"i":14,"n":"第十四条","txt":"用人单位申请提前移出失信联合惩戒名单，应当提交书面申请、已经改正拖欠农民工工资违法行为的证据和不再拖欠农民工工资书面信用承诺。 人力资源社会保障行政部门应当自收到用人单位提前移出失信联合惩戒名单申请之日起15个工作日内予以核实，决定是否准予提前移出，制作决定书并按照有关规定交付或者送达用人单位。不予提前移出的，应当说明理由。 人力资源社会保障行政部门准予用人单位提前移出失信联合惩戒名单的，应当将该用人单位的其他当事人一并提前移出失信联合惩戒名单。"},{"i":15,"n":"第十五条","txt":"申请提前移出的用人单位故意隐瞒真实情况、提供虚假资料，情节严重的，由作出提前移出决定的人力资源社会保障行政部门撤销提前移出决定，恢复列入状态。列入的起止时间重新计算。"},{"i":16,"n":"第十六条","txt":"列入决定所依据的责令限期支付工资文书被依法撤销的，作出列入决定的人力资源社会保障行政部门应当撤销列入决定。"},{"i":17,"n":"第十七条","txt":"有下列情形之一的，作出列入决定的人力资源社会保障行政部门应当于10个工作日内将当事人移出失信联合惩戒名单，在本部门门户网站停止公开相关信息，并告知第九条规定的有关网站: （一）当事人被列入失信联合惩戒名单期限届满的； （二）人力资源社会保障行政部门决定提前移出失信联合惩戒名单的； （三）列入决定被依法撤销的。 当事人被移出失信联合惩戒名单的，人力资源社会保障行政部门应当及时将移出信息共享至同级信用信息共享平台，相关部门联合惩戒措施按照规定终止。"},{"i":18,"n":"第十八条","txt":"当事人对列入失信联合惩戒名单决定或者不予提前移出失信联合惩戒名单决定不服的，可以依法申请行政复议或者提起行政诉讼。"},{"i":19,"n":"第十九条","txt":"人力资源社会保障行政部门工作人员在实施失信联合惩戒名单管理过程中，滥用职权、玩忽职守、徇私舞弊的，依法依规给予处分；构成犯罪的，依法追究刑事责任。"},{"i":20,"n":"第二十条","txt":"本办法自2022年1月1日起施行。"}],"zuidigongziguiding":[{"i":1,"n":"第一条","txt":"为了维护劳动者取得劳动报酬的合法权益，保障劳动者个人及其家庭成员的基本生活，根据劳动法和国务院有关规定，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于在中华人民共和国境内的企业、民办非企业单位、有雇工的个体工商户（以下统称用人单位）和与之形成劳动关系的劳动者。 国家机关、事业单位、社会团体和与之建立劳动合同关系的劳动者，依照本规定执行。"},{"i":3,"n":"第三条","txt":"本规定所称最低工资标准，是指劳动者在法定工作时间或依法签订的劳动合同约定的工作时间内提供了正常劳动的前提下，用人单位依法应支付的最低劳动报酬。 本规定所称正常劳动，是指劳动者按依法签订的劳动合同约定，在法定工作时间或劳动合同约定的工作时间内从事的劳动。劳动者依法享受带薪年休假、探亲假、婚丧假、生育（产）假、节育手术假等国家规定的假期间，以及法定工作时间内依法参加社会活动期间，视为提供了正常劳动。"},{"i":4,"n":"第四条","txt":"县级以上地方人民政府劳动保障行政部门负责对本行政区域内用人单位执行本规定情况进行监督检查。 各级工会组织依法对本规定执行情况进行监督，发现用人单位支付劳动者工资违反本规定的，有权要求当地劳动保障行政部门处理。"},{"i":5,"n":"第五条","txt":"最低工资标准一般采取月最低工资标准和小时最低工资标准的形式。月最低工资标准适用于全日制就业劳动者，小时最低工资标准适用于非全日制就业劳动者。"},{"i":6,"n":"第六条","txt":"确定和调整月最低工资标准，应参考当地就业者及其赡养人口的最低生活费用、城镇居民消费价格指数、职工个人缴纳的社会保险费和住房公积金、职工平均工资、经济发展水平、就业状况等因素。 确定和调整小时最低工资标准，应在颁布的月最低工资标准的基础上，考虑单位应缴纳的基本养老保险费和基本医疗保险费因素，同时还应适当考虑非全日制劳动者在工作稳定性、劳动条件和劳动强度、福利等方面与全日制就业人员之间的差异。 月最低工资标准和小时最低工资标准具体测算方法见附件。"},{"i":7,"n":"第七条","txt":"省、自治区、直辖市范围内的不同行政区域可以有不同的最低工资标准。"},{"i":8,"n":"第八条","txt":"最低工资标准的确定和调整方案，由省、自治区、直辖市人民政府劳动保障行政部门会同同级工会、企业联合会/企业家协会研究拟订，并将拟订的方案报送劳动保障部。方案内容包括最低工资确定和调整的依据、适用范围、拟订标准和说明。劳动保障部在收到拟订方案后，应征求全国总工会、中国企业联合会/企业家协会的意见。 劳动保障部对方案可以提出修订意见，若在方案收到后14日内未提出修订意见的，视为同意。"},{"i":9,"n":"第九条","txt":"省、自治区、直辖市劳动保障行政部门应将本地区最低工资标准方案报省、自治区、直辖市人民政府批准，并在批准后7日内在当地政府公报上和至少一种全地区性报纸上发布。省、自治区、直辖市劳动保障行政部门应在发布后10日内将最低工资标准报劳动保障部。"},{"i":10,"n":"第十条","txt":"最低工资标准发布实施后，如本规定第六条所规定的相关因素发生变化，应当适时调整。最低工资标准每两年至少调整一次。"},{"i":11,"n":"第十一条","txt":"用人单位应在最低工资标准发布后10日内将该标准向本单位全体劳动者公示。"},{"i":12,"n":"第十二条","txt":"在劳动者提供正常劳动的情况下，用人单位应支付给劳动者的工资在剔除下列各项以后，不得低于当地最低工资标准： （一）延长工作时间工资； （二）中班、夜班、高温、低温、井下、有毒有害等特殊工作环境、条件下的津贴； （三）法律、法规和国家规定的劳动者福利待遇等。 实行计件工资或提成工资等工资形式的用人单位，在科学合理的劳动定额基础上，其支付劳动者的工资不得低于相应的最低工资标准。 劳动者由于本人原因造成在法定工作时间内或依法签订的劳动合同约定的工作时间内未提供正常劳动的，不适用于本条规定。"},{"i":13,"n":"第十三条","txt":"用人单位违反本规定第十一条规定的，由劳动保障行政部门责令其限期改正；违反本规定第十二条规定的，由劳动保障行政部门责令其限期补发所欠劳动者工资，并可责令其按所欠工资的1至5倍支付劳动者赔偿金。"},{"i":14,"n":"第十四条","txt":"劳动者与用人单位之间就执行最低工资标准发生争议，按劳动争议处理有关规定处理。"},{"i":15,"n":"第十五条","txt":"本规定自2004年3月1日起实施。1993年11月24日原劳动部发布的《企业最低工资规定》同时废止。 附件：最低工资标准测算方法 最低工资标准测算方法 一、确定最低工资标准应考虑的因素 确定最低工资标准一般考虑城镇居民生活费用支出、职工个人缴纳社会保险费、住房公积金、职工平均工资、失业率、经济发展水平等因素。可用公式表示为： M＝f（C、S、A、U、E、a） M    最低工资标准； C    城镇居民人均生活费用； S    职工个人缴纳社会保险费、住房公积金； A    职工平均工资； U    失业率； E    经济发展水平； a    调整因素。 二、确定最低工资标准的通用方法 １．比重法    即根据城镇居民家计调查资料，确定一定比例的最低人均收入户为贫困户，统计出贫困户的人均生活费用支出水平，乘以每一就业者的赡养系数，再加上一个调整数。 ２．恩格尔系数法    即根据国家"}],"weichengniangongteshubaohuguiding":[{"i":1,"n":"第一条","txt":"为维护未成年工的合法权益，保护其在生产劳动中的健康，根据《中华人民共和国劳动法》的有关规定，制定本规定。"},{"i":2,"n":"第二条","txt":"未成年工是指年满十六周岁，未满十八周岁的劳动者。 未成年工的特殊保护是针对未成年工处于生长发育期的特点，以及接受义务教育的需要，采取的特殊劳动保护措施。"},{"i":3,"n":"第三条","txt":"用人单位不得安排未成年工从事以下范围的劳动： （一）《生产性粉尘作业危害程度分级》国家标准中第一级以上的接尘作业； （二）《有毒作业分级》国家标准中第一级以上的有毒作业； （三）《高处作业分级》国家标准中第二级以上的高处作业； （四）《冷水作业分级》国家标准中第二级以上的冷水作业； （五）《高温作业分级》国家标准中第三级以上的高温作业； （六）《低温作业分级》国家标准中第三级以上的低温作业； （七）《体力劳动强度分级》国家标准中第四级体力劳动强度的作业； （八）矿山井下及矿山地面采石作业； （九）森林业中的伐木、流放及守林作业； （十）工作场所接触放射性物质的作业； （十一）有易燃易爆、化学性烧伤和热烧伤等危险性大的作业； （十二）地质勘探和资源勘探的野外作业； （十三）潜水、涵洞、涵道作业和海拔三千米以上的高原作业（不包括世居高原者）； （十四）连续负重每小时在六次以上并每次超过２０"},{"i":4,"n":"第四条","txt":"未成年工患有某种疾病或具有某些生理缺陷（非残疾型）时，用人单位不得安排其从事以下范围的劳动： （一）《高处作业分级》国家标准中第一级以上的高处作业； （二）《低温作业分级》国家标准中第二级以上的低温作业； （三）《高温作业分级》国家标准中第二级以上的高温作业； （四）《体力劳动强度分级》国家标准中第三级以上体力劳动强度的作业； （五）接触铅、苯、汞、甲醛、二硫化碳等易引起过敏反应的作业。"},{"i":5,"n":"第五条","txt":"患有某种疾病或具有某些生理缺陷（非残疾型）的未成年工，是指有以下一种或一种以上情况者： （一）心血管系统 1.先天性心脏病； 2.克山病； 3.收缩期或舒张期二级以上心脏杂音。 （二）呼吸系统 1.中度以上气管炎或支气管哮喘； 2.呼吸音明显减弱； 3.各类结核病； 4.体弱儿，呼吸道反复感染者。 （三）消化系统 1.各类肝炎； 2.肝、脾肿大； 3.胃、十二指肠溃疡； 4.各种消化道疝。 （四）泌尿系统 1.急、慢性肾炎； 2.泌尿系感染。 （五）内分泌系统 1.甲状腺机能亢进； 2.中度以上糖尿病。 （六）精神神经系统 1.智力明显低下； 2.精神忧郁或狂暴。 （七）肌肉、骨骼运动系统 1.身高和体重低于同龄人标准； 2.一个及一个以上肢体存在明显功能障碍； 3.躯干四分之一以上部位活动受限，包括强直或不能旋转。 （八）其它 1.结核性胸膜炎； 2.各类重度关节炎； 3.血吸虫病；"},{"i":6,"n":"第六条","txt":"用人单位应按下列要求对未成年工定期进行健康检查： （一）安排工作岗位之前； （二）工作满１年； （三）年满18周岁，距前一次的体检时间已超过半年。"},{"i":7,"n":"第七条","txt":"未成年工的健康检查，应按本规定所附《未成年工健康检查表》列出的项目进行。"},{"i":8,"n":"第八条","txt":"用人单位应根据未成年工的健康检查结果安排其从事适合的劳动，对不能胜任原劳动岗位的，应根据医务部门的证明，予以减轻劳动量或安排其他劳动。"},{"i":9,"n":"第九条","txt":"对未成年工的使用和特殊保护实行登记制度。 （一）用人单位招收使用未成年工，除符合一般用工要求外，还须向所在地的县级以上劳动行政部门办理登记。劳动行政部门根据《未成年工健康检查表》、《未成年工登记表》，核发《未成年工登记证》。 （二）各级劳动行政部门须按本规定第三、四、五、七条的有关规定，审核体检情况和拟安排的劳动范围。 （三）未成年工须持《未成年工登记证》上岗。 （四）《未成年工登记证》由国务院劳动行政部门统一印制。"},{"i":10,"n":"第十条","txt":"未成年工上岗前用人单位应对其进行有关的职业安全卫生教育、培训；未成年工体检和登记，由用人单位统一办理和承担费用。"},{"i":11,"n":"第十一条","txt":"县级以上劳动行政部门对用人单位执行本规定的情况进行监督检查，对违反本规定的行为依照有关法规进行处罚。 各级工会组织对本规定的执行情况进行监督。"},{"i":12,"n":"第十二条","txt":"省、自治区、直辖市劳动行政部门可以根据本规定制定实施办法。"},{"i":13,"n":"第十三条","txt":"本规定自1995年１月１日起施行。"}],"jiguanshiyedanweizengrenjihuakazanxingguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强机关、事业单位职工队伍的总量管理，严格控制机关、事业单位人员增长，特制定本办法。"},{"i":2,"n":"第二条","txt":"在机关、事业单位实行增人计划卡办法，是加强社会主义市场经济条件下人事宏观调控的重要措施。各省、自治区、直辖市要按照本办法规定的范围，在机关、事业单位严格执行增人计划卡管理办法。各有关部门要加强协作，相互配合，切实保证增人计划卡管理办法有效实行。"},{"i":3,"n":"第三条","txt":"增人计划卡的管理范围与机关、事业单位职工人数计划的管理范围相一致。包括：各级国家机关、政党机关、社会团体及其所属的事业单位；国家规定的其他应纳入机关、事业单位计划管理的部门和单位。"},{"i":4,"n":"第四条","txt":"增人计划卡管理对象是机关、事业单位新增的全部职工，包括国家统一分配的人员、调入人员和社会招收人员。"},{"i":5,"n":"第五条","txt":"国家下达的机关、事业单位职工人数计划和计划管理意见是实行增人计划卡管理的依据。各省、自治区、直辖市要将自然减员指标集中起来，同国家下达的增人指标一起统筹安排，统一使用，并纳入增人计划管理。"},{"i":6,"n":"第六条","txt":"增人计划卡实行一卡一人，每年由人事计划部门在分解下达和调整职工人数计划时核发，当年核发的增人计划卡只在当年有效。"},{"i":7,"n":"第七条","txt":"增人计划卡是机关、事业单位办理增加职工手续和增加工资总额计划以及报批工资基金使用计划的凭证，用人单位要如实填写。人事计划部门凭卡检查核定职工人数与工资总额计划，并办理工资基金审批手续，同时收回增人计划卡。"},{"i":8,"n":"第八条","txt":"机关、事业单位无论以何种渠道和形式增加人员都要纳入人员计划管理范围，并使用增人计划卡。各单位增加人员须凭人事计划部门核发的增人计划卡办理录（聘）用、分配、调动、招工手续。凡是未凭增人计划卡办理手续的新增人员，不予以核认，不得增加工资总额计划和工资基金使用计划。"},{"i":9,"n":"第九条","txt":"增人计划卡式样由人事部制订，各省、自治区、直辖市人事（人事劳动）厅（局），可根据本地实际情况增加增人计划卡中的项目，并统一制发，任何单位不得复制。"},{"i":10,"n":"第十条","txt":"人事计划部门要加强对计划执行情况的监督检查工作，定期对依卡增人增资情况进行汇总分析。"},{"i":11,"n":"第十一条","txt":"各省、自治区、直辖市应根据本办法，结合本地实际情况，制定实施细则。"},{"i":12,"n":"第十二条","txt":"本办法由人事部负责解释。"},{"i":13,"n":"第十三条","txt":"本办法自发布之日起施行。"}],"jiguanshiyedanweigongrenjishudengjigangweikaohezan4eec72":[],"jiguanshiyedanweigongzuorenyuandaixinnianxiujiashif930d3":[{"i":1,"n":"第一条","txt":"为了规范机关、事业单位实施带薪年休假（以下简称年休假）制度，根据《职工带薪年休假条例》（以下简称《条例》）及国家有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"《条例》第二条中所称“连续工作”的时间和第三条、第四条中所称“累计工作”的时间，机关、事业单位工作人员（以下简称工作人员）均按工作年限计算。 工作人员工作年限满1年、满10年、满20年后，从下月起享受相应的年休假天数。"},{"i":3,"n":"第三条","txt":"国家规定的探亲假、婚丧假、产假的假期，不计入年休假的假期。"},{"i":4,"n":"第四条","txt":"工作人员已享受当年的年休假，年内又出现《条例》第四条第（二）、（三）、（四）、（五）项规定的情形之一的，不享受下一年的年休假。"},{"i":5,"n":"第五条","txt":"依法应享受寒暑假的工作人员，因工作需要未休寒暑假的，所在单位应当安排其休年休假；因工作需要休寒暑假天数少于年休假天数的，所在单位应当安排补足其年休假天数。"},{"i":6,"n":"第六条","txt":"工作人员因承担野外地质勘查、野外测绘、远洋科学考察、极地科学考察以及其他特殊工作任务，所在单位不能在本年度安排其休年休假的，可以跨1个年度安排。"},{"i":7,"n":"第七条","txt":"机关、事业单位因工作需要不安排工作人员休年休假，应当征求工作人员本人的意见。 机关、事业单位应当根据工作人员应休未休的年休假天数，对其支付年休假工资报酬。年休假工资报酬的支付标准是：每应休未休1天，按照本人应休年休假当年日工资收入的300%支付，其中包含工作人员正常工作期间的工资收入。 工作人员年休假工资报酬中，除正常工作期间工资收入外，其余部分应当由所在单位在下一年第一季度一次性支付，所需经费按现行经费渠道解决。实行工资统发的单位，应当纳入工资统发。"},{"i":8,"n":"第八条","txt":"工作人员应休年休假当年日工资收入的计算办法是：本人全年工资收入除以全年计薪天数（261天）。 机关工作人员的全年工资收入，为本人全年应发的基本工资、国家规定的津贴补贴、年终一次性奖金之和；事业单位工作人员的全年工资收入，为本人全年应发的基本工资、国家规定的津贴补贴、绩效工资之和。其中，国家规定的津贴补贴不含根据住房、用车等制度改革向工作人员直接发放的货币补贴。"},{"i":9,"n":"第九条","txt":"机关、事业单位已安排年休假，工作人员未休且有下列情形之一的，只享受正常工作期间的工资收入： （一）因个人原因不休年休假的； （二）请事假累计已超过本人应休年休假天数，但不足20天的。"},{"i":10,"n":"第十条","txt":"机关、事业单位根据工作的具体情况，并考虑工作人员本人意愿，统筹安排，保证工作人员享受年休假。机关、事业单位应当加强年休假管理，严格考勤制度。 县级以上地方人民政府人事行政部门应当依据职权，主动对机关、事业单位执行年休假的情况进行监督检查。"},{"i":11,"n":"第十一条","txt":"机关、事业单位不安排工作人员休年休假又不按本办法规定支付年休假工资报酬的，由县级以上地方人民政府人事行政部门责令限期改正。对逾期不改正的，除责令该单位支付年休假工资报酬外，单位还应当按照年休假工资报酬的数额向工作人员加付赔偿金。 对拒不支付年休假工资报酬、赔偿金的，属于机关和参照公务员法管理的事业单位的，应当按照干部管理权限，对直接负责的主管人员以及其他直接责任人员依法给予处分，并责令支付；属于其他事业单位的，应当按照干部管理权限，对直接负责的主管人员以及其他直接责任人员依法给予处分，并由同级人事行政部门或工作人员本人申请人民法院强制执行。"},{"i":12,"n":"第十二条","txt":"工作人员与所在单位因年休假发生的争议，依照国家有关公务员申诉控告和人事争议处理的规定处理。"},{"i":13,"n":"第十三条","txt":"驻外使领馆工作人员、驻港澳地区内派人员以及机关、事业单位驻外非外交人员的年休假，按照《条例》和本办法的规定执行。 按照国家规定经批准执行机关、事业单位工资收入分配制度的其他单位工作人员的年休假，参照《条例》和本办法的规定执行。"},{"i":14,"n":"第十四条","txt":"本办法自发布之日起施行。"}],"shehuibaoxianyewudanganguanliguiding":[{"i":1,"n":"第一条","txt":"为规范社会保险业务档案管理，维护社会保险业务档案真实、完整和安全，发挥档案的服务作用，根据《中华人民共和国档案法》和社会保险相关法规，制定本规定。"},{"i":2,"n":"第二条","txt":"依法经办养老、医疗、失业、工伤、生育等社会保险业务的机构（以下简称社会保险经办机构），管理社会保险业务档案，适用本规定。"},{"i":3,"n":"第三条","txt":"本规定所称社会保险业务档案，是指社会保险经办机构在办理社会保险业务过程中，直接形成的具有保存和利用价值的专业性文字材料、电子文档、图表、声像等不同载体的历史记录。"},{"i":4,"n":"第四条","txt":"人力资源社会保障行政部门负责社会保险业务档案管理工作的组织领导。 社会保险经办机构负责社会保险业务档案的管理工作，并接受档案行政管理部门的业务指导。 社会保险业务档案由县级以上社会保险经办机构集中保存。"},{"i":5,"n":"第五条","txt":"社会保险经办机构配备专门的管理人员和必要的设施、场所，确保档案的安全，并根据需要配备适应档案现代化管理要求的技术设备。"},{"i":6,"n":"第六条","txt":"社会保险经办机构应当认真落实档案保管、保密、利用、移交、鉴定、销毁等管理要求，保证社会保险业务档案妥善保管、有序存放，严防毁损、遗失和泄密。"},{"i":7,"n":"第七条","txt":"社会保险经办机构办理社会保险业务过程中形成的记录、证据、依据，按照《社会保险业务材料归档范围与保管期限》（见附件）进行收集、整理、立卷、归档，确保归档材料的完整、安全，不得伪造、篡改。"},{"i":8,"n":"第八条","txt":"社会保险业务档案分类应当按照社会保险业务经办的规律和特点，以方便归档整理和检索利用为原则，采用“年度—业务环节”或“年度—险种—业务环节”的方法对社会保险业务材料进行分类、整理，并及时编制归档文件目录、卷内目录、案卷目录、备考表等。负责档案管理的机构应当对接收的档案材料及时进行检查、分类、整理、编号、入库保管，并及时编制索引目录。"},{"i":9,"n":"第九条","txt":"社会保险业务档案的保管期限分为永久和定期两类。定期保管期限分为10年、30年、50年、100年，各种社会保险业务档案的具体保管期限按照《社会保险业务材料归档范围与保管期限》执行。 社会保险业务档案定期保管期限为最低保管期限。社会保险业务档案的保管期限，自形成之日的次年1月1日开始计算。"},{"i":10,"n":"第十条","txt":"社会保险经办机构依法为参保单位和参保个人提供档案信息查询服务。"},{"i":11,"n":"第十一条","txt":"社会保险经办机构应当对已到期的社会保险业务档案进行鉴定。 鉴定工作应当由社会保险经办机构相关负责人、业务人员和档案管理人员，以及人力资源社会保障行政部门有关人员组成鉴定小组负责鉴定并提出处理意见。 鉴定中如发现业务档案保管期限划分过短，有必要继续保存的，应当重新确定保管期限。"},{"i":12,"n":"第十二条","txt":"社会保险经办机构对经过鉴定可以销毁的档案，编制销毁清册，报同级人力资源社会保障行政部门备案，经社会保险经办机构主要负责人批准后销毁。 未经鉴定和批准，不得销毁任何档案。 社会保险经办机构应当派两人以上监督销毁档案。监督人员要在销毁清册上签名，并注明销毁的方式和时间。销毁清册永久保存。"},{"i":13,"n":"第十三条","txt":"社会保险经办机构按照有关规定，将永久保存的社会保险业务档案向同级国家综合档案馆移交。"},{"i":14,"n":"第十四条","txt":"社会保险经办机构有下列行为之一的，限期改正，并对直接负责的工作人员、主管人员和其他直接责任人员依法给予处分；给参保单位或者个人造成损失的，依法承担赔偿责任： （一） 不按规定归档或者不按规定移交档案的； （二） 伪造、篡改、隐匿档案或者擅自销毁档案的； （三） 玩忽职守，造成档案遗失、毁损的； （四） 违规提供、抄录档案，泄漏用人单位或者个人信息的； （五）违反社会保险业务档案和国家档案法律、法规的其他行为。"},{"i":15,"n":"第十五条","txt":"各类社会保险业务档案中涉及会计、电子文档等档案材料，国家有特别规定的，从其规定。"},{"i":16,"n":"第十六条","txt":"本规定自2009年9月1日起施行。 附件 社会保险业务材料归档范围与保管期限 一、社会保险管理类 （一）参保单位登记材料。包括参保单位办理参保登记、变更登记、注销登记时填报的登记表单及相关审核材料…………………………………………………………………………………………〔永久〕 （二）参保人员登记材料。包括缴费单位职工和退休人员，以家庭为单位或个人身份参加社会保险的城镇无业居民、农村居民、个体工商户、城镇灵活就业人员办理参保、社会保险关系变动、基本信息变更等登记手续时，填报的登记表单及相关审核材料………………………………………………………………………………………………………………〔100年〕 （三）社会保险个人账户管理材料。包括养老、医疗保险个人账户对账、个人账户修改等相关材料…………………………………………………………………………………………………………〔100年〕 （四）社会保险登记证管"}],"shehuibaoxiangerenquanyijiluguanlibanfa":[{"i":1,"n":"第一条","txt":"为了维护参保人员的合法权益，规范社会保险个人权益记录管理，根据《中华人民共和国社会保险法》等相关法律法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称社会保险个人权益记录，是指以纸质材料和电子数据等载体记录的反映参保人员及其用人单位履行社会保险义务、享受社会保险权益状况的信息，包括下列内容： （一）参保人员及其用人单位社会保险登记信息； （二）参保人员及其用人单位缴纳社会保险费、获得相关补贴的信息； （三）参保人员享受社会保险待遇资格及领取待遇的信息； （四）参保人员缴费年限和个人账户信息； （五）其他反映社会保险个人权益的信息。"},{"i":3,"n":"第三条","txt":"社会保险经办机构负责社会保险个人权益记录管理，提供与社会保险个人权益记录相关的服务。 人力资源社会保障信息化综合管理机构（以下简称信息机构）对社会保险个人权益记录提供技术支持和安全保障服务。 人力资源社会保障行政部门对社会保险个人权益记录管理实施监督。"},{"i":4,"n":"第四条","txt":"社会保险个人权益记录遵循及时、完整、准确、安全、保密原则，任何单位和个人不得用于商业交易或者营利活动，也不得违法向他人泄露。"},{"i":5,"n":"第五条","txt":"社会保险经办机构通过业务经办、统计、调查等方式获取参保人员相关社会保险个人权益信息，同时，应当与社会保险费征收机构、工商、民政、公安、机构编制等部门通报的情况进行核对。 与社会保险经办机构签订服务协议的医疗机构、药品经营单位、工伤康复机构、辅助器具安装配置机构、相关金融机构等（以下简称社会保险服务机构）和参保人员及其用人单位应当及时、准确提供社会保险个人权益信息，社会保险经办机构应当按照规定程序进行核查。"},{"i":6,"n":"第六条","txt":"社会保险经办机构应当依据业务经办原始资料及时采集社会保险个人权益信息。 通过互联网经办社会保险业务采集社会保险个人权益信息的，应当采取相应的安全措施。 社会保险经办机构应当在经办前台完成社会保险个人权益信息采集工作，不得在后台数据库直接录入、修改数据。 社会保险个人权益记录中缴费数额、待遇标准、个人账户储存额、缴费年限等待遇计发的数据，应当根据事先设定的业务规则，通过社会保险信息系统对原始采集数据进行计算处理后生成。"},{"i":7,"n":"第七条","txt":"社会保险经办机构应当建立社会保险个人权益信息采集的初审、审核、复核、审批制度，明确岗位职责，并在社会保险信息系统中进行岗位权限设置。"},{"i":8,"n":"第八条","txt":"社会保险经办机构和信息机构应当配备社会保险个人权益记录保管的场所和设施设备，建立并完善人力资源社会保障业务专网。"},{"i":9,"n":"第九条","txt":"社会保险个人权益数据保管应当符合以下要求： （一）建立完善的社会保险个人权益数据存储管理办法； （二）定期对社会保险个人权益数据的保管、可读取、备份记录状况等进行测试，发现问题及时处理； （三）社会保险个人权益数据应当定期备份，备份介质异地存放； （四）保管的软硬件环境、存储载体等发生变化时，应当及时对社会保险个人权益数据进行迁移、转换，并保留原有数据备查。"},{"i":10,"n":"第十条","txt":"参保人员流动就业办理社会保险关系转移时，新参保地社会保险经办机构应当及时做好社会保险个人权益记录的接收和管理工作；原参保地社会保险经办机构在将社会保险个人权益记录转出后，应当按照规定保留原有记录备查。"},{"i":11,"n":"第十一条","txt":"社会保险经办机构应当安排专门工作人员对社会保险个人权益数据进行管理和日常维护，检查记录的完整性、合规性，并按照规定程序修正和补充。 社会保险经办机构不得委托其他单位或者个人单独负责社会保险个人权益数据维护工作。其他单位或者个人协助维护的，社会保险经办机构应当与其签订保密协议。"},{"i":12,"n":"第十二条","txt":"社会保险经办机构应当建立社会保险个人权益记录维护日志，对社会保险个人权益数据维护的时间、内容、维护原因、处理方法和责任人等进行登记。"},{"i":13,"n":"第十三条","txt":"社会保险个人权益信息的采集、保管和维护等环节涉及的书面材料应当存档备查。"},{"i":14,"n":"第十四条","txt":"社会保险经办机构应当向参保人员及其用人单位开放社会保险个人权益记录查询程序，界定可供查询的内容，通过社会保险经办机构网点、自助终端或者电话、网站等方式提供查询服务。"},{"i":15,"n":"第十五条","txt":"社会保险经办机构网点应当设立专门窗口向参保人员及其用人单位提供免费查询服务。 参保人员向社会保险经办机构查询本人社会保险个人权益记录的，需持本人有效身份证件；参保人员委托他人向社会保险经办机构查询本人社会保险个人权益记录的，被委托人需持书面委托材料和本人有效身份证件。需要书面查询结果或者出具本人参保缴费、待遇享受等书面证明的，社会保险经办机构应当按照规定提供。 参保用人单位凭有效证明文件可以向社会保险经办机构免费查询本单位缴费情况，以及职工在本单位工作期间涉及本办法第二条第一项、第二项相关内容。"},{"i":16,"n":"第十六条","txt":"参保人员或者用人单位对社会保险个人权益记录存在异议时，可以向社会保险经办机构提出书面核查申请，并提供相关证明材料。社会保险经办机构应当进行复核，确实存在错误的，应当改正。"},{"i":17,"n":"第十七条","txt":"人力资源社会保障行政部门、信息机构基于宏观管理、决策以及信息系统开发等目的，需要使用社会保险个人权益记录的，社会保险经办机构应当依据业务需求规定范围提供。非因依法履行工作职责需要的，所提供的内容不得包含可以直接识别个人身份的信息。"},{"i":18,"n":"第十八条","txt":"有关行政部门、司法机关等因履行工作职责，依法需要查询社会保险个人权益记录的，社会保险经办机构依法按照规定的查询对象和记录项目提供查询。"},{"i":19,"n":"第十九条","txt":"其他申请查询社会保险个人权益记录的单位，应当向社会保险经办机构提出书面申请。申请应当包括下列内容： （一）申请单位的有效证明文件、单位名称、联系方式； （二）查询目的和法律依据； （三）查询的内容。"},{"i":20,"n":"第二十条","txt":"社会保险经办机构收到依前条规定提出的查询申请后，应当进行审核，并按照下列情形分别作出处理： （一）对依法应当予以提供的，按照规定程序提供； （二）对无法律依据的，应当向申请人作出说明。"},{"i":21,"n":"第二十一条","txt":"社会保险经办机构应当对除参保人员本人及其用人单位以外的其他单位查询社会保险个人权益记录的情况进行登记。"},{"i":22,"n":"第二十二条","txt":"社会保险经办机构不得向任何单位和个人提供数据库全库交换或者提供超出规定查询范围的信息。"},{"i":23,"n":"第二十三条","txt":"建立社会保险个人权益记录保密制度。人力资源社会保障行政部门、社会保险经办机构、信息机构、社会保险服务机构、信息技术服务商及其工作人员对在工作中获知的社会保险个人权益记录承担保密责任，不得违法向他人泄露。"},{"i":24,"n":"第二十四条","txt":"依据本办法第十八条规定查询社会保险个人权益记录的有关行政部门和司法机关，不得将获取的社会保险个人权益记录用作约定之外的其他用途，也不得违法向他人泄露。"},{"i":25,"n":"第二十五条","txt":"信息机构和社会保险经办机构应当建立健全社会保险信息系统安全防护体系和安全管理制度，加强应急预案管理和灾难恢复演练，确保社会保险个人权益数据安全。"},{"i":26,"n":"第二十六条","txt":"信息机构应当按照社会保险经办机构的要求，建立社会保险个人权益数据库用户管理制度，明确系统管理员、数据库管理员、业务经办用户和信息查询用户的职责，实行用户身份认证和权限控制。 系统管理员、数据库管理员不得兼职业务经办用户或者信息查询用户。"},{"i":27,"n":"第二十七条","txt":"人力资源社会保障行政部门及其他有关行政部门、司法机关违反保密义务的，应当依法承担法律责任。"},{"i":28,"n":"第二十八条","txt":"社会保险经办机构、信息机构及其工作人员有下列行为之一的，由人力资源社会保障行政部门责令改正；对直接负责的主管人员和其他直接责任人员依法给予处分；给社会保险基金、用人单位或者个人造成损失的，依法承担赔偿责任；构成违反治安管理行为的，由公安机关依法予以处罚；构成犯罪的，依法追究刑事责任： （一）未及时、完整、准确记载社会保险个人权益信息的； （二）系统管理员、数据库管理员兼职业务经办用户或者信息查询用户的； （三）与用人单位或者个人恶意串通，伪造、篡改社会保险个人权益记录或者提供虚假社会保险个人权益信息的； （四）丢失、破坏、违反规定销毁社会保险个人权益记录的； （五）擅自提供、复制、公布、出售或者变相交易社会保险个人权益记录的； （六）违反安全管理规定，将社会保险个人权益数据委托其他单位或个人单独管理和维护的。"},{"i":29,"n":"第二十九条","txt":"社会保险服务机构、信息技术服务商以及按照本办法第十九条规定获取个人权益记录的单位及其工作人员，将社会保险个人权益记录用于与社会保险经办机构约定以外用途，或者造成社会保险个人权益信息泄露的，依法对直接负责的主管人员和其他直接责任人员给予处分；给社会保险基金、用人单位或者个人造成损失的，依法承担赔偿责任；构成违反治安管理行为的，由公安机关依法予以处罚；构成犯罪的，依法追究刑事责任。"},{"i":30,"n":"第三十条","txt":"任何组织和个人非法提供、复制、公布、出售或者变相交易社会保险个人权益记录，有违法所得的，由人力资源社会保障行政部门没收违法所得；属于社会保险服务机构、信息技术服务商的，可由社会保险经办机构与其解除服务协议；依法对直接负责的主管人员和其他直接责任人员给予处分；给社会保险基金、用人单位或者个人造成损失的，依法承担赔偿责任；构成违反治安管理行为的，由公安机关依法予以处罚；构成犯罪的，依法追究刑事责任。"},{"i":31,"n":"第三十一条","txt":"社会保险个人权益记录管理涉及会计等材料，国家对其有特别规定的，从其规定。 法律、行政法规规定有关业务接受其他监管部门监督管理的，依照其规定执行。"},{"i":32,"n":"第三十二条","txt":"本办法自2011年7月1日起施行。"}],"shehuibaoxianjijinxianxingzhifuzanxingbanfa":[{"i":1,"n":"第一条","txt":"为了维护公民的社会保险合法权益，规范社会保险基金先行支付管理，根据《中华人民共和国社会保险法》（以下简称社会保险法）和《工伤保险条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"参加基本医疗保险的职工或者居民（以下简称个人）由于第三人的侵权行为造成伤病的，其医疗费用应当由第三人按照确定的责任大小依法承担。超过第三人责任部分的医疗费用，由基本医疗保险基金按照国家规定支付。 前款规定中应当由第三人支付的医疗费用，第三人不支付或者无法确定第三人的，在医疗费用结算时，个人可以向参保地社会保险经办机构书面申请基本医疗保险基金先行支付，并告知造成其伤病的原因和第三人不支付医疗费用或者无法确定第三人的情况。"},{"i":3,"n":"第三条","txt":"社会保险经办机构接到个人根据第二条规定提出的申请后，经审核确定其参加基本医疗保险的，应当按照统筹地区基本医疗保险基金支付的规定先行支付相应部分的医疗费用。"},{"i":4,"n":"第四条","txt":"个人由于第三人的侵权行为造成伤病被认定为工伤，第三人不支付工伤医疗费用或者无法确定第三人的，个人或者其近亲属可以向社会保险经办机构书面申请工伤保险基金先行支付，并告知第三人不支付或者无法确定第三人的情况。"},{"i":5,"n":"第五条","txt":"社会保险经办机构接到个人根据第四条规定提出的申请后，应当审查个人获得基本医疗保险基金先行支付和其所在单位缴纳工伤保险费等情况，并按照下列情形分别处理： （一）对于个人所在用人单位已经依法缴纳工伤保险费，且在认定工伤之前基本医疗保险基金有先行支付的，社会保险经办机构应当按照工伤保险有关规定，用工伤保险基金先行支付超出基本医疗保险基金先行支付部分的医疗费用，并向基本医疗保险基金退还先行支付的费用； （二）对于个人所在用人单位已经依法缴纳工伤保险费，在认定工伤之前基本医疗保险基金无先行支付的，社会保险经办机构应当用工伤保险基金先行支付工伤医疗费用； （三）对于个人所在用人单位未依法缴纳工伤保险费，且在认定工伤之前基本医疗保险基金有先行支付的，社会保险经办机构应当在3个工作日内向用人单位发出书面催告通知，要求用人单位在5个工作日内依法支付超出基本医疗保险基金先行支付部分的医疗费用，并向基本医疗"},{"i":6,"n":"第六条","txt":"职工所在用人单位未依法缴纳工伤保险费，发生工伤事故的，用人单位应当采取措施及时救治，并按照规定的工伤保险待遇项目和标准支付费用。 职工被认定为工伤后，有下列情形之一的，职工或者其近亲属可以持工伤认定决定书和有关材料向社会保险经办机构书面申请先行支付工伤保险待遇： （一）用人单位被依法吊销营业执照或者撤销登记、备案的； （二）用人单位拒绝支付全部或者部分费用的； （三）依法经仲裁、诉讼后仍不能获得工伤保险待遇，法院出具中止执行文书的； （四）职工认为用人单位不支付的其他情形。"},{"i":7,"n":"第七条","txt":"社会保险经办机构收到职工或者其近亲属根据第六条规定提出的申请后，应当在3个工作日内向用人单位发出书面催告通知，要求其在5个工作日内予以核实并依法支付工伤保险待遇，告知其如在规定期限内不按时足额支付的，工伤保险基金在按照规定先行支付后，取得要求其偿还的权利。"},{"i":8,"n":"第八条","txt":"用人单位未按照第七条规定按时足额支付的，社会保险经办机构应当按照社会保险法和《工伤保险条例》的规定，先行支付工伤保险待遇项目中应当由工伤保险基金支付的项目。"},{"i":9,"n":"第九条","txt":"个人或者其近亲属提出先行支付医疗费用、工伤医疗费用或者工伤保险待遇申请，社会保险经办机构经审核不符合先行支付条件的，应当在收到申请后5个工作日内作出不予先行支付的决定，并书面通知申请人。"},{"i":10,"n":"第十条","txt":"个人申请先行支付医疗费用、工伤医疗费用或者工伤保险待遇的，应当提交所有医疗诊断、鉴定等费用的原始票据等证据。社会保险经办机构应当保留所有原始票据等证据，要求申请人在先行支付凭据上签字确认，凭原始票据等证据先行支付医疗费用、工伤医疗费用或者工伤保险待遇。 个人因向第三人或者用人单位请求赔偿需要医疗费用、工伤医疗费用或者工伤保险待遇的原始票据等证据的，可以向社会保险经办机构索取复印件，并将第三人或者用人单位赔偿情况及时告知社会保险经办机构。"},{"i":11,"n":"第十一条","txt":"个人已经从第三人或者用人单位处获得医疗费用、工伤医疗费用或者工伤保险待遇的，应当主动将先行支付金额中应当由第三人承担的部分或者工伤保险基金先行支付的工伤保险待遇退还给基本医疗保险基金或者工伤保险基金，社会保险经办机构不再向第三人或者用人单位追偿。 个人拒不退还的，社会保险经办机构可以从以后支付的相关待遇中扣减其应当退还的数额，或者向人民法院提起诉讼。"},{"i":12,"n":"第十二条","txt":"社会保险经办机构按照本办法第三条规定先行支付医疗费用或者按照第五条第一项、第二项规定先行支付工伤医疗费用后，有关部门确定了第三人责任的，应当要求第三人按照确定的责任大小依法偿还先行支付数额中的相应部分。第三人逾期不偿还的，社会保险经办机构应当依法向人民法院提起诉讼。"},{"i":13,"n":"第十三条","txt":"社会保险经办机构按照本办法第五条第三项、第四项和第六条、第七条、第八条的规定先行支付工伤保险待遇后，应当责令用人单位在10日内偿还。 用人单位逾期不偿还的，社会保险经办机构可以按照社会保险法第六十三条的规定，向银行和其他金融机构查询其存款账户，申请县级以上社会保险行政部门作出划拨应偿还款项的决定，并书面通知用人单位开户银行或者其他金融机构划拨其应当偿还的数额。 用人单位账户余额少于应当偿还数额的，社会保险经办机构可以要求其提供担保，签订延期还款协议。 用人单位未按时足额偿还且未提供担保的，社会保险经办机构可以申请人民法院扣押、查封、拍卖其价值相当于应当偿还数额的财产，以拍卖所得偿还所欠数额。"},{"i":14,"n":"第十四条","txt":"社会保险经办机构向用人单位追偿工伤保险待遇发生的合理费用以及用人单位逾期偿还部分的利息损失等，应当由用人单位承担。"},{"i":15,"n":"第十五条","txt":"用人单位不支付依法应当由其支付的工伤保险待遇项目的，职工可以依法申请仲裁、提起诉讼。"},{"i":16,"n":"第十六条","txt":"个人隐瞒已经从第三人或者用人单位处获得医疗费用、工伤医疗费用或者工伤保险待遇，向社会保险经办机构申请并获得社会保险基金先行支付的，按照社会保险法第八十八条的规定处理。"},{"i":17,"n":"第十七条","txt":"用人单位对社会保险经办机构作出先行支付的追偿决定不服或者对社会保险行政部门作出的划拨决定不服的，可以依法申请行政复议或者提起行政诉讼。 个人或者其近亲属对社会保险经办机构作出不予先行支付的决定不服或者对先行支付的数额不服的，可以依法申请行政复议或者提起行政诉讼。"},{"i":18,"n":"第十八条","txt":"本办法自2011年7月1日起施行。"}],"shehuibaoxianjijinjiandujubaogongzuoguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范社会保险基金监督举报管理工作，切实保障社会保险基金安全，根据《中华人民共和国社会保险法》和有关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"人力资源社会保障行政部门开展社会保险基金监督举报的受理、办理等管理工作，适用本办法。 本办法所称社会保险基金是指基本养老保险基金、工伤保险基金、失业保险基金等人力资源社会保障部门管理的社会保险基金。"},{"i":3,"n":"第三条","txt":"人力资源社会保障部主管全国社会保险基金监督举报管理工作。县级以上地方人力资源社会保障行政部门负责本行政区域内的社会保险基金监督举报管理工作。 人力资源社会保障行政部门负责社会保险基金监督的机构具体承担社会保险基金监督举报综合管理工作。人力资源社会保障部门负责社会保险政策、经办、信息化综合管理等的机构，依据职责协同做好社会保险基金监督举报管理工作。"},{"i":4,"n":"第四条","txt":"人力资源社会保障行政部门要加强与公安、民政、司法行政、财政、卫生健康、人民银行、审计、税务等部门和人民法院、纪检监察等机关的协同配合，做好社会保险基金监督举报管理工作，共同保障社会保险基金安全。"},{"i":5,"n":"第五条","txt":"社会保险基金监督举报管理工作应当坚持依法、公正、高效、便民的原则。"},{"i":6,"n":"第六条","txt":"本办法所称社会保险基金监督举报（以下简称举报），是指任何组织或者个人向人力资源社会保障行政部门反映机构、单位、个人涉嫌欺诈骗取、套取或者挪用贪占社会保险基金情形的行为。 依照本办法，举报涉嫌欺诈骗取、套取或者挪用贪占社会保险基金情形的任何组织或者个人是举报人；被举报的机构、单位、个人是被举报人。"},{"i":7,"n":"第七条","txt":"参保单位、个人、中介机构涉嫌有下列情形之一的，任何组织或者个人可以依照本办法举报： （一）以提供虚假证明材料等手段虚构社会保险参保条件、违规补缴的； （二）伪造、变造有关证件、档案、材料，骗取社会保险基金的； （三）组织或者协助他人以伪造、变造档案、材料等手段骗取参保补缴、提前退休资格或者违规申领社会保险待遇的； （四）个人丧失社会保险待遇享受资格后，本人或者相关受益人不按规定履行告知义务、隐瞒事实违规享受社会保险待遇的； （五）其他欺诈骗取、套取或者挪用贪占社会保险基金的情形。"},{"i":8,"n":"第八条","txt":"社会保险服务机构及其工作人员涉嫌有下列情形之一的，任何组织或者个人可以依照本办法举报： （一）工伤保险协议医疗机构、工伤康复协议机构、工伤保险辅助器具配置协议机构、工伤预防项目实施单位、职业伤害保障委托承办机构及其工作人员以伪造、变造或者提供虚假证明材料及相关报销票据、冒名顶替等手段骗取或者协助、配合他人骗取社会保险基金的； （二）享受失业保险培训补贴的培训机构及其工作人员以伪造、变造、提供虚假培训记录等手段骗取或者协助、配合他人骗取社会保险基金的； （三）其他欺诈骗取、套取或者挪用贪占社会保险基金的情形。"},{"i":9,"n":"第九条","txt":"社会保险经办机构及其工作人员涉嫌有下列情形之一的，任何组织或者个人可以依照本办法举报： （一）隐匿、转移、侵占、挪用、截留社会保险基金的； （二）违规审核、审批社会保险申报材料，违规办理参保、补缴、关系转移、待遇核定、待遇资格认证等，违规发放社会保险待遇的；  （三）伪造或者篡改缴费记录、享受社会保险待遇记录等社会保险数据、个人权益记录的； （四）其他欺诈骗取、套取或者挪用贪占社会保险基金的情形。"},{"i":10,"n":"第十条","txt":"与社会保险基金收支、管理直接相关单位及其工作人员涉嫌有下列情形之一的，任何组织或者个人可以依照本办法举报： （一）人力资源社会保障行政部门及其工作人员违规出具行政执法文书、违规进行工伤认定、违规办理提前退休，侵害社会保险基金的； （二）劳动能力鉴定委员会及其工作人员违规进行劳动能力鉴定，侵害社会保险基金的； （三）劳动人事争议仲裁机构及其工作人员违规出具仲裁文书，侵害社会保险基金的； （四）信息化综合管理机构及其工作人员伪造或者篡改缴费记录、享受社会保险待遇记录等社会保险数据、个人权益记录的； （五）其他欺诈骗取、套取或者挪用贪占社会保险基金的情形。"},{"i":11,"n":"第十一条","txt":"依法应当通过劳动人事争议处理、劳动保障监察投诉、行政争议处理、劳动能力再次鉴定、信访等途径解决或者以举报形式进行咨询、政府信息公开申请等活动的，不适用本办法。人力资源社会保障行政部门应当告知举报人依法依规通过相关途径解决。 人力资源社会保障行政部门收到属于财政部门、社会保险费征收机构等部门、机构职责的举报事项，应当依法书面通知并移交有权处理的部门、机构处理。"},{"i":12,"n":"第十二条","txt":"人力资源社会保障行政部门通过12333或者其他服务电话、传真、信函、网络、现场等渠道接收举报事项。 人力资源社会保障行政部门应当向社会公布接收举报事项的电话号码、传真号码、通信地址、邮政编码、网络举报途径、接待场所和时间等渠道信息,并在其举报接待场所或者网站公布与举报有关的法律、法规、规章，举报范围和受理、办理程序等有关事项。"},{"i":13,"n":"第十三条","txt":"举报人举报应当提供被举报人的名称（姓名）和涉嫌欺诈骗取、套取或者挪用贪占社会保险基金的有效线索；尽可能提供被举报人地址（住所）、统一社会信用代码（公民身份号码）、法定代表人信息和其他相关佐证材料。 提倡举报人提供书面举报材料。"},{"i":14,"n":"第十四条","txt":"举报人进行举报，应当遵守法律、法规、规章等规定，不得捏造、歪曲事实，不得诬告陷害他人。"},{"i":15,"n":"第十五条","txt":"举报人可以实名举报或者匿名举报。提倡实名举报。 现场实名举报的，举报人应当提供居民身份证或者营业执照等有效证件的原件和真实有效的联系方式。 以电话、传真、来信、网络等形式实名举报的，举报人应当提供居民身份证或者营业执照等有效证件的复印件和真实有效的联系方式。 举报人未采取本条第二款、第三款的形式举报的，视为匿名举报。"},{"i":16,"n":"第十六条","txt":"现场举报应当到人力资源社会保障行政部门设立的接待场所；多人现场提出相同举报事项的，应当推选代表，代表人数不超过5人。"},{"i":17,"n":"第十七条","txt":"接收现场口头举报，应当准确记录举报事项，交举报人确认。经征得举报人同意后可以录音、录像。实名举报的，由举报人签名或者盖章；匿名举报的，应当记录在案。 接收电话举报，应当细心接听、询问清楚、准确记录，经告知举报人后可以录音。 接收传真、来信、网络等形式举报，应当保持举报材料的完整。 对内容不详的实名举报，应当及时联系举报人补充相关材料。"},{"i":18,"n":"第十八条","txt":"人力资源社会保障行政部门应当加强举报事项接收转交管理工作。"},{"i":19,"n":"第十九条","txt":"举报涉及重大问题或者紧急事项的，具体承担社会保险基金监督举报综合管理工作的机构应当立即向本部门负责人报告，并依法采取必要措施。"},{"i":20,"n":"第二十条","txt":"举报按照“属地管理、分级负责，谁主管、谁负责”的原则确定管辖。 必要时，上级人力资源社会保障行政部门可以受理下级人力资源社会保障行政部门管辖的举报事项，也可以向下级人力资源社会保障行政部门交办、督办举报事项。 两个及两个以上同级人力资源社会保障行政部门都有管辖权限的，由最先受理的人力资源社会保障行政部门管辖。对管辖发生争议的，应当自发生争议之日起5个工作日内协商解决；协商不成的，报请共同的上一级人力资源社会保障行政部门，共同的上一级人力资源社会保障行政部门应当自收到之日起5个工作日内指定管辖。"},{"i":21,"n":"第二十一条","txt":"人力资源社会保障行政部门接收到举报事项后，应当在5个工作日内进行审查，有下列情形之一的，不予受理： （一）不符合本办法第七条、第八条、第九条或者第十条规定的； （二）无法确定被举报人，或者不能提供欺诈骗取、套取或者挪用贪占社会保险基金行为有效线索的； （三）对已经办结的同一举报事项再次举报，没有提供新的有效线索的。 对符合本办法第七条、第八条、第九条或者第十条的规定但本部门不具备管辖权限的举报事项，应当移送到有管辖权限的人力资源社会保障行政部门，并告知实名举报人移送去向。 除前两款规定外，举报事项自人力资源社会保障行政部门接收之日起即为受理。"},{"i":22,"n":"第二十二条","txt":"人力资源社会保障行政部门应当自接收举报事项之日起10个工作日内，将受理（不予受理）决定通过纸质通知或者电子邮件、短信等形式告知有告知要求的实名举报人。"},{"i":23,"n":"第二十三条","txt":"受理举报事项后，人力资源社会保障行政部门办理举报事项以及作出行政处理、行政处罚决定的，应当按照《社会保险基金行政监督办法》等有关规定和本章的规定执行。 已经受理尚未办结的举报事项，再次举报的，可以合并办理；再次举报并提供新的有效线索的，办理期限自确定合并办理之日起重新计算。"},{"i":24,"n":"第二十四条","txt":"人力资源社会保障行政部门在办理举报事项中涉及异地调查的，可以向当地人力资源社会保障行政部门提出协助请求。协助事项属于被请求部门职责范围内的，应当依法予以协助。"},{"i":25,"n":"第二十五条","txt":"办理举报事项涉及其他部门职责的，人力资源社会保障行政部门可以会同相关部门共同办理。"},{"i":26,"n":"第二十六条","txt":"下级人力资源社会保障行政部门对上级人力资源社会保障行政部门交办、移送的举报事项，应当按照规定时限或者上级人力资源社会保障行政部门督办要求办理，并书面报告调查处理意见、办理结果。"},{"i":27,"n":"第二十七条","txt":"符合下列情形之一的，经人力资源社会保障行政部门批准，举报事项予以办结： （一）经办理发现问题，依法作出行政处理、行政处罚决定的；依法应当由其他部门、机构处理，向有关部门、机构提出处理建议，或者移交有关部门、机构处理的； （二）经办理未发现欺诈骗取、套取或者挪用贪占社会保险基金情形的； （三）其他依法应当予以办结的情形。 人力资源社会保障行政部门应当自受理举报事项之日起60个工作日内办结举报事项；情况复杂的，经人力资源社会保障行政部门负责人批准，可以适当延长，但延长期限不得超过30个工作日。"},{"i":28,"n":"第二十八条","txt":"符合下列情形之一的，经人力资源社会保障行政部门批准，可以中止对举报事项的办理： （一）举报涉及法律、法规、规章或者政策适用问题，需要有权机关作出解释或者确认的； （二）因被举报人或者有关人员下落不明等，无法继续办理的； （三）因被举报的机构、单位终止，尚未确定权利义务承受人，无法继续办理的； （四）因自然灾害等不可抗力原因，无法继续办理的； （五）因案情重大、疑难复杂或者危害后果特别严重，确需提请上级主管部门研究决定的； （六）其他依法应当中止办理的情形。 中止情形消除后，应当恢复对举报事项的办理。办理期限自中止情形消除之日起继续计算。"},{"i":29,"n":"第二十九条","txt":"上级人力资源社会保障行政部门发现下级人力资源社会保障行政部门对举报事项的办理确有错误的，应当责成下级人力资源社会保障行政部门重新办理，必要时可以直接办理。"},{"i":30,"n":"第三十条","txt":"实名举报人可以要求答复举报事项的办理结果，人力资源社会保障行政部门可以视具体情况采取口头或者书面形式答复实名举报人，答复不得泄露国家秘密、商业秘密和个人隐私。口头答复应当做好书面记录。"},{"i":31,"n":"第三十一条","txt":"人力资源社会保障行政部门应当严格管理举报材料，逐件登记接收举报事项的举报人、被举报人、主要内容、受理和办理等基本情况。"},{"i":32,"n":"第三十二条","txt":"举报材料的保管和整理，应当按照档案管理的有关规定执行。 省级人力资源社会保障行政部门应当完善举报信息系统，实行信息化管理。"},{"i":33,"n":"第三十三条","txt":"县级以上地方人力资源社会保障行政部门应当建立社会保险基金监督举报管理年度报告制度。 省级人力资源社会保障行政部门应当于每年1月31日前，向人力资源社会保障部报告上一年度社会保险基金监督举报管理情况。"},{"i":34,"n":"第三十四条","txt":"举报人的合法权益依法受到保护。任何单位和个人不得以任何借口阻拦、压制或者打击报复举报人。"},{"i":35,"n":"第三十五条","txt":"人力资源社会保障行政部门工作人员与举报事项、举报人、被举报人有直接利害关系或者其他关系，可能影响公正办理的，应当回避。 举报人有正当理由并且有证据证明人力资源社会保障行政部门工作人员应当回避的，可以提出回避申请，由人力资源社会保障行政部门决定。申请人力资源社会保障行政部门负责人回避的，由上级人力资源社会保障行政部门决定。"},{"i":36,"n":"第三十六条","txt":"人力资源社会保障行政部门应当建立健全工作责任制，严格遵守以下保密规定： （一）举报事项的接收、受理、登记及办理，应当依照国家有关法律、行政法规等规定严格保密，不得私自摘抄、复制、扣压、销毁举报材料； （二）严禁泄露举报人的姓名、身份、单位、地址、联系方式等信息，严禁将举报情况透漏给被举报人或者与举报工作无关的人员； （三）办理举报时不得出示举报信原件或者复印件，不得暴露举报人的有关信息，对匿名的举报书信及材料，除特殊情况外，不得鉴定笔迹； （四）开展宣传报道，未经举报人书面同意，不得公开举报人的姓名、身份、单位、地址、联系方式等信息。"},{"i":37,"n":"第三十七条","txt":"举报事项经查证属实，为社会保险基金挽回或者减少重大损失的，应当按照规定对实名举报人予以奖励。"},{"i":38,"n":"第三十八条","txt":"人力资源社会保障行政部门应当配备专门人员，提供必要的办公条件等，保障举报管理工作顺利进行。"},{"i":39,"n":"第三十九条","txt":"受理、办理举报事项的工作人员及其负责人有下列情形之一的，由人力资源社会保障行政部门责令改正；造成严重后果的，依法依规予以处理： （一）对于应当受理、办理的举报事项未及时受理、办理或者未在规定期限内办结举报事项的； （二）将举报人的举报材料或者有关情况透漏给被举报人或者与举报工作无关的人员的； （三）对涉及重大问题或者紧急事项的举报隐瞒、谎报、缓报，或者未依法及时采取必要措施的； （四）未妥善保管举报材料，造成举报材料损毁或者丢失的； （五）其他违法违规的情形。"},{"i":40,"n":"第四十条","txt":"举报人捏造、歪曲事实，诬告陷害他人的，依法承担法律责任。"},{"i":41,"n":"第四十一条","txt":"本办法自2023年5月1日起施行。原劳动和社会保障部《社会保险基金监督举报工作管理办法》（劳动和社会保障部令第11号）同时废止。"}],"shehuibaoxianjijinxingzhengjiandubanfa":[{"i":1,"n":"第一条","txt":"为了保障社会保险基金安全，规范和加强社会保险基金行政监督，根据《中华人民共和国社会保险法》和有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称社会保险基金行政监督，是指人力资源社会保障行政部门对基本养老保险基金、工伤保险基金、失业保险基金等人力资源社会保障部门管理的社会保险基金收支、管理情况进行的监督。"},{"i":3,"n":"第三条","txt":"社会保险基金行政监督应当遵循合法、客观、公正、效率的原则。"},{"i":4,"n":"第四条","txt":"人力资源社会保障部主管全国社会保险基金行政监督工作。县级以上地方各级人力资源社会保障行政部门负责本行政区域内的社会保险基金行政监督工作。 人力资源社会保障行政部门对下级人力资源社会保障行政部门管辖范围内的重大监督事项，可以直接进行监督。"},{"i":5,"n":"第五条","txt":"人力资源社会保障行政部门应当加强社会保险基金行政监督队伍建设，保证工作所需经费，保障监督工作独立性。"},{"i":6,"n":"第六条","txt":"社会保险基金行政监督工作人员应当忠于职守、清正廉洁、秉公执法、保守秘密。 社会保险基金行政监督工作人员依法履行监督职责受法律保护，失职追责、尽职免责。 社会保险基金行政监督工作人员应当具备与履行职责相适应的专业能力，依规取得行政执法证件，并定期参加培训。"},{"i":7,"n":"第七条","txt":"人力资源社会保障行政部门负责社会保险基金监督的机构具体实施社会保险基金行政监督工作。人力资源社会保障部门负责社会保险政策、经办、信息化综合管理等机构，依据职责协同做好社会保险基金行政监督工作。"},{"i":8,"n":"第八条","txt":"人力资源社会保障行政部门应当加强与公安、民政、司法行政、财政、卫生健康、人民银行、审计、税务、医疗保障等部门的协同配合，加强信息共享、分析，加大协同查处力度，共同维护社会保险基金安全。"},{"i":9,"n":"第九条","txt":"人力资源社会保障行政部门应当畅通社会监督渠道，鼓励和支持社会各方参与社会保险基金监督。 任何组织或者个人有权对涉及社会保险基金的违法违规行为进行举报。"},{"i":10,"n":"第十条","txt":"人力资源社会保障行政部门依法履行下列社会保险基金行政监督职责： （一）检查社会保险基金收支、管理情况； （二）受理有关社会保险基金违法违规行为的举报； （三）依法查处社会保险基金违法违规问题； （四）宣传社会保险基金监督法律、法规、规章和政策； （五）法律、法规规定的其他事项。"},{"i":11,"n":"第十一条","txt":"人力资源社会保障行政部门对社会保险经办机构的下列事项实施监督： （一）执行社会保险基金收支、管理的有关法律、法规、规章和政策的情况； （二）社会保险基金预算执行及决算情况； （三）社会保险基金收入户、支出户等银行账户开立、使用和管理情况； （四）社会保险待遇审核和基金支付情况； （五）社会保险服务协议订立、变更、履行、解除或者终止情况； （六）社会保险基金收支、管理内部控制情况； （七）法律、法规规定的其他事项。"},{"i":12,"n":"第十二条","txt":"人力资源社会保障行政部门对社会保险服务机构的下列事项实施监督： （一）遵守社会保险相关法律、法规、规章和政策的情况； （二）社会保险基金管理使用情况； （三）社会保险基金管理使用内部控制情况； （四）社会保险服务协议履行情况； （五）法律、法规规定的其他事项。"},{"i":13,"n":"第十三条","txt":"人力资源社会保障行政部门对与社会保险基金收支、管理直接相关单位的下列事项实施监督： （一）提前退休审批情况； （二）工伤认定（职业伤害确认）情况； （三）劳动能力鉴定情况； （四）法律、法规规定的其他事项。"},{"i":14,"n":"第十四条","txt":"人力资源社会保障行政部门有权要求被监督单位提供与监督事项有关的资料，包括但不限于与社会保险基金收支、管理相关的文件、财务资料、业务资料、审计报告、会议纪要等。 被监督单位应当全面、完整提供实施监督所需资料，说明情况，并对所提供资料真实性、完整性作出书面承诺。"},{"i":15,"n":"第十五条","txt":"人力资源社会保障行政部门有权查阅、记录、复制被监督单位与社会保险基金有关的会计凭证、会计账簿、财务会计报告、业务档案，以及其他与社会保险基金收支、管理有关的数据、资料，有权查询被监督单位社会保险信息系统的用户管理、权限控制、数据管理等情况。"},{"i":16,"n":"第十六条","txt":"人力资源社会保障行政部门有权询问与监督事项有关的单位和个人，要求其对与监督事项有关的问题作出说明、提供有关佐证。"},{"i":17,"n":"第十七条","txt":"人力资源社会保障行政部门应当充分利用信息化技术手段查找问题，加强社会保险基金监管信息系统应用。"},{"i":18,"n":"第十八条","txt":"信息化综合管理机构应当根据监督工作需要，向社会保险基金行政监督工作人员开放社会保险经办系统等信息系统的查询权限，提供有关信息数据。"},{"i":19,"n":"第十九条","txt":"人力资源社会保障行政部门有权对隐匿、伪造、变造或者故意销毁会计凭证、会计账簿、财务会计报告以及其他与社会保险基金收支、管理有关资料的行为予以制止并责令改正；有权对可能被转移、隐匿或者灭失的资料予以封存。"},{"i":20,"n":"第二十条","txt":"人力资源社会保障行政部门有权对隐匿、转移、侵占、挪用社会保险基金的行为予以制止并责令改正。"},{"i":21,"n":"第二十一条","txt":"社会保险基金行政监督的检查方式包括现场检查和非现场检查。人力资源社会保障行政部门应当制定年度检查计划，明确检查范围和重点。 被监督单位应当配合人力资源社会保障行政部门的工作，并提供必要的工作条件。"},{"i":22,"n":"第二十二条","txt":"人力资源社会保障行政部门实施现场检查，依照下列程序进行： （一）根据年度检查计划和工作需要确定检查项目及检查内容，制定检查方案，并在实施检查3个工作日前通知被监督单位；提前通知可能影响检查结果的，可以现场下达检查通知； （二）检查被监督单位社会保险基金相关凭证账簿，查阅与监督事项有关的文件、资料、档案、数据，向被监督单位和有关个人调查取证，听取被监督单位有关社会保险基金收支、管理使用情况的汇报； （三）根据检查结果，形成检查报告，并送被监督单位征求意见。被监督单位如有异议，应当在接到检查报告10个工作日内提出书面意见。逾期未提出书面意见的，视同无异议。"},{"i":23,"n":"第二十三条","txt":"人力资源社会保障行政部门实施非现场检查，依照下列程序进行： （一）根据检查计划及工作需要，确定非现场检查目的及检查内容，通知被监督单位按照规定的范围、格式及时限报送数据、资料；或者从信息系统提取社会保险基金管理使用相关数据； （二）审核被监督单位报送和提取的数据、资料，数据、资料不符合要求的，被监督单位应当补报或者重新报送； （三）比对分析数据、资料，对发现的疑点问题要求被监督单位核查说明；对存在的重大问题，实施现场核实；评估社会保险基金收支、管理状况及存在的问题，形成检查报告。 对报送和提取的数据、资料，人力资源社会保障行政部门应当做好存储和使用管理，保证数据安全。"},{"i":24,"n":"第二十四条","txt":"人力资源社会保障行政部门对监督发现的问题，采取以下处理措施： （一）对社会保险基金收支、管理存在问题的，依法提出整改意见，采取约谈、函询、通报等手段督促整改； （二）对依法应当由有关主管机关处理的，向有关主管机关提出处理建议。 人力资源社会保障行政部门有权对被监督单位的整改情况进行检查。"},{"i":25,"n":"第二十五条","txt":"人力资源社会保障行政部门对通过社会保险基金行政监督检查发现、上级部门交办、举报、媒体曝光、社会保险经办机构移送等渠道获取的违法违规线索，应当查处，进行调查并依法作出行政处理、处罚决定。 人力资源社会保障行政部门作出行政处理、处罚决定前，应当听取当事人陈述、申辩；作出行政处理、处罚决定，应当告知当事人依法享有申请行政复议或者提起行政诉讼的权利。"},{"i":26,"n":"第二十六条","txt":"社会保险基金行政监督的检查和查处应当由两名及以上工作人员共同进行，出示行政执法证件。 社会保险基金行政监督工作人员不得利用职务便利牟取不正当利益，不得从事影响客观履行基金监督职责的工作。 社会保险基金行政监督工作人员与被监督单位、个人或者事项存在利害关系的，应当回避。"},{"i":27,"n":"第二十七条","txt":"人力资源社会保障行政部门可以聘请会计师事务所等第三方机构对社会保险基金的收支、管理情况进行审计，聘请专业人员协助开展检查。 被聘请机构和人员不得复制涉及参保个人的明细数据，不得未经授权复制统计数据和财务数据，不得将工作中获取、知悉的被监督单位资料或者相关信息用于社会保险基金监督管理以外的其他用途，不得泄露相关个人信息和商业秘密。"},{"i":28,"n":"第二十八条","txt":"人力资源社会保障行政部门应当建立社会保险基金要情报告制度。 地方人力资源社会保障行政部门应当依规、按时、完整、准确向上级人力资源社会保障行政部门报告社会保险基金要情。 社会保险经办机构应当及时向本级人力资源社会保障行政部门报告社会保险基金要情。 本办法所称社会保险基金要情是指贪污挪用、欺诈骗取等侵害社会保险基金的情况。"},{"i":29,"n":"第二十九条","txt":"社会保险经办机构及其工作人员有下列行为之一的，由人力资源社会保障行政部门责令改正；对直接负责的主管人员和其他直接责任人员依法给予处分；法律法规另有规定的，从其规定： （一）未履行社会保险法定职责的； （二）未将社会保险基金存入财政专户的； （三）克扣或者拒不按时支付社会保险待遇的； （四）丢失或者篡改缴费记录、享受社会保险待遇记录等社会保险数据、个人权益记录的； （五）违反社会保险经办内部控制制度的； （六）其他违反社会保险法律、法规的行为。"},{"i":30,"n":"第三十条","txt":"社会保险经办机构及其工作人员隐匿、转移、侵占、挪用社会保险基金的，按照《中华人民共和国社会保险法》第九十一条的规定处理。"},{"i":31,"n":"第三十一条","txt":"社会保险服务机构有下列行为之一，以欺诈、伪造证明材料或者其他手段骗取社会保险基金支出的，按照《中华人民共和国社会保险法》第八十七条的规定处理： （一）工伤保险协议医疗机构、工伤康复协议机构、工伤保险辅助器具配置协议机构、工伤预防项目实施单位等通过提供虚假证明材料及相关报销票据等手段,骗取工伤保险基金支出的； （二）培训机构通过提供虚假培训材料等手段，骗取失业保险培训补贴的； （三）其他以欺诈、伪造证明材料等手段骗取社会保险基金支出的行为。"},{"i":32,"n":"第三十二条","txt":"用人单位、个人有下列行为之一，以欺诈、伪造证明材料或者其他手段骗取社会保险待遇的，按照《中华人民共和国社会保险法》第八十八条的规定处理： （一）通过虚构个人信息、劳动关系，使用伪造、变造或者盗用他人可用于证明身份的证件，提供虚假证明材料等手段虚构社会保险参保条件、违规补缴，骗取社会保险待遇的； （二）通过虚假待遇资格认证等方式，骗取社会保险待遇的； （三）通过伪造或者变造个人档案、劳动能力鉴定结论等手段违规办理退休，违规增加视同缴费年限，骗取基本养老保险待遇的； （四）通过谎报工伤事故、伪造或者变造证明材料等进行工伤认定或者劳动能力鉴定，或者提供虚假工伤认定结论、劳动能力鉴定结论，骗取工伤保险待遇的； （五）通过伪造或者变造就医资料、票据等，或者冒用工伤人员身份就医、配置辅助器具，骗取工伤保险待遇的； （六）其他以欺诈、伪造证明材料等手段骗取社会保险待遇的。"},{"i":33,"n":"第三十三条","txt":"人力资源社会保障行政部门工作人员弄虚作假将不符合条件的人员认定为工伤职工或者批准提前退休，给社会保险基金造成损失的，依法给予处分。 从事劳动能力鉴定的组织或者个人提供虚假鉴定意见、诊断证明，给社会保险基金造成损失的，按照《工伤保险条例》第六十一条的规定处理。"},{"i":34,"n":"第三十四条","txt":"被监督单位有下列行为之一的，由人力资源社会保障行政部门责令改正；拒不改正的，可以通报批评，给予警告；依法对直接负责的主管人员和其他责任人员给予处分： （一）拒绝、阻挠社会保险基金行政监督工作人员进行监督的； （二）拒绝、拖延提供与监督事项有关资料的； （三）隐匿、伪造、变造或者故意销毁会计凭证、会计账簿、财务会计报告以及其他与社会保险基金收支、管理有关资料的。"},{"i":35,"n":"第三十五条","txt":"报复陷害社会保险基金行政监督工作人员的，依法给予处分。"},{"i":36,"n":"第三十六条","txt":"人力资源社会保障行政部门、社会保险经办机构违反本办法第二十八条的规定，对发现的社会保险基金要情隐瞒不报、谎报或者拖延不报的，按照有关规定追究相关人员责任。"},{"i":37,"n":"第三十七条","txt":"人力资源社会保障行政部门负责人、社会保险基金行政监督工作人员违反本办法规定或者有其他滥用职权、徇私舞弊、玩忽职守行为的，依法给予处分。"},{"i":38,"n":"第三十八条","txt":"人力资源社会保障行政部门、社会保险经办机构、会计师事务所等被聘请的第三方机构及其工作人员泄露、篡改、毁损、非法向他人提供个人信息、商业秘密的，对直接负责的主管人员和其他直接责任人员依法给予处分；违反其他法律、行政法规的，由有关主管部门依法处理。"},{"i":39,"n":"第三十九条","txt":"违反本办法规定，构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":40,"n":"第四十条","txt":"本办法所称的社会保险服务机构，包括工伤保险协议医疗机构、工伤康复协议机构、工伤保险辅助器具配置协议机构、工伤预防项目实施单位、享受失业保险培训补贴的培训机构、承办社会保险经办业务的商业保险机构等。 对乡镇（街道）事务所（中心、站）等承担社会保险经办服务工作的机构的监督，参照对社会保险经办机构监督相关规定执行。"},{"i":41,"n":"第四十一条","txt":"基本养老保险基金委托投资运营监管另行规定。"},{"i":42,"n":"第四十二条","txt":"本办法自2022年3月18日起施行。原劳动和社会保障部《社会保险基金行政监督办法》（劳动和社会保障部令第12号）同时废止。"}],"shehuibaoxianshenjizanxingguiding":[{"i":1,"n":"第一条","txt":"为加强社会保险基金管理，严肃财经法纪，促进社会保险事业的健康发展，根据《中华人民共和国审计法》、《中华人民共和国劳动法》的有关规定，制定本规定。"},{"i":2,"n":"第二条","txt":"各级国家审计机关应当加强对劳动行政部门及社会保险基金经办机构和劳动就业服务机构管理的社会保险基金、资金的财务收支的审计，对其内部审计工作进行指导和监督。"},{"i":3,"n":"第三条","txt":"各级劳动行政部门负责对本级社会保险基金经办机构和劳动就业服务机构的审计监督。 上级社会保险基金经办机构负责对下级社会保险基金经办机构的审计监督；上级劳动就业服务机构负责对下级劳动就业服务机构的审计监督。 地方各级社会保险基金经办机构、劳动就业服务机构和系统统筹部门的社会保险基金经办机构，负责本地区、本部门管理范围内用人单位的社会保险审计事项。"},{"i":4,"n":"第四条","txt":"社会保险的内部审计监督，在本单位主要负责人的直接领导下实施。"},{"i":5,"n":"第五条","txt":"劳动行政部门及社会保险基金经办机构、劳动就业服务机构依法进行审计监督。其依法作出的审计决定，有关部门和单位必须执行。"},{"i":6,"n":"第六条","txt":"社会保险审计人员应当具备与所从事的审计工作相适应的专业知识和业务能力。"},{"i":7,"n":"第七条","txt":"社会保险审计人员办理审计事项，应依法实行回避制度。"},{"i":8,"n":"第八条","txt":"社会保险审计人员办理审计事项，应实事求是、客观公正、廉洁奉公、保守秘密。"},{"i":9,"n":"第九条","txt":"社会保险审计人员依法行使职权受法律保护。"},{"i":10,"n":"第十条","txt":"本规定第三条第一、二款规定的审计监督包括下列事项： （一）社会保险基金和管理服务费预算的执行情况和决算； （二）各项社会保险基金的核定、收缴、支付、上解、下拨、储存、调剂及管理服务费和其他专项经费的提取、使用、上解、下拨； （三）社会保险基金运营的经济效益； （四）购置固定资产的资金来源、使用、保管及工程预决算的情况； （五）国家财经法纪的执行情况和其他有关经济活动及会计行为的合法性； （六）上级社会保险基金经办机构和劳动就业服务机构交办的以及国家审计机关委托的审计事项。"},{"i":11,"n":"第十一条","txt":"社会保险基金经办机构和劳动就业服务机构对用人单位的下列事项进行审计监督： （一）在职职工和社会保险待遇享受人员的人数及花名册； （二）工资总额填报的真实性和合法性； （三）上缴各项社会保险基金的情况； （四）支付社会保险金和享受社会保险待遇人员的落实情况。"},{"i":12,"n":"第十二条","txt":"上级社会保险基金经办机构和劳动就业服务机构可以将其审计范围内的审计事项授权下级社会保险基金经办机构和劳动就业服务机构进行审计，也可对下级社会保险基金经办机构和劳动就业服务机构审计范围内的重大审计事项直接审计。"},{"i":13,"n":"第十三条","txt":"劳动行政部门及社会保险基金经办机构和劳动就业服务机构具有以下审计权限： （一）要求被审计单位报送有关的预算、决算、报告、报表和财务会计等资料； （二）检查被审计单位有关的会计凭证、帐簿、报表、资料和资产，参加被审计单位的有关会议； （三）向有关部门、单位和个人进行调查； （四）对被审计单位违反法律、法规的行为，有权制止，并由社会保险基金经办机构和劳动就业服务机构建议劳动行政部门给予行政处罚；构成犯罪的，提请司法机关依法追究刑事责任。"},{"i":14,"n":"第十四条","txt":"社会保险审计应按以下程序进行： （一）向被审计单位发出《审计通知书》； （二）依据本规定第十三条规定的权限进行调查取证，调查时应当出示审计证件和审计通知书副本； （三）提出审计报告，并征求被审计单位的意见。被审计单位应当在接到审计报告十日内提出书面意见。未提出书面意见的，视同没有异议； （四）出具审计意见书和作出审计决定； （五）审计意见书和审计决定经批准后发送被审计单位； （六）被审计单位对审计决定如有异议，可以申请审计复议。用人单位对审计复议决定不服的，可以向人民法院提起诉讼。 复议期间，不影响审计决定的执行。"},{"i":15,"n":"第十五条","txt":"社会保险基金经办机构和劳动就业服务机构进行的工作调查，不适用第十四条规定的审计程序。"},{"i":16,"n":"第十六条","txt":"社会保险审计可以采取就地审计、报送审计或与国家审计机关联合审计等方式进行。"},{"i":17,"n":"第十七条","txt":"需要委托审计师事务所或会计师事务所审计时，应当在事前就委托审计事项签订委托业务协议书，并就委托审计事项通知被审计单位。审计终结，由受委托方向委托方提交审计报告，委托方视情况出具审计意见书或作出审计决定，并发送被审计单位。"},{"i":18,"n":"第十八条","txt":"社会保险审计的情况应当向同级国家审计机关、劳动行政部门及上级社会保险基金经办机构和劳动就业服务机构报告。 各级国家审计机关对社会保险基金和管理服务费的审计情况应当向同级劳动行政部门及上级社会保险基金经办机构和劳动就业服务机构通报。"},{"i":19,"n":"第十九条","txt":"已经国家审计机关审计的，在半年内劳动行政部门或社会保险基金经办机构、劳动就业服务机构不得重复审计；已经劳动行政部门或社会保险基金经办机构、劳动就业服务机构审计的，除国家审计机关外，在半年内其他部门不得重复审计。"},{"i":20,"n":"第二十条","txt":"劳动行政部门及社会保险基金经办机构和劳动就业服务机构应按照有关规定建立审计档案。"},{"i":21,"n":"第二十一条","txt":"拒绝、阻挠社会保险审计人员依法执行公务或打击报复社会保险审计人员的，由劳动行政部门或者有关部门给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":22,"n":"第二十二条","txt":"社会保险审计人员监用职权、玩忽职守、徇私舞弊，构成犯罪的，依法追究刑事责任；不构成犯罪的，给予行政处分。"},{"i":23,"n":"第二十三条","txt":"省、自治区、直辖市劳动行政部门可以根据本规定，结合本地区的实际情况制定实施办法，并报劳动部和国家审计署备案。"},{"i":24,"n":"第二十四条","txt":"本规定由劳动部、国家审计署负责解释。"},{"i":25,"n":"第二十五条","txt":"本规定自一九九五年十月一日起施行。"}],"shehuibaoxianjihebanfa":[{"i":1,"n":"第一条","txt":"为了规范社会保险稽核工作，确保社会保险费应收尽收，维护参保人员的合法权益，根据《社会保险费征缴暂行条例》和国家有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称稽核是指社会保险经办机构依法对社会保险费缴纳情况和社会保险待遇领取情况进行的核查。"},{"i":3,"n":"第三条","txt":"县级以上社会保险经办机构负责社会保险稽核工作。 县级以上社会保险经办机构的稽核部门具体承办社会保险稽核工作。"},{"i":4,"n":"第四条","txt":"社会保险稽核人员应当具备以下条件： （一）坚持原则，作风正派，公正廉洁； （二）具备中专以上学历和财会、审计专业知识； （三）熟悉社会保险业务及相关法律、法规，具备开展稽核工作的相应资格。"},{"i":5,"n":"第五条","txt":"社会保险经办机构及社会保险稽核人员开展稽核工作，行使下列职权： （一）要求被稽核单位提供用人情况、工资收入情况、财务报表、统计报表、缴费数据和相关账册、会计凭证等与缴纳社会保险费有关的情况和资料； （二）可以记录、录音、录像、照相和复制与缴纳社会保险费有关的资料，对被稽核对象的参保情况和缴纳社会保险费等方面的情况进行调查、询问； （三）要求被稽核对象提供与稽核事项有关的资料。"},{"i":6,"n":"第六条","txt":"社会保险稽核人员承担下列义务： （一）办理稽核事务应当实事求是，客观公正，不得利用工作之便谋取私利； （二）保守被稽核单位的商业秘密以及个人隐私； （三）为举报人保密。"},{"i":7,"n":"第七条","txt":"社会保险稽核人员有下列情形之一的，应当自行回避： （一）与被稽核单位负责人或者被稽核个人之间有亲属关系的； （二）与被稽核单位或者稽核事项有经济利益关系的； （三）与被稽核单位或者稽核事项有其他利害关系，可能影响稽核公正实施的。 被稽核对象有权以口头形式或者书面形式申请有前款规定情形之一的人员回避。 稽核人员的回避，由其所在的社会保险经办机构的负责人决定。对稽核人员的回避做出决定前，稽核人员不得停止实施稽核。"},{"i":8,"n":"第八条","txt":"社会保险稽核采取日常稽核、重点稽核和举报稽核等方式进行。 社会保险经办机构应当制定日常稽核工作计划，根据工作计划定期实施日常稽核。 社会保险经办机构对特定的对象和内容应当进行重点稽核。 对于不按规定缴纳社会保险费的行为，任何单位和个人有权举报，社会保险经办机构应当及时受理举报并进行稽核。"},{"i":9,"n":"第九条","txt":"社会保险缴费情况稽核内容包括： （一）缴费单位和缴费个人申报的社会保险缴费人数、缴费基数是否符合国家规定； （二）缴费单位和缴费个人是否按时足额缴纳社会保险费； （三）欠缴社会保险费的单位和个人的补缴情况； （四）国家规定的或者劳动保障行政部门交办的其他稽核事项。"},{"i":10,"n":"第十条","txt":"社会保险经办机构对社会保险费缴纳情况按照下列程序实施稽核： （一）提前３日将进行稽核的有关内容、要求、方法和需要准备的资料等事项通知被稽核对象，特殊情况下的稽核也可以不事先通知； （二）应有两名以上稽核人员共同进行，出示执行公务的证件，并向被稽核对象说明身份； （三）对稽核情况应做笔录，笔录应当由稽核人员和被稽核单位法定代表人（或法定代表人委托的代理人）签名或盖章，被稽核单位法定代表人拒不签名或盖章的，应注明拒签原因； （四）对于经稽核未发现违反法规行为的被稽核对象，社会保险经办机构应当在稽核结束后５个工作日内书面告知其稽核结果； （五）发现被稽核对象在缴纳社会保险费或按规定参加社会保险等方面，存在违反法规行为，要据实写出稽核意见书，并在稽核结束后10个工作日内送达被稽核对象。被稽核对象应在限定时间内予以改正。"},{"i":11,"n":"第十一条","txt":"被稽核对象少报、瞒报缴费基数和缴费人数，社会保险经办机构应当责令其改正；拒不改正的，社会保险经办机构应当报请劳动保障行政部门依法处罚。 被稽核对象拒绝稽核或伪造、变造、故意毁灭有关账册、材料迟延缴纳社会保险费的，社会保险经办机构应当报请劳动保障行政部门依法处罚。 社会保险经办机构应定期向劳动保障行政部门报告社会保险稽核工作情况。劳动保障行政部门应将社会保险经办机构提请处理事项的结果及时通报社会保险经办机构。"},{"i":12,"n":"第十二条","txt":"社会保险经办机构应当对参保个人领取社会保险待遇情况进行核查，发现社会保险待遇领取人丧失待遇领取资格后本人或他人继续领取待遇或以其他形式骗取社会保险待遇的，社会保险经办机构应当立即停止待遇的支付并责令退还；拒不退还的，由劳动保障行政部门依法处理，并可对其处以500元以上1000元以下罚款；构成犯罪的，由司法机关依法追究刑事责任。"},{"i":13,"n":"第十三条","txt":"社会保险经办机构工作人员在稽核工作中滥用职权、徇私舞弊、玩忽职守的，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":14,"n":"第十四条","txt":"本办法自2003年４月１日起施行。"}],"shehuibaoxianfeizhengjiaojiandujianchabanfa":[{"i":1,"n":"第一条","txt":"为加强社会保险费征缴监督检查工作，规范社会保险费征缴监督检查行为，根据《社会保险费征缴暂行条例》（以下简称条例）和有关法律、法规规定，制定本办法。"},{"i":2,"n":"第二条","txt":"对中华人民共和国境内的企业、事业单位、国家机关、社会团体、民办非企业单位、城镇个体工商户（以下简称缴费单位）实施社会保险费征缴监督检查适用本办法。 前款所称企业是指国有企业、城镇集体企业、外商投资企业、城镇私营企业和其他城镇企业。"},{"i":3,"n":"第三条","txt":"劳动保障行政部门负责社会保险费征缴的监督检查工作，对违反条例和本办法规定的缴费单位及其责任人员，依法作出行政处罚决定，并可以按照条例规定委托社会保险经办机构进行与社会保险费征缴有关的检查、调查工作。 劳动保障行政部门的劳动保障监察机构具体负责社会保险费征缴监督检查和行政处罚，包括对缴费单位进行检查、调查取证、拟定行政处罚决定书、送达行政处罚决定书、拟定向人民法院申请强制执行行政处罚决定的申请书、受理群众举报等工作。 社会保险经办机构受劳动保障行政部门的委托，可以对缴费单位履行社会保险登记、缴费申报、缴费义务的情况进行调查和检查，发现缴费单位有瞒报、漏报和拖欠社会保险费等行为时，应当责令其改正。"},{"i":4,"n":"第四条","txt":"劳动保障监察机构与社会保险经办机构应当建立按月相互通报制度。社会保险经办机构应当及时将需要给予行政处罚的缴费单位情况向劳动保障监察机构通报，劳动保障监察机构应当及时将查处违反规定的情况通报给社会保险经办机构。"},{"i":5,"n":"第五条","txt":"县级以上地方各级劳动保障行政部门对缴费单位监督检查的管辖范围，由省、自治区、直辖市劳动保障行政部门依照社会保险登记、缴费申报和缴费工作管理权限，制定具体规定。"},{"i":6,"n":"第六条","txt":"社会保险费征缴监督检查应当包括以下内容： （一）缴费单位向当地社会保险经办机构办理社会保险登记、变更登记或注销登记的情况； （二）缴费单位向社会保险经办机构申报缴费的情况； （三）缴费单位缴纳社会保险费的情况； （四）缴费单位代扣代缴个人缴费的情况； （五）缴费单位向职工公布本单位缴费的情况； （六）法律、法规规定的其他内容。"},{"i":7,"n":"第七条","txt":"劳动保障行政部门应当向社会公布举报电话，设立举报信箱，指定专人负责接待群众投诉；对符合受理条件的举报，应当于７日内立案受理，并进行调查处理，且一般应当于30日内处理结案。"},{"i":8,"n":"第八条","txt":"劳动保障行政部门应当建立劳动保障年检制度，进行劳动保障年度检查，掌握缴费单位参加社会保险的情况；对违反条例规定的，应当责令其限期改正，并依照条例规定给予行政处罚。"},{"i":9,"n":"第九条","txt":"劳动保障监察人员在执行监察公务和社会保险经办机构工作人员对缴费单位进行调查、检查时，至少应当由两人共同进行，并应当主动出示执法证件。"},{"i":10,"n":"第十条","txt":"劳动保障监察人员执行监察公务和社会保险经办机构工作人员进行调查、检查时，行使下列职权： （一）可以到缴费单位了解遵守社会保险法律、法规的情况； （二）可以要求缴费单位提供与缴纳社会保险费有关的用人情况、工资表、财务报表等资料，询问有关人员，对缴费单位不能立即提供有关参加社会保险情况和资料的，可以下达劳动保障行政部门监督检查询问书； （三）可以记录、录音、录像、照相和复制有关资料。"},{"i":11,"n":"第十一条","txt":"劳动保障监察人员执行监察公务和社会保险经办机构工作人员进行调查、检查时，承担下列义务： （一）依法履行职责，秉公执法，不得利用职务之便谋取私利； （二）保守在监督检查工作中知悉的缴费单位的商业秘密； （三）为举报人员保密。"},{"i":12,"n":"第十二条","txt":"缴费单位有下列行为之一，情节严重的，对直接负责的主管人员和其他直接责任人员处以1000元以上5000元以下的罚款；情节特别严重的，对直接负责的主管人员和其他直接责任人员处以5000元以上10000元以下的罚款： （一）未按规定办理社会保险登记的； （二）在社会保险登记事项发生变更或者缴费单位依法终止后，未按规定到社会保险经办机构办理社会保险变更登记或者社会保险注销登记的； （三）未按规定申报应当缴纳社会保险费数额的。"},{"i":13,"n":"第十三条","txt":"对缴费单位有下列行为之一的，依照条例第十三条的规定，从欠缴之日起，按日加收千分之二的滞纳金，并对直接负责的主管人员和其他直接责任人员处以5000元以上20000元以下罚款： （一）因伪造、变造、故意毁灭有关帐册、材料造成社会保险费迟延缴纳的； （二）因不设帐册造成社会保险费迟延缴纳的； （三）因其他违法行为造成社会保险费迟延缴纳的。"},{"i":14,"n":"第十四条","txt":"对缴费单位有下列行为之一的，应当给予警告，并可以处以5000元以下的罚款： （一）伪造、变造社会保险登记证的； （二）未按规定从缴费个人工资中代扣代缴社会保险费的； （三）未按规定向职工公布本单位社会保险费缴纳情况的。 对上述违法行为的行政处罚，法律、法规另有规定的，从其规定。"},{"i":15,"n":"第十五条","txt":"对缴费单位有下列行为之一的，应当给予警告，并可以处以10000元以下的罚款： （一）阻挠劳动保障监察人员依法行使监察职权，拒绝检查的； （二）隐瞒事实真相，谎报、瞒报，出具伪证，或者隐匿、毁灭证据的； （三）拒绝提供与缴纳社会保险费有关的用人情况、工资表、财务报表等资料的； （四）拒绝执行劳动保障行政部门下达的监督检查询问书的； （五）拒绝执行劳动保障行政部门下达的限期改正指令书的； （六）打击报复举报人员的； （七）法律、法规及规章规定的其他情况。 对上述违法行为的行政处罚，法律、法规另有规定的，从其规定。"},{"i":16,"n":"第十六条","txt":"本办法第十二条、第十三条的罚款均由缴费单位直接负责的主管人员和其他直接责任人员个人支付，不得从单位报销。"},{"i":17,"n":"第十七条","txt":"对缴费单位或者缴费单位直接负责的主管人员和其他直接责任人员的罚款，必须全部上缴国库。"},{"i":18,"n":"第十八条","txt":"缴费单位或者缴费单位直接负责的主管人员和其他直接责任人员，对劳动保障行政部门作出的行政处罚决定不服的，可以于15日内，向上一级劳动保障行政部门或者同级人民政府申请行政复议。对行政复议决定不服的，可以自收到行政复议决定书之日起15日内向人民法院提起行政诉讼。 行政复议和行政诉讼期间，不影响该行政处罚决定的执行。"},{"i":19,"n":"第十九条","txt":"缴费单位或者缴费单位直接负责的主管人员和其他直接责任人员，在15日内拒不执行劳动保障行政部门对其作出的行政处罚决定，又不向上一级劳动保障行政部门或者同级人民政府申请行政复议，或者对行政复议决定不服，又不向人民法院提起行政诉讼的，可以申请人民法院强制执行。"},{"i":20,"n":"第二十条","txt":"劳动保障行政部门和社会保险经办机构的工作人员滥用职权、徇私舞弊、玩忽职守，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，给予责任人员行政处分。"},{"i":21,"n":"第二十一条","txt":"本办法自发布之日起施行。"}],"wangluozhaopinfuwuguanliguiding":[{"i":1,"n":"第一条","txt":"为了规范网络招聘服务，促进网络招聘服务业态健康有序发展，促进就业和人力资源流动配置，根据《中华人民共和国就业促进法》《中华人民共和国网络安全法》《中华人民共和国电子商务法》《人力资源市场暂行条例》《互联网信息服务管理办法》等法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称网络招聘服务，是指人力资源服务机构在中华人民共和国境内通过互联网等信息网络，以网络招聘服务平台、平台内经营、自建网站或者其他网络服务方式，为劳动者求职和用人单位招用人员提供的求职、招聘服务。 人力资源服务机构包括公共人力资源服务机构和经营性人力资源服务机构。"},{"i":3,"n":"第三条","txt":"国务院人力资源社会保障行政部门负责全国网络招聘服务的综合管理。 县级以上地方人民政府人力资源社会保障行政部门负责本行政区域网络招聘服务的管理工作。 县级以上人民政府有关部门在各自职责范围内依法对网络招聘服务实施管理。"},{"i":4,"n":"第四条","txt":"从事网络招聘服务，应当遵循合法、公平、诚实信用的原则，履行网络安全和信息保护等义务，承担服务质量责任，接受政府和社会的监督。"},{"i":5,"n":"第五条","txt":"对从事网络招聘服务的经营性人力资源服务机构提供公益性人力资源服务的，按照规定给予补贴或者通过政府购买服务等方式给予支持。"},{"i":6,"n":"第六条","txt":"人力资源社会保障行政部门加强网络招聘服务标准化建设，支持企业、研究机构、高等学校、行业协会参与网络招聘服务国家标准、行业标准的制定。"},{"i":7,"n":"第七条","txt":"人力资源服务行业协会应当依照法律、行政法规、规章及其章程的规定，加强网络招聘服务行业自律，推进行业诚信建设，促进行业公平竞争。"},{"i":8,"n":"第八条","txt":"从事网络招聘服务，应当符合就业促进、人力资源市场管理、电信和互联网管理等法律、行政法规规定的条件。"},{"i":9,"n":"第九条","txt":"经营性人力资源服务机构从事网络招聘服务，应当依法取得人力资源服务许可证。涉及经营电信业务的，还应当依法取得电信业务经营许可证。"},{"i":10,"n":"第十条","txt":"对从事网络招聘服务的经营性人力资源服务机构，人力资源社会保障行政部门应当在其服务范围中注明“开展网络招聘服务”。"},{"i":11,"n":"第十一条","txt":"网络招聘服务包括下列业务： （一）为劳动者介绍用人单位； （二）为用人单位推荐劳动者； （三）举办网络招聘会； （四）开展高级人才寻访服务； （五）其他网络求职、招聘服务。"},{"i":12,"n":"第十二条","txt":"从事网络招聘服务的经营性人力资源服务机构变更名称、住所、法定代表人或者终止网络招聘服务的，应当自市场主体变更登记或者注销登记办理完毕之日起15日内，书面报告人力资源社会保障行政部门，办理人力资源服务许可变更、注销。"},{"i":13,"n":"第十三条","txt":"从事网络招聘服务的经营性人力资源服务机构应当依法在其网站、移动互联网应用程序等首页显著位置，持续公示营业执照、人力资源服务许可证等信息，或者上述信息的链接标识。 前款规定的信息发生变更的，从事网络招聘服务的经营性人力资源服务机构应当及时更新公示信息。 从事网络招聘服务的经营性人力资源服务机构自行终止从事网络招聘服务的，应当提前30日在首页显著位置持续公示有关信息。"},{"i":14,"n":"第十四条","txt":"人力资源社会保障行政部门应当及时向社会公布从事网络招聘服务的经营性人力资源服务机构名单及其变更、注销等情况。"},{"i":15,"n":"第十五条","txt":"用人单位向人力资源服务机构提供的单位基本情况、招聘人数、招聘条件、用工类型、工作内容、工作条件、工作地点、基本劳动报酬等网络招聘信息，应当合法、真实，不得含有民族、种族、性别、宗教信仰等方面的歧视性内容。 前款网络招聘信息不得违反国家规定在户籍、地域、身份等方面设置限制人力资源流动的条件。"},{"i":16,"n":"第十六条","txt":"劳动者通过人力资源服务机构进行网络求职，应当如实提供本人基本信息以及与应聘岗位相关的知识、技能、工作经历等情况。"},{"i":17,"n":"第十七条","txt":"从事网络招聘服务的人力资源服务机构应当建立完备的网络招聘信息管理制度，依法对用人单位所提供材料的真实性、合法性进行审查。审查内容应当包括以下方面： （一）用人单位招聘简章； （二）用人单位营业执照或者有关部门批准设立的文件； （三）招聘信息发布经办人员的身份证明、用人单位的委托证明。 用人单位拟招聘外国人的，应当符合《外国人在中国就业管理规定》的有关要求。"},{"i":18,"n":"第十八条","txt":"人力资源服务机构对其发布的网络求职招聘信息、用人单位对所提供的网络招聘信息应当及时更新。"},{"i":19,"n":"第十九条","txt":"从事网络招聘服务的人力资源服务机构，不得以欺诈、暴力、胁迫或者其他不正当手段，牟取不正当利益。 从事网络招聘服务的经营性人力资源服务机构，不得向劳动者收取押金，应当明示其服务项目、收费标准等事项。"},{"i":20,"n":"第二十条","txt":"从事网络招聘服务的人力资源服务机构应当按照国家网络安全法律、行政法规和网络安全等级保护制度要求，加强网络安全管理，履行网络安全保护义务，采取技术措施或者其他必要措施，确保招聘服务网络、信息系统和用户信息安全。"},{"i":21,"n":"第二十一条","txt":"人力资源服务机构从事网络招聘服务时收集、使用其用户个人信息，应当遵守法律、行政法规有关个人信息保护的规定。 人力资源服务机构应当建立健全网络招聘服务用户信息保护制度，不得泄露、篡改、毁损或者非法出售、非法向他人提供其收集的个人公民身份号码、年龄、性别、住址、联系方式和用人单位经营状况等信息。 人力资源服务机构应当对网络招聘服务用户信息保护情况每年至少进行一次自查，记录自查情况，及时消除自查中发现的安全隐患。"},{"i":22,"n":"第二十二条","txt":"从事网络招聘服务的人力资源服务机构因业务需要，确需向境外提供在中华人民共和国境内运营中收集和产生的个人信息和重要数据的，应当遵守国家有关法律、行政法规规定。"},{"i":23,"n":"第二十三条","txt":"从事网络招聘服务的人力资源服务机构应当建立网络招聘服务有关投诉、举报制度，健全便捷有效的投诉、举报机制，公开有效的联系方式，及时受理并处理有关投诉、举报。"},{"i":24,"n":"第二十四条","txt":"以网络招聘服务平台方式从事网络招聘服务的人力资源服务机构应当遵循公开、公平、公正的原则，制定平台服务协议和服务规则，明确进入和退出平台、服务质量保障、求职者权益保护、个人信息保护等方面的权利和义务。 鼓励从事网络招聘服务的人力资源服务机构运用大数据、区块链等技术措施，保证其网络招聘服务平台的网络安全、稳定运行，防范网络违法犯罪活动，保障网络招聘服务安全，促进人力资源合理流动和优化配置。"},{"i":25,"n":"第二十五条","txt":"以网络招聘服务平台方式从事网络招聘服务的人力资源服务机构应当要求申请进入平台的人力资源服务机构提交其营业执照、地址、联系方式、人力资源服务许可证等真实信息，进行核验、登记，建立登记档案，并定期核验更新。"},{"i":26,"n":"第二十六条","txt":"以网络招聘服务平台方式从事网络招聘服务的人力资源服务机构应当记录、保存平台上发布的招聘信息、服务信息，并确保信息的完整性、保密性、可用性。招聘信息、服务信息保存时间自服务完成之日起不少于3年。"},{"i":27,"n":"第二十七条","txt":"人力资源社会保障行政部门采取随机抽取检查对象、随机选派执法人员的方式，对经营性人力资源服务机构从事网络招聘服务情况进行监督检查，并及时向社会公布监督检查的情况。 人力资源社会保障行政部门运用大数据等技术，推行远程监管、移动监管、预警防控等非现场监管，提升网络招聘服务监管精准化、智能化水平。"},{"i":28,"n":"第二十八条","txt":"人力资源社会保障行政部门应当加强网络招聘服务诚信体系建设，健全信用分级分类管理制度，完善守信激励和失信惩戒机制。对性质恶劣、情节严重、社会危害较大的网络招聘服务违法失信行为，按照国家有关规定实施联合惩戒。"},{"i":29,"n":"第二十九条","txt":"从事网络招聘服务的经营性人力资源服务机构应当在规定期限内，向人力资源社会保障行政部门提交经营情况年度报告。人力资源社会保障行政部门可以依法公示或者引导从事网络招聘服务的经营性人力资源服务机构依法通过互联网等方式公示年度报告的有关内容。"},{"i":30,"n":"第三十条","txt":"人力资源社会保障行政部门应当加强与其他部门的信息共享，提高对网络招聘服务的监管时效和能力。"},{"i":31,"n":"第三十一条","txt":"人力资源社会保障行政部门应当畅通对从事网络招聘服务的人力资源服务机构的举报投诉渠道，依法及时处理有关举报投诉。"},{"i":32,"n":"第三十二条","txt":"违反本规定第九条规定，未取得人力资源服务许可证擅自从事网络招聘服务的，由人力资源社会保障行政部门依照《人力资源市场暂行条例》第四十二条第一款的规定予以处罚。 违反本规定第十二条规定，办理变更或者注销登记未书面报告的，由人力资源社会保障行政部门依照《人力资源市场暂行条例》第四十二条第二款的规定予以处罚。"},{"i":33,"n":"第三十三条","txt":"未按照本规定第十三条规定公示人力资源服务许可证等信息，未按照本规定第十九条第二款规定明示有关事项，未按照本规定第二十九条规定提交经营情况年度报告的，由人力资源社会保障行政部门依照《人力资源市场暂行条例》第四十四条的规定予以处罚。"},{"i":34,"n":"第三十四条","txt":"违反本规定第十五条第一款规定，发布的招聘信息不真实、不合法的，由人力资源社会保障行政部门依照《人力资源市场暂行条例》第四十三条的规定予以处罚。 违反本规定第十五条第二款规定，违法设置限制人力资源流动的条件，违反本规定第十七条规定，未依法履行信息审查义务的，由人力资源社会保障行政部门责令改正；拒不改正，无违法所得的，处1万元以下的罚款；有违法所得的，没收违法所得，并处1万元以上3万元以下的罚款。"},{"i":35,"n":"第三十五条","txt":"违反本规定第十九条第一款规定，牟取不正当利益的，由人力资源社会保障行政部门依照《人力资源市场暂行条例》第四十三条的规定予以处罚。 违反本规定第十九条第二款规定，向劳动者收取押金的，由人力资源社会保障行政部门依照《中华人民共和国就业促进法》第六十六条的规定予以处罚。"},{"i":36,"n":"第三十六条","txt":"违反本规定第二十一条、第二十二条规定，未依法进行信息收集、使用、存储、发布的，由有关主管部门依照《中华人民共和国网络安全法》等法律、行政法规的规定予以处罚。"},{"i":37,"n":"第三十七条","txt":"违反本规定第二十五条规定，不履行核验、登记义务，违反本规定第二十六条规定，不履行招聘信息、服务信息保存义务的，由人力资源社会保障行政部门依照《中华人民共和国电子商务法》第八十条的规定予以处罚。法律、行政法规对违法行为的处罚另有规定的，依照其规定执行。"},{"i":38,"n":"第三十八条","txt":"公共人力资源服务机构违反本规定从事网络招聘服务的，由上级主管机关责令改正；拒不改正的，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":39,"n":"第三十九条","txt":"人力资源社会保障行政部门及其工作人员玩忽职守、滥用职权、徇私舞弊的，对直接负责的领导人员和其他直接责任人员依法给予处分。"},{"i":40,"n":"第四十条","txt":"违反本规定，给他人造成损害的，依法承担民事责任。违反其他法律、行政法规的，由有关主管部门依法给予处罚。 违反本规定，构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":41,"n":"第四十一条","txt":"本规定自2021年3月1日起施行。"}],"zhiyejinengjiandingguiding":[{"i":1,"n":"第一条","txt":"为适应社会主义市场经济发展的需要，进一步完善职业技能鉴定制度，实现职业技能鉴定的社会化管理，促进职业技能开发，提高劳动者素质，根据《工人考核条例》，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称职业技能鉴定是指对劳动者进行技术等级的考核和技师、高级技师（以下统称技师）资格的考评。"},{"i":3,"n":"第三条","txt":"职业技能鉴定实行政府指导下的社会化管理体制。 （一）劳动部综合管理全国职业技能鉴定工作，制定规划、政策和标准；审查批准有关行业的职业技能鉴定机构。 （二）各省、自治区、直辖市劳动行政部门综合管理本地区职业技能鉴定工作，审查批准各类职业技能鉴定指导中心和站（所），制定以下有关规定和办法： 1.参加技能鉴定人员的申报条件和鉴定程序； 2.专业技术知识、操作技能考核办法； 3.考务、考评人员工作守则和考评小组成员组成原则及其管理办法； 4.职业技能鉴定站（所）考场规则； 5.《技术等级证书》的印鉴和核发办法。 （三）职业技能鉴定指导中心负责组织、协调、指导职业技能鉴定工作。 （四）职业技能鉴定站（所），具体实施对劳动者职业技能的鉴定。"},{"i":4,"n":"第四条","txt":"本规定适用于各级劳动行政部门和各级职业技能鉴定指导中心、职业技能鉴定站（所）。"},{"i":5,"n":"第五条","txt":"劳动部所属职业技能鉴定指导中心主要职责是：参与制定国家职业技能标准和组建国家职业技能鉴定题库；开展职业分类、标准、技能鉴定理论研究及咨询服务；推动全国职业技能竞赛活动。"},{"i":6,"n":"第六条","txt":"各省、自治区、直辖市劳动行政部门所属职业技能鉴定指导中心主要职责是：组织本地区职业技能鉴定工作和具体实施考评员的资格培训；开展职业技能鉴定有关问题的研究和咨询服务；推动本地区职业技能竞赛活动。"},{"i":7,"n":"第七条","txt":"经劳动部批准，有关行业可建立行业的职业技能鉴定指导中心，主要职责是：参与制定国家职业技能标准以外非社会通用的本行业特有工种的职业技能标准；组织本行业特有工种的职业技能鉴定工作和考评员的资格培训；开展职业技能鉴定及有关问题的研究和咨询服务；推动本行业的职业技能竞赛活动。"},{"i":8,"n":"第八条","txt":"职业技能鉴定指导中心是事业性机构，在管理上实行中心主任负责制。"},{"i":9,"n":"第九条","txt":"职业技能鉴定站（所）是具体承担对待业人员、从业人员、军地两用人才、各级各类职业技术院校和其他职业培训机构的毕（结）业生，进行职业技能鉴定的事业性机构。在管理上实行站（所）长负责制。"},{"i":10,"n":"第十条","txt":"建立职业技能鉴定站（所）。 （一）建立职业技能鉴定站（所）的条件是： 1.具有与所鉴定工种（专业）及其等级或类别相适应的考核场地和设备； 2.具有与所鉴定工种（专业）及其等级或类别操作技能考核相适应的、符合国家标准的检测仪器； 3.有专（兼）职的组织管理人员和考评员； 4.有完善的管理办法。 （二）申请建立职业技能鉴定站（所）的单位，根据上述条件和省、自治区、直辖市的具体规定，报当地劳动行政部门审查批准并由其发给《职业技能鉴定许可证》，明确鉴定的工种（专业）范围、等级和类别，同时授予统一的职业技能鉴定站（所）标牌。 （三）鉴定技术等级的职业技能鉴定站（所），由省、自治区、直辖市劳动行政部门规定审批权限；鉴定技师资格的职业技能鉴定站（所），由省、自治区、直辖市劳动行政部门审批，并报劳动部备案。 （四）行业特有工种的职业技能鉴定站（所），一般由省、自治区、直辖市劳动行政部门审批；跨地区的行"},{"i":11,"n":"第十一条","txt":"职业技能鉴定站（所），享有独立进行职业技能鉴定的权利，有权拒绝任何组织或个人更改鉴定结果的非正当要求。"},{"i":12,"n":"第十二条","txt":"劳动部组织有关行业或单位的专家、名师，根据现行《工人技术等级标准》和《国家职业技能标准》，统一编制职业技能鉴定试题，建立职业技能鉴定题库。"},{"i":13,"n":"第十三条","txt":"职业技能鉴定站（所），必须遵守劳动行政部门的有关规定、实施办法。职业技能鉴定试题必须从国家规定的试题库提取，不得自行编制试题。"},{"i":14,"n":"第十四条","txt":"职业技能鉴定站（所），应受理一切符合申报条件、规定手续人员的职业技能鉴定，要严格执行考评员对其亲属的职业技能鉴定回避制度。"},{"i":15,"n":"第十五条","txt":"职业技能鉴定的对象： （一）各类职业技术学校和培训机构毕（结）业生，凡属技术等级考核的工种，逐步实行职业技能鉴定； （二）企业、事业单位学徒期满的学徒工，必须进行职业技能鉴定； （三）企业、事业单位的职工以及社会各类人员，根据需要，自愿申请职业技能鉴定。"},{"i":16,"n":"第十六条","txt":"申报职业技能鉴定的单位或个人，可向当地职业技能鉴定站（所）提出申请，由职业技能鉴定站（所）签发准考证，按规定的时间、方式进行考核或考评。"},{"i":17,"n":"第十七条","txt":"国家实行职业技能鉴定证书制度。 （一）对技术等级考核合格的劳动者，发给相应的《技术等级证书》；对技师资格考评合格者，发给相应的《技师合格证书》或《高级技师合格证书》； （二）《技术等级证书》、《技师合格证书》和《高级技师合格证书》是劳动者职业技能水平的凭证，同时，按照劳动部、司法部劳培字〔1992〕1号《对出国工人技术等级、技术职务证书公证的规定》，是我国公民境外就业、劳务输出法律公证的有效证件； （三）上述证书由劳动部统一印制，劳动行政部门按规定核发。"},{"i":18,"n":"第十八条","txt":"单位或个人申报职业技能鉴定，均应按照规定交纳鉴定费用。 （一）职业技能鉴定费用支付项目是：组织职业技能鉴定场地、命题、考务、阅卷、考评、检测及原材料、能源、设备消耗的费用； （二）职业技能鉴定收费标准，由省、自治区、直辖市劳动行政部门按照财政部、劳动部（92）财工字第68号《关于工人考核费用开支的规定》，商当地财政、物价部门做出具体规定。"},{"i":19,"n":"第十九条","txt":"职业技能鉴定考评员必须具有高级工或技师、中级专业技术职务以上的资格；鉴定技师资格的考评员必须具有高级技师、高级专业技术职务的资格。"},{"i":20,"n":"第二十条","txt":"考评员由职业技能鉴定指导中心进行资格考核，由劳动行政部门核准并颁发考评员资格证书和带有本人照片的职业技能鉴定资格胸卡。"},{"i":21,"n":"第二十一条","txt":"鉴定技术等级的考评员资格认定和合格证书的核发权限，由省、自治区、直辖市劳动行政部门具体规定；鉴定技师资格的考评员资格认定和合格证书的颁发，由省、自治区、直辖市劳动行政部门核准。"},{"i":22,"n":"第二十二条","txt":"职业技能鉴定站（所）要在取得考评员资格证书的人员中聘任相应工种、等级或类别的考评员，聘期三年，并应采取不定期轮换、调整考评员的方式组成专业考评小组。"},{"i":23,"n":"第二十三条","txt":"考评员要严格遵守考评员工作守则和执行考场规则。"},{"i":24,"n":"第二十四条","txt":"劳动行政部门对职业技能鉴定机构实行监督、检查。"},{"i":25,"n":"第二十五条","txt":"职业技能鉴定指导中心和职业技能鉴定站（所）的工作人员，在职业技能鉴定工作中弄虚作假、徇私舞弊的，视情节轻重，由其所在单位根据人事管理权限给予行政处分，并停止其在指导中心或鉴定站（所）的工作；考评人员如有上述行为者，吊销考评员资格证书。"},{"i":26,"n":"第二十六条","txt":"违反本规定第十三条、第十四条和第十八条（二），造成不良影响的职业技能鉴定站（所），由劳动行政部门吊销其《职业技能鉴定许可证》；对乱收费的，没收其非法所得费用。没收的费用，专项用于职业技能鉴定事业。"},{"i":27,"n":"第二十七条","txt":"违反本规定第三条（二）中第五项和第十七条（三），伪造、仿制或滥发《技术等级证书》、《技师合格证书》、《高级技师合格证书》的，除宣布其所发证书无效外，还应视情节轻重，由其上级主管部门或监察机关对主要责任者给予行政处分；对其中通过滥发证书获取非法收入的，应没收其非法所得，并处以非法所得五倍以下的罚款；构成犯罪的，应依法追究刑事责任。"},{"i":28,"n":"第二十八条","txt":"本规定由劳动部负责解释。"},{"i":29,"n":"第二十九条","txt":"本规定自颁发之日起施行。"}],"zhiyezigezhengshuzhiduzanxingbanfa":[{"i":1,"n":"第一条","txt":"根据国务院批准的人事部“三定”方案（国办发〔1994〕60号）和《关于加强职称改革工作统一管理的通知》（国办发〔1995〕1号）制定本暂行办法。"},{"i":2,"n":"第二条","txt":"国家按照有利于经济发展、社会公认、国际可比、事关公共利益的原则，在涉及国家、人民生命财产安全的专业技术工作领域，实行专业技术人员职业资格制度。"},{"i":3,"n":"第三条","txt":"专业技术人员职业资格是对从事某一职业所必备的学识、技术和能力的基本要求，职业资格包括从业资格和执业资格。 从业资格是政府规定专业技术人员从事某种专业技术性工作的学识、技术和能力的起点标准； 执业资格是政府对某些责任较大，社会通用性强，关系公共利益的专业技术工作实行的准入控制，是专业技术人员依法独立开业或独立从事某种专业技术工作学识、技术和能力的必备标准。"},{"i":4,"n":"第四条","txt":"符合本办法第二条规定的专业，由国务院有关业务主管部门提出建立职业资格的申请，经人事部审核批准后，共同拟定具体实施方案并颁布实施。"},{"i":5,"n":"第五条","txt":"从业资格通过学历认定或考试取得。具备下列条件之一者，可确认从业资格: (一)具有本专业中专毕业以上学历，见习一年期满，经单位考核合格者； (二)按国家有关规定已担任本专业初级专业技术职务或通过专业技术资格考试取得初级资格，经单位考核合格者； (三)在本专业岗位工作，经过国家或国家授权部门组织的从业资格考试合格者。"},{"i":6,"n":"第六条","txt":"从业资格确认工作由各省、自治区、直辖市人事  (职改)部门会同当地业务主管部门组织实施。"},{"i":7,"n":"第七条","txt":"执业资格通过考试方法取得。 参加执业资格考试的报名条件根据不同专业另行规定。"},{"i":8,"n":"第八条","txt":"执业资格考试工作由人事部会同国务院有关业务主管部门按照客观、公正、严格的原则组织进行。"},{"i":9,"n":"第九条","txt":"执业资格考试由国家定期举行。考试实行全国统一大纲、统一命题、统一组织、统一时间，所取得的执业资格经注册后，全国范围有效。"},{"i":10,"n":"第十条","txt":"凡符合规定条件的中华人民共和国公民，均可报名参加执业资格考试。"},{"i":11,"n":"第十一条","txt":"国务院有关业务主管部门负责组织执业资格考试大纲的拟定、培训教材的编写和命题工作，并组织考前培训和对取得执业资格人员的注册管理工作。培训要坚持考培分开、自愿参加的原则，参与考试管理工作的人员不得参与培训工作和参加考试。"},{"i":12,"n":"第十二条","txt":"人事部负责审定考试科目、考试大纲和审定命题;确定合格标准;会同有关部门组织实施执业资格考试的有关工作。各地人事(职改)部门会同当地有关业务部门负责本地区执业资格考试的考务工作。"},{"i":13,"n":"第十三条","txt":"经职业资格考试合格的人员，由国家授予相应的职业资格证书。"},{"i":14,"n":"第十四条","txt":"职业资格证书是证书持有人专业水平能力的证明。可作为求职、就业的凭证和从事特定专业的法定注册凭证。"},{"i":15,"n":"第十五条","txt":"职业资格证书在中华人民共和国境内有效。"},{"i":16,"n":"第十六条","txt":"职业资格证书分为《从业资格证书》和《执业资格证书》。证书由人事部统一印制，各地人事(职改)部门具体负责核发工作。"},{"i":17,"n":"第十七条","txt":"执业资格实行注册登记制度。注册是对专业技术人员执业管理的重要手段。未经注册者，不得使用相应名称和从事有关业务。国务院有关业务主管部门为执业资格的注册管理机构。各省、自治区、直辖市业务主管部门负责审核、注册，并报国务院业务主管部门备案。各省、自治区、直辖市人事(职改)部门负责对注册工作的监督、检查。"},{"i":18,"n":"第十八条","txt":"取得《执业资格证书》者，应在规定的期限内到指定的注册管理机构办理注册登记手续。逾期不办者，执业资格证书及考试成绩不再有效。"},{"i":19,"n":"第十九条","txt":"申请执业资格注册，必须同时具备下列条件: (一)遵纪守法，遵守职业道德； (二)取得《执业资格证书》； (三)身体健康，并能坚持在相应的岗位工作； (四)经所在单位考核合格。 再次注册者，应经单位考核合格并取得知识更新、参加业务培训的证明。"},{"i":20,"n":"第二十条","txt":"国务院业务主管部门负责确定必须由取得执业资格的人员充任的关键岗位及工作规范，并负责检查监督关键  岗位的执业人员上岗及执业情况，对违反岗位工作规范者要进行处罚。"},{"i":21,"n":"第二十一条","txt":"对已在须由取得执业资格人员充任的关键岗位工作、但尚未取得《执业资格证书》的人员，要进行强化培训，限期达到要求。对经过培训仍不能取得执业资格者，必须调离关键岗位。"},{"i":22,"n":"第二十二条","txt":"执业资格应考人员、考试工作人员和其他有关人员在考试和考务工作中有违法行为的，将追究其法律责任。"},{"i":23,"n":"第二十三条","txt":"对骗取、转让、涂改职业资格证书的人员，一经发现，发证机关应取消其资格，收回证书，并报国务院业务主管部门和当地同级人事(职改)部门备案。"},{"i":24,"n":"第二十四条","txt":"对伪造职业资格证书者，要依法追究责任。"},{"i":25,"n":"第二十五条","txt":"通过国家统一考试取得的专业技术资格，经鉴定认为水平相当，经批准确认，可视为执业资格。"},{"i":26,"n":"第二十六条","txt":"实行执业资格考试的专业不再组织该专业相应层次的专业技术资格评审或考试，并把取得执业资格作为申报高一级专业技术资格评审的必备条件。"},{"i":27,"n":"第二十七条","txt":"执业资格考试、认定、培训、发证、注册等工作费用的收取，必须经当地计划(物价)、财政部门核准。严禁乱收费。"},{"i":28,"n":"第二十八条","txt":"本办法由人事部负责解释。"},{"i":29,"n":"第二十九条","txt":"本办法自发布之日起施行。"}],"zhiyezigezhengshuguiding":[{"i":1,"n":"第一条","txt":"为了深化劳动、人事制度改革，适应社会主义市场经济对人才的需求，客观公正地评价专业（工种）技术人才，促进人才的合理流动，制定本规定。"},{"i":2,"n":"第二条","txt":"职业资格是对从事某一职业所必备的学识、技术和能力的基本要求。 职业资格包括从业资格和执业资格。从业资格是指从事某一专业（工种）学识、技术和能力的起点标准。执业资格是指政府对某些责任较大，社会通用性强，关系公共利益的专业（工种）实行准入控制，是依法独立开业或从事某一特定专业（工种）学识、技术和能力的必备标准。"},{"i":3,"n":"第三条","txt":"职业资格分别由国务院劳动、人事行政部门通过学历认定、资格考试、专家评定、职业技能鉴定等方式进行评价，对合格者授予国家职业资格证书。"},{"i":4,"n":"第四条","txt":"职业资格证书是国家对申请人专业（工种）学识、技术、能力的认可，是求职、任职、独立开业和单位录用的主要依据。"},{"i":5,"n":"第五条","txt":"职业资格证书制度遵循申请自愿、费用自理，客观公正的原则。凡中华人民共和国公民和获准在我国境内就业的其他国籍的人员都可按照国家有关政策规定和程序申请相应的职业资格。"},{"i":6,"n":"第六条","txt":"职业资格证书实行政府指导下的管理体制，由国务院劳动、人事行政部门综合管理。 若干专业技术资格和职业技能鉴定（技师、高级技师考评和技术等级考核）纳入职业资格证书制度。 劳动部负责以技能为主的职业资格鉴定和证书的核发与管理（证书的名称、种类按现行规定执行）。 人事部负责专业技术人员的职业资格评价和证书的核发与管理。 各省、自治区、直辖市劳动、人事行政部门负责本地区职业资格证书制度的组织实施。"},{"i":7,"n":"第七条","txt":"国务院劳动、人事行政部门会同有关行业主管部门研究和确定职业资格的范围、职业（专业、工种）分类、职业资格标准以及学历认定、资格考试、专家评定和技能鉴定的办法。"},{"i":8,"n":"第八条","txt":"国家职业资格证书参照国际惯例，实行国际双边或多边互认。"},{"i":9,"n":"第九条","txt":"本规定适用于国家机关、团体和所有企、事业单位。"},{"i":10,"n":"第十条","txt":"国务院劳动、人事行政部门按职责范围分别制定实施细则。"},{"i":11,"n":"第十一条","txt":"本规定由国务院劳动、人事行政部门按职责范围分别负责解释。"},{"i":12,"n":"第十二条","txt":"本规定自颁发之日起实施。"}],"zhichengpingshenguanlizanxingguiding":[{"i":1,"n":"第一条","txt":"为规范职称评审程序，加强职称评审管理，保证职称评审质量，根据有关法律法规和国务院规定，制定本规定。"},{"i":2,"n":"第二条","txt":"职称评审是按照评审标准和程序，对专业技术人才品德、能力、业绩的评议和认定。职称评审结果是专业技术人才聘用、考核、晋升等的重要依据。 对企业、事业单位、社会团体、个体经济组织等（以下称用人单位）以及自由职业者开展专业技术人才职称评审工作，适用本规定。"},{"i":3,"n":"第三条","txt":"职称评审坚持德才兼备、以德为先的原则，科学公正评价专业技术人才的职业道德、创新能力、业绩水平和实际贡献。"},{"i":4,"n":"第四条","txt":"国务院人力资源社会保障行政部门负责全国的职称评审统筹规划和综合管理工作。县级以上地方各级人力资源社会保障行政部门负责本地区职称评审综合管理和组织实施工作。 行业主管部门在各自职责范围内负责本行业的职称评审管理和实施工作。"},{"i":5,"n":"第五条","txt":"职称评审标准分为国家标准、地区标准和单位标准。 各职称系列国家标准由国务院人力资源社会保障行政部门会同行业主管部门制定。 地区标准由各地区人力资源社会保障行政部门会同行业主管部门依据国家标准，结合本地区实际制定。 单位标准由具有职称评审权的用人单位依据国家标准、地区标准，结合本单位实际制定。 地区标准、单位标准不得低于国家标准。"},{"i":6,"n":"第六条","txt":"各地区、各部门以及用人单位等按照规定开展职称评审，应当申请组建职称评审委员会。 职称评审委员会负责评议、认定专业技术人才学术技术水平和专业能力，对组建单位负责，受组建单位监督。 职称评审委员会按照职称系列或者专业组建，不得跨系列组建综合性职称评审委员会。"},{"i":7,"n":"第七条","txt":"职称评审委员会分为高级、中级、初级职称评审委员会。 申请组建高级职称评审委员会应当具备下列条件： （一）拟评审的职称系列或者专业为职称评审委员会组建单位主体职称系列或者专业； （二）拟评审的职称系列或者专业在行业内具有重要影响力，能够代表本领域的专业发展水平； （三）具有一定数量的专业技术人才和符合条件的高级职称评审专家； （四）具有开展高级职称评审的能力。"},{"i":8,"n":"第八条","txt":"国家对职称评审委员会实行核准备案管理制度。职称评审委员会备案有效期不得超过3年，有效期届满应当重新核准备案。 国务院各部门、中央企业、全国性行业协会学会、人才交流服务机构等组建的高级职称评审委员会由国务院人力资源社会保障行政部门核准备案；各地区组建的高级职称评审委员会由省级人力资源社会保障行政部门核准备案；其他用人单位组建的高级职称评审委员会按照职称评审管理权限由省级以上人力资源社会保障行政部门核准备案。 申请组建中级、初级职称评审委员会的条件以及核准备案的具体办法，按照职称评审管理权限由国务院各部门、省级人力资源社会保障行政部门以及具有职称评审权的用人单位制定。"},{"i":9,"n":"第九条","txt":"职称评审委员会组成人员应当是单数，根据工作需要设主任委员和副主任委员。按照职称系列组建的高级职称评审委员会评审专家不少于25人，按照专业组建的高级职称评审委员会评审专家不少于11人。各地区组建的高级职称评审委员会的人数，经省级人力资源社会保障行政部门同意，可以适当调整。"},{"i":10,"n":"第十条","txt":"职称评审委员会的评审专家应当具备下列条件： （一）遵守宪法和法律； （二）具备良好的职业道德； （三）具有本职称系列或者专业相应层级的职称； （四）从事本领域专业技术工作； （五）能够履行职称评审工作职责。 评审专家每届任期不得超过3年。"},{"i":11,"n":"第十一条","txt":"各地区、各部门和用人单位可以按照职称系列或者专业建立职称评审委员会专家库，在职称评审委员会专家库内随机抽取规定数量的评审专家组成职称评审委员会。 职称评审委员会专家库参照本规定第八条进行核准备案，从专家库内抽取专家组成的职称评审委员会不再备案。"},{"i":12,"n":"第十二条","txt":"职称评审委员会组建单位可以设立职称评审办事机构或者指定专门机构作为职称评审办事机构，由其负责职称评审的日常工作。"},{"i":13,"n":"第十三条","txt":"申报职称评审的人员（以下简称申报人）应当遵守宪法和法律，具备良好的职业道德，符合相应职称系列或者专业、相应级别职称评审规定的申报条件。 申报人应当为本单位在职的专业技术人才，离退休人员不得申报参加职称评审。 事业单位工作人员受到记过以上处分的，在受处分期间不得申报参加职称评审。"},{"i":14,"n":"第十四条","txt":"申报人一般应当按照职称层级逐级申报职称评审。取得重大基础研究和前沿技术突破、解决重大工程技术难题，在经济社会各项事业发展中作出重大贡献的专业技术人才，可以直接申报高级职称评审。 对引进的海外高层次人才和急需紧缺人才，可以合理放宽资历、年限等条件限制。 对长期在艰苦边远地区和基层一线工作的专业技术人才，侧重考查其实际工作业绩，适当放宽学历和任职年限要求。"},{"i":15,"n":"第十五条","txt":"申报人应当在规定期限内提交申报材料，对其申报材料的真实性负责。 凡是通过法定证照、书面告知承诺、政府部门内部核查或者部门间核查、网络核验等能够办理的，不得要求申报人额外提供证明材料。"},{"i":16,"n":"第十六条","txt":"申报人所在工作单位应当对申报材料进行审核，并在单位内部进行公示，公示期不少于5个工作日，对经公示无异议的，按照职称评审管理权限逐级上报。"},{"i":17,"n":"第十七条","txt":"非公有制经济组织的专业技术人才申报职称评审，可以由所在工作单位或者人事代理机构等履行审核、公示、推荐等程序。 自由职业者申报职称评审，可以由人事代理机构等履行审核、公示、推荐等程序。"},{"i":18,"n":"第十八条","txt":"职称评审委员会组建单位按照申报条件对申报材料进行审核。 申报材料不符合规定条件的，职称评审委员会组建单位应当一次性告知申报人需要补正的全部内容。逾期未补正的，视为放弃申报。"},{"i":19,"n":"第十九条","txt":"职称评审委员会组建单位组织召开评审会议。评审会议由主任委员或者副主任委员主持，出席评审会议的专家人数应当不少于职称评审委员会人数的2/3。"},{"i":20,"n":"第二十条","txt":"职称评审委员会经过评议，采取少数服从多数的原则，通过无记名投票表决，同意票数达到出席评审会议的评审专家总数2/3以上的即为评审通过。 未出席评审会议的评审专家不得委托他人投票或者补充投票。"},{"i":21,"n":"第二十一条","txt":"根据评审工作需要，职称评审委员会可以按照学科或者专业组成若干评议组，每个评议组评审专家不少于3人，负责对申报人提出书面评议意见；也可以不设评议组，由职称评审委员会3名以上评审专家按照分工，提出评议意见。评议组或者分工负责评议的专家在评审会议上介绍评议情况，作为职称评审委员会评议表决的参考。"},{"i":22,"n":"第二十二条","txt":"评审会议结束时，由主任委员或者主持评审会议的副主任委员宣布投票结果，并对评审结果签字确认，加盖职称评审委员会印章。"},{"i":23,"n":"第二十三条","txt":"评审会议应当做好会议记录，内容包括出席评委、评审对象、评议意见、投票结果等内容，会议记录归档管理。"},{"i":24,"n":"第二十四条","txt":"评审会议实行封闭管理，评审专家名单一般不对外公布。 评审专家和职称评审办事机构工作人员在评审工作保密期内不得对外泄露评审内容，不得私自接收评审材料，不得利用职务之便谋取不正当利益。"},{"i":25,"n":"第二十五条","txt":"评审专家与评审工作有利害关系或者其他关系可能影响客观公正的，应当申请回避。 职称评审办事机构发现上述情形的，应当通知评审专家回避。"},{"i":26,"n":"第二十六条","txt":"职称评审委员会组建单位对评审结果进行公示，公示期不少于5个工作日。 公示期间，对通过举报投诉等方式发现的问题线索，由职称评审委员会组建单位调查核实。 经公示无异议的评审通过人员，按照规定由人力资源社会保障行政部门或者职称评审委员会组建单位确认。具有职称评审权的用人单位，其经公示无异议的评审通过人员，按照规定由职称评审委员会核准部门备案。"},{"i":27,"n":"第二十七条","txt":"申报人对涉及本人的评审结果不服的，可以按照有关规定申请复查、进行投诉。"},{"i":28,"n":"第二十八条","txt":"不具备职称评审委员会组建条件的地区和单位，可以委托经核准备案的职称评审委员会代为评审。具体办法按照职称评审管理权限由国务院各部门、省级人力资源社会保障行政部门制定。"},{"i":29,"n":"第二十九条","txt":"专业技术人才跨区域、跨单位流动时，其职称按照职称评审管理权限重新评审或者确认，国家另有规定的除外。"},{"i":30,"n":"第三十条","txt":"职称评审委员会组建单位应当建立职称评价服务平台，提供便捷化服务。"},{"i":31,"n":"第三十一条","txt":"职称评审委员会组建单位应当加强职称评审信息化建设，推广在线评审，逐步实现网上受理、网上办理、网上反馈。"},{"i":32,"n":"第三十二条","txt":"人力资源社会保障行政部门建立职称评审信息化管理系统，统一数据标准，规范评审结果等数据采集。"},{"i":33,"n":"第三十三条","txt":"人力资源社会保障行政部门在保障信息安全和个人隐私的前提下，逐步开放职称信息查询验证服务，积极探索实行职称评审电子证书。电子证书与纸质证书具有同等效力。"},{"i":34,"n":"第三十四条","txt":"人力资源社会保障行政部门和行业主管部门应当加强对职称评审工作的监督检查。 被检查的单位、相关机构和个人应当如实提供与职称评审有关的资料，不得拒绝检查或者谎报、瞒报。"},{"i":35,"n":"第三十五条","txt":"人力资源社会保障行政部门和行业主管部门通过质询、约谈、现场观摩、查阅资料等形式，对各级职称评审委员会及其组建单位开展的评审工作进行抽查、巡查，依据有关问题线索进行倒查、复查。"},{"i":36,"n":"第三十六条","txt":"人力资源社会保障行政部门和行业主管部门应当依法查处假冒职称评审、制作和销售假证等违法行为。"},{"i":37,"n":"第三十七条","txt":"职称评审委员会组建单位应当依法执行物价、财政部门核准的收费标准，自觉接受监督和审计。"},{"i":38,"n":"第三十八条","txt":"违反本规定第八条规定，职称评审委员会未经核准备案、有效期届满未重新核准备案或者超越职称评审权限、擅自扩大职称评审范围的，人力资源社会保障行政部门对其职称评审权限或者超越权限和范围的职称评审行为不予认可；情节严重的，由人力资源社会保障行政部门取消职称评审委员会组建单位职称评审权，并依法追究相关人员的责任。"},{"i":39,"n":"第三十九条","txt":"违反本规定第十三条、第十五条规定，申报人通过提供虚假材料、剽窃他人作品和学术成果或者通过其他不正当手段取得职称的，由人力资源社会保障行政部门或者职称评审委员会组建单位撤销其职称，并记入职称评审诚信档案库，纳入全国信用信息共享平台，记录期限为3年。"},{"i":40,"n":"第四十条","txt":"违反本规定第十六条规定，申报人所在工作单位未依法履行审核职责的，由人力资源社会保障行政部门或者职称评审委员会组建单位对直接负责的主管人员和其他直接责任人员予以批评教育，并责令采取补救措施；情节严重的，依法追究相关人员责任。 违反本规定第十七条规定，非公有制经济组织或者人事代理机构等未依法履行审核职责的，按照前款规定处理。"},{"i":41,"n":"第四十一条","txt":"违反本规定第十八条规定，职称评审委员会组建单位未依法履行审核职责的，由人力资源社会保障行政部门对其直接负责的主管人员和其他直接责任人员予以批评教育，并责令采取补救措施；情节严重的，取消其职称评审权，并依法追究相关人员责任。"},{"i":42,"n":"第四十二条","txt":"评审专家违反本规定第二十四条、第二十五条规定的，由职称评审委员会组建单位取消其评审专家资格，通报批评并记入职称评审诚信档案库；构成犯罪的，依法追究刑事责任。 职称评审办事机构工作人员违反本规定第二十四条、第二十五条规定的，由职称评审委员会组建单位责令不得再从事职称评审工作，进行通报批评；构成犯罪的，依法追究刑事责任。"},{"i":43,"n":"第四十三条","txt":"涉密领域职称评审的具体办法，由相关部门和单位参照本规定另行制定。"},{"i":44,"n":"第四十四条","txt":"本规定自2019年9月1日起施行。"}],"weifanlaodongfayouguanlaodonghetongguidingdepeicha4de9b0":[{"i":1,"n":"第一条","txt":"为明确违反劳动法有关劳动合同规定的赔偿责任，维护劳动合同双方当事人的合法权益，根据《中华人民共和国劳动法》的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"用人单位有下列情形之一，对劳动者造成损害的，应赔偿劳动者损失； （一）用人单位故意拖延不订立劳动合同，即招用后故意不按规定订立劳动合同以及劳动合同到期后故意不及时续订劳动合同的； （二）由于用人单位的原因订立无效劳动合同，或订立部分无效劳动合同的； （三）用人单位违反规定或劳动合同的约定侵害女职工或未成年工合法权益的； （四）用人单位违反规定或劳动合同的约定解除劳动合同的。"},{"i":3,"n":"第三条","txt":"本办法第二条规定的赔偿，按下列规定执行： （一）造成劳动者工资收入损失的，按劳动者本人应得工资收入支付给劳动者，并加付应得工资收入25%的赔偿费用。 （二）造成劳动者劳动保护待遇损失的，应按国家规定补足劳动者的劳动保护津贴和用品； （三）造成劳动者工伤、医疗待遇损失的，除按国家规定为劳动者提供工伤、医疗待遇外，还应支付劳动者相当于医疗费用25%的赔偿费用； （四）造成女职工和未成年工身体健康损害的，除按国家规定提供治疗期间的医疗待遇外，还应支付相当于其医疗费用25%的赔偿费用； （五）劳动合同约定的其他赔偿费用。"},{"i":4,"n":"第四条","txt":"劳动者违反规定或劳动合同的约定解除劳动合同，对用人单位造成损失的，劳动者应赔偿用人单位下列损失： （一）用人单位招收录用其所支付的费用； （二）用人单位为其支付的培训费用，双方另有约定的按约定办理； （三）对生产、经营和工作造成的直接经济损失； （四）劳动合同约定的其他赔偿费用。"},{"i":5,"n":"第五条","txt":"劳动者违反劳动合同中约定的保密事项，对用人单位造成经济损失的，按《反不正当竞争法》第二十条的规定支付用人单位赔偿费用。"},{"i":6,"n":"第六条","txt":"用人单位招用尚未解除劳动合同的劳动者，对原用人单位造成经济损失的，除该劳动者承担直接赔偿责任外，该用人单位应当承担连带赔偿责任。其连带赔偿的份额应不低于对原用人单位造成经济损失总额的百分之七十。向原用人单位赔偿下列损失： （一）对生产、经营和工作造成的直接经济损失； （二）因获取商业秘密给原用人单位造成的经济损失。 赔偿本条第（二）项规定的损失，按《反不正当竞争法》第二十条的规定执行。"},{"i":7,"n":"第七条","txt":"因赔偿引起争议的，按照国家有关劳动争议处理的规定办理。"},{"i":8,"n":"第八条","txt":"本办法自发布之日起施行。"}],"bufenhangyeqiyegongshangbaoxianfeijiaonabanfa":[{"i":1,"n":"第一条","txt":"根据《工伤保险条例》第十条第三款的授权，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称的部分行业企业是指建筑、服务、矿山等行业中难以直接按照工资总额计算缴纳工伤保险费的建筑施工企业、小型服务企业、小型矿山企业等。 前款所称小型服务企业、小型矿山企业的划分标准可以参照《中小企业标准暂行规定》（国经贸中小企〔2003〕143号）执行。"},{"i":3,"n":"第三条","txt":"建筑施工企业可以实行以建筑施工项目为单位，按照项目工程总造价的一定比例，计算缴纳工伤保险费。"},{"i":4,"n":"第四条","txt":"商贸、餐饮、住宿、美容美发、洗浴以及文体娱乐等小型服务业企业以及有雇工的个体工商户，可以按照营业面积的大小核定应参保人数，按照所在统筹地区上一年度职工月平均工资的一定比例和相应的费率，计算缴纳工伤保险费；也可以按照营业额的一定比例计算缴纳工伤保险费。"},{"i":5,"n":"第五条","txt":"小型矿山企业可以按照总产量、吨矿工资含量和相应的费率计算缴纳工伤保险费。"},{"i":6,"n":"第六条","txt":"本办法中所列部分行业企业工伤保险费缴纳的具体计算办法，由省级社会保险行政部门根据本地区实际情况确定。"},{"i":7,"n":"第七条","txt":"本办法自2011年1月1日起施行。"}],"zhongdalaodongbaozhangweifaxingweishehuigongbubanfac037c":[{"i":1,"n":"第一条","txt":"为加强对重大劳动保障违法行为的惩戒，强化社会舆论监督，促进用人单位遵守劳动保障法律、法规和规章，根据《劳动保障监察条例》《企业信息公示暂行条例》等有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"人力资源社会保障行政部门依法向社会公布用人单位重大劳动保障违法行为，适用本办法。"},{"i":3,"n":"第三条","txt":"人力资源社会保障行政部门向社会公布重大劳动保障违法行为，应当遵循依法依规、公平公正、客观真实的原则。"},{"i":4,"n":"第四条","txt":"人力资源社会保障部负责指导监督全国重大劳动保障违法行为社会公布工作，并向社会公布在全国有重大影响的劳动保障违法行为。 省、自治区、直辖市人力资源社会保障行政部门负责指导监督本行政区域重大劳动保障违法行为社会公布工作，并向社会公布在本行政区域有重大影响的劳动保障违法行为。 地市级、县级人力资源社会保障行政部门依据行政执法管辖权限，负责本辖区的重大劳动保障违法行为社会公布工作。"},{"i":5,"n":"第五条","txt":"人力资源社会保障行政部门对下列已经依法查处并作出处理决定的重大劳动保障违法行为，应当向社会公布： （一）克扣、无故拖欠劳动者劳动报酬，数额较大的；拒不支付劳动报酬,依法移送司法机关追究刑事责任的； （二）不依法参加社会保险或者不依法缴纳社会保险费，情节严重的； （三）违反工作时间和休息休假规定，情节严重的； （四）违反女职工和未成年工特殊劳动保护规定，情节严重的； （五）违反禁止使用童工规定的； （六）因劳动保障违法行为造成严重不良社会影响的； （七）其他重大劳动保障违法行为。"},{"i":6,"n":"第六条","txt":"向社会公布重大劳动保障违法行为，应当列明下列事项： （一）违法主体全称、统一社会信用代码（或者注册号）及地址； （二）法定代表人或者负责人姓名； （三）主要违法事实； （四）相关处理情况。 涉及国家秘密、商业秘密以及个人隐私的信息不得公布。"},{"i":7,"n":"第七条","txt":"重大劳动保障违法行为应当在人力资源社会保障行政部门门户网站公布，并在本行政区域主要报刊、电视等媒体予以公布。"},{"i":8,"n":"第八条","txt":"地市级、县级人力资源社会保障行政部门对本辖区发生的重大劳动保障违法行为每季度向社会公布一次。 人力资源社会保障部和省级人力资源社会保障行政部门每半年向社会公布一次重大劳动保障违法行为。 根据工作需要，对重大劳动保障违法行为可随时公布。"},{"i":9,"n":"第九条","txt":"县级以上地方人力资源社会保障行政部门在向社会公布重大劳动保障违法行为之前，应当将公布的信息报告上一级人力资源社会保障行政部门。"},{"i":10,"n":"第十条","txt":"人力资源社会保障行政部门应当将重大劳动保障违法行为及其社会公布情况记入用人单位劳动保障守法诚信档案，纳入人力资源社会保障信用体系，并与其他部门和社会组织依法依规实施信息共享和联合惩戒。"},{"i":11,"n":"第十一条","txt":"用人单位对社会公布内容有异议的，由负责查处的人力资源社会保障行政部门自收到申请之日起15个工作日内予以复核和处理，并通知用人单位。 重大劳动保障违法行为处理决定被依法变更或者撤销的，负责查处的人力资源社会保障行政部门应当自变更或者撤销之日起10个工作日内，对社会公布内容予以更正。"},{"i":12,"n":"第十二条","txt":"人力资源社会保障行政部门工作人员在重大劳动保障违法行为社会公布中滥用职权、玩忽职守、徇私舞弊的，依法予以处理。"},{"i":13,"n":"第十三条","txt":"本办法自2017年1月1日起施行。"}],"jitihetongguiding":[{"i":1,"n":"第一条","txt":"为规范集体协商和签订集体合同行为，依法维护劳动者和用人单位的合法权益，根据《中华人民共和国劳动法》和《中华人民共和国工会法》，制定本规定。"},{"i":2,"n":"第二条","txt":"中华人民共和国境内的企业和实行企业化管理的事业单位（以下统称用人单位）与本单位职工之间进行集体协商，签订集体合同，适用本规定。"},{"i":3,"n":"第三条","txt":"本规定所称集体合同，是指用人单位与本单位职工根据法律、法规、规章的规定，就劳动报酬、工作时间、休息休假、劳动安全卫生、职业培训、保险福利等事项，通过集体协商签订的书面协议；所称专项集体合同，是指用人单位与本单位职工根据法律、法规、规章的规定，就集体协商的某项内容签订的专项书面协议。"},{"i":4,"n":"第四条","txt":"用人单位与本单位职工签订集体合同或专项集体合同，以及确定相关事宜，应当采取集体协商的方式。集体协商主要采取协商会议的形式。"},{"i":5,"n":"第五条","txt":"进行集体协商，签订集体合同或专项集体合同，应当遵循下列原则： （一）遵守法律、法规、规章及国家有关规定； （二）相互尊重，平等协商； （三）诚实守信，公平合作； （四）兼顾双方合法权益； （五）不得采取过激行为。"},{"i":6,"n":"第六条","txt":"符合本规定的集体合同或专项集体合同，对用人单位和本单位的全体职工具有法律约束力。 用人单位与职工个人签订的劳动合同约定的劳动条件和劳动报酬等标准，不得低于集体合同或专项集体合同的规定。"},{"i":7,"n":"第七条","txt":"县级以上劳动保障行政部门对本行政区域内用人单位与本单位职工开展集体协商、签订、履行集体合同的情况进行监督，并负责审查集体合同或专项集体合同。"},{"i":8,"n":"第八条","txt":"集体协商双方可以就下列多项或某项内容进行集体协商，签订集体合同或专项集体合同： （一）劳动报酬； （二）工作时间； （三）休息休假； （四）劳动安全与卫生； （五）补充保险和福利； （六）女职工和未成年工特殊保护； （七）职业技能培训； （八）劳动合同管理； （九）奖惩； （十）裁员； （十一）集体合同期限； （十二）变更、解除集体合同的程序； （十三）履行集体合同发生争议时的协商处理办法； （十四）违反集体合同的责任； （十五）双方认为应当协商的其他内容。"},{"i":9,"n":"第九条","txt":"劳动报酬主要包括： （一）用人单位工资水平、工资分配制度、工资标准和工资分配形式； （二）工资支付办法； （三）加班、加点工资及津贴、补贴标准和奖金分配办法； （四）工资调整办法； （五）试用期及病、事假等期间的工资待遇； （六）特殊情况下职工工资（生活费）支付办法； （七）其他劳动报酬分配办法。"},{"i":10,"n":"第十条","txt":"工作时间主要包括： （一）工时制度； （二）加班加点办法； （三）特殊工种的工作时间； （四）劳动定额标准。"},{"i":11,"n":"第十一条","txt":"休息休假主要包括： （一）日休息时间、周休息日安排、年休假办法； （二）不能实行标准工时职工的休息休假； （三）其他假期。"},{"i":12,"n":"第十二条","txt":"劳动安全卫生主要包括： （一）劳动安全卫生责任制； （二）劳动条件和安全技术措施； （三）安全操作规程； （四）劳保用品发放标准； （五）定期健康检查和职业健康体检。"},{"i":13,"n":"第十三条","txt":"补充保险和福利主要包括： （一）补充保险的种类、范围； （二）基本福利制度和福利设施； （三）医疗期延长及其待遇； （四）职工亲属福利制度。"},{"i":14,"n":"第十四条","txt":"女职工和未成年工的特殊保护主要包括： （一）女职工和未成年工禁忌从事的劳动； （二）女职工的经期、孕期、产期和哺乳期的劳动保护； （三）女职工、未成年工定期健康检查； （四）未成年工的使用和登记制度。"},{"i":15,"n":"第十五条","txt":"职业技能培训主要包括： （一）职业技能培训项目规划及年度计划； （二）职业技能培训费用的提取和使用； （三）保障和改善职业技能培训的措施。"},{"i":16,"n":"第十六条","txt":"劳动合同管理主要包括： （一）劳动合同签订时间； （二）确定劳动合同期限的条件； （三）劳动合同变更、解除、续订的一般原则及无固定期限劳动合同的终止条件； （四）试用期的条件和期限。"},{"i":17,"n":"第十七条","txt":"奖惩主要包括： （一）劳动纪律； （二）考核奖惩制度； （三）奖惩程序。"},{"i":18,"n":"第十八条","txt":"裁员主要包括： （一）裁员的方案； （二）裁员的程序； （三）裁员的实施办法和补偿标准。"},{"i":19,"n":"第十九条","txt":"本规定所称集体协商代表（以下统称协商代表），是指按照法定程序产生并有权代表本方利益进行集体协商的人员。 集体协商双方的代表人数应当对等，每方至少3人，并各确定1名首席代表。"},{"i":20,"n":"第二十条","txt":"职工一方的协商代表由本单位工会选派。未建立工会的，由本单位职工民主推荐，并经本单位半数以上职工同意。 职工一方的首席代表由本单位工会主席担任。工会主席可以书面委托其他协商代表代理首席代表。工会主席空缺的，首席代表由工会主要负责人担任。未建立工会的，职工一方的首席代表从协商代表中民主推举产生。"},{"i":21,"n":"第二十一条","txt":"用人单位一方的协商代表，由用人单位法定代表人指派，首席代表由单位法定代表人担任或由其书面委托的其他管理人员担任。"},{"i":22,"n":"第二十二条","txt":"协商代表履行职责的期限由被代表方确定。"},{"i":23,"n":"第二十三条","txt":"集体协商双方首席代表可以书面委托本单位以外的专业人员作为本方协商代表。委托人数不得超过本方代表的三分之一。 首席代表不得由非本单位人员代理。"},{"i":24,"n":"第二十四条","txt":"用人单位协商代表与职工协商代表不得相互兼任。"},{"i":25,"n":"第二十五条","txt":"协商代表应履行下列职责： （一）参加集体协商； （二）接受本方人员质询，及时向本方人员公布协商情况并征求意见； （三）提供与集体协商有关的情况和资料； （四）代表本方参加集体协商争议的处理； （五）监督集体合同或专项集体合同的履行； （六）法律、法规和规章规定的其他职责。"},{"i":26,"n":"第二十六条","txt":"协商代表应当维护本单位正常的生产、工作秩序，不得采取威胁、收买、欺骗等行为。 协商代表应当保守在集体协商过程中知悉的用人单位的商业秘密。"},{"i":27,"n":"第二十七条","txt":"企业内部的协商代表参加集体协商视为提供了正常劳动。"},{"i":28,"n":"第二十八条","txt":"职工一方协商代表在其履行协商代表职责期间劳动合同期满的，劳动合同期限自动延长至完成履行协商代表职责之时，除出现下列情形之一的，用人单位不得与其解除劳动合同： （一）严重违反劳动纪律或用人单位依法制定的规章制度的； （二）严重失职、营私舞弊，对用人单位利益造成重大损害的； （三）被依法追究刑事责任的。 职工一方协商代表履行协商代表职责期间，用人单位无正当理由不得调整其工作岗位。"},{"i":29,"n":"第二十九条","txt":"职工一方协商代表就本规定第二十七条、第二十八条的规定与用人单位发生争议的，可以向当地劳动争议仲裁委员会申请仲裁。"},{"i":30,"n":"第三十条","txt":"工会可以更换职工一方协商代表；未建立工会的，经本单位半数以上职工同意可以更换职工一方协商代表。 用人单位法定代表人可以更换用人单位一方协商代表。"},{"i":31,"n":"第三十一条","txt":"协商代表因更换、辞任或遇有不可抗力等情形造成空缺的，应在空缺之日起15日内按照本规定产生新的代表。"},{"i":32,"n":"第三十二条","txt":"集体协商任何一方均可就签订集体合同或专项集体合同以及相关事宜，以书面形式向对方提出进行集体协商的要求。 一方提出进行集体协商要求的，另一方应当在收到集体协商要求之日起20日内以书面形式给以回应，无正当理由不得拒绝进行集体协商。"},{"i":33,"n":"第三十三条","txt":"协商代表在协商前应进行下列准备工作： （一）熟悉与集体协商内容有关的法律、法规、规章和制度； （二）了解与集体协商内容有关的情况和资料，收集用人单位和职工对协商意向所持的意见； （三）拟定集体协商议题，集体协商议题可由提出协商一方起草，也可由双方指派代表共同起草； （四）确定集体协商的时间、地点等事项； （五）共同确定一名非协商代表担任集体协商记录员。记录员应保持中立、公正，并为集体协商双方保密。"},{"i":34,"n":"第三十四条","txt":"集体协商会议由双方首席代表轮流主持，并按下列程序进行： （一）宣布议程和会议纪律； （二）一方首席代表提出协商的具体内容和要求，另一方首席代表就对方的要求作出回应； （三）协商双方就商谈事项发表各自意见，开展充分讨论； （四）双方首席代表归纳意见。达成一致的，应当形成集体合同草案或专项集体合同草案，由双方首席代表签字。"},{"i":35,"n":"第三十五条","txt":"集体协商未达成一致意见或出现事先未预料的问题时，经双方协商，可以中止协商。中止期限及下次协商时间、地点、内容由双方商定。"},{"i":36,"n":"第三十六条","txt":"经双方协商代表协商一致的集体合同草案或专项集体合同草案应当提交职工代表大会或者全体职工讨论。 职工代表大会或者全体职工讨论集体合同草案或专项集体合同草案，应当有三分之二以上职工代表或者职工出席，且须经全体职工代表半数以上或者全体职工半数以上同意，集体合同草案或专项集体合同草案方获通过。"},{"i":37,"n":"第三十七条","txt":"集体合同草案或专项集体合同草案经职工代表大会或者职工大会通过后，由集体协商双方首席代表签字。"},{"i":38,"n":"第三十八条","txt":"集体合同或专项集体合同期限一般为1至3年，期满或双方约定的终止条件出现，即行终止。 集体合同或专项集体合同期满前3个月内，任何一方均可向对方提出重新签订或续订的要求。"},{"i":39,"n":"第三十九条","txt":"双方协商代表协商一致，可以变更或解除集体合同或专项集体合同。"},{"i":40,"n":"第四十条","txt":"有下列情形之一的，可以变更或解除集体合同或专项集体合同： （一）用人单位因被兼并、解散、破产等原因，致使集体合同或专项集体合同无法履行的； （二）因不可抗力等原因致使集体合同或专项集体合同无法履行或部分无法履行的； （三）集体合同或专项集体合同约定的变更或解除条件出现的； （四）法律、法规、规章规定的其他情形。"},{"i":41,"n":"第四十一条","txt":"变更或解除集体合同或专项集体合同适用本规定的集体协商程序。"},{"i":42,"n":"第四十二条","txt":"集体合同或专项集体合同签订或变更后，应当自双方首席代表签字之日起10日内，由用人单位一方将文本一式三份报送劳动保障行政部门审查。 劳动保障行政部门对报送的集体合同或专项集体合同应当办理登记手续。"},{"i":43,"n":"第四十三条","txt":"集体合同或专项集体合同审查实行属地管辖，具体管辖范围由省级劳动保障行政部门规定。 中央管辖的企业以及跨省、自治区、直辖市的用人单位的集体合同应当报送劳动保障部或劳动保障部指定的省级劳动保障行政部门。"},{"i":44,"n":"第四十四条","txt":"劳动保障行政部门应当对报送的集体合同或专项集体合同的下列事项进行合法性审查： （一）集体协商双方的主体资格是否符合法律、法规和规章规定； （二）集体协商程序是否违反法律、法规、规章规定； （三）集体合同或专项集体合同内容是否与国家规定相抵触。"},{"i":45,"n":"第四十五条","txt":"劳动保障行政部门对集体合同或专项集体合同有异议的，应当自收到文本之日起15日内将《审查意见书》送达双方协商代表。《审查意见书》应当载明以下内容： （一）集体合同或专项集体合同当事人双方的名称、地址； （二）劳动保障行政部门收到集体合同或专项集体合同的时间； （三）审查意见； （四）作出审查意见的时间。 《审查意见书》应当加盖劳动保障行政部门印章。"},{"i":46,"n":"第四十六条","txt":"用人单位与本单位职工就劳动保障行政部门提出异议的事项经集体协商重新签订集体合同或专项集体合同的，用人单位一方应当根据本规定第四十二条的规定将文本报送劳动保障行政部门审查。"},{"i":47,"n":"第四十七条","txt":"劳动保障行政部门自收到到文本之日起15日内未提出异议的，集体合同或专项集体合同即行生效。"},{"i":48,"n":"第四十八条","txt":"生效的集体合同或专项集体合同，应当自其生效之日起由协商代表及时以适当的形式向本方全体人员公布。"},{"i":49,"n":"第四十九条","txt":"集体协商过程中发生争议，双方当事人不能协商解决的，当事人一方或双方可以书面向劳动保障行政部门提出协调处理申请；未提出申请的，劳动保障行政部门认为必要时也可以进行协调处理。"},{"i":50,"n":"第五十条","txt":"劳动保障行政部门应当组织同级工会和企业组织等三方面的人员，共同协调处理集体协商争议。"},{"i":51,"n":"第五十一条","txt":"集体协商争议处理实行属地管辖，具体管辖范围由省级劳动保障行政部门规定。 中央管辖的企业以及跨省、自治区、直辖市用人单位因集体协商发生的争议，由劳动保障部指定的省级劳动保障行政部门组织同级工会和企业组织等三方面的人员协调处理，必要时，劳动保障部也可以组织有关方面协调处理。"},{"i":52,"n":"第五十二条","txt":"协调处理集体协商争议，应当自受理协调处理申请之日起30日内结束协调处理工作。期满未结束的，可以适当延长协调期限，但延长期限不得超过15日。"},{"i":53,"n":"第五十三条","txt":"协调处理集体协商争议应当按照以下程序进行： （一）受理协调处理申请； （二）调查了解争议的情况； （三）研究制定协调处理争议的方案； （四）对争议进行协调处理； （五）制作《协调处理协议书》。"},{"i":54,"n":"第五十四条","txt":"《协调处理协议书》应当载明协调处理申请、争议的事实和协调结果，双方当事人就某些协商事项不能达成一致的，应将继续协商的有关事项予以载明。《协调处理协议书》由集体协商争议协调处理人员和争议双方首席代表签字盖章后生效。争议双方均应遵守生效后的《协调处理协议书》。"},{"i":55,"n":"第五十五条","txt":"因履行集体合同发生的争议，当事人协商解决不成的，可以依法向劳动争议仲裁委员会申请仲裁。"},{"i":56,"n":"第五十六条","txt":"用人单位无正当理由拒绝工会或职工代表提出的集体协商要求的，按照《工会法》及有关法律、法规的规定处理。"},{"i":57,"n":"第五十七条","txt":"本规定于2004年5月1日起实施。原劳动部1994年12月5日颁布的《集体合同规定》同时废止。"}],"feifayonggongdanweishangwangrenyuanyicixingpeichan67a8b6":[{"i":1,"n":"第一条","txt":"根据《工伤保险条例》第六十六条第一款的授权，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称非法用工单位伤亡人员，是指无营业执照或者未经依法登记、备案的单位以及被依法吊销营业执照或者撤销登记、备案的单位受到事故伤害或者患职业病的职工，或者用人单位使用童工造成的伤残、死亡童工。 前款所列单位必须按照本办法的规定向伤残职工或者死亡职工的近亲属、伤残童工或者死亡童工的近亲属给予一次性赔偿。"},{"i":3,"n":"第三条","txt":"一次性赔偿包括受到事故伤害或者患职业病的职工或童工在治疗期间的费用和一次性赔偿金。一次性赔偿金数额应当在受到事故伤害或者患职业病的职工或童工死亡或者经劳动能力鉴定后确定。 劳动能力鉴定按照属地原则由单位所在地设区的市级劳动能力鉴定委员会办理。劳动能力鉴定费用由伤亡职工或童工所在单位支付。"},{"i":4,"n":"第四条","txt":"职工或童工受到事故伤害或者患职业病，在劳动能力鉴定之前进行治疗期间的生活费按照统筹地区上年度职工月平均工资标准确定，医疗费、护理费、住院期间的伙食补助费以及所需的交通费等费用按照《工伤保险条例》规定的标准和范围确定，并全部由伤残职工或童工所在单位支付。"},{"i":5,"n":"第五条","txt":"一次性赔偿金按照以下标准支付： 一级伤残的为赔偿基数的16倍，二级伤残的为赔偿基数的14倍，三级伤残的为赔偿基数的12倍，四级伤残的为赔偿基数的10倍，五级伤残的为赔偿基数的8倍，六级伤残的为赔偿基数的6倍，七级伤残的为赔偿基数的4倍，八级伤残的为赔偿基数的3倍，九级伤残的为赔偿基数的2倍，十级伤残的为赔偿基数的1倍。 前款所称赔偿基数，是指单位所在工伤保险统筹地区上年度职工年平均工资。"},{"i":6,"n":"第六条","txt":"受到事故伤害或者患职业病造成死亡的，按照上一年度全国城镇居民人均可支配收入的20倍支付一次性赔偿金，并按照上一年度全国城镇居民人均可支配收入的10倍一次性支付丧葬补助等其他赔偿金。"},{"i":7,"n":"第七条","txt":"单位拒不支付一次性赔偿的，伤残职工或者死亡职工的近亲属、伤残童工或者死亡童工的近亲属可以向人力资源和社会保障行政部门举报。经查证属实的，人力资源和社会保障行政部门应当责令该单位限期改正。"},{"i":8,"n":"第八条","txt":"伤残职工或者死亡职工的近亲属、伤残童工或者死亡童工的近亲属就赔偿数额与单位发生争议的，按照劳动争议处理的有关规定处理。"},{"i":9,"n":"第九条","txt":"本办法自2011年1月1日起施行。劳动和社会保障部2003年9月23日颁布的《非法用工单位伤亡人员一次性赔偿办法》同时废止。"}],"xianggangaomentaiwanjuminzaineidicanjiashehuibaoxif58c5e":[{"i":1,"n":"第一条","txt":"为了维护在内地（大陆）就业、居住和就读的香港特别行政区、澳门特别行政区居民中的中国公民和台湾地区居民（以下简称港澳台居民）依法参加社会保险和享受社会保险待遇的合法权益，加强社会保险管理，根据《中华人民共和国社会保险法》（以下简称社会保险法）等规定，制定本办法。"},{"i":2,"n":"第二条","txt":"在内地（大陆）依法注册或者登记的企业、事业单位、社会组织、有雇工的个体经济组织等用人单位（以下统称用人单位）依法聘用、招用的港澳台居民，应当依法参加职工基本养老保险、职工基本医疗保险、工伤保险、失业保险和生育保险，由用人单位和本人按照规定缴纳社会保险费。 在内地（大陆）依法从事个体工商经营的港澳台居民，可以按照注册地有关规定参加职工基本养老保险和职工基本医疗保险；在内地（大陆）灵活就业且办理港澳台居民居住证的港澳台居民，可以按照居住地有关规定参加职工基本养老保险和职工基本医疗保险。 在内地（大陆）居住且办理港澳台居民居住证的未就业港澳台居民，可以在居住地按照规定参加城乡居民基本养老保险和城乡居民基本医疗保险。 在内地（大陆）就读的港澳台大学生，与内地（大陆）大学生执行同等医疗保障政策，按规定参加高等教育机构所在地城乡居民基本医疗保险。"},{"i":3,"n":"第三条","txt":"用人单位依法聘用、招用港澳台居民的，应当持港澳台居民有效证件，以及劳动合同、聘用合同等证明材料，为其办理社会保险登记。在内地（大陆）依法从事个体工商经营和灵活就业的港澳台居民，按照注册地（居住地）有关规定办理社会保险登记。 已经办理港澳台居民居住证且符合在内地（大陆）参加城乡居民基本养老保险和城乡居民基本医疗保险条件的港澳台居民，持港澳台居民居住证在居住地办理社会保险登记。"},{"i":4,"n":"第四条","txt":"港澳台居民办理社会保险的各项业务流程与内地（大陆）居民一致。社会保险经办机构或者社会保障卡管理机构应当为港澳台居民建立社会保障号码，并发放社会保障卡。 港澳台居民在办理居住证时取得的公民身份号码作为其社会保障号码；没有公民身份号码的港澳居民的社会保障号码，由社会保险经办机构或者社会保障卡管理机构按照国家统一规定编制。"},{"i":5,"n":"第五条","txt":"参加社会保险的港澳台居民，依法享受社会保险待遇。"},{"i":6,"n":"第六条","txt":"参加职工基本养老保险的港澳台居民达到法定退休年龄时,累计缴费不足15年的，可以延长缴费至满15年。社会保险法实施前参保、延长缴费5年后仍不足15年的，可以一次性缴费至满15年。 参加城乡居民基本养老保险的港澳台居民，符合领取待遇条件的，在居住地按照有关规定领取城乡居民基本养老保险待遇。达到待遇领取年龄时，累计缴费不足15年的，可以按照有关规定延长缴费或者补缴。 参加职工基本医疗保险的港澳台居民，达到法定退休年龄时累计缴费达到国家规定年限的，退休后不再缴纳基本医疗保险费，按照国家规定享受基本医疗保险待遇；未达到国家规定年限的，可以缴费至国家规定年限。退休人员享受基本医疗保险待遇的缴费年限按照各地规定执行。 参加城乡居民基本医疗保险的港澳台居民按照与所在统筹地区城乡居民同等标准缴费，并享受同等的基本医疗保险待遇。 参加基本医疗保险的港澳台居民，在境外就医所发生的医疗费用不纳入基本医疗保险基"},{"i":7,"n":"第七条","txt":"港澳台居民在达到规定的领取养老金条件前离开内地（大陆）的，其社会保险个人账户予以保留，再次来内地（大陆）就业、居住并继续缴费的，缴费年限累计计算；经本人书面申请终止社会保险关系的，可以将其社会保险个人账户储存额一次性支付给本人。 已获得香港、澳门、台湾居民身份的原内地（大陆）居民，离开内地（大陆）时选择保留社会保险关系的，返回内地（大陆）就业、居住并继续参保时，原缴费年限合并计算；离开内地（大陆）时已经选择终止社会保险关系的，原缴费年限不再合并计算，可以将其社会保险个人账户储存额一次性支付给本人。"},{"i":8,"n":"第八条","txt":"参加社会保险的港澳台居民在内地（大陆）跨统筹地区流动办理社会保险关系转移时，按照国家有关规定执行。港澳台居民参加企业职工基本养老保险的，不适用建立临时基本养老保险缴费账户的相关规定。已经领取养老保险待遇的，不再办理基本养老保险关系转移接续手续。已经享受退休人员医疗保险待遇的，不再办理基本医疗保险关系转移接续手续。 参加职工基本养老保险的港澳台居民跨省流动就业的，应当转移基本养老保险关系。达到待遇领取条件时，在其基本养老保险关系所在地累计缴费年限满10年的，在该地办理待遇领取手续；在其基本养老保险关系所在地累计缴费年限不满10年的，将其基本养老保险关系转回上一个缴费年限满10年的参保地办理待遇领取手续；在各参保地累计缴费年限均不满10年的，由其缴费年限最长的参保地负责归集基本养老保险关系及相应资金，办理待遇领取手续，并支付基本养老保险待遇；如有多个缴费年限相同的最长参保地，则由其最后一个"},{"i":9,"n":"第九条","txt":"按月领取基本养老保险、工伤保险待遇的港澳台居民，应当按照社会保险经办机构的规定，办理领取待遇资格认证。 按月领取基本养老保险、工伤保险、失业保险待遇的港澳台居民丧失领取资格条件后，本人或者其亲属应当于1个月内向社会保险经办机构如实报告情况。因未主动报告而多领取的待遇应当及时退还社会保险经办机构。"},{"i":10,"n":"第十条","txt":"各级财政对在内地（大陆）参加城乡居民基本养老保险和城乡居民基本医疗保险（港澳台大学生除外）的港澳台居民，按照与所在统筹地区城乡居民相同的标准给予补助。 各级财政对港澳台大学生参加城乡居民基本医疗保险补助政策按照有关规定执行。"},{"i":11,"n":"第十一条","txt":"已在香港、澳门、台湾参加当地社会保险，并继续保留社会保险关系的港澳台居民，可以持相关授权机构出具的证明，不在内地（大陆）参加基本养老保险和失业保险。"},{"i":12,"n":"第十二条","txt":"内地（大陆）与香港、澳门、台湾有关机构就社会保险事宜作出具体安排的，按照相关规定办理。"},{"i":13,"n":"第十三条","txt":"社会保险行政部门或者社会保险费征收机构应当按照社会保险法的规定，对港澳台居民参加社会保险的情况进行监督检查。用人单位未依法为聘用、招用的港澳台居民办理社会保险登记或者未依法为其缴纳社会保险费的，按照社会保险法等法律、行政法规和有关规章的规定处理。"},{"i":14,"n":"第十四条","txt":"办法所称“港澳台居民有效证件”，指港澳居民来往内地通行证、港澳台居民居住证。"},{"i":15,"n":"第十五条","txt":"本办法自2020年1月1日起施行。"}]};
